{"assumptions":[],"created_at":"2026-10-27T23:11:09.318423+00:00","domain":"probability theory","id":"claim_6e8ab914592b26b7c7c721957605c984b39a81d0ca33ea4b5db576adcc3947a1","kind":"definition","schema_version":1,"statement":"[Definition def:parameters-restriction-to-a-subset of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] We define new transition probabilities, rates, and weights as follows
  \begin{align}
    & p^{\neq}=\left(p^{\neq}_{ij}:=\frac{p_{ij}}{1-p_{ii}}1_{\{i\neq j\}}\right)_{i,j\in\Lambda}, \quad
      q^{\neq}=(q^{\neq}_{ij}:=q_{ij}1_{\{i\neq j\}})_{i,j\in\Lambda}, \\
    & C^{\neq}=(C^{\neq}_{ij}:=C_{ij}1_{\{i\neq j\}})_{i,j\in\Lambda}, \quad
      C^{\neq}_i:=\sum_{k\in\Lambda}C^{\neq}_{ik}, i\in\Lambda. 
  \end{align}
  For any subset $J\subseteq\Lambda$ with $\rho\in J$, $|J|\ge 2$, we set
  $I=\Lambda\setminus J$ and define 
  \begin{align}

    p^J=(p^J_{ij})_{i,j\in J}:=p_{JJ}+\sum_{l=0}^\infty p_{JI}p_{II}^lp_{IJ},
  \end{align}
  which is a convergent series with $p_{ij}^J=Q^{C,\Lambda}_i(X^J_1=j)$.
  Furthermore, we define
  \begin{align}
    C^J=(C^J_{ij}:=C_ip^J_{ij})_{i,j\in J}, \quad
    q^J=\left(q^J_{ij}:=\frac{C_i}{\pi_i}p^J_{ij}\right)_{i,j\in J}.
  \end{align}
  The notation $p^{J\neq}$, $q^{J\neq}$, and $C^{J\neq}$ means that the two
  operations $\mbox{}^J$ and $\mbox{}^{\neq}$ have been applied successively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058506+00:00","domain":"probability theory","id":"claim_6e8b41d59c42b020828d82e79be82938e180193f55e1ede30776958a88237e1e","kind":"lemma","schema_version":1,"statement":"[Lemma 43 (Explicit balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ has the expansion
\begin{equation}

    \xi(a)=\sum_{p\geq1}\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}a_{s_1}\cdots a_{s_p},\qquad a\in\R^\sS,
\end{equation}
where the coefficients are nonnegative and satisfy the standing summability assumptions. For each $p\geq1$, define the symmetrized coefficients
\begin{equation}

    \widehat\Delta^2_{s_1,\ldots,s_p}:=\frac1{p!}\sum_{\pi\in\mathfrak S_p}\Delta^2_{s_{\pi(1)},\ldots,s_{\pi(p)}}.
\end{equation}
Suppose that
\begin{align}
    \begin{cases}
        \widehat\Delta_t^2\quad\text{does not depend on }t\in\sS,
        \\
        \sum_{s_2,\ldots,s_p\in\sS}\widehat\Delta^2_{t,s_2,\ldots,s_p}\lambda_{s_2}\cdots\lambda_{s_p}\quad\text{does not depend on $t\in\sS$ for every $p\geq2$.}
    \end{cases}
\end{align}
Define
\begin{equation}

    \beta_p^2:=\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}\quad\text{for $p\geq1$},\quad\text{and}\quad \xi_\star(r):=\sum_{p\geq1}\beta_p^2r^p=\xi(r\lambda)\quad \text{for $r\in\R_+$}.
\end{equation}
Then $\xi$ is balanced with respect to $\lambda$ in the sense of Definition~\ref{d.balanced_comparison_structure}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.853417+00:00","domain":"probability theory","id":"claim_6e8c56532a6f18725825ca00737e3fa3df3cae91014b27ce264c99e8bc22691e","kind":"lemma","schema_version":1,"statement":"[Lemma thm:upper_bound of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $0\leq \zeta <\xi\le 1$ and recall (equation eq:Al of the paper). Then, for all $\hat \beta \in [0,z_a)$:
\begin{equation}

\limsup_{\delta\to 0}\, \limsup_{N\to\infty}\sup_{x_0\in [N^{\zeta - \delta},N^{\zeta+\delta}]\cap \mathbb{Z}^2_{even}} \Phi_{N^\xi}(x_0)\leq \frac{\tilde J_{\alpha}\Big( \hat{\beta}\zeta^{\frac{a+2}{2}}\Big)}{\tilde J_{\alpha}\Big( \hat{\beta}\xi^{\frac{a+2}{2}}\Big)}.
\end{equation}
In particular,
\begin{equation}
   \sup_{N\geq 1} \sup_{x_0\in\mathbb{Z}^2} \,\Phi_{N}(x_0) <\infty\,.
\end{equation}","status":"unverified"}

