{"assumptions":[],"created_at":"2026-10-27T12:43:43.315612+00:00","domain":"probability theory","id":"claim_73ecfebe0e7869eb755974a357303f08570127c0475adea2712ec6c1ee4b2274","kind":"lemma","schema_version":1,"statement":"[Lemma lem: bulk gamma convergence of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $f\in C^\infty(M)$ and $\Xi^\partial_\infty \in \boldsymbol{\mathcal B}$.
\begin{enumerate}
\item[(i)] (Fatou) For every $\mu \in \overline{\mathcal X}$, for every sequence $\mu_n \rightarrow \mu$ in $\overline{\mathcal {X}}$, every sequence $(T_n) \rightarrow \infty$, and every sequence $\Xi^\partial_{T_n} \rightarrow \Xi^\partial_\infty $ in $\boldsymbol{\mathcal B}$,
\begin{equation}
\tilde{\mathbb F}^{f;\Xi^\partial_\infty}_\infty(\mu) \leq \liminf_{n\rightarrow \infty} \tilde {\mathbb F}^{f;\Xi^\partial_{T_n}}_{T_n}(\mu_n). 
\end{equation}
\item[(ii)] (Recovery sequence) For every $\mu \in \overline{ \mathcal X}$, for every sequence $(T_n) \rightarrow \infty$, and every sequence $\Xi^\partial_{T_n} \rightarrow \Xi^\partial_\infty$ in $\boldsymbol{\mathcal B}$, there exists a sequence $\mu_n \rightarrow \mu$ in $\overline {\mathcal X}$ such that
\begin{equation}
	\tilde{\mathbb F}^{f;\Xi^\partial_\infty}_\infty( \mu) \geq \limsup_{n\rightarrow \infty} \tilde {\mathbb F}^{f;\Xi^\partial_{T_n}}_{T_n}(\mu_n).
\end{equation} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.304657+00:00","domain":"probability theory","id":"claim_73ef9f12ae14b95c7437240964eb54d9ccc276e3bf03d44c5371326071c234d7","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2607.27082, '2607.27082'] Let \(X=(X_t)_{t\ge0}\) be either
