			+\mathbb{E}^{\mathcal{F}_\tau}\left[\int_{\tau}^{\sigma}e^{\beta A_s}\left\{\bar{U}_{s-}^{-}dK^{-}_s+\bar{U}_{s-}^{+}dK^{\prime,-}_s \right\}\right] \Biggr\}.
		\end{split}
