{"assumptions":[],"created_at":"2026-10-28T00:45:32.095076+00:00","domain":"probability theory","id":"claim_77eff5ff471ccd7df458afb0b247cfcc61330d1a67f5e64df333bcbb6b586fa6","kind":"concept","schema_version":1,"statement":"[Theorem thm-bhm of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] [BHM11]
\begin{enumerate}
