{"assumptions":[],"created_at":"2026-10-26T20:48:17.129415+00:00","domain":"probability theory","id":"claim_78004321b94696323b67906e8ccbebf63e4744253b9d93c91d5987e5fe426b59","kind":"concept","schema_version":1,"statement":"[Lem 50 of arXiv:2605.27974, 'Discrete approximation of semi-Dirichlet forms with non-symmetric perturbations of resista'] For any $\alpha > \lambda$ and $f \in C(X)$, we have the following: 
\begin{equation}
\limtoinfty{n}\norm{
\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}
-(\tilde{G}_{\alpha}f)\lvert_{V_{n}}
}_{\infty}=0.
\end{equation}
\begin{proof}
For the sake of simplicity, let $\mathscr{H}_{n}$ (resp.\ $\mathscr{H}$) denote $L^2(V_{n},\mu_{n})$ (resp.\ $L^2(X,\mu)$). 
For any $n \in \N$, by Proposition~\ref{prp5}, we have 
\begin{align}
\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
\mathcal{E}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
(1-s)^{-1}\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]).
\end{align}
Thus we obtain $\supover{n}\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]) < \infty$
since the following holds:
\begin{align}
\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
&=([f\lvert_{V_{n}}],{G}^{n}_{\alpha}[f\lvert_{V_{n}}])_{\mathscr{H}_{n}}
+(\lambda+1-\alpha)\norm{{G}^{n}_{\alpha}[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\norm{{G}^{n}_{\alpha}}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}}
+\abs{\lambda+1-\alpha}
\norm{{G}^{n}_{\alpha}}^{2}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\left\{(\alpha-\lambda)^{-1}+\abs{\lambda+1-\alpha}(\alpha-\lambda)^{-2}\right\}
\norm{f}^{2}_{\infty} < \infty.
\end{align}
On the other hand, since $[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ strongly K-S converges 
to $[f] \in \mathscr{H}$ and ${G}^{n}_{\alpha}$ strongly K-S converges to ${G}_{\alpha}$ 
by Proposition~\ref{main1}, ${G}^{n}_{\alpha}[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ 
strongly K-S converges to ${G}_{\alpha}[f] \in \mathscr{H}$. Therefore, we obtain the conclusion 
from Corollary~\ref{cor2} and Proposition~\ref{cptop}, noticing that 
$[\tilde{G}_{\alpha}f]=G_{\alpha}[f]$ 
(resp.\ $[\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}]=G_{\alpha}^{n}[f\lvert_{V_{n}}]$)
holds by Proposition~\ref{resolvdouitu}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:58:40.871851+00:00","domain":"probability theory","id":"claim_78035cd90d32dc5e2eb7e42282b1ba1a4352765bca254c871c2fa9c468e40aa2","kind":"lemma","schema_version":1,"statement":"[Lemma lem:clconvhull of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] Let $\psi : \mathbb{R}^d \to \mathbb{R} \cup \{\infty\}$ be a closed convex function and let $D \subset \mathbb{R}^d$ be such that $D \cap \operatorname{dom} \psi \ne \varnothing$. Define the function $\phi$ by $\phi = \operatorname{cl}(\operatorname{conv} g)$, where $g(x) = \psi(x)$ if $x \in D$ and $g(x) = \infty$ if $x \in \mathbb{R}^d \setminus D$. Then $\phi$ is a closed convex function with the following properties:
	\begin{enumerate}[label=(\alph*)]
		\item $\phi \geqslant \psi$;
		\item $\phi(x) = \psi(x)$ for $x \in D$;
		\item $\partial \phi(x) = \{ v \in \mathbb{R}^d : \forall z \in D, \, \psi(z) \geqslant \psi(x) + \langle{z-x,v}\rangle \} \supset \partial \psi(x)$ for $x \in  D$;
		\item $\operatorname{dom} \nabla \phi \subset \operatorname{dom} \partial \psi$;
		\item $D \cap \operatorname{dom} \nabla \phi \subset \operatorname{dom} \nabla \psi$ and $\nabla \phi(x) = \nabla \psi(x)$ for all $x \in D \cap \operatorname{dom} \nabla \phi$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.673251+00:00","domain":"probability theory","id":"claim_780474c7afe9489efe9cd72c7e3a0d59c74b1ec70b80700cad8aecb5bacce1e7","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Sharp Poincar\'e interpolation) of arXiv:2607.10769, '\fontsize{14}{17}\selectfont\bfseries Sharp Poincar\'e interpolation along Wasserstein geo'] For every $t\in[0,1]$, we have
