{"assumptions":[],"created_at":"2026-10-27T19:48:47.297956+00:00","domain":"probability theory","id":"claim_78840322c3e11d28af695c27f5b3e913ace15e31eaef6ed85d395c9a4842d48d","kind":"lemma","schema_version":1,"statement":"[Lemma 2DHD-lemma6.3 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Assume that the hypotheses of Theorem (2DHD-the3.3-0 of the paper) and condition (equation LSWs6.3 of the paper) hold. There exists a $\varepsilon_0=\sqrt{\frac{\mu\lambda_1}{12L_g+2\mathbf{c}_4L_g+8\mathbf{c}_4\widetilde{L}_g}}>0$ such that for all $\tau \in \mathbb{R}$, $t>1$ and $\varepsilon_1, \varepsilon_2 \in (0,\varepsilon_0]$, the solution $ u$ of system ((2DHD-1.1 of the paper)) satisfies
\begin{align}
	\begin{split}
		&~~\int_{\tau-1}^{\tau}\mathbb{ E}\left[\|u(s,\tau-t,u_{\tau-t})\|_{V}^2\right]ds\\
		&\leq \rho_2 e^{-\widetilde{\kappa} t}\mathbb{ E}\left[\|u_{\tau-t}\|_{H}^2\right]+\rho_2\left(\int_{-\infty}^{\tau} e^{-\widetilde{\kappa} (\tau-s)}\|f(s)\|_{H}^{4}ds\right)^{1/2}+\rho_2,
	\end{split}
\end{align}
and
\begin{align}
	&~\mathbb{ E}\left[\|u(\tau,\tau-t,u_{\tau-t})\|_{H}^4\right]+\int_{\tau-t}^{\tau}e^{-\widetilde{\kappa} (\tau-s)}\mathbb{ E}\left[\|u(s,\tau-t,u_{\tau-t})\|_{H}^2\|u(s,\tau-t,u_{\tau-t})\|_{V}^2\right]ds\notag\\
	&\leq \rho_3 e^{-\widetilde{\kappa} t}\mathbb{ E}\left[\|u_{\tau-t}\|_{H}^4\right]+\rho_3\int_{-\infty}^{\tau}e^{-\widetilde{\kappa} (\tau-s)} \|f(s)\|_{H}^{4} ds+\rho_3,
\end{align}
where $u_{\tau-t}\in L^{4}(\Omega,\mathscr{F}_{\tau-t};H)$, $\rho_2, \rho_3>0$ are the positive numbers independent of $\varepsilon_1, \varepsilon_2$, $\tau$, $t$ and $u_{\tau-t}$, and $\widetilde{\kappa}$ is the same number as in (equation LSWs6.3 of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.623584+00:00","domain":"probability theory","id":"claim_7885d2204095d9403460c17299c0e68d1d58083107e9356808cb4d4c24be9385","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ergodic theorem for some function of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $(\Omega,\mathcal{H},U_f,\hat{\mathbb{E}})$ be a regular sublinear expectation system, where $U_f$ is the linear operator induced by a measurable transform $f:\Omega\to\Omega$. Then the following two statements are equivalent:
		\begin{enumerate}[(i)]
			\item $\hat{\mathbb{E}}$ is ergodic;
			\item  for any  $X\in \mathcal{H}$ with
			$\overline{X},\underline{X}\in\mathcal{H},$ there exists a constant $c_X\in\mathbb{R}$ such that 
			\[\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}U_f^iX=c_X,\text{ }\hat{\mathbb{E}}\text{-q.s.}\]
		\end{enumerate}
		Moreover, if one of two equivalent statements above holds, then for any invariant probability $P\in\mathcal{P}$ and for any  $X\in \mathcal{H}$ with
			$\overline{X},\underline{X}\in\mathcal{H},$
		\[\int XdP=c_X.\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:11:57.321113+00:00","domain":"probability theory","id":"claim_788698dc43a449fd16cbe03ab0fbe3c240f99fb8d86044cd5a0e18ce95c50dd6","kind":"concept","schema_version":1,"statement":"[Theorem 11 of arXiv:2607.23526, 'Equivalence of Canonical and Microcanonical Ensembles for Euclidean Lattices'] Let $\lambda\in\mathcal{D}$. Assume that $\langle(F_1(x),\cdots,F_r(x)):x\in\Lambda\rangle_{\Z}=\Z^r$. For $N\geq1$, suppose there are $\lambda_N\in\mathcal{D}$ such that $\lambda_N\to\lambda$, $N\to+\infty$. Let $n_N=(n_{N,1},\cdots,n_{N,r})\in\Z^r$ be reachable such that
