{"assumptions":[],"created_at":"2026-10-27T18:44:24.685214+00:00","domain":"probability theory","id":"claim_78b1f2949a3879b986b26f351f455158d5fd277e26fbce20e77ae81669c19c14","kind":"definition","schema_version":1,"statement":"[Definition def:inhomo of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] An inhomogeneous  random matrix and its  deformation via  the entrywise product  “\(\circ\)”  are defined as
\begin{equation} 
H_N = \Sigma_N \circ W_N,
\end{equation}
and
\begin{equation}
X_N = H_N + A_N,
\end{equation}
where  the  three $N\times N$ matrices $W_N$, $\Sigma_N$ and $A_N$ satisfy the following conditions.

\begin{enumerate}[leftmargin=*,label=(A\arabic*)]
\item  \textbf{(Wigner matrix)}
The entries $\{W_{ij}\}_{1\leq i\le j\leq N}$ of $W_N$ are independent and  symmetrically distributed,  satisfying    the moment assumptions
\begin{equation}
\begin{cases}
\mathbb{E}[W_{ii}^2]=2,\;\mathbb{E}[W_{ij}^2]=1, & \text{real case},\\
\mathbb{E}[W_{ii}^2]=1,\;\mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex case},
\end{cases}
\end{equation}
and  for all $k\ge2$
\begin{equation}
\mathbb{E}\bigl[|W_{ij}\bigr|^{2k}] \;\le\; \theta^{\,k-1}(2k-1)!!.
\end{equation}
Here,  $\theta\ge 1$ is a  constant, which may depend on $N$ if required.

\item  \textbf{(Markov variance profile)}
The variance profile  $\Sigma_N=(\sigma_{ij})_{i,j=1}^N$ is a symmetric matrix with   nonnegative entries such that
$P_N:=(\sigma_{ij}^2)_{i,j=1}^N$ is a symmetric Markov transition matrix.

\item  \textbf{(Finite-rank deformation)}
The perturbation $A_N$ is symmetric (respectively, Hermitian) with  rank $r$, and admits the spectral decomposition
\begin{equation}
A_N = Q\,\Lambda\,Q^*, \qquad \Lambda = \mathrm{diag}(a_1,\dots,a_r,0,\dots,0),
\end{equation}
for    some  orthogonal  (respectively, unitary) matrix $Q$.
\end{enumerate}

In particular, when $W_N$ is a GOE/GUE matrix, $H_N$ is referred to as an IRM Gaussian matrix.
Similarly, a second IRM matrix is obtained by replacing the profile matrix $\Sigma$ solely with $\widetilde{\Sigma}=(\tilde{\sigma}_{ij})_{i,j=1}^N$. This substitution defines the modified quantities $\widetilde{P}_N=(\tilde{\sigma}_{ij}^2)_{i,j=1}^N$, $\widetilde{H}_N=\widetilde{\Sigma}_N \circ W_N$, and consequently $\widetilde{X}_N = \widetilde{H}_N + A_N$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.059925+00:00","domain":"probability theory","id":"claim_78b7ee33642510d4eea26350ada0ba143c327f06e1d43d65425b8ed1e3b280dd","kind":"lemma","schema_version":1,"statement":"[Lem technical_series of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] For any $\kappa \in (0,1)$ and $a_1,a_2,a_3,a_4>0$, there exists $C,c>0$ such that, for any $u \geq 1$ and $v \geq 0$,
