{"assumptions":[],"created_at":"2026-10-26T19:32:58.355855+00:00","domain":"probability theory","id":"claim_7a0db5bf05ba28bb18d7929f3ec76844c7eff562ff0e82b140013dbef10d887c","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] (Gonz\'alez-Navarrete \& Lambert, 2019 \cite{GL2})
Consider the random-trend diffusion model. If $0 \le a+b \le 1$ and $b\le a$ we get

\begin{equation}

\lim_{n \to \infty}\left(\frac{N_n}{N_n+M_n},\frac{M_n}{N_n+M_n}\right) = \left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right)  \ \ \mbox{a.s.},
\end{equation}
where $\theta=b(\alpha-\beta)$. In addition,
\begin{itemize}
\item[(i)]  If $\theta <  \frac{1}{2}$ then, for $n \to \infty$, in $D[0, \infty)$

\begin{equation}

\frac{1}{\sqrt{n}}\left[(N_{\floor*{tn}},M_{\floor*{tn}}) - tn\left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right) \right] \xrightarrow{d} W_t,
\end{equation}
where $W_t$ is a continuous bivariate Gaussian process with $W_0=(0,0)$, $\E(W_t)=(0,0)$ and, for $0 < s \le t$,

\begin{equation*}
\E(W_s W_t^T) = s\left(\frac{t}{s}\right)^{\theta} \dfrac{a(1-a-\theta)}{(1-\theta)^2(1-2\theta)} \left( 
\begin{array}{cc}
1
& 
-1
\\
-1
& 
1
\end{array}
\right) \ .
\end{equation*}

\item[(ii)]  If $\theta =  \frac{1}{2}$ then, for $n \to \infty$, in $D[0, \infty)$

\begin{equation}

\frac{1}{\sqrt{n^t\log(n)}}\left[(N_{\floor*{n^t}},M_{\floor*{n^t}}) - n^t\left(2a, 1-2a\right) \right] \xrightarrow{d} W_t,
\end{equation}
where $W_t$ is a continuous bivariate Gaussian process with $W_0=(0,0)$, $\E(W_t)=(0,0)$ and, \break for $0 < s \le t$,

\begin{equation*}
\E(W_s W_t^T) = 2sa(1-2a)\left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right) \ .
\end{equation*}

\item[(iii)]
Suppose that $ \frac{1}{2}< \theta < 1$. Then we have tightness for the sequence of two-dimensional random variables $\{V_n\}_{n\geq2}$ given by $
V_n := \frac{1}{n^{b(\alpha - \beta)}}\left[{(N_n, M_n) - n\left(\frac{a}{1-\theta},1-\frac{a}{1-\theta}\right)}\right]$. Furthermore, there exists {a} random vector $W = ({W_1}, \ {W_2})$ such that, as $n$ diverges
\begin{equation}

V_n  \longrightarrow W \ \ \  \mbox{a.s.}
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:25:39.087098+00:00","domain":"probability theory","id":"claim_7a0fb27d0399a56882a526c2f3829c8e36f3216b3877ca5b080d57e0986cf1be","kind":"concept","schema_version":1,"statement":"[Theorem thm:back_BESQ of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Let $\mathcal W^*$ be the image of $\mathcal W$ under $(a,r)\mapsto(a,-r)$.
\vspace{-0.5em}
\begin{enumerate}[label=(\roman*)]
    \item For each $(a,r)\in {\mathbb H}$, $(\mathcal S^*_{-r,-x}(a),\, x\ge r)$ is the almost sure unique strong solution to
    \begin{align*}
        \mathcal S^*_{-r,-x}(a)=a-2\int_r^x \mathcal W^*([0,\mathcal S^*_{-r,-u}(a)], \ensuremath{\mathrm{d}} u) + (2-\delta)(x-r), \quad x\ge r.
    \end{align*}
    Let $\mathscr{S}^*_{r,x}(a):=\mathcal S^*_{-r,-x}(a)$ for $x\ge r$. Then ${\mathscr S}^*$ is a general ${\rm BESQ}^{2-\delta}$ flow driven by $-\mathcal W^*$. Moreover, ${\mathscr S}^*$ is killed if $\mathcal S$ is not killed, and it is not killed if $\mathcal S$ is killed. 

    \vspace{-0.5em}
    \item For each $(a,r)\in (0,1)\times {\mathbb R}$, $(\mathcal Y^*_{-r,-x}(a),\, x\ge r)$ is the almost sure unique strong solution to
    \begin{align*}
    \mathcal Y^*_{-r,-x}(a)= a 
    &- 2 \int_r^x\!\! \int_0^1 
    \bigl(\mathbbm{1}_{\{s \le \mathcal Y^*_{-r,-u}(a)\}} 
          - \mathcal Y^*_{-r,-u}(a)\bigr)
    \mathcal W^*(\ensuremath{\mathrm{d}} s, \ensuremath{\mathrm{d}} u) \nonumber\\
    &+ \int_r^x 
    \Bigl[(2-\delta)\bigl(1-\mathcal Y^*_{-r,-u}(a)\bigr)
          - (2-\delta')\,\mathcal Y^*_{-r,-u}(a)\Bigr]
    \ensuremath{\mathrm{d}} u, \quad x\ge r.
    \end{align*}
    Let $\mathscr{Y}^*_{r,x}(a):=\mathcal Y^*_{-r,-x}(a)$ for $x\ge r$. Then ${\mathscr Y}^*$ is a general ${\rm Jacobi}(2-\delta,2-\delta')$ flow driven by $-\mathcal W^*$. Moreover, $\mathcal Y^*$ is killed at a boundary $0$ or $1$ if and only if $\mathcal Y$ is not. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.745588+00:00","domain":"probability theory","id":"claim_7a10e5e12fa859857d584aefa273a12a7b099b4986ef3953565e236c39333194","kind":"definition","schema_version":1,"statement":"[Defn DefAvoidingBridges of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $[a,b]\subset \mathbb{R}_+$, $k\in \mathbb{N}$ and $\mathbf{x}=(x_i)_{i=1}^k$, $\mathbf{y}=(y_i)_{i=1}^k\in \mathbf{W}_{k}^\circ$. Let $u, l \in \mathrm{C}([a,b])$ be such that: $u(t)>l(t)$ for all $t\in [a,b]$ and $u(a)>x_1, u(b)>y_1, l(a)<x_k, l(b)<y_k$. We define $\mathbf{P}_{\mathrm{avoid}}^{a,b;\mathbf{x},\mathbf{y};u,l}$ to be the law of the process $(\mathsf{A}(t;i))_{i\in \llbracket 1, k \rrbracket,t\in [a,b]}$ distributed according to $\mathbf{P}^{a,b;\mathbf{x},\mathbf{y}}$ and conditioned on the non-zero probability event
\begin{equation*}
\left\{u(r)>\mathsf{A}(r;1)>\mathsf{A}(r;2)>\cdots >\mathsf{A}(r;k)>l(r), \ \ \forall r\in [a,b]\right\}.
\end{equation*}
Write $\mathbf{E}_{\mathrm{avoid}}^{a,b;\mathbf{x},\mathbf{y};u,l}$ for the corresponding expectation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:49:06.325895+00:00","domain":"probability theory","id":"claim_7a12e27ed73a45ad09402b3fbe367abf88752dbb7accc2acd2f6e2248517ec13","kind":"concept","schema_version":1,"statement":"[Theorem thm:inftrace of arXiv:2601.10624, 'Source localisation in simple random walks'] For each $d \geqslant 5$, we have $\inf_{v \in \mathbb{Z}^d} \mathbb{P}_v(\Gamma(G_\infty) = v) > 0$. Moreover, we have
