\qquad h=(h_1,\ldots,h_d)\in\N^d.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:59:45.503167+00:00","domain":"probability theory","id":"claim_7b076daea1851a41459c6e032d147a372de9d95c7cfb5cfda08c851bb8b09672","kind":"concept","schema_version":1,"statement":"[Proposition u1pn of arXiv:2411.16647, 'The stochastic evolution of an infinite population with logistic-type interaction'] Assume that: (a) for each $t>0$, the family $\{\mu^\sigma_t: \sigma \in (0,1]\}\subset \mathcal{P}(\Gamma_*)$ is weakly relatively compact; (b) for each $T>0$, there exists $C(T)>0$ such that for each triple $(t_1, t_2 , t_3)$ satisfying $t_3\leq T$ the following holds
 \begin{equation}

