{"assumptions":[],"created_at":"2026-10-27T22:11:11.712633+00:00","domain":"probability theory","id":"claim_7b1f4cc4995b53197298f72a7f28a49b8ba8adbc5ea8fa35e6f33f33b6f796d6","kind":"lemma","schema_version":1,"statement":"[Lemma lem:finite-part-remainder-trace of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Fix $V_m$ and the atlas radius $\ell_{\mathrm{vtx}}$, so $\partial\Omega\cap B_{\ell_{\mathrm{vtx}}}(V_m)$ consists only of the two incident ray segments $x=V_m+\sidedistat{m}{i}\tphys{m}{i}$, $\sidedistat{m}{i}=\abs{x-V_m}\in(0,\ell_{\mathrm{vtx}})$, $i=1,2$. Let $\mathcal R_{m,i}\in C^1((0,\ell_{\mathrm{vtx}}])$ be the restriction of a residual boundary trace to ray $i$, and suppose for some $\sigma>0$, $B\in\mathbb N_0$,
\begin{align}
 M_{\rm tr}
 &:=
 \max_{i=1,2}\sup_{0<\sidedistat{m}{i}<\ell_{\mathrm{vtx}}}
 \Big(
 \abs{\mathcal R_{m,i}(\sidedistat{m}{i})}
 +\sidedistat{m}{i}
  \babs{\partial_{\sidedistat{m}{i}}
       \mathcal R_{m,i}(\sidedistat{m}{i})}
 \Big)
 \sidedistat{m}{i}^{-\sigma}
 (1+\abs{\ln \sidedistat{m}{i}})^{-B}
 <\infty.

\end{align}
Then $\mathcal R_{m,i}(\sidedistat{m}{i})\to0$ as $\sidedistat{m}{i}\to0$, $i=1,2$, so the piecewise trace $\mathcal R(V_m+\sidedistat{m}{i}\tphys{m}{i}):=\mathcal R_{m,i}(\sidedistat{m}{i})$, $\mathcal R(V_m):=0$, belongs locally to $H^{\frac{1}{2}}$ across the vertex, with $\nm{\mathcal R}_{H^{\frac{1}{2}}(\partial\Omega\cap B_{\ell_{\mathrm{vtx}}}(V_m))}\le C_{\sigma,B,\omega_m,\ell_{\mathrm{vtx}}}M_{\rm tr}$. If this holds at every vertex and the residual trace is $H^1$ on the parts of the open sides away from the vertices, then $\mathcal R\in H^{\frac{1}{2}}(\partial\Omega)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.047353+00:00","domain":"probability theory","id":"claim_7b22014a378ac8e6e235aeabe76f9f152f26c0cff3cb52c9505ea19b6563ded3","kind":"theorem","schema_version":1,"statement":"[Theorem 20 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let $\mathcal{B} \subseteq \mathcal{F}$ and $\mathcal P_{M} : = (B_m)_{m=1}^M$ be an $M$-partition of $N_n$, and let $\mathcal C_{r} : = (C_{1},...,C_{K_r})$  be a proper $r$-coloring of $(B_m)_{m=1}^M$.	Then there exists an extension of the probability space and, on that extension,
	a collection $(Z_i^\ast)_{i\in N_n}$ with the following properties:

	\begin{enumerate}
		\item For every $m\in [M] $, $Z_{B_m}^\ast \stackrel{d}{=} Z_{B_m}$ with  $Z_{B_m}^\ast := (Z_i^\ast)_{i\in B_m}$ and  $Z_{B_m} := (Z_i)_{i\in B_m}$.

		\item For every $k\in [K_r]$, the family $\bigl(Z_{B_m}^\ast\bigr)_{m\in C_k}$	is mutually independent.

		\item For every $k\in [K_r]$ and every $m\in C_k$,
		\begin{align}
			\mathbb E_{\Pr}\!\left[
			d_{\mathcal{B},|B_m|}\!\left(Z_{B_m}^\ast,Z_{B_m}\right)
			\right]	 =		&	\inf \Big\{
			\mathbb E\big[	d_{\mathcal{B},|B_m|}(Z_{B_{m}},X')\big]
			:\;
			X' \stackrel{d}{=} Z_{B_{m}},\;
			X' \indep	\mathcal{F}^{m-1}_{C_{k}}  
			\Big\} \\
			= & 	\tau_{d_{\mathcal B,|B_{m}|}}
			\left(
			\mathcal{F}^{m-1}_{C_{k}}, 
			Z_{B_{m}}
			\right), 
		\end{align}
				\begin{align}
			\mathbb E_{\Pr}\!\left[
			d_{\mathcal{B},|B_m|}\!\left(Z_{B_m}^\ast,Z_{B_m}\right)
			\right]
			\le |B_{m}| \tau_{\mathcal{B},G_n}(r,|B_{m}|),
		\end{align}
		and 
		\begin{align}
		n^{-1} \sum_{k=1}^{K_{r}} \sum_{m \in C_{k}} \mathbb E_{\Pr} \left[ d_{ \mathcal{B},|B_{m}|}(Z^{\ast}_{B_{m}},Z_{B_{m}}) \right] =  \bar{\tau}_{ \mathcal B,G_{n}}(\mathcal P_{M}, \mathcal{C}_{r}). 
		\end{align}
	\end{enumerate}","status":"unverified"}

