For $n\geq1$, we use the boundary conditions
$N^{\mathrm{Wend}}_{n,0}=2^n$, $N^{\mathrm{Wend}}_{n,n} = 0$,  $N^{\mathrm{walk}}_{n,0}=2^n n!$,  $N^{\mathrm{walk}}_{n,n}=0$.
For $n\geq2$, we also set $N^{\mathrm{br}}_{n,0}=n!$,
$N^{\mathrm{br}}_{n,n-1}=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.451159+00:00","domain":"probability theory","id":"claim_7dd027473924d0b8ed1a71306a88fe8dc5eeede4d0d470b1d8629b5994744754","kind":"theorem","schema_version":1,"statement":"[Proposition prop:Q_path_expansion of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Define  a family of  polynomials $\mathcal{Q}_n(x)$ recursively by
\begin{equation} 
\mathcal{Q}_0(x) = 1, \quad
\mathcal{Q}_1(x) = x - 1, \quad
\mathcal{Q}_n(x) = (x - 1 - \alpha)\mathcal{Q}_{n-1}(x) - \alpha \mathcal{Q}_{n-2}(x) \quad (n \ge 2),
\end{equation}
with the convention that $\mathcal{Q}_n(x) = 0$ for $n < 0$. Then for $X = (H+A)(H+A)^*$ and  for each $n \ge 0$, we have
\begin{equation}
\mathcal{Q}_n(X)
= \sum_{k \ge 0} \sum_{\alpha \in \{2,3,A,A^*\}^k} \sum_{\substack{\ell_0 + \cdots + \ell_k = 2n}}
V_{\ell_0}\,\underline{\Phi_{\alpha_1} V_{\ell_1}} \cdots \underline{\Phi_{\alpha_k} V_{\ell_k}}.
\end{equation}
Here, each $\alpha_i$ denotes insertion of $\Phi_2$, $\Phi_3$, $\Phi_A$, or $\Phi_{A^*}$, and the indices satisfy $\ell_i \ge 0$ with $\sum \ell_i = 2n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.529593+00:00","domain":"probability theory","id":"claim_7dd08f182dfb8c0d9a3f1f73a33ee23546bdad0576f44b02c6e0af3e19990ca3","kind":"concept","schema_version":1,"statement":"[Corollary 17 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $(\mathcal{X}_y)_{y \geq 0}$ be the $\text{SBM}(4)$ defined in Theorem \ref{theorem sbm snake} and let $(\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ be the $\text{ooSBM}(4, c, \Tilde{c})$ (defined in Corollary \ref{corollary continuous modifications}) which is the continuous modification of the process $(\mathcal{Z}^{(\rm d)}_s, \mathcal{Z}^{(\rm a)}_s)_{s \geq 0}$ (defined in Theorem \ref{theorem ooSBM ffd convergence}). Note that both $(\mathcal{X}_y)_{y \geq 0}$ and $(\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ are constructed on the same probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. As above let $\mathcal{Y}_s = \mathcal{Y}^{(\rm d)}_s \cup \mathcal{Y}^{(\rm a)}_s$ for $s \geq 0$. Let $\delta > 0$. Then we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that
    \begin{equation}
        \overline{\bigcup_{y \geq \delta}\text{supp}(\mathcal{X}_y)} =  \overline{\bigcup_{i \in I} \{\hat{w}^i_t: f^i_t > \delta\}} \subseteq \overline{\bigcup_{i \in I} \{ \hat{w}^i_t: f^i_t > H^i_t(\delta)\}} = \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)}.
    \end{equation}
    Secondly we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that 
    \begin{equation*}
        \mathcal{R}(\mathcal{X}) \subseteq \mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)}).
    \end{equation*}
    \begin{proof}
        The first equality in \eqref{equation coupled domination} follows from the snake representation in Theorem \ref{theorem sbm snake} and the result in Proposition \ref{proposition closure of range of continuous process} means we can exclude the case where $f^i_t = \delta$. The second equality follows by Lemma \ref{lemma support sbm interval}. The subset relation follows by the fact that for $z \geq 0$, $i \in I$, $r \in [0,\sigma(f^i)]$ we have $H^i_r(z) \leq z$. 
        \par
        The second result follows from the fact that the range can be written as a countable union, e.g.
        \newline
        $\mathcal{R}(\mathcal{X}) = \bigcup_{\delta>0, \delta \in \mathbb{Q}}\overline{\bigcup_{y \geq \delta}\text{supp}(\mathcal{X}_y)}$ and similarly for $\mathcal{Y}$ and so we can apply the first result countably many times to obtain the second result here.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

