{"assumptions":[],"created_at":"2026-10-27T06:29:21.947175+00:00","domain":"probability theory","id":"claim_7dedbdedc2919ea6994ee4e16f6197823f268a1f4e3e177e8db44805ac5a5de4","kind":"theorem","schema_version":1,"statement":"[Prop 18 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Choosing 
\begin{align*}
     &\gamma_T:\R^3\times\R^3\to\R^3,\quad \gamma_T(z)(p)=&&\sum_{i,j,k,l\in\{1,2,3\}}(576\sum_{q_1,q_2\in\Z^3\setminus\{0\}}\\& &&(q_1^i q_2^j)\int_0^T\int_0^T\frac{\sigma^2_{r_1}(q_1)}{(|q_1|^2+|q_1|^4) } \frac{\sigma^2_{r_2}(q_2)}{(|q_2|^2+|q_2|^4) }\\
     & &&(-q^k_1-q^k_2)(z(q_1\cdot q_2)+q_1(z\cdot q_2)+q_2(z\cdot q_1))\\
     & &&\int_{r_1\vee r_2}\frac{\sigma^2_{u}(-q_1-q_2)}{(|-q_1-q_2|^2+|-q_1-q_2|^4) }\ du\ dr_1\ dr_2)p^l,\\
     \end{align*}\vspace{-1.5cm}
     \begin{align*}
     \delta_T=&\mathbb{E}\bigg[-32\int_0^T\int(\nabla\cdot J_t  [\![\nabla Y_t^3]\!])^3\ dt+96\int  [\![\nabla Y_T^2]\!](\nabla\int_0^T J_t(\nabla\cdot J_t  [\![\nabla Y_t^3]\!]) ds)^2 \\
     &-8\gamma_T(\nabla Y_T)(\nabla\int_0^T J_t(\nabla\cdot J_t  [\![\nabla Y_t^3]\!])ds)+256\nabla Y_T\cdot (\nabla\int_0^T J_t(\nabla\cdot J_t  [\![\nabla Y_t^3]\!])ds)^3 \bigg]
\end{align*}
yields
\begin{align}
   F_T(u)
    =&\mathbb{E}\bigg[f(Y_T+Z_T)+ 4\int [\![\nabla Y_T^3]\!]\cdot\nabla Z_T(u)+4 \int \nabla Y_T\cdot(\nabla Z_T(u))^3\nonumber\\&+\sum_{i,j,k,l\in\{1,2,3\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})[\![\partial_iY_T\partial_j Y_T]\!]\partial_k Z_T(u) \partial_l Z_T\nonumber\\&-2 \int \gamma_T( \nabla Y_T)(\nabla Z_T(u))+\int  \gamma_T(\nabla Z_T(u))(\nabla Z_T(u))+\delta_T\bigg]\nonumber\\&+\mathbb{E}\bigg[ \int  (\nabla Z_T(u))^4+\frac{1}{2}\Vert u\Vert^2_\mathcal{H}\bigg]\nonumber\\
    =&\mathbb{E}\left[ f(Y_T+Z_T(u))+\Phi_T(u)+\Vert\nabla Z_T(u)\Vert_{L^4}^4+\frac{1}{2}\Vert l^T(u)\Vert_\mathcal{H}^2\right],
\end{align}
where
\begin{align}
\Phi_T(u)&\coloneq \sum_{i=1}^6\mathcal{Y}^{(i)}_T
\end{align}\vspace{-0.1pt}
    with
\begin{align*}
    \mathcal{Y}^{(1)}_T&\coloneq \frac{1}{2}\int_\Lambda (12\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})(-([\![\partial_iY_T\partial_j Y_T]\!]\succ\partial_k Z_T(w)) \partial_l Z_T(w)\\&-([\![\partial_iY_T\partial_j Y_T]\!]\circ\partial_k Z_T(w)) \partial_l Z_T(w)+([\![\partial_iY_T\partial_j Y_T]\!]\prec\partial_k Z_T(w))\partial_l Z_T(w))\\&+ 4([\![\partial_iY_T\partial_j Y_T]\!]\prec(\partial_k\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)) \partial_l Z_T(w)),\\
\mathcal{Y}^{(2)}_T&\coloneq \int_\Lambda 12\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})(([\![\partial_iY_T\partial_j Y_T]\!]\succ\partial_k (Z_T(u)-Z_T^b(u))) \partial_l Z_T(w)),\\
\mathcal{Y}^{(3)}_T&\coloneq \int_0^T \int_\Lambda 12\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})(([\![\partial_iY_t\partial_j Y_T]\!]\succ\partial_k Z_t^b(u)) \partial_l Z_t(w)),\\
\mathcal{Y}^{(4)}_T&\coloneq 4  \int_\Lambda  \nabla Y_T\cdot(\nabla Z_T(w))^3+4 \int_\Lambda  \nabla\ Y_T \cdot(4\nabla\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt) (\nabla Z_T(w))^2\\
&+ 8 \int_\Lambda ( \nabla\ Y_T \cdot\nabla Z_T(w))((4\nabla\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)\cdot \nabla Z_T(w))\\&+ 4 \int_\Lambda  (4\nabla\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)^2\nabla Y_T\cdot \nabla Z_T(w)\\
&+8 \int_\Lambda(  (4\nabla\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)\cdot\nabla Y_T)((4\nabla\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)\cdot \nabla Z_T(w)),\\
\mathcal{Y}^{(5)}_T&\coloneq - \int_\Lambda \gamma_T(\nabla Z_T^b(u))(\nabla Z_T(u)-\nabla Z_T^b(u))- \int_\Lambda \gamma_T(\nabla Z_T(u)-\nabla Z_T^b(u))(\nabla Z_T^b(u))\\&
- \int_\Lambda \gamma_T(\nabla Z_T(u)-\nabla Z_T^b(u))(\nabla Z_T(u)-\nabla Z_T^b(u))-\int_0^T \int_\Lambda\gamma_t(\nabla Z_t^b(u))(\nabla\dot{Z}_t^b(u))\ dt\\&-\int_0^T \int_\Lambda\gamma_t(\nabla \dot{Z}_t^b(u))(\nabla Z_t^b(u))\ dt,\\
\mathcal{Y}^{(6)}_T&\coloneq \int_\Lambda (48\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})([\![\partial_iY_T\partial_j Y_T]\!]\circ(\partial_k\int_0^TJ_t(\nabla\cdot J_t [\![\nabla Y_T^3]\!]) dt)) \part","status":"unverified"}

