            \left\| \mathfrak P^{-1}_n (\mathbf u_n)^\mu \right\|_{H^\theta_0} \leq C \left\| \mathfrak P^{-1}_n (\mathbf u_n^\mu) \right\|_{H^\theta_0}.
        \end{aligned}
    \]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.171981+00:00","domain":"probability theory","id":"claim_7f08eb6b30129238fced4ec1660d249644a94e19f91b9e985f2b7d2ed8cc8303","kind":"concept","schema_version":1,"statement":"[Prop Prop_UniversalZeroLocus_Eigen of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] The \defined{universal zero locus} of non-degenerate $\mathbb{Z}/2\mathbb{Z}$ eigenspinors
