{"assumptions":[],"created_at":"2026-10-26T19:48:27.277221+00:00","domain":"probability theory","id":"claim_8054ebf28fd4ce37bffa19ef05ba90f2ec234a03a009173c49d7bcd661793037","kind":"theorem","schema_version":1,"statement":"[Theorem 6 of arXiv:2604.24664, 'Absolute continuity of Rosenblatt measures'] Let $H \in (1/2, 1)$ and let $(B_t)_{t \in [0, T]}$ be a standard $\FctT$-Wiener process. Let $(B^{\frac{H}{2} + \frac12}_t)_{t\in [0,T]}$ be the FBM defined by \eqref{eq:fbm_representation} (with $\frac{H}{2} + \frac12$ in place of $H$) and let $(R^H_t)_{t\in [0,T]}$ be the Rosenblatt process defined by \eqref{eq:rosenblatt_representation}. Let also 
	\[
		\theta\in H^{\frac{H}{2},2}([0,T])
	\]
be given and define the process $(Z_t)_{t\in [0,T]}$ by
	\begin{multline*}
		Z_t = \exp \left(

			\vphantom{- \frac12 \frac{1}{c_{\frac{H}{2} + \frac{1}{2}}^2 \Gamma \left( \tfrac{H}{2} \right)^2} \int_0^t s^{H} \left[ I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \right]^2 \d{s}}
			- \frac{1}{c_{\frac{H}{2} + \frac{1}{2}} \Gamma \left( \tfrac{H}{2} \right)} \int_0^t s^{\frac{H}{2}} I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \d{B_s} \right.
		\\
		\left. - \frac12 \frac{1}{c_{\frac{H}{2} + \frac{1}{2}}^2 \Gamma \left( \tfrac{H}{2} \right)^2} \int_0^t s^{H} \left[ I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \right]^2 \d{s} \right).
	\end{multline*}
Then the measure $\tilde{\Pbb}$ defined by $\d{\tilde{\Pbb}} = Z_T \d{\Pbb}$ is a probability measure on $(\Omega,\Fcal)$ and the process $(\tilde{R}_t^H)_{t\in [0,T]}$ defined by
	\begin{equation}

		\tilde{R}^H_t = R_t^H + 2 d_H \int_0^t \theta_u \d{B^{\frac{H}{2} + \frac{1}{2}}_u} + d_H \int_0^t \theta^2_u \d{u}
	\end{equation}
is a Rosenblatt process with Hurst index $H$ with respect to $\tilde{\Pbb}$ that is adapted to $\FctT$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:11:44.405194+00:00","domain":"probability theory","id":"claim_8055bfde9aa64363718f51d253f906e0aebbc70c36c7c2af5fa6653e21fd60e5","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2609.03187, 'Duality for a Martingale Transport Problem with Moment Constraints'] For every $c\in\mathcal C$ we have
\begin{equation} 
V(c)\leq \inf_{\lambda\in\mathbb R^N}\left\{\lambda\cdot c-\int \Psi_\lambda^*(x)\,\mu(dx)\right\}.
\end{equation}
Assume, in addition, that $c \in \operatorname{int} (\mathcal{C})$. Then there is no duality gap:
\begin{equation}
V(c)= \inf_{\lambda\in\mathbb R^N}\left\{\lambda\cdot c-\int \Psi_\lambda^*(x)\,\mu(dx)\right\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.118183+00:00","domain":"probability theory","id":"claim_80585043f4ce92ef5921b582baa278b457fa52f4afdfa8e57c86836fbbea5bbb","kind":"lemma","schema_version":1,"statement":"[Lemma lem:corrector of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] For any $\phi\in\mathscr C_0$,
\begin{align}
\nrm{\mathscr{A}_m\phi}&\le\frac1{2\sqrt m}\,\nrm{\phi},\\
\nrm{\mathscr{L}_a\mathscr{A}_m\phi}&\le\nrm{\phi},\\
\nrm{\mathscr{A}_m\mathscr{L}_a(1-\Pi_v)\phi}&\le\sqrt{2+\frac{K}{2m}}\;\nrm{\phi}.
\end{align}
In particular, $\mathscr{A}_m$, $\mathscr{L}_a\mathscr{A}_m$ and $\mathscr{A}_m\mathscr{L}_a(1-\Pi_v)$ extend uniquely to bounded operators on $\Lmuz$ with the same bounds, and if $\varepsilon<\sqrt m$ then
\begin{equation}
\frac{1-\varepsilon/\sqrt m}{2}\,\nrm{\phi}^2\le\mathsf L_m(\phi)\le\frac{1+\varepsilon/\sqrt m}{2}\,\nrm{\phi}^2
\qquad\text{for any $\phi\in\Lmuz$}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.632154+00:00","domain":"probability theory","id":"claim_8059474a5855f2a9db2a3af5196e98847559f853703f6e39f6ac8180913fe0f3","kind":"definition","schema_version":1,"statement":"[Definition def:NL-MP of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $\mathcal P_0 \subseteq \mathcal P$. 
   A (\emph{time-homogeneous}) \emph{nonlinear Markov process} is a family $\{P^\zeta\}_{\zeta \in \mathcal P_0} \subseteq \mathcal P(\mathcal C)$ such that, setting $\mu^\zeta_t := P^\zeta_t \in \mathcal P$ for $(t,\zeta) \in [0,\infty) \times \mathcal P_0$,
    \begin{enumerate}[(i)]
        \item $\mu^\zeta_0 = \zeta$ for all $\zeta \in \mathcal P_0$, and $\mu^\zeta_t \in \mathcal P_0$ for all $(t,\zeta) \in (0,\infty)\times \mathcal P_0$;
        \item the (\emph{time-homogeneous}) \emph{nonlinear Markov property} holds, i.e.,
        \begin{equation*}
        P^\zeta(\pi_{t+s} \in A | \mathcal F_s) ( \cdot) = P^{\mu^\zeta_s,\pi_s(\cdot)}(\pi_t \in A)\quad P^\zeta\text{-a.s.},\quad \forall s,t \geq 0, \, \zeta \in \mathcal P_0
    \end{equation*}
    for every Borel set $A \subseteq \mathbb{R}^d$,
    where for $\zeta \in \mathcal P_0$, $\{P^{\zeta,y}\}_{y\in \mathbb{R}^d}$ is the disintegration family of $P^{\zeta}$ with respect to $\pi_0$, i.e., the $\zeta$-a.s.\ unique family $\{Q^y\}_{y\in \mathbb{R}^d}$ in $\mathcal P(\mathcal C)$ such that $y\mapsto Q^y(W)$ is measurable and $P^\zeta(W) = \int_{\mathbb{R}^d} Q^y(W) \,\mathrm d \zeta(y)$ for all $W \in \mathcal B(\mathcal C)$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.200260+00:00","domain":"probability theory","id":"claim_805d8327a5a5a662bdaa2bd15aa58f32934cea3a67a87865be3887ee2ed2b7ce","kind":"concept","schema_version":1,"statement":"[Lemma 1 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Assume \eqref{assump:alpha} and \eqref{assump:notapower}. 
