{"assumptions":[],"created_at":"2026-10-27T18:58:38.107518+00:00","domain":"probability theory","id":"claim_812e246202ea1068ed1e6a71fbaa76e3fe0da991915f9ecfe6081684c677a2c8","kind":"concept","schema_version":1,"statement":"[Proposition prop:properties-Phi-Pi of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] Under Assumption (assump:plasticity-function of the paper) on the plasticity function \(\Gamma\), there exists a unique continuous map \(\Phi: [0,T]\times \mathcal{C}^d_T \times \mathcal{C}^d_T \times \mathbb{R} \to \mathbb{R}\) such that for any \(\gamma_1,\gamma_2 \in \mathcal{C}^d_T\) and any \(w \in \mathbb{R}\), the function \(t\mapsto \Phi(t,\gamma_1,\gamma_2,w)\) is the unique solution to the initial value problem:
	\[
		\begin{aligned}
		&\frac{d}{dt}w(t) = \Gamma(\gamma_1(t),\gamma_2(t),w(t)), \quad t\in [0,T],\\
		&w(0) = w.
		\end{aligned}
	\]
	Furthermore, the flow map \(\Phi\) satisfies the following properties:
	\begin{enumerate}[label=(\roman*)]
		\item \textbf{(\(\Phi\) is non-anticipative):} There exists a family of functionals \((\Phi_t)_{t\in [0,T]}\), with \(\Phi_t: \mathcal{C}^d_t\times \mathcal{C}^d_t\times \mathbb{R} \to \mathbb{R}\), such that 
		\[
			\Phi(t,\gamma,\bar{\gamma},w) = \Phi_t(\gamma_{[0,t]},\bar{\gamma}_{[0,t]},w).
		\]
		\item \textbf{(\(\Phi\) is Lipschitz):}  
		\[
			\vert \Phi(t,\gamma_1,\bar{\gamma}_1,w_1) - \Phi(t,\gamma_2,\bar{\gamma}_2,w_2) \vert \leq L_{\Phi}(t) \left(\Vert \gamma_1-\gamma_2\Vert_{\ast,t} + \Vert \bar{\gamma}_1-\bar{\gamma}_2\Vert_{\ast,t} + \vert w_1-w_2\vert \right),
		\]
		with \(L_{\Phi}(t) = e^{L_{\Gamma}t}\left(1+tL_{\Gamma}\right)\).
		\item \textbf{(\(\Phi\) has linear growth in the weight variable):} 
		\begin{equation}
		\vert \Phi(t,\gamma,\bar{\gamma},w)\vert \leq B_{\Phi}(t)(1+ \vert w\vert), 
		\end{equation}
		with \(B_{\Phi}(t) = (1+B_{\Gamma}t)e^{L_{\Gamma}t}\).
	\end{enumerate}

	Let us denote the product of the flow map and the kernel \(K\) by \(\Pi: [0,T]\times \mathcal{C}_T^d\times \mathcal{C}_T^d\times \mathbb{R} \to \mathbb{R}^d\), defined as 
	\[
		(t,\gamma,\bar{\gamma},w) \mapsto \Phi(t,\gamma,\bar{\gamma},w)K(\gamma(t),\bar{\gamma}(t)).
	\] 
	If the kernel \(K\) satisfies Assumption (assump:interaction-kernel of the paper), then the map \(\Pi\) inherits the
	following properties:
	\begin{enumerate}[label=(\roman*), resume]
		\item \textbf{(\(\Pi\) is Lipschitz):}  
		\begin{equation} 
			\vert \Pi(t,\gamma_1,\bar{\gamma}_1,w_1) -\Pi(t,\gamma_2,\bar{\gamma}_2,w_2)\vert \leq L_{\Pi}(t)(1+\vert w_1\vert) \left( \Vert \gamma_1-\gamma_2 \Vert_{\ast,t}+\Vert \bar{\gamma}_1-\bar{\gamma}_2 \Vert_{\ast,t} +\vert w_1-w_2\vert\right), 
		\end{equation}
		with \(L_{\Pi}(t) = (B_K L_{\Phi}(t)+B_{\Phi}(t)L_K)\).
		\item \textbf{(\(\Pi\) has linear growth in the weight variable):}  
		\begin{equation} 
		\vert \Pi(t,\gamma,\bar{\gamma},w)\vert \leq B_{\Pi}(t)(1+ \vert w\vert), 
		\end{equation}
		with \(B_{\Pi}(t) = B_{\Phi}(t)B_K\).
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:25:35.764856+00:00","domain":"probability theory","id":"claim_8134b6c5bd55b00ff8f0baf0b47f12c6bfcaf684c51cca755f270879286b74e8","kind":"theorem","schema_version":1,"statement":"[Proposition uniform case convergences of arXiv:2603.09008, 'On the statistics of random-to-top shuffles'] Let $\pi$ be a uniformly random permutation of $[n]$. Let $F(\pi)$ be the number of fixed points, $d(\pi)$ be the number of descents, and $I(\pi)$ be the number of inversions. Then, we have
