{"assumptions":[],"created_at":"2026-10-27T17:11:02.358451+00:00","domain":"probability theory","id":"claim_81e06c584c4581bdacccfeb29a96777081ff3a218fccffcfa1ca90fe57171c8b","kind":"concept","schema_version":1,"statement":"[Cor one-environment-ergodicity of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] Suppose that $M$ is a matrix which is associated to a CRN in the sense of equation (equation eq:associated CRN of the paper). If there exists a vector $v\in\mathbb R_{>0}^d$ such that $vM\in\mathbb R_{<0}^d$, then the CRN converges exponentially fast.
\begin{proof}
    We can view this as a switched process in one environment with $M_1=M$ and switching matrix $Q=(0)$. So if we consider the process with matrix $\kappa Q$, then Theorem (thm:slow-switching-ergodicity of the paper) says that the process converges exponentially fast if $\kappa$ is small enough and Theorem (thm:fast-switching-ergodicity of the paper) says that the process converges exponentially fast if $\kappa$ is large enough. But $\kappa Q=Q$ in this case, so either theorem is enough to conclude the claimed result.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.443086+00:00","domain":"probability theory","id":"claim_81e36a1fd10d5f05d854b306ca38350cdd65bb2a451791ec3dc96c1709c883c8","kind":"definition","schema_version":1,"statement":"[Defn 4 (Kinetic solution) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u,\nu)$ is a kinetic solution of \eqref{eq:intro-reflected-model} with initial datum $u^0$ and obstacle $\psi$ if the following conditions hold.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item The process $u$ is predictable as an $L^1(\mathbb{T}^N)$-valued process.
  \item For any $p\geq1$, there exists $C_p\geq0$ such that
\begin{equation}
\E\Big(\underset{0\leq t\leq T}{{\rm{ess\sup}}}\ \Vert u(t)\Vert ^p_{L^p(\mathbb{T}^N)}\Big)\leq C_p,
\end{equation}
\item \textbf{Obstacle constraint.} For $\mathbb{P}\otimes\dd x\otimes\dd t$-a.e. $(\omega,x,t)$,
\begin{equation*}
u(x,t)\geq\psi(x,t),
\end{equation*}
and $\nu$ is a nonnegative predictable Radon measure on $\mathbb{T}^N\times[0,T)$ satisfying $\E\nu(\mathbb{T}^N\times[0,T))<\infty$.
\item \textbf{Weak initial trace condition.} The process $u$ almost surely satisfies
\begin{equation}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation}
\item There exists a kinetic measure $q$ such that $f:= \one_{u>\xi}$ satisfies, for all $\varphi\in C^1_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla \varphi (t)\rangle \dd t\\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)\dd\mu_{x,t}(\xi)\dd x\dd\beta_k(t) \\ \notag
&\quad -\frac{1}{2}\sum_{k\geq1}\int^T_0\int_{\mathbb{T}^N}\int_{\mathbb{R}}\partial_{\xi}\varphi (x,t,\xi)G^2(x,\xi)\dd\mu_{x,t}(\xi)\dd x\dd t\\
&\quad + q(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu(x,t), \quad\ a.s. ,\nonumber
\end{align}
 where $f^0:=\one_{u^0>\xi}$, $a(\xi)=A'(\xi)$ and  $\mu_{x,t}(\dd\xi)=\delta_{u(x,t)}(\dd\xi)$.
\end{enumerate}","status":"unverified"}

