{"assumptions":[],"created_at":"2026-10-27T14:18:13.247910+00:00","domain":"probability theory","id":"claim_826ad0ea38413a9b6cd7b6048a501f296a80998b8d1dc43e5ce9c36b348a4012","kind":"definition","schema_version":1,"statement":"[Definition eq-operators of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp We will introduce the following operators for functions {\small$\mathsf{A}:[0,\infty)\times\R\to\R$}.

\begin{enumerate}
\item Let us introduce notation that will capture the main error terms. Suppose {\small$\mathfrak{q}\in\mathscr{C}^{\infty}(\R^{\Z})$} is a local function so that {\small$\mathfrak{q}[\bphi]$} depends only on {\small$\bphi_{\w}$} for {\small$\w\in\{1,\ldots,\mathfrak{l}_{\mathfrak{q}}\}$} for some {\small$1\leq\mathfrak{l}_{\mathfrak{q}}\lesssim1$}. We define the following space-time average, in which {\small$\mathfrak{t}_{\mathbf{Av}}=N^{-2/3-10\delta_{\mathbf{S}}}$} and {\small$\mathfrak{n}_{\mathbf{Av}}=N^{1-3\delta_{\mathbf{S}}/2}$}:

\begin{align}
\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathfrak{t}_{\mathbf{Av}}^{-1}{\int_{0}^{\mathfrak{t}_{\mathbf{Av}}}}\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\Big(\mathfrak{q}[\tau_{\x+\j}\bphi_{\t-\r}]\cdot\mathbf{Z}^{N}_{\t-\r,\x+\j}(\mathbf{Z}^{N}_{\t,\x})^{-1}\Big)\d\r.
\end{align}

Note that {\small$\mathfrak{t}_{\mathbf{Av}}\ll1$} and {\small$\mathfrak{n}_{\mathrm{Av}}\ll N$}; thus, these scales are mesoscopic. {\color{black}We also note that the exact exponents of {\small$\approx-2/3$} and {\small$\approx1$} are not so meaningful; they are just sufficiently large to yield enough cancellations in (equation eq:mult-op-1 of the paper).} On the other hand, suppose {\small$\mathfrak{q}[\bphi]$} depends only on {\small$\bphi_{\w}$} for {\small$\w\in\{-\mathfrak{l}_{\mathfrak{q}},\ldots,0\}$} for some {\small$1\leq\mathfrak{l}_{\mathfrak{q}}\lesssim1$}. In this case, let us define the space-time average in the same way but with the ``left-wards" orientation:

\begin{align}
\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathfrak{t}_{\mathbf{Av}}^{-1}{\int_{0}^{\mathfrak{t}_{\mathbf{Av}}}}\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\Big(\mathfrak{q}[\tau_{\x-\j}\bphi_{\t-\r}]\cdot\mathbf{Z}^{N}_{\t-\r,\x-\j}(\mathbf{Z}^{N}_{\t,\x})^{-1}\Big)\d\r.
\end{align}

We remark that (equation eq:mult-op-1 of the paper) and (equation eq:mult-op-2 of the paper) make sense for any other non-negative {\small$\mathfrak{t}_{\mathbf{Av}}$}. In particular, if {\small$\mathfrak{t}_{\mathbf{Av}}=0$}, then the meaning of (equation eq:mult-op-1 of the paper)-(equation eq:mult-op-2 of the paper) is obtained by setting {\small$\r=0$} and dropping the {\small$\d\r$} integration; for this, we write

\begin{align}
\mathbf{Av}^{\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}|_{\mathfrak{t}_{\mathbf{Av}}\mapsto0}.
\end{align}

In particular, by (equation eq:ch of the paper), if {\small$\mathfrak{q}[\bphi]$} is supported on {\small$\bphi_{\w}$} for {\small$\w\geq1$}, then

\begin{align}
\mathbf{Av}^{\mathbf{X},\mathfrak{q}}_{\t,\x}&:=\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\mathfrak{q}[\tau_{\x+\j}\bphi_{\t}]\cdot\exp\Big\{\lambda N^{-\frac12}(\bphi_{\t,\x+1}+\ldots+\bphi_{\t,\x+\j})\Big\}.\nonumber
\end{align}

On the other hand, if {\small$\mathfrak{q}[\bphi]$} is supported on {\small$\bphi_{\w}$} for {\small$\w\leq0$}, then

\begin{align}
