{"assumptions":[],"created_at":"2026-10-27T05:53:54.887881+00:00","domain":"probability theory","id":"claim_8415cb19aef49eb1e462017844037943b3231b92823ecd75cbd41a913c6c960d","kind":"concept","schema_version":1,"statement":"[Theorem 35 ({\cite[Theorem 2.7) of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] {Xu-Wei:2023}}]
