{"assumptions":[],"created_at":"2026-10-27T15:38:04.529412+00:00","domain":"probability theory","id":"claim_846e73fcb58c6feeaf76637445bbd8dfdea72ae646bfac407bca4aa7d6c2aa43","kind":"concept","schema_version":1,"statement":"[Proposition {\cite[Proposition 1.4 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] {contreras_locality_2023}}]
