{"assumptions":[],"created_at":"2026-10-27T07:23:05.285697+00:00","domain":"probability theory","id":"claim_859ab2bf2d9d8e2c961948193da225be9c8e9ed033e04bb15006bb57cb3e31cf","kind":"theorem","schema_version":1,"statement":"[Proposition 11 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] For $j=1,\ldots,d$, let $\Lambdab_j\in\CC^{p_j\times k_j}$ be a nonzero true loading matrix, and let $\widehat{\Lambdab}_j$ denote its estimate. Define the orthogonal projector onto the column space of $\widehat{\Lambdab}_j$ by
\begin{align*}
  \widehat{\Pb}_j
  &=
  \widehat{\Lambdab}_j
  \left(
    \widehat{\Lambdab}_j^\star
    \widehat{\Lambdab}_j
  \right)^+
  \widehat{\Lambdab}_j^\star,
\end{align*}
where $+$ denotes the Moore--Penrose pseudoinverse. The weighted null-space projection error is
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \frac{
    \left\|
      \left(
        \Ib_{p_j}-\widehat{\Pb}_j
      \right)
      \Lambdab_j
    \right\|_F^2
  }{
    \|\Lambdab_j\|_F^2
  }.

\end{align}

Let $  \Lambdab_j = \Ub_j\Deltab_j\Vb_j^\star$ be a ``compact'' singular value decomposition of $\Lambdab_j$, where
$r_j=\operatorname{rank}(\Lambdab_j)$. For $i=1,\ldots,r_j$, let $\ub_{(j)i}$ denote the $i$th column of $\Ub_j$, and let $d_{(j)i}>0$ be the corresponding singular value. Define $\omega_{(j)i}\in[0,\pi/2]$ by
\begin{align}
  \cos\left(\omega_{(j)i}\right)
  &=
  \left\|
    \widehat{\Qb}_j^\star\ub_{(j)i}
  \right\|_2,

\end{align}
where the columns of $\widehat{\Qb}_j$ form an orthonormal basis for the column space of $\widehat{\Lambdab}_j$. The
angle between $\ub_{(j)i}$ and the estimated loading space is $\omega_{(j)i}$. Then,
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \sum_{i=1}^{r_j}
  v_{(j)i}
  \sin^2\left(\omega_{(j)i}\right),
  \qquad
  v_{(j)i}
  =
  \frac{
    d_{(j)i}^2
  }{
    \displaystyle
    \sum_{\ell=1}^{r_j}d_{(j)\ell}^2
  }.

\end{align}
In particular, $\operatorname{err}_{\Lambdab_j}^2\in[0,1]$.","status":"unverified"}

