{"assumptions":[],"created_at":"2026-10-27T15:56:37.663503+00:00","domain":"probability theory","id":"claim_86df0113fdf18724e84a74ada330e668d8b25ec65a40ec6494717629380c605e","kind":"concept","schema_version":1,"statement":"[Thm meso-main of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that the edge weights satisfy Assumption~(ass:weight of the paper). Fix $\mathsf{u}\in(0,1/2)$ and let $T_n^{(\ell)}(0,\mathsf{u}_n)$ be the first-passage time defined in~(equation eq:fixed-target-Tn of the paper). The following holds.
\begin{enumeratea}
 \item  When $1\ll \ell\log\ell \ll n$, we have
 \begin{align} 
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot T_n^{(\ell)}(0,\mathsf{u}_n)
 \stackrel{\pr}{\to}
 \frac1{\mathsf{v}^\star}
 \text{ and }
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot\E T_n^{(\ell)}(0,\mathsf{u}_n)
 \to \frac{1}{\mathsf{v}^\star} \text{ as }n\to\infty,
\end{align}
where $\mathsf{v}^\star\in (0,\infty)$ is the constant defined in~(equation def:vstar of the paper).

 \item  When $1\ll\ell\ll n$, there is a constant $C=C(\theta,\mathsf{u})\in (0,\infty)$ such that, for all large $n$,
\begin{align} 
 C^{-1}\cdot \left( \frac n{\ell^{2+2/\theta}} \vee\frac1{\ell^{2/\theta}} \right)
 \leqslant \var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)
 \leqslant C\cdot \frac{n}{\ell^{1+2/\theta}}\cdot (\log\ell)^{2\gth}.
\end{align}

 \item  When $\ell\ll n^{1/4}(\log n)^{-3\gth/2}$, we have
 \begin{align}
 \frac{T_n^{(\ell)}(0,\mathsf{u}_n)-\E T_n^{(\ell)}(0,\mathsf{u}_n)}{\sqrt{\var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)}}
 \Rightarrow\N(0,1)\text{ as } n\to\infty.
\end{align}
\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.484402+00:00","domain":"probability theory","id":"claim_86df83fd3961b531828e7715e8181684af62a869a364b1f548299853f775069d","kind":"concept","schema_version":1,"statement":"[Cor 55 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$, $k\geq 0$, $j\geq 1$ and $l\geq 0$, with $j+2l\leq 2k+1$.
