\widetilde{X}^N(t)  & = \bar{Q}^N(0) + \lambda^N t - (\mathbf{1}-(\boldsymbol{G}^N)^T)\mu^Nt, \\ \widetilde{Y}^N (t) &= {\operatorname{diag}}(\mu^N)\widetilde{I}^N(t).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.620228+00:00","domain":"probability theory","id":"claim_8705a4692a642735968f808f652855b276e123b1869b7ea93c2b1878bc2d2bbe","kind":"concept","schema_version":1,"statement":"[Prop 36 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $(C_v)_{v\mid \infty}$ be a collection of fixed real numbers satisfying $C_v\geq 1$ and $\q$, $x$, and $\pi_0\ni\phi_0$ be as in \S\ref{sec:choices}. Then there exists a spectral weight function $\H$ defined on the generic automorphic representations for $\bar{G}_n(F)$, factorizing as
	\begin{equation*}
		\H(\sigma)=\prod_{v<\infty}H_v(\sigma_v)\prod_{v\mid\infty}h_v(\sigma_v),\quad \sigma=\otimes'_v\sigma_v,
	\end{equation*}
	such that we have the spectral expansion of the period
	\begin{multline*}
		\mathrm{vol}^{-1}(K_0(\q))\frac{\zeta_\q(1)\zeta_\q(\frac{n}{2})^2}{\zeta_\q(n)}\int_{[\bar{G}_{n}]}|\phi_0\cdot R(x)\Eis(f)|^2 = \\ \Delta^{-\mu_1}\sum_{P}n_P^{-1}\sum_{\pi\in\Pi_{\mathrm{c}}(\bar{M})}\intop_{i\a^\ast_P/i\a^\ast_G}\frac{|L\left(\frac{1}{2},\mathcal{I}(\pi,\lambda)\otimes\tilde{\pi}_0\right)|^2}{\ell(\mathcal{I}(\pi,\lambda))}\mathcal{H}\left(\mathcal{I}(\pi,\lambda)\right)\, d\lambda,
	\end{multline*}
	where $\mu_1$ is a constant depending only on $n$ and $\H$ satisfies the following properties:
	\begin{itemize}
		\item If $v<\infty$ and $c(\sigma_v)>r_v$ then $H_v(\sigma_v)=0$;
		\item If $v<\infty$ and $c(\sigma_v)\le r_v$ then $H_v(\sigma_v)\geq 1$, with equality when $r_v=0$; 
		\item If $v\mid\infty$ and $C(\sigma_v)\leq C_v$ then $h_v(\sigma_v) \gg_{C_v} 1$;
		\item $\int_{\widehat{\bar{G}_n(F_v)}}H_v(\sigma_v)\, d\mu_{\loc}\sigma_v\asymp \mathrm{vol}^{-1}\left(K_0\left(\p_v^{r_v}\right)\right)$;
	\end{itemize}
	as $N(\q)\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

