{"assumptions":[],"created_at":"2026-10-27T19:26:26.798175+00:00","domain":"probability theory","id":"claim_8807d16e2c0db21935bc47e66ee09566aecd510f9348f0f7415bc2299a945b32","kind":"theorem","schema_version":1,"statement":"[Proposition thm:sublinear-accelerating of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] Let \(q=-\alpha\in(0,1)\). Then
\[
    0<T_q<\infty.
\]
More precisely, define
\begin{equation}

    \kappa_q
    :=
    \inf_{0<u<1}
    \frac{
        u^q+(1-u)^q-u^{2q}-(1-u)^{2q}
    }{
        2u^q(1-u)^q
    }.
\end{equation}
Then \(\kappa_q>0\), and
\begin{equation}

    \frac1q
    \le
    T_q
    \le
    \min\left\{
        \frac1{\kappa_q},
        \frac1{1-2^{-q}}
    \right\}.
\end{equation}

Furthermore, if
\[
    M_q(t):=A_{\alpha}(t)=\sum_{k\ge1}k^q p_k(t),
\]
then, for every \(t<T_q\),
\begin{equation}

    \frac1{T_q-t}
    \le
    M_q(t)
    \le
    \frac1{\kappa_q(T_q-t)}.
\end{equation}
Consequently,
\begin{equation}

    \bigl(q(T_q-t)\bigr)^{-1/q}
    \le
    \mu(t)
    \le
    \left(
        \frac{T_q}{T_q-t}
    \right)^{1/\kappa_q},
    \qquad 0\le t<T_q,
\end{equation}
and
\begin{equation}

    \left(
        \frac{T_q-t}{T_q}
    \right)^{1/\kappa_q}
    \le
    d(t)
    \le
    \bigl(q(T_q-t)\bigr)^{1/q}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:29:27.984109+00:00","domain":"probability theory","id":"claim_88087ba8c95f3973cfac233b7493c05c8509e82128cd1aedf5bf19fd6c89d7b6","kind":"theorem","schema_version":1,"statement":"[Proposition 6 (Center-of-mass factorization) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] Let
\begin{equation}
