{"assumptions":[],"created_at":"2026-10-27T16:03:35.732758+00:00","domain":"probability theory","id":"claim_88e9e511dd62dd6f9b237335b26dfa91cec60dd9f73a919e78ec83e2619f3b57","kind":"concept","schema_version":1,"statement":"[Prop masterLayerCake of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $\mu\in\mathcal{P}({\mathbb{R}}^\mathsf{d})$, and let $L\ge1$ be the universal constant in (equation eq:Ustattail of the paper).  Let $g:({\mathbb{R}}^\mathsf{d})^2\rightarrow{\mathbb{R}}$ be a symmetric, measurable two-body kernel and $w:{\mathbb{R}}^\mathsf{d}\to{\mathbb{R}}$ a measurable one-body function, and consider the statistics
\begin{align}
\Xi_N(X_N)\coloneqq -\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde g(x_i,x_j)+\frac1N\sum_{i=1}^N w(x_i),
\qquad N\ge1.
\end{align}
Let $U_0\ge1$ be a threshold, and suppose that for every $N\ge1$ and every $u\ge U_0$ there exist a bounded symmetric kernel $q_{N,u}$ and a number $\mathsf m_{N,u}>0$ such that the following hold.
\begin{enumerate}[(M1)]
\item\emph{(Event reduction)}  For $\mu^{\otimes N}$-a.e.\ configuration $X_N$,
\begin{align}
\Xi_N(X_N)\ge u
\quad\Longrightarrow\quad
-\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde q_{N,u}(x_i,x_j)\ge u.
\end{align}
\item\emph{(Deterministic diagonal bound)}  For every configuration $X_N$,
\begin{align}
-\frac{1}{2N}\sum_{1\le i\ne j\le N}\tilde q_{N,u}(x_i,x_j)\le \mathsf m_{N,u}.
\end{align}
\item\emph{(Norm bounds)}
\begin{align}
\|\tilde q_{N,u}\|_{L^\infty L^2(\mu)}^2\le \frac1{L},
\qquad
\|\tilde q_{N,u}\|_{L^2(\mu^{\otimes2})}^2\le \frac1{L},
\qquad
\|\mathcal{T}_{\tilde q_{N,u}}\|_{\mathrm{op}}\le\frac1{L}.
\end{align}
\end{enumerate}
Suppose, finally, that there exists $N_0\ge1$ such that
\begin{align}
2L^2\,\sup_{u\ge U_0}\ \min\brac[\big]{u,\ \mathsf m_{N,u}}\,\pa[\big]{1+\|\tilde q_{N,u}\|_{L^\infty}}\le N
\qquad\text{for every }N\ge N_0,
\end{align}
the supremum being finite also for $N<N_0$.  Then, writing $\mathsf S_N$ for the supremum in (equation eq:masterLayerCondition of the paper),
\begin{align}
\sup_{N\ge1}\ {\mathbb{E}}_{\mu^{\otimes N}}\brak[\big]{e^{\Xi_N}}
\le \max\brac[\Big]{\max_{1\le N<N_0}e^{U_0+\mathsf S_N},\ e^{U_0}+L},
\end{align}
the inner maximum being absent when $N_0=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.471644+00:00","domain":"probability theory","id":"claim_88e9f2e501403d7d4d399930f3dabe6b0e6825d525236d85336677faa78b1011","kind":"concept","schema_version":1,"statement":"[Proposition Proposition3 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that (A1 of the paper)-(A7 of the paper) hold and that $\varphi$ is an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$,  satisfying (C1 of the paper)-(C3 of the paper). Then, for every $t \in \mathbb{R}$, 
