	\mathcal{D}(u,w):=\int_\Omega u\big\vert \nabla\big(\phi'(u)-\mathcal{K}[ w-\langle  w \rangle]\big)\big\vert^2\,\rd x+\|\nabla \mathcal{K}[u-w - \langle u-w\rangle]\|_2^2\ge 0\,.
