{"assumptions":[],"created_at":"2026-10-27T13:28:33.870502+00:00","domain":"probability theory","id":"claim_89c9cb97b01961b85cc47e89f98fcf572af73ff4922df595f51137f85d3c9e61","kind":"theorem","schema_version":1,"statement":"[Theorem thm:pgl2-cumulative of arXiv:2504.19367, 'Reduced Random Walks in the Hyperbolic Plane\textinterrobang'] Let $W \simeq PGL_2(\mathbb{Z})$ be the Coxeter group generated by the set $S = \{s_1, s_2, s_3\}$ of simple reflections, where $s_1, s_2, s_3$ are the following transformations of the upper half-plane $\mathbb{H}$:
    \begin{align*}
    s_1(z) &= -1 - \overline{z} \\
    s_2(z) &= 1/\overline{z} \\
    s_3(z) &= -\overline{z}.
    \end{align*}
    Consider the sequence $(z_m)_{m \geq 0}$, which was defined in (subsec:oneway of the paper) as a geometric interpretation of the reduced random walk in $(W, S)$. The limit $\zeta = \lim_{m \to \infty} z_m$ almost surely exists and is a real number. The cumulative distribution function $F_\zeta$ is given by
    \begin{equation}F_\zeta(x) = \Pr[\zeta \leq x] = \begin{cases}
        \interro(-1/x) & \mbox{if $x \leq -2$} \\
        1/4 - \interro(-x-1)/2 & \mbox{if $-2 \leq x \leq -1$} \\
        1/4 + \interro(-1-1/x)/2 + \interro(x + 1)/2 & \mbox{if $-1 \leq x \leq -1/2$} \\
        1/2 - \interro(-x)/2 & \mbox{if $-1/2 \leq x \leq 0$} \\
        1/2 + \interro(x) & \mbox{if $0 \leq x \leq 1$} \\
        7/8 + \interro(x-1)/4 & \mbox{if $1 \leq x \leq 2$} \\
        1 - \interro(1/x)/2 & \mbox{if $2 \leq x$}
    \end{cases}\end{equation}
    for all $x \in \mathbb{R}$, where $\interro$ is the interrobang function ((thm:interro-real of the paper)). In particular,
    \begin{enumerate}[(i)]
        \item  $F_\zeta$ is continuous and strictly increasing;
        \item  for all $x \in \mathbb{Q}$, we have that $F_\zeta(x)$ is an explicitly computable dyadic rational number;
        \item  for all quadratic irrationals $x$, we have that $F_\zeta(x)$ is an explicitly computable rational number.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:04:39.209489+00:00","domain":"probability theory","id":"claim_89cabc7038f33b8d8674846e1a192b0e2d1b9caf57f0b929b0403c2baddf7245","kind":"concept","schema_version":1,"statement":"[Maintheorem 1 of arXiv:2608.13687, 'Multiplicative chaos from random multiplicative functions'] Let $\theta\in (0,1]$, and let $f: \N \to \C$ satisfy
    \begin{equation}
     |f|^2\in\bP_\theta\,,\qquad
    \sum_{p\geq2}\bigg(
    \frac{|f(p)|^3}{p^{3/2}} \log^{2+\delta_1} p+
    \frac{|f(p^2)|^2}{p^2}\log^{1+\delta_2} p+\sum_{j\geq3}\frac{\vert f(p^j)\vert}{p^{j/2}}\bigg)<\infty
    \end{equation}
    for some $\delta_1, \delta_2 >0$.
    For each $\varepsilon\geq0$ and $N\geq0$, we set 
    \[
    V_{N,\varepsilon}(\theta) \coloneqq \one_{\theta\in (0,1)}+\one_{\theta=1}\sum_{p=1}^N \frac{|f(p)|^2}{p^{1+2\varepsilon}}\qquad\text{and}\qquad \mathrm{d}\rho_{N,\varepsilon}(x) \coloneqq \sqrt{V_{N,\varepsilon}(\theta)} \ \d x\,.
    \] 
    We define the random measure $\mu_{N,\varepsilon}$ on $\R$ via
    \begin{equation}
        \mu_{N,\varepsilon}(\d x)\coloneqq\frac{\vert D_{N}(\alpha f,\frac12+\varepsilon+ix)\vert^{2}}{\E[\vert  D_{N}(\alpha f,\frac12+\varepsilon+ix)\vert^{2}]} \,\d\rho_{N,\varepsilon}(x) \,.
    \end{equation}
    There exists a nontrivial, non-atomic random measure $\mu_\infty$ on $\R$ such that the following hold.
    \begin{enumerate}[(i)]
        \item In the subcritical phase $\theta\in(0,1)$,
        for every $r\in[1,1/\theta)$ and $h\in C_c(\R)$,
    \begin{equation}
        \mu_{N,\varepsilon}(h)\xrightarrow[\min(N,\,1/\ep)\to\infty]{L^r}\mu_\infty(h).
    \end{equation}
        \item In the critical phase $\theta=1$, for every $h\in C_c(\R)$,  
    \end{enumerate}
    \begin{equation}
        \mu_{N,\varepsilon}(h)\xrightarrow[\min(N,\, 1/\ep)\to\infty]{\P}\mu_\infty(h).
    \end{equation}
    Moreover, for all $\theta \in (0,1]$, there exists a GMC measure $\mu_{\infty}^{\mathrm{GMC}}$ of inverse temperature $\theta$ coupled on the same probability space as $\mu_{\infty}$ such that the two measures are mutually absolutely continuous, almost surely. The Radon-Nikodym derivative is continuous and  nonnegative, is positive $\mu_{\infty}^{\text{GMC}}$-almost everywhere, and its $L^\infty$-norm on any compact interval has finite positive moments. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:45:10.134530+00:00","domain":"probability theory","id":"claim_89cd5c45f359ee36166d19a3b487df4becbd4039221876bd9c2d653ff1fd8b74","kind":"concept","schema_version":1,"statement":"[Lemma capacity_bound of arXiv:2505.07145, 'Nonamenable Poisson zoo'] For any $K \subset \subset V$ we have 
	\begin{equation}

		(1 - \rho(G)) \cdot |K| \leq
		\mathrm{cap}(K) \leq
		|K|,
	\end{equation}
	where recall that $\rho(G)$ denotes the spectral radius of the graph. In particular, by (equation eq:relation_of_spectral_radius_and_Cheeger_constant of the paper), on a nonamenable graph $G$ the capacity and the cardinality of a finite vertex set are comparable. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.973151+00:00","domain":"probability theory","id":"claim_89d0144c0b03efdda84de62f5420859c9fe61b403a36aea7e3556dacd476628a","kind":"theorem","schema_version":1,"statement":"[Propn 3 of arXiv:2606.13487, 'Branching-Selection Particle Systems and Inverse First Passage Problems'] Let $(\mu_t^N)_{t\geq 0}$ be the measure-valued process describing the $(\omega,f,\Lambda,N)$-BBM process, and define $b^N(t):=\inf\{x:\Lambda\langle \mu_t^N,\omega(\cdot-x)\rangle\geq f(t)\}$. Then for any bounded $\omega$ and any test function $\phi(x,t)\in \C{BC}^{2,1}(\B{R}\times [0,\infty),\B{R})$ we have
    \begin{align}  \langle \mu_t^N,\phi(\cdot,t)\rangle = \langle \rho^N, \phi(\cdot,0)\rangle &+ \int_0^t \langle \mu_s^N, \frac12 \phi_{xx}(\cdot,s) + \phi_t(\cdot,s)+f(s)\phi(\cdot,s)\rangle \\
    &- \frac{f(s)\langle \mu_s^N,\phi(\cdot,s)\omega(\cdot-b^N(s))}{\langle \mu_s^N,\omega(\cdot-b^N(s))\rangle} ds
    \nonumber + M_t^{N,W} + M_t^{N,b},
    \end{align}
    where $M^{N,W}_t$ is a continuous local martingale and $M^{N,b}_t$ is a local martingale, with $\B{E}[[M^{N,W}]_t],\B{E}[[M^{N,b}]_t]\to 0$ as $N\to\infty$ for fixed $t\geq 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:58:38.148535+00:00","domain":"probability theory","id":"claim_89d1660ea7232fff8efca1e54e9eae86c3bd1bf2f167e574162883acde0d5cf0","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Jordan2_lower_tail_lower_bound of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For the Jordan-$2$ ordering $\widehat{\sigma}_2$, there exist positive constants $C$, $\delta$ such that for any $n\geq 1$, any vertex $v \in[n]$ and any $S\in[1, \delta\sqrt{v}]$ 

