{"assumptions":[],"created_at":"2026-10-27T06:25:55.318344+00:00","domain":"probability theory","id":"claim_8a681598970b83b7d87ac8af62b81df8cd63cad5843dc6623f19f2878e2863ef","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] The functions $\Theta_1(r; \cdot)$ and $\Theta_3(r; \cdot)$ are analytic and have no zeros in the open strip $\mathbb{S}_r$. Consequently, one can define single-valued, continuous branch of the argument functions $\arg\Theta_1$ and $\arg\Theta_3$ in $\mathbb{S}_r$. These functions are harmonic in $\mathbb{S}_r$ and can be continuously extended to the boundary with the following boundary data: 
\begin{align} 
\begin{split}
	&\begin{cases}
		\arg \Theta_1(r; x)= -\ell \pi, \quad x\in (2\ell\pi,2(\ell+1)\pi), \quad \ell\in \Z;\\
		\arg \Theta_1(r; x+\ii r)=\frac{\pi}{2}-\frac{x}{2}, \quad x\in\R;
	\end{cases}\\
	&\begin{cases}
		\arg \Theta_3(r; x)=0, \quad x\in\R;\\
		\arg \Theta_3(r; x+\ii r)=\frac{\pi}{2}-\frac{x}{2}+\ell \pi, \quad x\in (2\ell\pi,2(\ell+1)\pi), \quad \ell\in \Z.
	\end{cases}	
\end{split}
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:11:44.357792+00:00","domain":"probability theory","id":"claim_8a69f0582a4a2c83bcbcc608a34358641159a964072721ddad04d557e742577f","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] Let $E$ be a separable Banach space and let $B\subset L^1([a,b],E)$ be a countable and integrably bounded set, i.e., there exists $c\in L^1([a,b])$ such that $$\|w(t)\|\leq c(t), \quad w\in B \text{ and a.e. }t\in [a,b].$$ Define the function $\phi (t):= \beta(\{u(t)|\, u\in B \})$ for $t\in[a,b]$. Then $\phi\in L^1([a,b])$ and
			$$
			\beta \left(\left\{
			\int_{a}^{b} u(\tau) \d \tau\,|\, u \in B\right\} \right)
			\leq \int_{a}^{b} \phi(\tau) \d \tau.
			$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:44:28.086726+00:00","domain":"probability theory","id":"claim_8a722905d49e986f10c05548435e3d2134a6543ffb558c786e2952122c7db11e","kind":"concept","schema_version":1,"statement":"[Thm 19 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Let 
$\varsigma=(\varsigma_t)_{t \in [0,T]}$ satisfy \textbf{\bf C1} and \textbf{\bf C2}, and 
$(\varphi : [0,T] \ni t \mapsto \varphi_t)_{t \in [0,T]}$ 
be a continuous curve from $[0,T]$
to  $\mathcal{H}^4_{\mathrm{Sym}}(\mathbb{S})$. Then, there exists an integral curve, denoted 
\begin{equation*}
\biggl( \int_0^t \varphi_s \cdot 
{\mathrm d} \varsigma_s 
\biggr)_{0 \leq t \leq T},
\end{equation*}
satisfying the following properties:
\begin{enumerate}
    \item the integral curve is continuous in $t \in [0,T]$;
    \item 
\begin{equation*}
\lim_{N \rightarrow \infty}
\sup_{t \in [0,T]}
\biggl\vert 
\int_0^t 
\varphi_s  \cdot 
{\mathrm d} \varsigma_s 
- 
\sum_{k=0}^N 
\biggl( 
\int_0^t \langle \varphi_s,e_k\rangle 
{\mathrm d} \langle 
\varsigma_s,e_k^{\star,+}\rangle
- 
\int_0^t \langle \varphi_s,e_k\rangle 
{\mathrm d} \langle 
\varsigma_s,e_k^{\star,-}\rangle
\biggr) 
\biggr\vert
=0,
\end{equation*}
with
the integral curves
$(\int_0^t \langle \varphi_s,e_k\rangle 
{\mathrm d} \langle 
\varsigma_s,e_k^{\star,\pm}\rangle)_{t \in [0,T]}$ being understood as 
Riemann-Stieltjes integrals;
\item there exists a universal constant $c>0$ such that, 
\begin{equation*}
\sup_{t \in [0,T]}
\biggl\vert 
\int_0^t
\varphi_s \cdot {\mathrm d} 
\varsigma_s 
\biggr\vert
\leq c \sup_{t \in [0,T]}
\| \varphi_t \|_{2,4}
\sup_{t \in [0,T]} \sup_{\psi \in {\mathcal H}^{3+\delta}({\mathbb S}) : \| \psi \|_{2,2} \leq 1}
\bigl\vert \langle \varsigma_t, \psi \rangle 
\bigr\vert;
\end{equation*}
\item 
\begin{equation*}
\lim_{N \rightarrow \infty}
\sup_{t \in [0,T]}
\biggl\vert 
\int_0^t 
\varphi_s  \cdot 
{\mathrm d} \varsigma_s 
- 
\sum_{k \in {\mathbb N} : k  \leq N t} 
\langle 
\varphi_{k/N}, \varsigma_{t \wedge (k+1)/N}
- 
\varsigma_{k/N}
\rangle  
\biggr\vert
=0;
\end{equation*}
\item if, in addition, $\varphi$ takes values in 
${\mathcal U}^2({\mathbb S})$, then 
$[0,T] \ni t \mapsto 
\int_0^t \varphi_s \cdot {\mathrm d} \varsigma_s$
is non-decreasing. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.188255+00:00","domain":"probability theory","id":"claim_8a72728741dd7256dd3262b66abc8fe049f9dfe6518ba425814e901add0853b9","kind":"concept","schema_version":1,"statement":"[Lemma 1 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $a \geq b \geq 0$. Then, for $p, p+q \geq 0$ and $x \in [0,a]$, we have the following:
			\begin{itemize}
				\item[\upshape{(i)}] For $u \in [0,b)$, \begin{equation}
					q \int_0^x \mathbb{W}^{(p+q)}(x-y) w^{(p)}(y;u) \mathrm{d} y = 	\W^{(p+q)}(x-u) - w^{(p)}(x;u) - \delta \int_{[0,b-u)} \W^{(p+q)}(x-u-y) W^{(p)} (\dd y), 
				\end{equation}
				where $W^{(p)}(\dd y)$ is the measure defined on $[0,\infty)$ associated with $W^{(p)}(a,b]:= W^{(p)}(b) - W^{(p)}(a)$ for $p \geq 0$ and $-\infty < a \leq b < \infty$ (see Chapter 8 of \cite{K2014} for more details).
				\item[\upshape{(ii)}] 	\begin{equation}
					q \int_0^x \mathbb{W}^{(p+q)}(x-y) z^{(p)}(y) \mathrm{d} y = 	\Z^{(p+q)}(x) - z^{(p)}(x) - \delta p \int^b_0 \W^{(p+q)}(x-y) W^{(p)} (y) \dd y. 
				\end{equation}

				\item[\upshape{(iii)}] Let $u \geq 0$ and define 
				\begin{equation}
					\ovl{w}_b^{(p,q)}(x;u) :=  w^{(p)}(x;u) +q \int_b^x \mathbb{W}^{(p+q)}(x-y) w^{(p)}(y;u) \mathrm{d} y, 
				\end{equation}
				with the convention that $\ovl{w}_b^{(p,q)}(x) = \ovl{w}_b^{(p,q)}(x;0)$. Then, we have also that
				\begin{equation}
					\begin{aligned}
						\ovl{w}_b^{(p,q)}(x;u) &= \W^{(p+q)}(x-u) -q \int_0^{b-u} \mathbb{W}^{(p+q)}(x-u-y) W^{(p)}(y) \mathrm{d} y \\
						&\eqsp - \delta \int_{[0,b-u)} \W^{(p+q)}(x-u-y) W^{(p)} (\dd y).
					\end{aligned} 
				\end{equation}

				\item[\upshape{(iv)}] Define
				\begin{equation}
					\ovl{z}_b^{(p,q)}(x) := z^{(p)}(x)+q \int_b^x \mathbb{W}^{(p+q)}(x-y) z^{(p)}(y) \mathrm{d} y. 
				\end{equation}
				Then, we have also that
				\begin{equation}
					\ovl{z}_b^{(p,q)}(x) =  \Z^{(p+q)}(x) -q \int_0^b \mathbb{W}^{(p+q)}(x-y) Z^{(p)}(y) \mathrm{d} y - \delta p \int^b_0 \W^{(p+q)}(x-y) W^{(p)} (y) \dd y. 
				\end{equation}
				\item[\upshape{(v)}]
				For $u \in [0,b]$,
				\begin{equation}
					\begin{aligned}
						{\E}_x \bigl(\mathrm{e}^{-(p+q) \tau_{b,Y}^{-} }\1_{\{ \tau_{b,Y}^{-}<\tau_{a,Y}^{+}\}} W^{(p)}(Y_{\tau_{b,Y}^{-}}-u) \bigr)=\ovl{w}_b^{(p,q)}(x;u)-\frac{\mathbb{W}^{(p+q)}(x-b)}{\mathbb{W}^{(p+q)}(a-b)} \ovl{w}_b^{(p,q)}(a;u),
					\end{aligned} 
				\end{equation}
				and
				\begin{equation}
					\begin{aligned}
						{\E}_x \bigl(\mathrm{e}^{-(p+q) \tau_{b,Y}^{-} }\1_{\{ \tau_{b,Y}^{-}<\tau_{a,Y}^{+}\}} Z^{(p)}(Y_{\tau_{b,Y}^{-}}) \bigr)=\ovl{z}_b^{(p,q)}(x) -\frac{\mathbb{W}^{(p+q)}(x-b)}{\mathbb{W}^{(p+q)}(a-b)} \ovl{z}_b^{(p,q)}(a), 
					\end{aligned} 
				\end{equation}
				where $\ovl{w}_b^{(p,q)}$ and $	\ovl{z}_b^{(p,q)}$ are given in Eqs.~\eqref{eq:SecondGenFunc-RefractedWTilde1} and \eqref{eq:SecondGenFunc-RefractedZTilde1}, respectively.
			\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.935265+00:00","domain":"probability theory","id":"claim_8a7704417df295cdb4a992ca7a081ac3ec4bb914fccbff6146cd83c3acd146f1","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] The limit
