\end{equation}
and 
\begin{equation}
\alpha_c(\kappa) = d^2 \log \bigg( \frac{d-1}{d-2} \bigg)(1+\kappa)^2 + O_d(1),\quad\text{as }\kappa\to\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:46:12.274278+00:00","domain":"probability theory","id":"claim_8be085a1ae3254c948f59f6e1e00b2c11f56b7b68a6259511ff4b16471f4f8a5","kind":"concept","schema_version":1,"statement":"[Lemma 10 (Theorem 2.2 of \cite{AHP2024}) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $\bG^{a, L}, \bG^{b, M} \in \cFG$ and $\pi \in \Cpl_{\mathrm{bc}}(\bG^{a, L}, \bG^{b, M})$. The following are equivalent:
\begin{enumerate}
\item[(i)] $\pi \in \cP(\bR^{Nd} \times \bR^{Nd}) \cong  \cP(\bR^{2Nd})$ is jointly Gaussian. (Here and below, we identify $(x, y) \in \bR^{Nd} \times \R^{Nd}$ with the column vector $\begin{bmatrix} x^{\intercal} & y^{\intercal} \end{bmatrix}^{\intercal} \in \bR^{2Nd}$.)
\item[(ii)] There exists a block diagonal matrix $P =\textup{diag}(P_1,\dots,P_N)$, where each diagonal block $P_t \in \bR^{d \times d}$ satisfies $\|P_t\|_{2\rightarrow 2}\le 1$ (that is, each $P_t$ is a contraction and hence is a correlation matrix), such that
\begin{equation} 
\pi = \pi^P := \cN_{2Nd} \left( \begin{bmatrix} 0 \\ 0 \end{bmatrix}, \begin{bmatrix} I & P \\ P^{\intercal} & I \end{bmatrix} \right).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:18.803470+00:00","domain":"probability theory","id":"claim_8be1f761df94f17f1d0bca7dff9dbfd1abfe519c9c0f79e95f37cee68f4d9d20","kind":"concept","schema_version":1,"statement":"[Thm 5 Hodge n point formula of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\sum_{i=1}^5 \epsilon_i = 0$. (conj:GW:vertex of the paper) holds if and only if, for all $n\in\{1,\ldots,5\}$, we have
    \begin{equation}

        \mathsf{H}(\epsilon_1^{-1},\ldots, \epsilon_n^{-1} ; \epsilon_1,\ldots, \epsilon_5 ; u)
        =
        \mathsf{V}(\epsilon_1,\ldots,\epsilon_n;u)
        \prod_{j=1}^n \frac{1}{u^2}
        \prod_{i\neq j} \frac{\gamfct{-\epsilon_j^{-1}\epsilon_i}{u\epsilon_j}}{\epsilon_i} \,,
    \end{equation}
    where
    \begin{equation}

        \mathsf{V}(\epsilon_1,\ldots,\epsilon_n;u)
        \coloneqq
        \begin{cases}
            1
            & n=1 \,, \\[0.75em]
            \dfrac{\varsigma(u \epsilon_3)\varsigma(u \epsilon_4)\varsigma(u \epsilon_5)}{\varsigma(u (\epsilon_1+\epsilon_2))}
            & n=2 \,, \\[0.95em]
            \varsigma(u \epsilon_4)^2 \varsigma(u \epsilon_5)^2
            & n=3 \,, \\[0.75em]
            \Big(\prod_{i=1}^5 \varsigma(u\epsilon_i) \Big) \, \varsigma(u\epsilon_5)^2 \sum_{i=1}^4 \kappa(u\epsilon_i)
            & n=4 \,, \\[0.75em]
            \Big(\prod_{i=1}^5 \varsigma(u \epsilon_i) \Big)^2 \Big(\big(\sum_{i=1}^5 \kappa(u \epsilon_i)\big)^2 -\frac{1}{4} \Big)
            & n=5 \,,
        \end{cases}
    \end{equation}
    and $\varsigma(x) = 2 \sinh \tfrac{x}{2}$, $\kappa(x) = \frac{d}{dx} \log{\varsigma(x)} = \tfrac{1}{2} \coth \tfrac{x}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

