	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:06:18.058532+00:00","domain":"probability theory","id":"claim_8bff8072a59fd593739cca540416a8c4a0dd90851a21be0d48e30b47b33516bb","kind":"theorem","schema_version":1,"statement":"[Proposition 38 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let $\pi_{A,N}$ be an invariant probability for $P_{A,N}$ on $\Kcal_N$ with
  $\pi_{A,N}(\{0\})=0$. Then, for every bounded measurable
  $\varphi:\Kcal_N\to\R$,
  \begin{equation}
    \int_{\Kcal_N}\varphi(y)\,\pi_{A,N}(\mathrm{d}y)
    =
    \int_{\Kcal_N}
    \int_{\R^N}
    \varphi\bigl(\tanh(A\norm{x}_2 g/\sqrt N)\bigr)\,
    \mathcal G_N(\mathrm{d}g)\,\pi_{A,N}(\mathrm{d}x).
  \end{equation}
  Moreover, $\pi_{A,N}(\partial[-1,1]^N)=0$ and $\pi_{A,N}$ is absolutely
  continuous on $(-1,1)^N$. If $f_{A,N}$ denotes its density, then, for
  $x\neq0$ and $y\in(-1,1)^N$,
  \begin{equation}
    \kappa_{A,N}(x,y)
    =
    \prod_{i=1}^N
    \frac{\sqrt N}{A\norm{x}_2\sqrt{2\pi}}
    \frac{1}{1-y_i^2}
    \exp\left(
      -\frac{N\,\arctanh(y_i)^2}
      {2A^2\norm{x}_2^2}
    \right)
  \end{equation}
  is the transition density from $x$ to $y$, and
  \begin{equation}
    f_{A,N}(y)
    =
    \int_{\Kcal_N\setminus\{0\}}
    \kappa_{A,N}(x,y)\,\pi_{A,N}(\mathrm{d}x).
  \end{equation}
  If $\pi_{A,N}(\mathrm{d}x)=f_{A,N}(x)\,\mathrm{d}x$, this becomes
  \begin{equation}
    f_{A,N}(y)
    =
    \int_{\Kcal_N\setminus\{0\}}
    \kappa_{A,N}(x,y)f_{A,N}(x)\,\mathrm{d}x .
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.276729+00:00","domain":"probability theory","id":"claim_8bffddd8ea1af5e6159a82400704a5e16ea6a15b43719998898bba73e26aa137","kind":"concept","schema_version":1,"statement":"[Lemma 12 of arXiv:2606.21394, 'McKean-Vlasov Equations for Large Networks of Neurons with Adaptive Asymmetric Edges'] Let $a > 0$. If $b(a)$ is sufficiently large, then for all $b\geq b(a)$, it holds $\mathbb{P}$-almost-surely that
