{"assumptions":[],"created_at":"2026-10-26T19:25:12.193587+00:00","domain":"probability theory","id":"claim_8ccfd4fc2bc5c270a6a9c41e260e8faaed4c470a622dceb62ce9bef45ba14bce","kind":"concept","schema_version":1,"statement":"[Proposition 14 (Transformation of conditional laws under rerooting) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds.
Let $k \in \N_0$ and let $h \colon (\PolishX^{k+1})^2 \times \SQ(\PolishX^{k+1}) \to \Rmb$ be bounded and measurable.
Define $\Xi_k \colon (\{0,1\} \times \PolishX^{k+1})^2 \rightarrow \Rmb$ by 
\begin{equation*}
\Xi_k(X_{\myroot}[k], X_1[k]) := 1_{\{N_{\myroot}(\tree)\ne\emptyset\}} \frac{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} h(X_{\myroot}[k],X_1[k],\lan X_{N_{\myroot}(\tree)}[k]\ran) \,\big|\, X_{\myroot}[k],X_1[k]\right]}{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} \,\big|\, X_{\myroot}[k],X_1[k]\right]}.
\end{equation*}
Then, for each $v \in \N$, 
\begin{equation} 
\Xi_k(X_v[k], X_{\myroot}[k]) = \Emb\left[ h(X_v[k],X_{\myroot}[k],\lan X_{N_v(\tree)}[k]\ran) \,|\, X_{\myroot}[k],X_v[k] \right], \mbox{ on } \{v \in \tree\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.119160+00:00","domain":"probability theory","id":"claim_8cd1a26a9e9d74799e6649d1018c13deb2d3897e5c3a28cde75ce492e742dd1f","kind":"theorem","schema_version":1,"statement":"[Proposition Prop:PropertiesGamma of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $\alpha \in (0,1)$ and let the effective branching rate $R\in C^{0,\alpha}_p(\mathbb{R}^d)$ defined in (equation eq:Intro:EffectiveBranching of the paper) be such that $R \ge 0$ and $R\not\equiv 0$. Then $\gamma(\zeta)=\gamma(\zeta;b,\sigma,R)$ satisfies the following properties.
    \begin{enumerate}[(i)]
        \item The function $\gamma$ belongs to $C^2(\mathbb{R}^d)$, is strictly convex, and for $\zeta\in \mathbb{R}^d$,
        \begin{equation}
             \gamma(\zeta) \in \left[\Big(\min_{x\in \mathbb{R}^d}R(x)\Big) + \frac{\theta^{-1} |\zeta|^2}{2} - |\zeta| \| b\|_\infty ,  \Big(\max_{x\in \mathbb{R}^d}R(x)\Big) + \frac{\theta |\zeta|^2}{2} + |\zeta| \| b\|_\infty  \right],
        \end{equation}
        where we recall that $\theta$ is a positive constant such that $0<\theta^{-1} \mathrm{Id}<\sigma \sigma^T<\theta \mathrm{Id}$ (see \textbf{(AssumptionA:SigmaEllipticity of the paper)}).
        \item Let $\nu(\cdot;0):\mathbb{T}^d\to \mathbb{R}$ be the density on the torus of the invariant measure of a periodic diffusion with generator $\mathcal{L}^0$ as defined in (equation eq:Intro:GeneratorExponential of the paper). Recall that $\nu(R;0)$ denotes the integral $\int_{\mathbb{T}^d}R(x)\nu(x;0)dx$. We have that $\gamma(0)\geq \nu(R;0)>0$, and for $e\in S^{d-1}$,
        \begin{equation}
            \begin{split}
                &\lim_{\lambda \rightarrow 0^+ }\frac{\gamma(\lambda e)}{\lambda}=\lim_{\lambda \rightarrow + \infty }\frac{\gamma(\lambda e)}{\lambda}=+\infty, \ \mathrm{ and } \ \lim_{\lambda \rightarrow 0^- }\frac{\gamma(\lambda e)}{\lambda}= \lim_{\lambda \rightarrow - \infty }\frac{\gamma(\lambda e)}{\lambda}=-\infty.
            \end{split}
        \end{equation}
        \item For all $e\in S^{d-1}$, there exists a unique $\lambda_e\in (0,\infty)$ such that 
        \begin{equation*}
            \inf_{\lambda>0} \frac{\gamma(\lambda e)}{\lambda}=\frac{\gamma(\lambda_e e)}{\lambda_e}.
        \end{equation*}
        \item At every $\zeta\in \mathbb{R}^d$, the Hessian $\nabla^2 \gamma (\zeta)$ is invertible.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:51:33.322312+00:00","domain":"probability theory","id":"claim_8cd21a7034e94d6e18acf5bfbf67ebe432618405507304428ec27dd5b7173a8b","kind":"concept","schema_version":1,"statement":"[Lemma idempotent-restrict of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $i\colon S\hookrightarrow T$ be a cleft, let ${\mathcal{C}}\in\CAT_T^\textup{$S$-cc}$, and let $X$ be a global section. Then $({\mathcal{C}},X)$ is an idempotent in $\CAT_T^\textup{$S$-cc}$ if and only if the restriction $(i^*{\mathcal{C}},i^*X)$ is an idempotent in $\CAT^\textup{$S$-cc}_S$. Moreover, in this case a ${\mathcal{D}}\in\CAT_T^\textup{$S$-cc}$ is a ${\mathcal{C}}$-module if and only if $i^*{\mathcal{D}}$ is an $i^*{\mathcal{C}}$-module.
    \begin{proof}
        This follows at once from Lemma~(lemma:restr-cleft-sym-mon of the paper) since the restriction functor $i^*\colon\CAT_T\to\CAT_S$ is conservative.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.613583+00:00","domain":"probability theory","id":"claim_8cd2ad68094d9f78f35a07995ba9443bdbd8085009aefa0b6bc15ab51d1c49e9","kind":"concept","schema_version":1,"statement":"[Proposition 54 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Under the event where the bounds in Propositions \ref{prop:pbar_square_root_G} and \ref{prop:u_ratio_concentration_G} hold true, we have
    \begin{align}
        F_1(i)\lesssim \begin{cases}
        \frac{1}{\sqrt{i}}+\frac{\log n}{\sqrt{n}}\quad &\mbox{if $n_0\le i\le n/2$}\\
        \frac{\log n}{\sqrt{n-i}}\quad &\mbox{if $i>n/2$}
            \end{cases},\qquad 
        F_2(i)\lesssim \begin{cases}
       \sqrt{\frac{n}{i}}\log T \quad &\mbox{if $n_0\le i\le n/2$}\\
        \sqrt{\frac{n}{i}}\quad &\mbox{if $i>n/2$}
