{"assumptions":[],"created_at":"2026-10-27T22:57:49.907684+00:00","domain":"probability theory","id":"claim_8d2f53b2e87f14dffd8245352ee568c584ed7cb8e5593db347800740a5fb7777","kind":"theorem","schema_version":1,"statement":"[Theorem thm: of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},\mu,T)$ be a capacity preserving system. If $\mu$ is continuous from above and concave then the following four statements are equivalent:
	\begin{longlist}
		\item $\mu$ is ergodic;
		\medskip
		\item there exists $Q\in\operatorname{core}(\mu)\cap \mathcal{ M}^e(T)$ such that $\mu(A)=Q(A)$ for any $A\in\mathcal{I}$, and 
	\begin{align*}
	\lim_{n\to\infty}&\max_{P\in\operatorname{core}(\mu)}\frac{1}{n}\sum_{i=0}^{n-1}\int f\cdot(g\circ T^i)dP\\
	&=\max_{P\in\operatorname{core}(\mu)}\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}\int f\cdot(g\circ T^i)dP=\int fd\mu\int gdQ
	\end{align*}
		for any $f,g\in B(\Omega,\mathcal{F})$ such that $g\ge 0$;
		\medskip
		\item there exists $Q\in\operatorname{core}(\mu)\cap \mathcal{ M}(T)$ such that 
		\[\lim_{n\to\infty}\max_{P\in\operatorname{core}(\mu)}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=\max_{P\in\operatorname{core}(\mu)}\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=\mu(B)Q(C)\]
		for any $B,C\in \mathcal{F}$;
		\medskip

		\item there exists $Q\in\Delta^{\sigma}(\Omega,\mathcal{F})$ such that  $\mu|_{\mathcal{I}}\ll Q|_{\mathcal{I}}$  and
		\begin{equation*}
			\liminf_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}\mu(B\cap T^{-i}C)\ge\mu(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
		\end{equation*}
	\end{longlist}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:47:04.925891+00:00","domain":"probability theory","id":"claim_8d2fbd637411da0879a2e2842f5a81c6bef5774c98bde144de52cf9a385e43cb","kind":"lemma","schema_version":1,"statement":"[Lemma comparaison of arXiv:2412.02486, 'On the curvatures of \\ random complex submanifolds'] Using the above notations, for any $T\in \sym_\mathbb{C}(n-r,r)$ the following holds.
	\begin{enumerate}
\item 	$\displaystyle \min_{ (x,y)\in (\mathbb S^{2n-2r-1})^2 } |T(x,y)|_{\mathbb{C}^r}
	= \min_{([X],[Y])\in (\mathbb{C} \mathbb{P}^{n-r-1})^2 }\|\Phi_1(T)([X],[Y])\|_{\mathrm{FS}}$,
	\item 	$\displaystyle \min_{x\in \mathbb S^{2n-2r-1}} |T(x,x)|_{\mathbb{C}^r}
	= \min_{[X]\in \mathbb{C} \mathbb{P}^{n-r-1} }\|\Phi_2(T)([X])\|_{\mathrm{FS}}$,
	\item 	$\displaystyle \min_{x\in \mathbb S^{2n-2r-1}} \|T(x,\cdot)\|_{\mathbb{C}^r}
	= \min_{[X]\in \mathbb{C} \mathbb{P}^{n-r-1}}\|\Phi_3(T)([X])\|_{\mathrm{FS}}$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:38:57.143138+00:00","domain":"probability theory","id":"claim_8d343519005e883d63674602fdd24b170114cf8385c82b8a84ef90c2dae2d06b","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2604.05999, 'Branching Process in a Varying Environment: How to Grow Like the Product of Means'] Let $\{Z_n\}$ be a BPVE, ${\bf E}X_{i,1}$ be positive and $\Var X_{i,1}$ be finite for every $i$. Let 
    $\xi_i = \log {\bf E}X_{i,1}$, $\zeta_i = \Var X_{i,1} e^{-2\xi_i}$, $i>0$. Let $S_n=\xi_1+\dotsb+\xi_n$. Assume that 
    \begin{eqnarray}  
     {\bf P}\left(Z_n \rightarrow \infty \right) + {\bf P}\left(\exists n:  Z_n = 0 \right) = 1,\\
     \liminf_{l \to \infty} a_l<+\infty,\ a_l:=\sum_{i = 0}^{\infty} \zeta_{i+l} e^{-(S_{i+l} - S_l)}. 
    \end{eqnarray}
    Then the martingale $W_n=Z_n/\exp(S_n)$, $n\ge 1$, converges in $L^2$ to some random variable $W$ and 
    \begin{equation}

    {\bf P}(W>0)={\bf P}(Z_n>0,\ n>0)>0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.370997+00:00","domain":"probability theory","id":"claim_8d3459d747a1be24cc2b4ad04b38d175291052fdae3f0ff7a9f326c5be9cee0b","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2606.03661, '2606.03661'] Let $\mathscr{L}_t[f(t);z]$ be the Laplace transform of the function $f(t)$ with conjugate variable $z$. Here $t$ denotes the time variable and $z$ is the Laplace dual variable. Then 
\begin{equation}

