\\         
\,   [R^{{\color{blue}F(X)}}]_{\mathcal{V}^{\rho/2}_2([s,t])}  &  \leq C\|F\|_{\mathcal{C}^2} \big(  [R^{{\color{blue}X}}]_{\mathcal{V}^{\rho/2}_2([s,t])}+ \|X'\|_{\mathcal{C}^0([s,t])}[R^{\color{blue}X}]_{\mathcal{V}^{\rho/2}_2([s,t])} [B]_{\mathcal{V}^\rho([s,t])}
  \\ 
