{"assumptions":[],"created_at":"2026-10-27T07:21:06.855435+00:00","domain":"probability theory","id":"claim_8d99662ddf9555a5dc4fd3592804185d2b807a841a815cc344fe392e9ab21925","kind":"theorem","schema_version":1,"statement":"[Theorem 12 (Local well-posedness in the weakened setting) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Suppose that Assumption~\ref{assumption_weakened_setting} holds. Then for all $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$, there exists a (unique) maximal solution $(u,\sigma)$ to \eqref{eq:AVP} such that a.s.\ $u\in C([0,\sigma);H^1(\sO))\cap L^2_{\loc}([0,\sigma);\nH^3(\sO))$. Moreover, the following blow-up criterion holds
\begin{equation}

    \P \bigg(\sigma < \infty ,\sup\limits_{t\in [0,\sigma)} \| u(t) \|_{H^1(\sO)} + \int_0^\sigma \|u(t) \|^2_{H^3(\sO)} \dt<\infty  \bigg) =0.
\end{equation}

In the noncritical case $d=3$ the blow-up criterion can be relaxed to 
\begin{equation}

    \P \bigg(\sigma < \infty ,\sup\limits_{t\in [0,\sigma)} \| u(t) \|_{H^1(\sO)} <\infty  \bigg) =0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.563225+00:00","domain":"probability theory","id":"claim_8d99b3fafdccd4ec92751d522719d4f5c92286d97da94f66f3b7b1ebfe524d55","kind":"concept","schema_version":1,"statement":"[Theorem t.main of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Under Assumption~(a.environment of the paper) with $d\ge 2$, $\mathbb{Q}$-almost surely,
	\begin{equation}
		\Bigl|\frac{\ell_X(\lambda)}{\lambda}-\Sigma_X e_1\Bigr|
		\le \lambda^{\beta^*}
		\qquad\text{for every }0<\lambda\le\lambda_0(\omega)\, ,
	\end{equation}
	where $\beta^*=\beta^*(d)\in(0,1/4)$ is a deterministic exponent and $\lambda_0\colon\Omega\to(0,1]$ is a random scale satisfying the tail bound
	\begin{equation}
		\mathbb{Q}\bigl(\lambda_0\le\lambda\bigr)\le C\exp\bigl(-c (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, ,
	\end{equation}
	with $C=C(d,\Lambda,r_0)<\infty$, $c=c(d,\Lambda,r_0)>0$, and an exponent $\sigma=\sigma(d,\Lambda,r_0)\in(0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:31.999575+00:00","domain":"probability theory","id":"claim_8d9a8f66378b475091cd3a7f28a1e55ef25f383209073d10c44a4d74fb94adb2","kind":"theorem","schema_version":1,"statement":"[Corollary 19 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] For every $\delta_0 >0$ there exist $\delta \leq \delta_0$ and $c>0$ such that the following holds for every $x_0\in D$.
	Suppose that one is given $T,C,\gamma>0$ such that for every $\varepsilon \leq \gamma r_\delta$,
	\begin{align}
		\bbP(X_T \in \sB(y,\varepsilon) \mid X_0 = x_0)\geq C \Area(\sB(y,\varepsilon))  \text{ for every } y \in \cD(\delta). 
	\end{align}
	Then, for $T' \de T + c \min\{1/\kappa^2, 1/\lambda_{\max}^2, \rho^2 \}$ and every measurable $E\subseteq D$,
	\begin{align}
		\bbP(X_{T'} \in E \mid X_0 = x_0)\geq (C/2)\Area(E).
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:52:51.760033+00:00","domain":"probability theory","id":"claim_8d9c07d4352b8b332d9fc7a3d7a495e857f5a924dfc2eecedaf13ab8d371a213","kind":"lemma","schema_version":1,"statement":"[Lemma S-lem of arXiv:2604.24914, 'SPDEs with time-independent\\ L\'evy colored noise'] Let $S \in \mathcal{O}_{C}'(\mathbb{R}^d)$ be such that $\int_{\mathbb{R}^d}|\mathcal{F} S(\xi)|^2 \mu(d\xi)<\infty$. Then $S \in \overline{\mathcal{P}}_{d}(\mathbb{R}^d)$, $S * \kappa \in L^2(\mathbb{R}^d)$ and 
