{"assumptions":[],"created_at":"2026-10-27T21:30:14.217355+00:00","domain":"probability theory","id":"claim_8df385a7379543450fa968e7fd6a91a73744d13c6aefd0e66f1c2e80de591342","kind":"lemma","schema_version":1,"statement":"[Lemma le:projection-geometry of arXiv:2608.19358, 'An optimal Poincaré inequality\\for the complex Ginibre log-gas'] The following properties hold.
  \begin{enumerate}
  \item
    $\mathcal{H}_n^{\mathrm{div},0}$ and
    $\overline{\mathcal{H}_n^{\mathrm{div},0}}$ are orthogonal.
  \item For every symmetric $f\in L^2(\mu_n)$,
    \begin{equation}
      \|Pf\|_{L^2(\mu_n)}^2+\|Qf\|_{L^2(\mu_n)}^2
      \leq
      \|f\|_{L^2(\mu_n)}^2+\|P_0f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \item If $f\in L^2(\mu_n)$ is real-valued, symmetric, and centered, then
    $h=Pf$, its pointwise complex conjugate $\overline h$, and
    $r=f-h-\overline h$, are three pairwise orthogonal functions in $L^2(\mu_n)$, and
    \begin{align}
      \|f\|_{L^2(\mu_n)}^2
      &=2\|h\|_{L^2(\mu_n)}^2+\|r\|_{L^2(\mu_n)}^2,
      \\
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      &=\frac{1}{2}\|f\|_{L^2(\mu_n)}^2
        +\frac{1}{2}\|r\|_{L^2(\mu_n)}^2.

    \end{align}
    In particular, we have the half-distance estimate 
    \begin{equation}
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      \geq\frac{1}{2}\|f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.473798+00:00","domain":"probability theory","id":"claim_8df4656cb5469fc3cc9221a20d7456feab94c965501cf22edd68ebf05b16cdf2","kind":"theorem","schema_version":1,"statement":"[Corollary LemmaCondExpII of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, for $t \in \mathbb{R}$ and $k=0, \dots, h+1$, 
\begin{align}  
\mathbb{E}[\varphi_{u_{1}}(t-S(u_{1})) \mid \mathcal{G}^{(k)}_{0}] \stackrel{a.s.}{=}  \varphi^{(0)}_{u_{1}}(t-S(u_{1})),
\end{align} 
\noindent while for $i \geq 2$,
\begin{align} 
\mathbb{E}[\varphi_{u_{i}}(t-S(u_{i})) \mid \mathcal{G}^{(k)}_{i-1}] \stackrel{a.s.}{=}  \varphi^{(k)}_{u_{i}}(t-S(u_{i})).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.304873+00:00","domain":"probability theory","id":"claim_8df46c1395a54741abbafa42fe43df065bff76db497639e7c7b562b40a4c8b18","kind":"lemma","schema_version":1,"statement":"[Lemma 11 (Uniform bounds for the unweighted partial traces) of arXiv:2606.24090, 'Sparsity-adaptive concentration inequalities for random polynomials'] Let $I\subseteq[d]$, $|I|=l$, let $\varepsilon\in\{0,1\}^l$, and let
