{"assumptions":[],"created_at":"2026-10-26T19:30:24.607175+00:00","domain":"probability theory","id":"claim_8e6a06a3f69bb5db9d72ed559afe6bf20d890ad392fe6ceebbdc36238b17ce3a","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] Fix $t,\tau\in{\mathbb R}_+$, and let $\bm{Q}(0)= \bm{0}$, $\bm{\lambda}(0)=\bm{\overline{\lambda}}$. Then, for any  $\bm{y},\bm{z}\in[-1,1]^d$, $\bm{r},\bm{s} \in \rr_+^d$,
\begin{align}
\begin{split}
    \zeta_\tau(t,\bm{r},\bm{y},\bm{s},\bm{z}) &= \zeta(t, \bm{y}\odot\hat{\bm{z}}(t), \bm{r} + \tilde{\bm{s}}(t+\tau))
    \prod_{j=1}^d \exp\Big(-\overline{\lambda}_j \alpha_j \int_t^{t+\tau} \tilde{s}_j(u)\ddiff u\Big)\\
    &=\prod_{j=1}^d
    \exp\Big(-\overline{\lambda}_j\tilde{r}_j(t) - \overline{\lambda}_j\alpha_j \int_0^t \tilde{r}_j(v)\ddiff v -\overline{\lambda}_j \alpha_j \int_t^{t+\tau} \tilde{s}_j(u)\ddiff u\Big).
\end{split}
\end{align}
Here $\zeta(\cdot)$ is given by Eqn.~\eqref{eq: zeta characterization in terms of s(u)}, and, for $j\in[d]$, the functions $\hat{z}_j(\cdot)$, $\tilde{s}_j(\cdot)$ and $\tilde{r}_j(\cdot)$ satisfy
\begin{align} 
\begin{split}
    &\hat{z}_j(u) = 1 + (z_j-1)e^{-\mu_j(t+\tau-u)}, \\
    &\frac{\mathrm{d} \tilde{s}_j(u)}{\mathrm{d} u} + \alpha_j \tilde{s}_j(u) + \big(1 + (z_j - 1)e^{-\mu_j(u-t)}\big) \beta_j(\tilde{\bm{s}}(u)) - 1 = 0,\\
    &\frac{\ddiff \tilde{r}_j(v)}{\ddiff v} + \alpha_j \tilde{r}_j(v) + \big(1 + (y_j-1)e^{-\mu_jv} + y_j(z_j-1)e^{-\mu_j(v+\tau)}\big)\beta(\tilde{\bm{r}}(v)) - 1 = 0,\\
\end{split}
\end{align}
with boundary condition $\tilde{s}_j(t) = s_j$ and $\tilde{r}_j(0) = r_j+\tilde{s}_j(t+\tau)$, and where $0\leqslant v \leqslant t$ and $t \leqslant u \leqslant t+\tau$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:01:25.660090+00:00","domain":"probability theory","id":"claim_8e7210d6bf0ef6e20e5a48e08c5a94bca56c74e4537ac66aa7269d98b120476e","kind":"lemma","schema_version":1,"statement":"[Lem Lemma: Inverse limit approximation of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] Let $Y$ be an ergodic $\mathbb{Z}^d$-system with $f_1,f_2 \in L^\infty(Y)$ taking values in $[0, 1]$, and let $\underline{Y_1}, \underline{Y_2}$ be the point processes obtained by drawing $y \in Y$ at random and keeping each $t \in \mathbb{Z}^d$ independently with probability $f_1((-t) \cdot y)$ and $f_2((-t) \cdot y)$ respectively. 
    Then there is a coupling of $\underline{Y_1}$ and $\underline{Y_2}$ such that
    $$d(\underline{Y_1} \Delta \underline{Y_2}) \leq \|f_1-f_2 \|_2$$
    almost surely - where for a subset $A \subset \mathbb{Z}^d$, $d(A)$ denotes the \emph{density}
    $$ d(A) = \limsup_{N \rightarrow \infty} \frac{\vert A \cap [-N,N]^d\vert }{(2N+1)^d}.$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.065336+00:00","domain":"probability theory","id":"claim_8e7307d28304d01cdea7f7d8ee7382e5400d638cb9186b2b96f0204495e1b19f","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Let $\alpha\in [\alpha_0,2)$. Suppose $u$ satisfies 
    \[
    L_\alpha u = g ~\text{ in } B_2, 
    \]
    where $g\in L^\infty(B_2)$. Then 
    \begin{equation}
        \begin{aligned}
        \|u\|_{C^\alpha(B_{1})} \leq& C (2-\alpha)^{-1} \|g\|_{L^\infty(B_2)} \\
        &+ C (2 - \alpha)^{-\frac{\alpha}{\alpha - 1}} \left( 1+\|b\|_{L^\infty(B_2)}\right)^{\frac{\alpha}{\alpha-1}}  \|u\|_{L^\infty(B_2)}+C \int_{B_2^c} \frac{|u(y)|}{|y|^{d+\alpha}} \d y
        \end{aligned}
    \end{equation}
    and 
    \begin{equation}
        \begin{aligned}
        \|u\|_{C^{\frac{3}{2}}(B_{1})} \leq& C \|g\|_{L^\infty(B_2)} + C \left[ 1+\|b\|_{L^\infty(B_2)}\right]^{\frac{7}{3}}  \|u\|_{L^\infty(B_2)}+C \int_{B_2^c} \frac{|u(y)|}{|y|^{d+\alpha}} \d y, 
        \end{aligned}
    \end{equation}
    where the constant $C$ does not depend on $\alpha$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:47:04.924712+00:00","domain":"probability theory","id":"claim_8e73b9c802b5877eb04e6c5aa587922e9f439c706aa562621efd550312f53d8c","kind":"lemma","schema_version":1,"statement":"[Lemma TechEst of arXiv:2412.02160, 'A functional central limit theorem for weighted occupancy processes of the Karlin model'] Let $(b_j)_{j\in{\mathbb N}_0}$ be a sequence such that $b_0 = 0$, $|b_j| \le Cj^{\alpha'}$ for some $\alpha'<\alpha$. Fix~$t>0$. Then, 
    \begin{equation}
        \sum_{\ell=\ell_n+1}^\infty\mathbb{E} b_{N_\ell(nt)}\sim \sigma_n^2  \alpha t^\alpha \sum_{j=1}^\infty \frac{b_j \gamma(j-\alpha,t\epsilon^{-{1}/{\alpha}})}{j!},
    \end{equation}
    as $n\to\infty$, and there exists a constant $C>0$ such that
       \begin{equation}
    \summ \ell1{\ell_n}{\mathbb E} |b_{N_\ell(nt)}| \le C\sigma_n^2t^{\alpha'}\epsilon^{1-\alpha'/\alpha}
    \end{equation}
    for all $n\in{\mathbb N}$. As a consequence, there exists a constant $C>0$ such that for all $t\in(0,1]$, 
\[
    \sif\ell1{\mathbb E} |b_{N_\ell(nt)}|\le C \sigma_n^2t^{\alpha'}.
\]","status":"unverified"}

