{"assumptions":[],"created_at":"2026-10-27T21:01:39.422382+00:00","domain":"probability theory","id":"claim_8f26af1f84edeb1cd69e97c80dff7be0f50268e3376b04165bfc95c6e1825132","kind":"definition","schema_version":1,"statement":"[Definition conditionnal expectation of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $\mathcal{A}$ be a unital algebra and $\mathcal{B}$ a unital subalgebra of $\mathcal{A}$. An \emph{operator-valued probability space} $(\mathcal{A},\mathcal{B},\Delta)$ consists of $\mathcal{B}\subset\mathcal{A}$ and a map $\Delta :\mathcal{A}\rightarrow\mathcal{B}$ satisfying
        \begin{align}
            \Delta(b)&=b\quad\quad\forall b\in\mathcal{B},\\
            \Delta(b_{1}ab_{2})&=b_{1}\Delta(a)b_{2}\quad\quad\forall a\in\mathcal{A},\quad\forall b_{1},b_{2}\in\mathcal{B}.
        \end{align}
        Such a map $\Delta$ is called a \emph{conditional expectation}.

        Let $K$ be an arbitrary index set. We write $\mathcal{B}\langle X_{k}: k \in K\rangle$ for the free non commutating algebra generated by $\mathcal{B}$ and the non commutating indeterminate $(X_{k})_{k\in K}$. We call an element of $\mathcal{B}\langle X_{k}: k \in K\rangle$ a $\mathcal{B}$-valued polynomial. The \emph{operator-valued distribution} (or $\Delta$-distribution for short) of a family $\mathbf{A} = (A^{(k)} )_{k\in K} \subset \mathcal{A}$ is the linear map of operator-valued moments
        \begin{equation}
            \Delta_{\mathbf{A}}:\mathcal{B}\langle X_{k}: k \in K\rangle\rightarrow\mathcal{B},\quad P\mapsto\Delta(P(\mathbf{A})).
        \end{equation}

        We say that the families $\mathbf{A}_{1} = (A^{(k)}_{1} )_{k\in K} ,\cdots , \mathbf{A}_{L} = (A^{(k)}_{L} )_{k\in K} \subset \mathcal{A}$ are \emph{free with amalgamation over $\mathcal{B}$} (or free over $\mathcal{B}$ for short) if
        \begin{equation}
            \Delta\left((P_{1}(\mathbf{A}_{l_{1}})-\Delta(P_{1}(\mathbf{A}_{l_{1}})))\cdots(P_{n}(\mathbf{A}_{l_{n}})-\Delta(P_{n}(\mathbf{A}_{l_{n}})))\right)=0,
        \end{equation}
        for any $\mathcal{B}$-polynomials $P_{1},\cdots,P_{n}\in\mathcal{B}\langle X_{k}: k \in K\rangle$ whenever $l_{j}\neq l_{j+1}$ for $1\leq j\leq n-1$.","status":"unverified"}

