{"assumptions":[],"created_at":"2026-10-27T11:43:45.398111+00:00","domain":"probability theory","id":"claim_8f872992d9a0b5500ac5b5df46a3ea162eb22e7a4189917349b677795fe96a6a","kind":"theorem","schema_version":1,"statement":"[Proposition 8 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q=(q_1,\ldots,q_m)$ be a Bohnenblust--Hille exponent.

\begin{enumerate}
\item If $p=\min_{1\le i\le m}q_i$ and $\mathbf q^+=(q_1,\ldots,q_m,2)$, then
\[
 C_{\mathbf q^+}^{(m+1)}\le A_p^{-1}C_{\mathbf q}^{(m)}.
\]

\item Suppose that two adjacent coordinates of $\mathbf q$ are $(q,p)$ with $1\le p\le q\le2$, and let $\mathbf q'$ be obtained by replacing them by $(p,q)$. Then
\[
 \textcolor{black}{C_{\mathbf q}^{(m)}\le C_{\mathbf q'}^{(m)}.}
\]
Consequently, if $\mathbf t$ is any permutation of the vector with $k$ copies of $p$ followed by $m-k$ copies of $2$, then
\[
 \textcolor{black}{C_{\mathbf t}^{(m)}
 \le C_{(\underbrace{p,\ldots,p}_{k},\underbrace{2,\ldots,2}_{m-k})}^{(m)}.}
\]

\item Let $2\le k\le m$. If $p_k\le q_i\le2$ for every $1\le i\le m$, then
\begin{equation}
 C_{\mathbf q}^{(m)}
 \le A_{p_k}^{-(m-k)}B_{\R,k}^{\mult}.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.332182+00:00","domain":"probability theory","id":"claim_8f883c1667496cd1dc7ac75a8388d8e41bec15ef2070377f9ad716041d3d2d8f","kind":"concept","schema_version":1,"statement":"[Theorem 5 (Annealed heat kernel bound) of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $m_{0} > d$, $p \in \big(\max\{1,\frac{d}{m_{0}-2}\}, \infty\big]$ and $q \in (1,\infty]$ be satisfying \eqref{a1-1-2}.

  \begin{enumerate}[(i)]
  \item
    For $d \geq 3$ and suppose there exist $p_{1}, p_{2} \in (1, \infty]$ and $q_{1}, q_{2} \in (1, \infty]$ satisfying

    \begin{align}
      \frac{1}{p_1} + \frac{1}{p_2} \;=\; 1,
      \qquad
      \frac{1}{q_1} + \frac{1}{q_2} \;=\; 1,
    \end{align}

    such that

    \begin{align}
      \theta^{\omega}(0), \mu^{\omega}_{m_{0}}(0) \in L^{\tilde p}(\prob),
      \qquad
      \nu^{\omega}(0) \in L^{\tilde q}(\prob),
      \qquad
      \frac{\mu^{\omega}_{m_{0}}(0)}{\theta^{\omega}(0)}\in L^{q_2}(\prob),
    \end{align}

    where

    \begin{align} 
      \tilde p\ldef\max\Big\{p,p_1q_1\Big(1+\frac{1+m_{0}\gamma}{\beta}\Big)\Big\},\quad \tilde q \ldef \max\Big\{q,p_2q_1\Big(1+\frac{1+m_{0}\gamma}{\beta}\Big)\Big\}.
    \end{align}

    Then there exists a constant $C_5\in (0,\infty)$ such that

    \begin{align}
      \mean\bigl[p^{\omega}(t, x, y) \bigr]
      \;\leq\;
      C_{5}\, t^{-d/2},
      \qquad  \forall\, x, y \in \bbZ^{d}, t > 0.
    \end{align}

  \item
    Let $d=2$ and  suppose there exist $p_1,p_2\in (1, \infty]$ and $q_1,q_2\in (1, \infty]$ satisfying \eqref{t1-3-2a}
    such that

    \begin{align}

      \theta^{\omega}(0), \mu^{\omega}_{m_{0}}(0) \in L^{2\tilde{p}}(\prob),
      \quad
      \nu^{\omega}(0) \in L^{2\tilde{q}}(\prob),
      \quad
      \frac{\mu^{\omega}_{m_{0}}(0)}{\theta^{\omega}(0)} \in L^{2q_2}(\prob),
    \end{align}

    and

    \begin{align} 
      \frac{
        \bigl(
          1 \vee \theta^{\omega}(0) \vee \mu^{\omega}_{m_{0}}(0)
        \bigr)^2}{\theta^{\omega}(0)} \in L^{1}(\prob)
    \end{align}

    with $\tilde{p}$ and $\tilde{q}$ as defined in \eqref{eq:defTildep0}. Then there exists $C_{6} \in (0, \infty)$ such that

    \begin{align}
      \mean\bigl[p^{\omega}(t, x, y)\bigr]
      \;\leq\;
      C_{6}\,
      \Bigl(
        1 + \log t\,
        \indicator_{\{t \geq 2\}}
      \Bigr)\, t^{-1},
      \qquad \forall\, x,y \in \bbZ^{d}, t > 0.
    \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:53:30.526331+00:00","domain":"probability theory","id":"claim_8f89fb50f10280ecf948a3f071bb19bcb3c5b053209947ea7d9542780fffc815","kind":"theorem","schema_version":1,"statement":"[Prop eq:rescaled of arXiv:2505.21770, 'Gradient-flow SDEs have unique transient population dynamics'] If $p_\mathrm{eq}$ is a stationary distribution for the SDE (equation eq:overdamped_langevin_SDE of the paper), then it is also a stationary distribution for the ``rescaled'' SDE
