{"assumptions":[],"created_at":"2026-10-26T19:43:16.150767+00:00","domain":"probability theory","id":"claim_9087c79f28c5fb14bd59ce084d4e00717ad29931dd97e0e3dcc8c9fc48dd40f1","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] For arbitrary $\epsilon>0$ and $t,\delta\in (0,\infty)\bigcap\mathbb{Q}$, there exists a constant $N(t,\delta,\epsilon)\in\mathbb{N}$ such that 
        \begin{equation*}
                \sup\limits_{n}\mathbb{P}\left( \sum\limits_{i=N(t,\delta,\epsilon)+1}^\infty \vert\tilde{X}_i^{(n)}(t) \vert^2 \rho(i)\geq\delta \right)\leq \frac{\epsilon}{2^{m(t)+m(\delta)}},
        \end{equation*}
        where $m$ is a bijection between the rational numbers in $(0,+\infty)$ and the natural numbers $\mathbb{N}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:19:42.667466+00:00","domain":"probability theory","id":"claim_9089d7923a55dd6060eeb8fd04d6658ac101b5bbaf62791fc602064cadb4dd9c","kind":"theorem","schema_version":1,"statement":"[Proposition 13 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:increments_stochastic}
