{"assumptions":[],"created_at":"2026-10-26T19:31:49.833317+00:00","domain":"probability theory","id":"claim_90bc4bdf15588efc05e2f40b1bed6df5cf81b59bdb9d9931261675444c91d970","kind":"theorem","schema_version":1,"statement":"[Corollary 7 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] Suppose $p$ satisfies Condition \ref{lighttail}, $\nu$ satisfies Condition \ref{initialprofilecond}, and $\eta_0 \sim \nu_L$, where $L \uparrow \infty$ as $t \to \infty$. Let $0 \le m_0 < m_1 < \cdots < m_k$. 

\begin{enumerate}[(a)]

\item If $L \big(\frac{\log t}{t}\big)^{1/2} \to \psi \in (0, \infty]$, then 
\begin{align*}
	&\bigg( \frac{X^{(m_0)}_{t/K}}{\sigma b_t} - a_t, \ldots,  \frac{X^{(m_k)}_{t/K}}{\sigma b_t} - a_t \bigg) \underset{t\to\infty}{\Longrightarrow} \bigg( - \log  \frac{T_{m_0}}{c_\nu\sigma(1 - e^{-\psi/\sigma})}, \ldots, - \log  \frac{T_{m_k}}{c_\nu\sigma(1 - e^{-\psi/\sigma})} \bigg). 
\end{align*}

\item If $L \big(\frac{\log t}{t}\big)^{1/2} \to 0$, then 
\begin{align*}
	&\bigg( \frac{X^{(m_0)}_{t/K}}{\sigma b_{t,L}} - a_{t,L}, \ldots,  \frac{X^{(m_k)}_{t/K}}{\sigma b_{t,L}} - a_{t,L} \bigg) \underset{t\to\infty}{\Longrightarrow} \bigg( - \log  \frac{T_{m_0}}{c_\nu}, \ldots, - \log  \frac{T_{m_k}}{c_\nu} \bigg). 
\end{align*}

