			\ \ \ \ \ \ \ \ -n\int_t^T(\bar{Y}^n_s-U_s)^+ds-\int_t^T \bar{Z}^n_sdB_s+(\bar{A}^n_T-\bar{A}^n_t), \\
			\bar{Y}^n_t\geq L_t, \forall t\in[0,T], \{-\int_0^t (\bar{Y}^n_s-L_s)d\bar{A}^n_s\}_{t\in[0,T]} \textrm{ is a non-increasing $G$-martingale}.
		\end{cases}
