{"assumptions":[],"created_at":"2026-10-27T08:44:39.744364+00:00","domain":"probability theory","id":"claim_917d8894af570f0c54612f5a07f0894db64a834b7328e75b5669d40a0cab6467","kind":"concept","schema_version":1,"statement":"[Lemma 5 (Lemma 3.2 in \cite{Isotropic_local}) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Let $\xi$ and $\zeta$ be families of nonnegative random variables.
\begin{itemize}
  \item[(i)] Suppose that $\xi (u,v)\prec \zeta(u,v)$ uniformly in $u\in U$ and $v\in V$. If $|V|\le n^C$ for some constant $C$, then $\sum_{v\in V} \xi(u,v) \prec \sum_{v\in V} \zeta(u,v)$ uniformly in $u$.

\item[(ii)] If $\xi_1 (u)\prec \zeta_1(u)$ and $\xi_2 (u)\prec \zeta_2(u)$ uniformly in $u\in U$, then $\xi_1(u)\xi_2(u) \prec \zeta_1(u)\zeta_2(u)$ uniformly in $u$.

\item[(iii)] Suppose that $\psi(u)\ge n^{-C}$ is deterministic and $\xi(u)$ satisfies $\mathbb E[\xi(u)^2] \le n^C$ for all $u$. Then if $\xi(u)\prec \psi(u)$ uniformly in $u$, we have $\mathbb E\xi(u) \prec \psi(u)$ uniformly in $u$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:15:34.406022+00:00","domain":"probability theory","id":"claim_917f7b25f2ff5b150277b36c56764c6517febc96d9cc0e69f8d5e6038caf7155","kind":"lemma","schema_version":1,"statement":"[Lemma 5 (Divided-power Koszul--Schur complex) of arXiv:2609.03282, 'Characteristic-free characterizations of projective space for smooth toric varieties'] Let
\begin{equation}
0\longrightarrow\cA\xrightarrow{\iota}\cB\xrightarrow{\pi}\cC\longrightarrow0
\end{equation}
be a short exact sequence of vector bundles on a scheme $S$.  For every integer $m\geq1$, there is an exact complex
\begin{equation}
\begin{split}
0\longrightarrow\Gamma^m\cA
&\xrightarrow{d_m}\Gamma^{m-1}\cA\otimes\cB
\longrightarrow\cdots\longrightarrow
\Gamma^q\cA\otimes\bigwedge^{m-q}\cB\\
&\xrightarrow{d_q}\Gamma^{q-1}\cA\otimes\bigwedge^{m-q+1}\cB
\longrightarrow\cdots\longrightarrow
\bigwedge^m\cB
\xrightarrow{\wedge^m\pi}\bigwedge^m\cC
\longrightarrow0.
\end{split}
\end{equation}
For $1\leq q\leq m$, the differential $d_q$ is the composite
\begin{equation}
\begin{split}
\Gamma^q\cA\otimes\bigwedge^{m-q}\cB
&\xrightarrow{\Delta_{q-1,1}\otimes\id}
\Gamma^{q-1}\cA\otimes\cA\otimes\bigwedge^{m-q}\cB\\
&\xrightarrow{\id\otimes(\iota\wedge-)}
\Gamma^{q-1}\cA\otimes\bigwedge^{m-q+1}\cB,
\end{split}
\end{equation}
where $\Delta_{q-1,1}$ is the $(q-1,1)$ component of the standard comultiplication on the divided-power algebra (see \eqref{eq:divided-comultiplication} below).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.463272+00:00","domain":"probability theory","id":"claim_9184666aa7e74e4a2b5c6f8accb7754e4de42254cff4368183403a1921b1c8c0","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] Fix a monotone set $A\subseteq \{0,1\}^{n}$. For all $f:A\rightarrow\ensuremath{\mathbb{R}}$, we define\footnote{
