{"assumptions":[],"created_at":"2026-10-26T20:58:09.066965+00:00","domain":"probability theory","id":"claim_923816e880badd3c35634f0b799058026ce0a59f75121b86a73b7b5e4a8af725","kind":"concept","schema_version":1,"statement":"[Theorem 14 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\alpha > 0$ and $\kappa \geq \kappa_c$. There exist $\lambda = \lambda(\alpha, \kappa)$ and $\psi = \psi(\alpha,\kappa) > 0$ such that for all $r \geq 1$,
    \begin{equation}
        \P_{\alpha,\kappa}( 0 \leftrightarrow x_r) = \psi\lambda^r\, (1 + o_{\alpha,\kappa}(1)). 
    \end{equation}
    Furthermore, $\lambda$ is monotone increasing in $\alpha$, and it is the unique solution in $(\tau^2_\kappa, 1)$ to
    \begin{equation} 
         (\lambda^{-1} -1) \sum_{n \geq 0} \big( (1-\tau_\kappa^{2(n+1)})^{-\alpha} -1 \big) \lambda^{-n}  = 1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.888432+00:00","domain":"probability theory","id":"claim_923bad3f0bfd5d4d448267451ab6eb0f8207c3a27efc4b424e0937427f3c2d95","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2607.17087, 'Transportation-cost inequalities for invariant measures of stochastic reaction-diffusion e'] Let $p_{t}(x,y)$ be the heat kernel of the operator $\frac{1}{2}\partial_{xx}$ on $[0,1]$ with the Dirichlet boundary condition, and
\begin{align*}
 P_t f(x) := \int_{0}^{1} p_{t}(x,y) f(y)dy, \quad x\in [0,1].
\end{align*}
Then for any $p> 1$,
\begin{align}
  \sup_{x\in [0,1]} |P_t f(x)| \leq C_{p\rightarrow\infty} t^{-\frac{1}{2p}}\Vert f\Vert_{L^p([0,1])},
\end{align}
where
\begin{align}
  C_{p\rightarrow\infty}:= (2\pi)^{-\frac1{2p}} \left(\frac{p-1}{p}\right)^{\frac{p-1}{2p}}.
\end{align}
The constant $C_{p\rightarrow\infty}$ can be bounded by
\begin{align}
  C_{p\rightarrow\infty} \leq \left(\frac{1}{2\sqrt{\pi}}\right)^{\frac{1}{p}}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.188392+00:00","domain":"probability theory","id":"claim_923be0bc9fb8b28bb3e9f26e12321aff9a0977f219af8c4a9e79c3d1f6450c6e","kind":"definition","schema_version":1,"statement":"[Definition def:Irb of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] Fix $\varepsilon \in (0,\tfrac{1}{9})$, $\Delta=N^{2/3+\varepsilon}$, $a_0^+=N+\Delta$ 
and set
\begin{align*}

\mathfrak I_{\pm r} &:=\pm [a^+_{r}- \Delta,a^+_{r-1}-\Delta)\qquad(1 \le r \le K)\,,\\

\mathfrak I_{K+1} &:= \;\;\, (a^-_K+\Delta,a^+_K-\Delta) \,.
\end{align*}    
Consider the event 
\begin{equation}
A := \{ \underline{\widetilde \phi} (N)=\underline 0\} \cap A^- \cap A^+ \,,
\end{equation}
where
\begin{equation}

A^\pm := \big\{\widetilde \phi_{r} \ge \cdots \ge \widetilde \phi_{K} \ge 0
\quad \mbox{on} \quad \mathfrak I_{\pm r}, \quad \mbox{for} \quad 1 \le r \le K\big\} \,.
\end{equation}
Note that 
$\{\mathfrak I_r\}$ 
partitions $(-N,N)$ into $2K+1$ sub-intervals,
as depicted in (fig:tilde-phi-events-A-B of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.465207+00:00","domain":"probability theory","id":"claim_923c0227c97ee32c1fa4cc1c6558b845b61fb8da150e490660a7888b599e81c5","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2606.29131, '2606.29131'] Suppose that \eqref{t1-1-1} holds for some $\beta>0$. Let $\Upsilon_\e^1 f(x,y)$ be defined by \eqref{l2-1-3a}. Then there exists a positive constant $C_7:=C_7(\beta)$ such that for every $f\in \M_\beta$, $x\in \R^d$ and $y\in \T^d$,
\begin{equation}
|\Upsilon_\e^1 f(x,y)|\le C_7\left(\sum_{i=0}^2\|f\|_{\M_{\beta},i}\right)(1+|x|)^{-d-\beta_0}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.713707+00:00","domain":"probability theory","id":"claim_923cc84990db54efe048179b575f7d4a812f099ee0be9ad1d149e9270eb87b4b","kind":"lemma","schema_version":1,"statement":"[Lem l:1104.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $\widehat{\eta}_{\rm D}$ be limit of $\{\widehat{\eta}_{n,r_n}\}$ along some subsequence, with $\{r_n\}$ as in~(equation e:1.11i of the paper). Then, there exists a coupling between $\widehat{\eta}_{\rm D}$, the random measure $\eta_{\rm D}$ from~(equation e:1.10i of the paper), and $h_{\rm D}^\psi$ from~(equation e:1104.13 of the paper), such that $\widehat{\eta}_{\rm D}$ and $h_{\rm D}^\psi$ are independent and 
\begin{equation}

\widehat{\eta}_{\rm D} \circ \tau^{-1}_{h^{\psi}_{\rm D}} = \eta_{\rm D} \,,
\end{equation}
where $\tau_{\psi}: {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2} \to {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2}$ is the translation operator
\begin{equation}
	\tau_{\psi}(x,s,\omega) =(x,s + \psi(x), \omega) \,.
\end{equation}
Moreover, along the above subsequence we have
\begin{equation}
	 \big(\eta_{n,r_n}, \widehat{\eta}_{n,r_n}, h_n^\psi\big) \Longrightarrow \big(\eta_{\rm D}, \widehat{\eta}_{\rm D}, h^\psi_{\rm D}\big) \,.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.245146+00:00","domain":"probability theory","id":"claim_923df2cca1a03a7fb2492a2692006dfaa67c8deda6a39e371a2573ef7cae0627","kind":"lemma","schema_version":1,"statement":"[Lemma eq: short first row of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] For all $\lambda=(\lambda_1,\lambda_2,\ldots)\vdash n$, we have
\begin{equation}
-\frac{\lambda_1'}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le\frac{\lambda_1}{n},
\end{equation}
\begin{equation}
-1+2\frac{\lambda_1}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le1-2\frac{\lambda_1}{n}+2\left(\frac{\lambda_1}{n}\right)^2.
\end{equation}
In particular, when $\lambda_1\ge n-n^{o(1)}$, set $r:=n-\lambda_1$. Then, we have
\begin{equation}
\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}=1-2\frac{r}{n}+O(n^{-2+o(1)}).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.446421+00:00","domain":"probability theory","id":"claim_923e4a6a7798862baf5cb1ff598bb0813b8c18180995ff16fde1b008ce437cdd","kind":"definition","schema_version":1,"statement":"[Def ass of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $ \{\mu_N\}_{N\geq 1} $ be a sequence of probability measures on $ \Omega_N $, and let $g:\mathbb{T}\to[0,1] $ be a measurable function. If, for any continuous function $ G:\mathbb{T}\to\mathbb{R} $ and every $ \delta>0 $, it holds
	\begin{align*}
		\lim_{N\to+\infty}\mu_N
		\left(
		\eta\in\Omega_N
		:\big|\pi^N(\eta,G)-\langle g,G\rangle\big|>\delta
		\right)
		=0,
	\end{align*}
	we say that the sequence $ \{\mu_N\}_{N\geq 1} $ is a local equilibrium measure associated with the profile $ g $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.550641+00:00","domain":"probability theory","id":"claim_923e54303387905389ced97914c9fef794ae3a4f26de7b917ddd7b7463be755c","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2604.01978, 'Homogenized Transformers'] Under Assumption \ref{ass:high_order_short}, there exist $C_1,C_2>0$ independent of $\alpha, \eta, L$ such that
\begin{enumerate}
\item $b\in C^4((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$.
\smallskip
\item We have
\begin{equation*}
    \upsigma \coloneqq \max_{X\in(\S^{d-1})^n}\|G(X,\cdot)\|_{L^2({\uprho_*})}<\infty
\end{equation*}
and 
\begin{equation*}
     \underset{X \in (\S^{d-1})^{n}}{\max}\|G(X,\cdot)\|_{L^3({\uprho_*})}\leq C_1\upsigma .
\end{equation*}
\smallskip 
\item For ${\uprho_*}$-a.e.\ $\bm{\theta}$, $G(\cdot,\bm{\theta})\in C^5((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$ and
\begin{equation*}
    \left\|\Big\|G(\cdot, \bm\theta)\Big\|_{C^5} \right\|_{L^2({\uprho_*})} + \left\|\Big\|\nabla_{G(\cdot,\bm{\theta})}G(\cdot,\bm{\theta})\Big\|_{C^5}\right\|_{L^2({\uprho_*})} \leq C_2 \upsigma .
\end{equation*}
\end{enumerate}
Moreover we can choose $C_1=O(1+\frac{\sigma_{\bA}\|\E\bV\|_{\mathrm{op}}\upbeta}{\sigma_{\bV}})$ and $C_2=O(1+\upbeta^{10}\sigma_{\bA}^{10}d^5)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.504483+00:00","domain":"probability theory","id":"claim_924c6489049599f0191ae577647e472f3af08711fbc8f64d518a59eead88f356","kind":"definition","schema_version":1,"statement":"[Definition 80 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following notions:
\begin{enumerate}
\item We say that a path $Y \in \hat{\calc}^{\alpha}([0,T],\bar{W})$ is \emph{mildly controlled} by $X$ if there exists $Y' \in \hat{\calc}^{\alpha}([0,T], L(V,\bar{W}))$ such that for the remainder term $R^Y : [0,T]^2 \to \bar{W}$ given by
\begin{align}
R_{s,t}^Y := \hat{\delta} Y_{s,t} - S_{t-s} Y_s' X_{s,t} \quad \text{for all $s,t \in [0,T]$.}
\end{align}
we have $R^Y \in \calc_2^{2 \alpha}([0,T]^2,\bar{W})$, where $\hat{\delta} Y_{s,t} = Y_t - S_{t-s} Y_s$.

\item This defines the space of \emph{mildly controlled rough paths}, and we write
\begin{align*}
(Y,Y') \in \scrd_{S,X}^{2 \alpha}([0,T], \bar{W}).
\end{align*}
\item We call $Y'$ a \emph{mild Gubinelli derivative} of $Y$ (with respect to $X$).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:05:28.081079+00:00","domain":"probability theory","id":"claim_9253f29212a0edc45ac3c4ca6a96e00cd5aeec7107b0c334f7b9a0627dcb6a6f","kind":"concept","schema_version":1,"statement":"[Coro ERmb of arXiv:2601.20502, 'Optimal matching under size priority'] Under the same condition and notation of Theorem~(thm:mandatory of the paper), we have that
    \begin{align}
        &\frac{1}{|E(G_n)|}\sum_{e \in E(G_n)} \mathbbm{1}_{e \in \bigcap_{M \in M_{n,\max}}M} \overset{\mathbb{P}}{\longrightarrow} \gamma^2, \\
        &\frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{e \in \bigcap_{M \in M_{n,\max}}M^{\complement}} \overset{\mathbb{P}}{\longrightarrow} (1-\gamma)^2.
    \end{align}
    where the convergence holds in probability and $\gamma$ is the unique fixed point of $t \mapsto \hat{\phi}(1-t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.769407+00:00","domain":"probability theory","id":"claim_92559bc3edd78416577f3005cd30fc2a63a55976f77e8fd6d2c1447941ca1163","kind":"definition","schema_version":1,"statement":"[Defi smooth of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] {Revuz}}}}]
{\rm Let $\nu$ be a $\sigma$-finite Borel measure. We say that $\nu$ is \emph{smooth (in the strict sense)} if:
\begin{enumerate}
\item[\rm(1)] $\nu$ does not charge any semi-polar sets.
\item[\rm(2)] There exists an increasing sequence of Borel sets 
$\{E_n\}$ such that $X=\bigcup_{n=1}^{\infty}E_n$ and 
\begin{enumerate}
\item[\rm(a)] $\nu(E_n)<\infty$ for each $n\in\mathbb{N}$.
\item[\rm(b)] $\int_{E_n}G_1(x,y)d\nu(y)$ is bounded with respect to $x$.
\item[\rm(c)] Let $T_n:=\sigma_{X\setminus E_n}$ and $T:=\lim_{n\to\infty}T_n$. Then, it should hold 
\begin{align*}
\mathbb{P}_x(T\geq\zeta)=1\quad\text{ for any }\quad x\in X.
\end{align*}
\end{enumerate}
\end{enumerate}
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:38:17.795113+00:00","domain":"probability theory","id":"claim_9256e37ab636e8ce7ab03f05ad8680e0d395b61ba43a551b78b84a6eadd88027","kind":"lemma","schema_version":1,"statement":"[Lemma lem:renormalization_constants of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] Let $0\leq\gamma<1$ and $1<\delta \leq\infty$ and assume $\gamma = 0$ and $\delta = \infty$ do not occur simultaneously. For every $a>0$ there exist constants $0<c(a)<C(a)$ (depending on $\gamma$ and $\delta$) such that
for all $0<u<1$  and $R>0$ we have
\begin{align}
     c(a) \pi_{(u),R} \leq & \pi_{(u),aR} \leq C(a) \pi_{(u),R}, \\
    c(a) \pi^{(2)}_{(u),R} \leq & \pi^{(2)}_{(u),aR} \leq C(a) \pi^{(2)}_{(u),R}.
\end{align}
 Moreover, for every $\varepsilon>0$ and $a,b>0$, there exist constants 
 $0<c(a,b,\varepsilon)<C(a,b,\varepsilon)$ (again, depending on $\gamma$ and $\delta$) such that, for $r,R>0$ with 
 $0<\frac{r}{R}\leq (1-\varepsilon)(\frac{b}{a}\wedge1)$, we have
 \begin{align}
     c(a,b,\varepsilon) \pi_{r,R} \leq & \pi_{ar, bR} \leq C(a,b,\varepsilon) \pi_{r,R}, \\
     c(a,b,\varepsilon) \pi^{(2)}_{r,R} \leq & \pi^{(2)}_{ar, bR} \leq C(a,b,\varepsilon) \pi^{(2)}_{r,R}.
 \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.128361+00:00","domain":"probability theory","id":"claim_9259eb3fb0fd54f7255e8afd85e8774fb3061cc6c41c7e166048acc616a33657","kind":"definition","schema_version":1,"statement":"[Definition b2 of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] Let $B$ be a fractional Brownian motion, with covariance function given by~(equation fBm:cov of the paper).
Recall that the graph measure $\mu_G$ of $B$ is given by (equation mu_G of the paper).
Then the image measure of $B$ is defined on Borel sets $F \subset \mathbb R$ by
\begin{align}
	\nu(F) = \mu_G([0,1] \times F) = \int_0^1 {\bf 1}_{\{B_t \in F\}} \, dt.
\end{align}
Its Fourier transform $\hat{\nu}$ is given for $\xi_2 \in \mathbb R$ by
\begin{align*}
	\hat{\nu}(\xi_2) = \int_0^1 e^{-2\pi i \xi_2 B_t} dt.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.722667+00:00","domain":"probability theory","id":"claim_926358afbaa1cef7b1446e3ddf5d844720fec5688113d8f6b0dbaa58ae7806cd","kind":"concept","schema_version":1,"statement":"[Corollary coro1dimensional1 of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $S\subseteq \mathbb R$ be a subset with an accumulation point in $\mathbb R$ and $X=(X_t)_{t\in [0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$. Fix $\varepsilon>0$ and assume that $b_j,a_{ij}\in\mathcal O_\varepsilon(S)$ and 
\begin{align}
    \int_{\mathbb R}\xi^\beta K(\cdot,d\xi) \in \mathcal{O}_\varepsilon(S),\quad \text{for all }  \beta\geq2. 
\end{align}
Suppose furthermore that the following conditions hold true.
\begin{enumerate}
\item for all $x\in {S}$, $ \int_{|\xi|>1} \exp(|\xi|) K(x,d\xi)<\infty;$
    \item the real valued map
$\sum_{\beta\geq2}\frac{1}{\beta!}|h_{\mathbf{m}^\beta}(\cdot)|
$
is locally bounded on $P^1_{R(S)+\varepsilon}(0)$.
\end{enumerate}
Fix 
\begin{equation}
    G>\sup_{x\in {S}}\sup_{\xi\in \textup{supp}(K(x,\cdot))}|x|+|\xi|
\end{equation}
and set $\mathcal{V}$, $\mathcal{V}^*$ as in equation (equation eq:Vgeneralkernel of the paper).  Then $X$ is an $S$-valued $\mathcal{V}$-holomorphic process and
for all $\mathbf{u}\in\mathcal{V}^*$  
$$\mathcal{A}h_\mathbf{u}=h_{L(\mathbf{u})}|_S,$$
where $L:\mathcal{V}^*\rightarrow \mathcal{S}^*$  is the operator defined in equation (equation eq:Lgeneralkernel of the paper), whose explicit form for $d=1$ reads
\begin{align}
    L(\mathbf{u})_\alpha=(\mathbf{u}^{(1)}\ast \mathbf{b})_\alpha+\frac{1}{2}(\mathbf{u}^{(2)}\ast (\mathbf{a}+\mathbf{m}^2))_\alpha+\sum_{\beta=3}^\infty\frac{1}{\beta!}(\mathbf{u}^{(\beta)}\ast \mathbf{m}^\beta)_\alpha.
\end{align}
for all $\mathbf{u}\in\mathcal{V}^*$, $\alpha\in\mathbb{N}_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:33:11.981584+00:00","domain":"probability theory","id":"claim_9264442c73bc2d3f0442b888746439197146484a194896110ed36241fd8ab3c4","kind":"theorem","schema_version":1,"statement":"[Proposition of arXiv:2608.19050, 'Online Permutation Embedding: \\ Optimal Stopping and Scaling Laws'] \begin{equation}\label{eq:beta+}
