{"assumptions":[],"created_at":"2026-10-28T00:15:09.028236+00:00","domain":"probability theory","id":"claim_9265677eeee56a6bfdfd5215d59277b6c7e6df3106bfdde345f49d3b7b302337","kind":"concept","schema_version":1,"statement":"[Lemma lem:RW1 of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] For any $C_1, C_2>0$, there is a constant $C_3=C_3(C_1,C_2)>0$, such that for any $C_1N^{-2/3}<x<C_2$ and $0\le h, g <C_2$, and $X, H, G\in \mathbb Z_{\ge 0}$, such that $|X-xN^{2/3}|, |H-hN^{1/3}|, |G-gN^{1/3}|<C_2$, the following estimates hold:
\begin{enumerate}
    \item[(1)] When $X+H+G$ is even and $h,g>C_1N^{-1/3}$, we have
\begin{multline*}
\left|N^{1/3}I(X;H,G)-\mathbf I(x;h,g)\right| \\ <C_3\mathbf F(x;h,g)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} + N^{-1/3}/h+N^{-1/3}/g)\right).
\end{multline*}
    \item[(2)] When $X+H$ is even and $h>C_1N^{-1/3}$, we have
\[
\left|N^{2/3}I(X;H,0)-\mathbf I_0(x;h)\right| < C_3\mathbf F_0(x;h)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} +N^{-1/3}/g )\right).
\]
    \item[(3)] When $X+H+G$ is even, $H\le G$, and $g-h>C_1N^{-1/3}$, we have
\begin{multline*}
\left|N^{2/3}I^+(X;H,G)-\exp(-\beta^{-1} xh )\mathbf I_0(x;g-h)\right| \\ <C\mathbf F_0(x;g-h)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} +N^{-1/3}/g)\right).
\end{multline*}
    \item[(4)] When $X$ is even, we have
\[
\left|NI^+(X;H,H)-\exp(-\beta^{-1} xh)\mathbf I_{0,0}(x)\right| < C_3\mathbf F_{0,0}(x)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} )\right).
\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.848853+00:00","domain":"probability theory","id":"claim_926ad27731f9fc0cd8940e0030dad45ccee07946f5bc2f29eceabb7e790a857b","kind":"definition","schema_version":1,"statement":"[Defination 7 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let  $(A(t))_{t\ge 0}$  be  a family  of  measurable  locally  bounded processes with  values in the class of  $n \times n $  matrices, let $\zeta $  be  the matrix-valued  solution of \begin{equation}
				\dot{\zeta}(t)= A(t) \zeta(t),~~~\zeta(0)= I.
			\end{equation}

			\noindent	 We will  say  that $(A(t))_{t\ge 0}$  is  \textbf{exponentially  stable} if there  exist  some positive  constants  $C$  and $c$    such  that for $s \leq t$,
			\begin{equation} 
				\vert \zeta(t)\vert\leq C e^{ (- c(t-s))} \vert \zeta(s) \vert.
			\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.955916+00:00","domain":"probability theory","id":"claim_926b0f5da172acd6d0b5a38f52059269789ba5e352a679367f900dea9b115223","kind":"lemma","schema_version":1,"statement":"[Lemma lem:kl_integral of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Assume that $h \lesssim \gamma^{-1} \wedge \gamma/\beta$ and $c_0/A \lesssim 1$ for sufficiently small implied constants.
    Define
    \begin{align*}
        \lambda_t \coloneqq \omega_+ + \eta_t\,, \qquad \Lambda_t \coloneqq \int_0^t \lambda_s\,\mathrm{d} s\,, \qquad \mathscr{E}_t \coloneqq \frac{1}{\gamma_t^2}\,\Bigl[\frac{(\bar{\mathcal{E}}^{\rm w})^2}{\lambda_t h} + \bigl(1+\frac{\beta^2 h}{\gamma_t^2\lambda_t}\bigr)\, (\bar{\mathcal{E}}^{\rm s})^2\Bigr]\,,
