        &\qquad{} + \frac{1}{\gamma h^4} \int_0^{Nh} \exp(-c\,(\Lambda_{Nh} - \Lambda_t)) \,\mathscr{E}_t\,\mathrm{d} t \\
        &\qquad{} + \frac{1}{\gamma h} \int_0^{Nh} \gamma_t^2 \eta_t^2 \int_0^t \exp(-c\,(\Lambda_t - \Lambda_s))\,\mathscr{E}_s\,\mathrm{d} s \,\mathrm{d} t\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.445752+00:00","domain":"probability theory","id":"claim_926c2594c5f239246861fc2e8f48a1069be7ab0d0d7319adf848948a1a63182f","kind":"definition","schema_version":1,"statement":"[Definition def:generalversionXY of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$, a collection of non-negative conductances $\left( J_{xy,k} \right)_{\{ x, y\} \in E(\Lambda_L), 1 \leq k \leq n}$, and a parameter $\lambda > 0$, we define the generalised XY model to be the probability distribution on the set $\Omega_{\Lambda_L}^{\mathrm{div-}\mathbb{S}^1}$ given by the identity
    \begin{equation} 
        \mu_{\Lambda_L , J, \lambda}^{\mathrm{XY}} (d \theta) := \frac{1}{Z_{\Lambda_L, J, \lambda}^{\mathrm{XY}}} \exp \left( \lambda \cos(\theta_{0g}) \right) \exp \left( \sum_{x \sim y} \sum_{1 \leq k \leq n} J_{xy,k} \cos(\theta_{xy, k}) \right) d \theta.
    \end{equation}
    We denote by $\left\langle \cdot \right\rangle_{L , J, \lambda}^{\mathrm{XY}}$ the expectation with respect to this measure.","status":"unverified"}

