{"assumptions":[],"created_at":"2026-10-27T14:04:39.774886+00:00","domain":"probability theory","id":"claim_9380f7bd35699b30ccc813e37ab4e52203a7a01fa6b35c3257dbfa2276eb31cf","kind":"concept","schema_version":1,"statement":"[Theorem Thm:PW_Robin of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Let $\Omega\subset \mathbb{R}^2$ be a bounded simply connected domain with $C^2$~boundary and let~$\delta_\Omega$ denote its isoperimetric deficit, as in (equation Eq:IsopDeficit of the paper).
    Then, for all $a>0$ there holds
    \begin{equation} 
        |\Omega| \, \mu_\Omega^\mathrm{Rob} \bigg(\frac{a}{\sqrt{|\Omega|}}  \bigg)
         - \pi \, \mu_\mathbb{D}^\mathrm{Rob}\bigg(\frac{a}{\sqrt{\pi}}  \bigg) 
        \leqslant 
        F \left(\sqrt{\mu_\mathbb{D}^\mathrm{Rob}\big(\tfrac{a}{\sqrt{\pi}}\big)} \right) \delta_\Omega( \delta_\Omega+2) +  G \left(\sqrt{\mu_\mathbb{D}^\mathrm{Rob}\big(\tfrac{a}{\sqrt{\pi}}\big)} \right) \delta_\Omega,
    \end{equation}
    where $F$ and $G$ are as in (equation Eq:def_FG of the paper). In particular, 
    \begin{equation} 
        |\Omega| \, \mu_\Omega^\mathrm{Rob} \bigg(\dfrac{a}{\sqrt{|\Omega|}}  \bigg)
        - \pi \, \mu_\mathbb{D}^\mathrm{Rob}\bigg(\dfrac{a}{\sqrt{\pi}}  \bigg) 
        \leqslant  
        C_{\mathrm{PW}} \, \delta_\Omega( \delta_\Omega+2) + \pi j_{0,1} \, \delta_\Omega
    \end{equation}
    and the equality holds in (equation Eq:PW_Robin_uniform of the paper) if and only if $\Omega$ is a disk. Here, $C_{\mathrm{PW}}>0$ is the constant in~(equation Eq:PW_Dirichlet of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.886653+00:00","domain":"probability theory","id":"claim_9381a3cc7f402ce89acb042f057793628d6e072382587fed18f6407fcc802b71","kind":"theorem","schema_version":1,"statement":"[Proposition 22 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Suppose $v\in(-\alpha,0)\setminus \ZZ$ and $m\in\ZZ_{\geq 0}$ is such $v+m<0$. Let  $u=v+m$.
 \begin{enumerate}[(A)]
  \item    If $2v\not\in\ZZ_{\leq 0}$ 
     then
         \begin{multline}
         \GG_N(\alpha,v+m,v)
        \\   = \tfrac{1}{
    2\pi \Gamma(2v+m)} \int_{0}^\infty \left|\Gamma(\alpha+\i x)\right|^{2N} \tfrac{|\Gamma(v+\i x)|^2|\Gamma(v+m +\i x )|^2}{|\Gamma(2\i x)|^2}\d x
    -2S_1+2S_2,
     \end{multline}
     where
     \begin{multline*}
         S_1=\tfrac{1}{ \Gamma
   (1-2 v)} \sum_{j=0}^{m-1} \tfrac{(-1)^{j}  (j+v)  (m-j-1)! (2 v)_j
   (m+2 v)_j}{j! }  \Gamma(\alpha +j+v)^N \Gamma (\alpha-j-v )^N
     \end{multline*}
     and
     \begin{multline*}
         S_2= {(-1)^m} \sum _{i=0}^{\lfloor -v\rfloor -m} \tfrac{(i+m+v) \Gamma
   (-m-2 v+1) }{i! (i+m)! \Gamma (-i-2 m-2 v+1) \Gamma
   (-i-m-2 v+1)}
   \\ \cdot  \Big[N(\psi
   (i+m+v+\alpha )-\psi (-i-m-v+\alpha
   ))+\frac{1}{i+m+v}+\psi (-i-2 m-2 v+1)\\ +\psi
   (-i-m-2 v+1)-\psi (i+m+1)-\psi
   (i+1)\Big]\Gamma (\alpha-i-m-v )^N \Gamma (\alpha+i+m+v)^N.
     \end{multline*}
  \item   If  $v\in(-\alpha,0)\setminus \ZZ$ is such that $2v\in\ZZ_{\leq 0}$, then  formula \eqref{G(v+m,v)} still holds, except that the integral term vanishes:
  \begin{equation}

