{"assumptions":[],"created_at":"2026-10-27T21:31:49.846229+00:00","domain":"probability theory","id":"claim_93cbdc9dddcc37cc7cf9a0662f58ad5468011ff7018a87d3e0def5789f385d25","kind":"concept","schema_version":1,"statement":"[Theorem the: Kurtz's criteria of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Consider a sequence of processes $\setc{\boldsymbol{X}^N}{N \geq 1}$ in $D_\mathbbm{R}[0, \infty)$. If the following conditions are satisfied, then the sequence is tight.
	\begin{enumerate}
		\item[\normalfont{K1.}] For each rational $t \geq 0$, we have
		\begin{equation*}
			\lim_{K \to \infty} \limsup_{N \to \infty} P\left(\left|\boldsymbol{X}_t^N\right| > K\right) = 0.
		\end{equation*}

		\item[\normalfont{K2.}] For each $t > 0$, there exists $\beta > 0$ such that
		\begin{equation*}
			\lim_{\delta \to 0} \limsup_{N \to \infty} E\left|\boldsymbol{X}_{t + \delta}^N - \boldsymbol{X}_t^N\right|^\beta = 0.
		\end{equation*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.971849+00:00","domain":"probability theory","id":"claim_93cf3b123b654b70ebe0079832ec3ed4276bddc088c928f63e455549113500a3","kind":"concept","schema_version":1,"statement":"[Lem 43 (Kru{\v{z}}kov's interpolation lemma \cite{Kruzhkov1969ResultsCT}) of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $z \in L^{\infty}(\R^{d}\times[0,T])$. Assume that $z$ has a spatial modulus of continuity $\nu$ on $\R^{d}\times[0,T]$. Given $C>1$, if  $t_1, t_2 \in [0,T]$ are such that for all $\vp \in C^{\infty}_{c}(\R^{d})$,
	\begin{equation} 
		\left| \int_{\R^{d}} (z(x,t_2)-z(x,t_{1})) \vp(x) \, dx\right| \leq C\cdot\left(\sum_{i = 1}^{d} \norm{\partial_{x_{i}}^{2}\vp}_{L^{\infty}(\R^{d})}\right)\cdot |t_{2}-t_{1}|,
	\end{equation}
	then for all $\ve > 0$, 
	\begin{equation*}
		\norm{z(\cdot,t_{2}) - z(\cdot,t_{1})}_{L^{1}(\R^{d})} \leq 2C \cdot \left( \frac{|t_{2}-t_{1}|}{\ve^2} + \nu(\ve)\right).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.240067+00:00","domain":"probability theory","id":"claim_93d5c8206046cd3dad11880d3b3014589f04de5dda6d7addef790951a6c86732","kind":"theorem","schema_version":1,"statement":"[Proposition ibp_proposition of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Let $G$ and $F$ be random variables such that $G \in \mathbb{D}^{1,2}(\mathbb{R})$, and let $h \in L^{2}(\Omega \times [0,T], \mathbb{R}^{d})$ be such that $\langle \mathbf{D} G, h\rangle_{L^2} \not= 0$ a.s. and $\dfrac{Fh}{\langle \mathbf{D} G, h\rangle_{L^2}} \in \mathrm{Dom}(\delta)$. Then, for any $f\in C^1_b(\mathbb{R}, \mathbb{R})$ we have
    \begin{equation}
        \mathbb{E}[f'(G)F] = \mathbb{E}\left[f(G)\delta\left(\dfrac{Fh}{\langle \mathbf{D} G, h \rangle_{L^2}}\right)\right].
    \end{equation}
    Moreover, if $\dfrac{F}{\langle \mathbf{D} G, h\rangle_{L^2}} \in \mathbb{D}^{1, 2}$ and $h \in \mathrm{Dom}(\delta)$, then
    \begin{equation}
        \mathbb{E}\left[f'(G)F\right] = 
        \mathbb{E}\left[
        f(G)\left(
        \dfrac{F\delta(h)}{\langle \mathbf{D} G, h \rangle_{L^2}}
        - \dfrac{\langle \mathbf{D} F, h\rangle_{L^2}}{\langle \mathbf{D} G, h\rangle_{L^2}}
        + \dfrac{F\left\langle \mathbf{D}\langle \mathbf{D} G, h\rangle_{L^2}, h\right\rangle_{L^2}}{\langle \mathbf{D} G, h\rangle_{L^2}^2}
        \right)\right].
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.210645+00:00","domain":"probability theory","id":"claim_93d62edb35484d08ed0281429df5732aea85e65ec15ef922e28841a0082475b4","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] For any \(3/4<H<5/6\) we have that, if \(u>v\)  
\begin{equation}
