{"assumptions":[],"created_at":"2026-10-28T02:28:34.965111+00:00","domain":"probability theory","id":"claim_948495d2313156ef173c7940bb0f74ac0c6392416ef98df368df8edc212eeb02","kind":"theorem","schema_version":1,"statement":"[Prop thm:submatrices_suffice of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] \begin{enumerate}[left=0pt]
