{"assumptions":[],"created_at":"2026-10-28T00:32:56.095324+00:00","domain":"probability theory","id":"claim_958f55f65377ee4e9377aea1992cace44abe7a8a7c12839034e8d7aac04eb8bb","kind":"concept","schema_version":1,"statement":"[Prop proposition:ManyToOneL* of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $r\geq 0$.  For every non-negative measurable function $\Phi$ on $\mathcal{M}^2_f(\mathbb{R}_+) \times \mathcal{W}_{\overline{E}}$, we have:
\begin{align}
     &  \mathbf{N}^{\bullet, L}_{x,r} \big(  \Phi\big( \rho_U,\eta_U, \overline{W}_U\big)  \big)  
  =   E^0 \otimes \mathcal{N}_{x,r} \Big(  \exp\big(- \alpha\cdot  \uptau \big)\Phi\big( \mathcal{J}_{\uptau}, \widecheck{\mathcal{J}}_{\uptau}, (\bar{\xi}_t:~t\in [0,\uptau] ) \big) \Big). 
\end{align}
Under $\mathbf{N}_{x,r}^{\bullet, L}$, conditionally on $(\rho_U,\eta_U, \overline{W}_U)$ the
processes $(\rho,\overline{W})^{U,\leftarrow}$ and  $(\rho,\overline{W})^{U,\rightarrow}$ are independent and their  conditional distributions are as follows:
\begin{itemize}
\item the process $(\rho,\overline{W})^{U,\leftarrow}$ is distributed as  $(\eta, \overline{W})$ under $\mathbb{P}_{\eta_U, \rho_U,\overline{W}_U}^\dagger$; 
\item the process $(\rho, \overline{W})^{U,\rightarrow}$ is distributed as  $(\rho, \overline{W})$ under $\mathbb{P}_{\rho_U,\overline{W}_U}^\dagger$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:18:19.200337+00:00","domain":"probability theory","id":"claim_95903a0b88e7fc08025000ec3211ce63c0be3f4c178d2c4f2f4659c4986e826a","kind":"concept","schema_version":1,"statement":"[Theorem 11 of arXiv:2608.28964, '2608.28964'] {\rm(}\hspace{-0.1mm}{\rm\cite[Theorems 3.4, 4.5]{HM-08})}
    Let $Z(t,x)$ be a stochastic semiflow on a Hilbert space $X$, with $C^1$ dependence on $x\in X$, and let $\{P_t\}_{t\geq0}$ and $\{P_t^*\}_{t\geq0}$ be the associated Markov semigroups. Assume that 
    \begin{itemize}
        \item[(1)] There exist constants $C,\gamma>0$ and a decreasing function $\xi\colon[0,1]\to(0,\infty)$ with $\xi(1)<1$ such that for any $x\in X$, $r\in[1/4,3]$ and $t\in[0,1]$,
	\begin{equation}
	\E\exp\left(r\gamma\|Z(t,x)\|_{X}^2\right)\left(1+\|\nabla_xZ(t,x)\|_{\mathcal L(X)}\right)\leq C\exp\left(r\gamma\xi(t)\|x\|_{X}^2\right).
	\end{equation}
        \item[(2)] There exist constants $C,\alpha>0$ such that for any Fr\'echet differentiable function $\varphi\colon X\to\R$, $x\in X$ and $t\geq0$,
	\begin{equation}
	\|\nabla P_t\varphi(x)\|_{X}\leq C\exp\left(\tfrac{\gamma}{2}\|x\|_{X}^2\right)\left(\sqrt{P_t(|\varphi|^2)(x)}+e^{-\alpha t}\sqrt{P_t(\|\nabla\varphi\|_{X}^2)(x)}\right).
	\end{equation}
        \item[(3)] For any $\varepsilon,R>0$ and $r\in(0,1)$, there exists $T>0$ such that for any $t\geq T$,
	\begin{equation}
	\inf_{x,x'\in B_{X}(0,R)}\sup_{\Gamma\in\mathscr C(P_t^*\delta_x,P_t^*\delta_{x'})}\Gamma\left\{(y,y')\in X\times X:\rho_r(y,y')\leq\varepsilon\right\}>0,
	\end{equation}
        where $\mathscr C(\mu,\mu')$ is the set of couplings of $\mu$ and $\mu'$, and
	\begin{equation*}
	\rho_s(x,y):=\inf_{\substack{\ell\in C^1([0,1];X),\\
	\ell(0)=x,\ \ell(1)=y}}\int_0^1\exp\left(s\gamma\|\ell(r)\|_{X}^2\right)\|\ell'(r)\|_{X}dr,\quad s\in(0,1].
	\end{equation*}
    \end{itemize}

    Then there exist constants $C,\alpha>0$ such that
	\begin{equation*}
	\rho_1(P_t^*\mu,P_t^*\mu')\leq Ce^{-\alpha t}\rho_1(\mu,\mu')\quad\forall\,\mu,\mu'\in\mathcal P(X),\;t\geq0.
	\end{equation*}
    In particular, $\{P_t^*\}_{t\geq0}$ admits a unique invariant measure $\mu_*\in\mathcal P(X)$, and
	\begin{equation*}
	\left|P_t\varphi(x)-\int_{X}\varphi d\mu_*\right|\leq Ce^{-\alpha t}\exp\left(\gamma\|x\|_{X}^2\right)\left\|\varphi-\int_{X}\varphi d\mu_*\right\|_\gamma
	\end{equation*}
    for any $\varphi\in\mathcal O_\gamma$, $x\in X$ and $t\geq0$, where
	\begin{equation*}
	\mathcal O_\gamma:=\left\{\varphi\in C^1(X):\|\varphi\|_\gamma<\infty\right\},\quad\|\varphi\|_\gamma:=\sup_{x\in X}\left(e^{-\gamma\|x\|_{X}^2}\left(|\varphi(x)|+\|\nabla\varphi(x)\|_{X}\right)\right).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

