{"assumptions":[],"created_at":"2026-10-26T19:34:33.547874+00:00","domain":"probability theory","id":"claim_95aaf0ac9650387a029b752c79fed05e52cac18e01deb5c4c9718d83990dbded","kind":"concept","schema_version":1,"statement":"[Lemma 5 (WKB expansion) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $\lambda>0$ be fixed and $n \in \N$. Assuming \cref{eq:spectralcondition} there exists a turning point $x^\ast$ of
	\begin{equation*}
		T(x):=\frac{|V'(x)|^2}{4} - \frac{V''(x)}{2} - \lambda,
	\end{equation*}
	that is,  the point $x^*$ for which $T(x)\geq 0$ for all $x \geq x^*$.
	Denote $f = V'$ and let $f \in \mathcal{C}^1([x^*,\infty))$.
	Let $v$ be a solution to \cref{eq:Wittenprime} in $[x^*,\infty)$. Write $v(x) = e^{\sum_{i=0}^{n} S_i(x)+R_n(x)}$, where
	\begin{equation}
		\begin{split}
			S_0(x)=   & -\int_{x^*}^{x} \frac{f(s)}{2}
			\ds, \quad
			S_1(x)=  \int_{x^*}^x \frac{\lambda}{f(s)} \ds,                                                                                           \\
			S_k'(x) = & \frac{1}{f(x)} S_{k-1}''(x) + \frac{1}{f(x)} \sum_{j=1}^{k-1} S_j'(x) S_{k-j}'(x), \quad S_k(x^*) = 0, \quad 2 \leq k \leq n,
		\end{split}
	\end{equation}
	for all $x\geq x^*$.
	Then the remainder term $R_{n}$ satisfies for $\widehat u =e^{R_{n}}$
	\begin{equation} 
		-\widehat u''(x) - 2\widehat u'(x) \sum_{j=0}^{n} S_j'(x) = \widehat u(x)  \left ( S_n''(x) +\sum_{n_1+n_2 \geq n+1}^{n_1 \leq n; n_2 \leq n} S_{n_1}'(x)S_{n_2}'(x) \right ),
	\end{equation}
	with initial condition $\widehat u(x^*) = v(x^*)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.794087+00:00","domain":"probability theory","id":"claim_95ad107a7fbf27fc19f0b9f4b100501d8534c9a59852cce82b9a20e8937bf615","kind":"concept","schema_version":1,"statement":"[Corollary 2 of arXiv:2604.10051, 'Ergodicity of the voter model with dynamic anti-voter bonds'] Let~$(\xi_t)_{t \ge 0}$ be a Feller process on a metric space~$\mathcal C$. Let~$I$ be an index set and, for each~$i \in I$, let~$(Z^i_t)_{t \ge 0}$ be a Markov chain with countable state space~$\mathcal S_i$ and~$Q$-matrix satisfying~$\eqref{eq_q_finite}$. Suppose that, for every~$i \in I$, the processes~$(\xi_t)$ and~$(Z^i_t)$ are dual with respect to~$D_i:\mathcal C \times \mathcal S_i \to [0,\infty)$, which satisfies conditions~$(i)$ and~$(ii)$ of Lemma~\ref{lemma_uniqueness_1} for all~$z \in \mathcal S_i$.
\begin{enumerate}
    \item[(1)] If, in addition, the family of functions~$\xi \mapsto D_i(\xi,z)$, indexed by~$i \in I$ and~$z \in \mathcal S_i$, is measure-determining (that is, two probability measures coincide whenever their integrals against all these functions coincide), then every measure in~$\mathscr{I}_\infty$ is stationary for~$(\xi_t)_t$.
    \item[(2)] If, furthermore, the metric space~$\mathcal C$ is compact and~$(\xi_t)_t$ admits a unique stationary measure, then $(\xi_t)_t$ is ergodic.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.568741+00:00","domain":"probability theory","id":"claim_95ae626d3b193344514619570babbe459d6c927b45afb7b73740f28d43a74136","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $0 \leq p, \, q \leq \infty$ and $s, \, \beta \in \mathbb{R}$, the hyperbolic Besov space with hyperbolic scale is defined by
\begin{equation}
 \widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)  :  = \Big\{ f \in \mathcal{S}'(\mathbb{R}^2)~:~ \,   \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q < \infty \Big\}
\end{equation}
with the norm
$$
\Vert f \Vert_{\widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)} = \left( \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q \right)^{1/q},
$$
with the usual modification if $q= \infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.329437+00:00","domain":"probability theory","id":"claim_95aed303693776be14924471fb220ef11080fdd3d1121a28ae9eac93f5a73eb1","kind":"concept","schema_version":1,"statement":"[Corollary cor:spectral of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] There exists a generic constant $C_7=C_7(\kappa )>0$ such that for any sequence of local functions $(f_i)_{i\ge 1}$ from $[0,T]\times \Omega \longrightarrow\mathbb{R}$ such that $f_i(t,\cdot )$ satisfies the hypotheses of (cor:spectral0 of the paper) for any $t\in [0,T]$ and any $i\ge 1$, we have
    \begin{equation}
        \mathbb{E}_{\rho ,\mathcal{E}}\left[\sup_{0\le t\le T}\left( \int_0^t \sum_{i=1}^\infty f_i(s,\eta (s))\,\mathrm{d} s\right)^2\right] \le \frac{C_7}{N^a}\sum_{i=1}^\infty \ell_i^2 \int_0^T\mathrm{Var}_{\rho ,\mathcal{E}}(f_i(t,\cdot ))\,\mathrm{d} t.
