{"assumptions":[],"created_at":"2026-10-26T19:34:33.549304+00:00","domain":"probability theory","id":"claim_9630fd63ec7d79f213fa9558e5091247c98ab6ff19fbcb14dd9ab87f04542448","kind":"concept","schema_version":1,"statement":"[Lemma 19 (Growth of the Fourier coefficients for $0<\gamma<1$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $\gamma\in(0,1)$, let $\varrho_{\varepsilon,0}$ be the initial density from \cref{eq:initialcond} with $\delta(\varepsilon)=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$, let $\psi_{k,\varepsilon}$ be the $k$-th non-constant eigenfunction of $-\mathcal{L}_\varepsilon$ with eigenvalue $\lambda_{k,\varepsilon}=\lambda_k\varepsilon^{\frac{\gamma-1}{1+\gamma}}$, and let $N$ be as in \cref{lem:general-shape}.
	With the notation introduced after \cref{lem:general-shape}, define for $0\leq d\leq N-1$ and $d+1\leq j\leq N$
	\begin{equation}
		\alpha_{j,d}:=(2j-d-1)\gamma+d.
	\end{equation}
	Assume first that $x_0\neq 0$. In the non-resonant case, that is when $N>\frac{1+\gamma}{2\gamma}$, for all sufficiently small $\varepsilon>0$ one has
	\begin{equation*}
		\int \varrho_{\varepsilon,0}(x)\psi_{k,\varepsilon}(x)\,\dx
		\approx
		\exp\Bigg(\sum_{d=0}^{N-1}\sum_{j=d+1}^{N}
		\lambda_k^{\,j-d}\,\hat A_{j,j-d}(\gamma)\,
		\varepsilon^{\frac{\alpha_{j,d}-1}{1+\gamma}}
		|x_0|^{\,1-\alpha_{j,d}}
		\Bigg),
	\end{equation*}
	where the implied comparability constants are independent of $\varepsilon$. In the resonant case $N = \frac{1+\gamma}{2\gamma}$, the same asymptotic holds except that the term corresponding to $(j,d)=(N,0)$ is replaced by 
	\[
		\lambda_k^N A_{N,N}(\gamma)\left(\log|x_0| - \frac{1}{1+\gamma}\log\varepsilon\right).
	\]

	If $x_0=0$ and $\psi_k(0)=0$, then the Fourier coefficient vanishes. If $x_0=0$ and $\psi_k(0)\neq0$, then in the non-resonant case $N>\frac{1+\gamma}{2\gamma}$ one has
	\begin{equation}
		\left\lvert \int \varrho_{\varepsilon,0}(x)\psi_{k,\varepsilon}(x)\,\dx\right\rvert
		\approx
		\varepsilon^{\frac{\gamma(1-\gamma)}{1+\gamma}}
		\exp\!\Bigg(
		\sum_{d=0}^{N-1}\sum_{j=d+1}^{N}
		\lambda_k^{\,j-d}\,\hat A_{j,j-d}(\gamma)\,
		\varepsilon^{\frac{\gamma(\alpha_{j,d}-1)}{1+\gamma}}
		\Bigg).
	\end{equation}
	In the resonant case $N=\frac{1+\gamma}{2\gamma}$, the same asymptotic holds except that the term corresponding to $(j,d)=(N,0)$ is replaced by $-\lambda_k^{N}A_{N,N}(\gamma)\,\frac{\gamma}{1+\gamma}\log\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:48:17.123945+00:00","domain":"probability theory","id":"claim_9632e430a8223e7da469367bed0222d67a023671157e7b97950c88a2251da6bf","kind":"concept","schema_version":1,"statement":"[Corollary 15 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} (i). Let $0\leq \alpha < d$ and $0\leq \beta \leq 1$ be such that \eqref{eq:key-restriction} holds, and let $\zeta$ be as in  Proposition \ref{prop:moment-bounds}.
		\begin{enumerate}	
