			\begin{equation}

				\mathbb{P}\Big(L^{\alpha,X}(x,I)\geq \lvert I\rvert ^{1-H(d-\alpha)}[\log(e+|I|)]^{2d\zeta} u^{H(\theta+d-\alpha)}\Big) \leq c_{10}\exp(-c_{11}u),
