				\leq c_{10}\exp(-c_{11}u),
			\end{multline}
			and this remains true if $x$ and $y$ are replaced by $x+X_\tau$ respectively $y+X_\tau$ with $\tau\in I$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.464537+00:00","domain":"probability theory","id":"claim_96337882e8c7b8920e53b5ffd1bfa3f5cebecd8646a6996936ea5ff5e250c0d9","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.29131, '2606.29131'] Suppose that Assumption {\rm\ref{a1-1}}{\rm(i)} and Assumption {\rm\ref{a1-2}} hold, and
