{"assumptions":[],"created_at":"2026-10-27T10:07:48.545070+00:00","domain":"probability theory","id":"claim_964bc2699d795bb8bc7f30690deea8378c19c85ecf1f1778bae650c52ed54545","kind":"definition","schema_version":1,"statement":"[Definition 3 ($(\beta,\sigma)$-consistency of $\emprashomonset$) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given $\emprashomonset$ with distribution $\tau$, a random model $\rf$ $\iid \tau$, an instance $x \in \dtest$, the expected model $\E_{\rf}[\rf(x)]$ of the empirical Rashomon set $\emprashomonset$ at $x$, a random perturbation $\rlocaltest$ $\iid \Unif(\ltwohsphere(x,\sigma))$, and parameters $\beta \in [-\frac{1}{2},\frac{1}{2}]$ and $\sigma > 0$, let 
	\begin{align}
	 \consistency(\emprashomonset,x)
    =\abs*{\E_{\rf}\bracks*{\rf(x)} 
        - \frac{1}{2}} 
    - \E_{\rf,\rlocaltest}\bracks*{\abs*{\rf(x) - \rf(\rlocaltest)}},
    \end{align}
be the margin of the expected model of $\emprashomonset$ at $x$, penalized by the expected variability around $x$, where the expectation is taken jointly with respect to the perturbation $\rlocaltest$, and the model $\rf$. Then the expected model of $\emprashomonset$ is said to be $(\beta,\sigma)$-consistent at $x$ if, 
    \begin{align} 
    \consistency(\emprashomonset,x)  \ge \beta.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:20.966315+00:00","domain":"probability theory","id":"claim_9650484b106dd7c370f85c757c64a63e63d6acd3f17ab46efaedbd216082bf14","kind":"concept","schema_version":1,"statement":"[Theorem 26 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\theta_n$ be as in \eqref{Eq: recursion_general_SA}. Suppose the following assumptions are satisfied. 
\begin{enumerate}[i.]
\item $\sup_{n \ge 1} \lVert \theta_n \rVert < \infty$. 
\item $h$ is a Lipschitz function, that is, there exists $L>0$, such that, $\lVert h(x)-h(y) \rVert \le L \lVert x-y\rVert$.
\item $\sup_{n \ge 1} \E \left[ \lVert \Delta M_{n}\rVert ^2 |\FF_{n-1} \right] < \infty$.
\item Assume that $r_n \longrightarrow 0, \text{ a.s.}$ as $n \to \infty$.
\item Let $\theta^*$ be an equilibrium point of $h$, that is, $\theta^* \in \{\theta: \, h(\theta)=0\}$, such that $\langle \theta-\theta^*, h(\theta)\rangle <0$, for all $\theta \neq \theta^*$.
\end{enumerate}
Then, as $n \to \infty$
\begin{equation}

\theta_n \longrightarrow \theta^*, \text { a.s.}
\end{equation}
where the convergence is sample path dependent, in case, $\theta^*$ is not unique. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.977814+00:00","domain":"probability theory","id":"claim_96508637e19cf31e588611383233bce3f4c9a10664bcca694ebab5e80e12b9aa","kind":"theorem","schema_version":1,"statement":"[Corollary 54 (Bounded bracket-density control) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume
\begin{equation}
 \mathop{}\!\mathrm dV_t\leq\Lambda\,\mathop{}\!\mathrm dt
 \qquad(0\leq t\leq T).

\end{equation}
For every finite \(q\geq2\) and \(0\leq s<t\leq T\),
\begin{align}
 \left\|\sup_{s\leq u\leq t}\|M_u-M_s\|_H\right\|_{L^q}
 &\leq C_q\Lambda^{1/2}|t-s|^{1/2},
 \\
 \left\|\sup_{s\leq u\leq t}\|A_{s,u}\|_{1,\infty}\right\|_{L^q}
 &\leq C_q\Lambda|t-s|.

\end{align}
For every \(\beta\in(1/3,1/2)\) there is a modification and an almost
surely finite random \(C_\beta\) such that, simultaneously for all
\(s<t\),
\begin{equation}
 \|M_t-M_s\|_H\leq C_\beta|t-s|^\beta,
 \qquad
 \|A_{s,t}\|_{1,\infty}\leq C_\beta|t-s|^{2\beta}.

\end{equation}
Moreover, for every finite \(p\), the constant may be chosen so that
\begin{equation}
 \|C_\beta\|_{L^p}
 \leq C_{p,\beta,T}\bigl(\Lambda^{1/2}+\Lambda\bigr),

\end{equation}
where the constant is independent of the Hilbert-space dimension.  Thus
bounded bracket density is already a dimension-free grade-one entrance
certificate; no model-specific dyadic argument is required later.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.322780+00:00","domain":"probability theory","id":"claim_9650cd27db3fb10997df2504f29504c4feba1a9a973a37cfcf2ed0009a5c09b5","kind":"lemma","schema_version":1,"statement":"[Lemma 32 (Exact top-\texorpdfstring{$m$}{m} occupancy mixture) of arXiv:2604.09933, 'Explicit cutoff profiles for colored top-\texorpdfstring{$m$}{m}-to-random shuffles'] Fix \(1\le m\le n\) and \(k\ge0\). Then
\begin{align}
(Q^{(m)})^{*k}
&=\sum_{a=0}^{n}\mu_k^{(m)}(a)\,\widetilde Q_{a,p},
\\
&=\sum_{u=0}^{n}P_k^{(m)}(u)\,\widetilde Q_{n-u,p}.

\end{align}
In particular,
\[
P_k^{(m)}(u)=\mu_k^{(m)}(n-u),
\qquad
(Q^{(m)})^{*k}=\widetilde Q_{\mu_k^{(m)},p}.
\]
If \(k\ge1\), then
\begin{equation}
\mu_k^{(m)}(a)
=
\frac{1}{(n)_m^k}\binom{n}{a}
\sum_{j=0}^{a}(-1)^j\binom{a}{j}(a-j)_m^k,
\qquad
0\le a\le n,
\end{equation}
with the convention \((x)_m=0\) for \(x<m\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.655972+00:00","domain":"probability theory","id":"claim_965242fb6ec990d381ac62a7861c9926f4bab1dc0ba16e4b31733bfc7062a99f","kind":"concept","schema_version":1,"statement":"[Theorem th:TV_asympt of arXiv:2411.04690, 'Asymptotic distribution of the derivative of the taut string accompanying Wiener process'] Let $(W_t)_{t\geq 0}$ be a Wiener process; for $\mu\in\mathbb{R}$ define
	\begin{equation*}
		X_t := W_t- \mu t,\quad t\geq 0.
	\end{equation*}
	Then, as $T\to +\infty$,
	\begin{equation*}
		\begin{aligned}
		\frac{1}{T}\,TV^{r}(X,[0,T])
		&\xrightarrow{\text{a.s.}}
		m_{r}(\mu),
            \\
            \frac{1}{T}\,UTV^{r}(X,[0,T])
		&\xrightarrow{\text{a.s.}}
		q_r(\mu),
		\end{aligned}
	\end{equation*}
	where
	\begin{equation}

		m_{r}(\mu)=
		\begin{cases}
			\mu \coth({r\mu}),\ &\mu\neq 0;\\
			r^{-1},\ &\mu=0;
		\end{cases}
        \end{equation}
        \begin{equation}

		q_r(\mu)=
		\begin{cases} \frac12 (\mu \coth(r\mu)-\mu),& \mu \not=0; \\
		\frac12 r^{-1},& \mu=0.
	\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

