{"assumptions":[],"created_at":"2026-10-27T20:50:48.845838+00:00","domain":"probability theory","id":"claim_968281b18cdecc9a77c89dc994c542da50208486258f213c544155ad4d0ca257","kind":"concept","schema_version":1,"statement":"[Lemma lem:sob of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] \begin{enumerate}[(i)]
			\item For any $k, k_1, k_2 \in {\mathbb{N}} $ with $k_1 \le k_2 $, we have the continuous embeddings
			\begin{align*}
				&L^2\hookrightarrow L^2(w^{-1}(x)\,\mathrm{d} x),\quad
				L^2(w(x)\,\mathrm{d} x)\hookrightarrow L^2,\quad
				{\mathcal{H}}^{k}\hookrightarrow {\mathcal{H}}^{k}_w,\\
				&{\mathcal{H}}_w^{k_2}\hookrightarrow {\mathcal{H}}_w^{k_1},\quad
				{\mathcal{H}}^{-k}_w\hookrightarrow {\mathcal{H}}^{-k},\quad
				{\mathcal{H}}^{k_2}\hookrightarrow {\mathcal{H}}^{k_1},\quad
				{\mathcal{H}}^{-k_1}_w\hookrightarrow {\mathcal{H}}^{-k_2}_w.
			\end{align*}
			\item 
			For any $k_1, k_2 \in {\mathbb{N}}$ with $k_1\le k_2$, $u\in {\mathcal{H}}_w^{-k_1}$, and $f\in {\mathcal{H}}_w^{k_2}$, we have
			\begin{align} 
				\langle u,f\rangle_{{\mathcal{H}}^{-k_1}_w,{\mathcal{H}}_w^{k_1}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_2}_w,{\mathcal{H}}_w^{k_2}}.
			\end{align}
			If in addition, $f\in {\mathcal{H}}^{k_2}$, then
			\begin{align} 
				\langle u,f\rangle_{{\mathcal{H}}^{-k_1}_w,{\mathcal{H}}_w^{k_1}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_1},{\mathcal{H}}^{k_1}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_2},{\mathcal{H}}^{k_2}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_2}_w,{\mathcal{H}}_w^{k_2}}.
			\end{align}
			\item For any $k \in {\mathbb{N}}$, $C_c^\infty({\mathbb{R}}^d)$ is dense in  ${\mathcal{H}}^{k}_w$ and 
			\begin{align} 
				\bigg\{f \mapsto \int_{{\mathbb{R}}^d} \varphi (x) f(x) \, \mathrm{d} x : \varphi \in C^\infty_c({\mathbb{R}}^d)\bigg\}
			\end{align}
			is dense in  ${\mathcal{H}}^{-k}_w$. 
			\item For any $k\in{\mathbb{N}}$ and $u\in C_c^\infty({\mathbb{R}}^d)$, let $u\in {\mathcal{H}}_w^{-k}$ denote the continuous linear functional
			\begin{align*}
				\varphi\mapsto \int_{{\mathbb{R}}^d}u(x)\varphi(x)\,\mathrm{d} x, \quad \varphi \in {\mathcal{H}}^k_w.
			\end{align*}
			Let $\widetilde{u}\in {\mathcal{H}}_w^k$ be the element given by the Riesz Representation Theorem, namely
			\begin{align} 
				\langle u,\varphi\rangle_{{\mathcal{H}}_w^{-k},{\mathcal{H}}_w^k}
				=
				\langle \widetilde{u},\varphi\rangle_{{\mathcal{H}}_w^k},
				\quad \varphi\in {\mathcal{H}}_w^k.
			\end{align}
			Then $\widetilde{u}\in {\mathcal{H}}_w^m$ for every  ${\mathbb{N}} \ni m\ge k$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.353406+00:00","domain":"probability theory","id":"claim_9684309b00a969fc17f84ec7e7f040156545f5e677b0ad36a79b578d740f40ef","kind":"definition","schema_version":1,"statement":"[Dfn 203 (buckets for Ising perceptron) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For the Ising perceptron, first apply Definition~\ref{d:buckets}  to obtain $\vX^{\trunc,\RomI:\RomIII}$ and $\vX^{\frstar,\RomI:\RomIII}$. We separately apply an analogous procedure in the Ising coordinate: let 
$X^{\trunc,\Ising}(q_0) \equiv X^{\trstar,\Ising}(q_0)$
and
$X^{\frozen,\Ising}(q_0) \equiv X^{\frstar,\Ising}(q_0)$,
and suppose inductively that 
$X^{\trunc,\Ising}(q_\ell)$
and $X^{\frozen,\Ising}(q_0)$
have been defined for all $0\le\ell\le d$. Then let
    \begin{align*}
    B^\Ising(q_d, K(q_{0:d})) 
    &\equiv \Big\{ i\in[N]:
    X^{\trunc,\Ising}(q_\ell,i)
    \in K(q_{\ell})
    \textup{ for each }0\le\ell\le d
    \Big\}\,,\\
    B^{\frozen,\Ising}(q_d, K(q_{0:d})) 
    &\equiv \Big\{ i\in[N^\frozen]:
    X^{\frozen,\Ising}(q_\ell,i)
    \in K(q_\ell)
    \textup{ for each }0\le\ell\le d
    \Big\}\,,\end{align*}
analogously to \eqref{e:bucket} and \eqref{e:bucket.fr}. Then define the \textbf{buckets}
    \begin{align*}
    B^\Ising(q_d,i)
    &= \begin{cases}
    B^\Ising(q_d, K(q_{0:d}))
    &\textup{if $i\in B^\Ising(q_d, K(q_{0:d}))$,}\\
    \{i\}
    &\textup{otherwise, meaning $X^{\trunc,\Ising}(i)\notin[-\trK,\trK)$;}
    \end{cases} \\
    B^{\frozen,\Ising}(q_d,i)
    &= \begin{cases}
    B^\frozen(q_d, K(q_{0:d}))
    &\textup{if }i\in B(q_d, K(q_{0:d}))\,,\\
    \{i\}
    &\textup{otherwise, meaning }X^{\frozen,\Ising}(i)\notin[-\trK,\trK)\,.
    \end{cases}
    \end{align*}
Write $\mathcal{B}^\Ising(q_d)\equiv\{B^\Ising(q_d,i):i\in[N]\}$
and $\mathcal{B}^{\frozen,\Ising}(q_d)
\equiv\{B^{\frozen,\Ising}(q_d,i):i\in[N^\frozen]\}$. Lastly, let
    \begin{align*}
    X^{\trunc,\Ising}(q_{d+1},i)
    &=\begin{cases}
    X^{\trstar,\Ising}(q_{d+1},i)
    &\textup{if $|B^\Ising(q_d,i)| 
        \ge N/\BUCKETS^2$,}\\
    X^{\trunc,\Ising}(q_d,i)
    &\textup{otherwise.}
    \end{cases}\\
    X^{\frozen,\Ising}(q_{d+1},i)
    &=\begin{cases}
    \vX^\frstar(q_{d+1},i)
    &\textup{if $|B^{\frozen,\Ising}(q_d,i)  \cap[N]  | 
        \ge N/\BUCKETS^2$,}\\
    X^{\frozen,\Ising}(q_d,i)
    &\textup{otherwise.}
    \end{cases}
    \end{align*}
Note that when determining whether buckets are too small we only look at particle indices in $[N]$, that is, we ignore the added particles from Definition~\ref{d:froze} when determining bucket size. Altogether we denote
$\vX^\trunc\equiv(\vX^{\trunc,\RomI:\RomIII},X^{\trunc,\Ising})$ and $\vX^\frozen\equiv(\vX^{\frozen,\RomI:\RomIII},X^{\frozen,\Ising})$. One can verify by induction that the set of buckets $B^\Ising\in \mathcal{B}^\Ising(q_d)$ can be obtained by taking $B^\Ising = B^{\frozen,\Ising}\cap[N]$ for each $B^{\frozen,\Ising}\in\mathcal{B}^{\frozen,\Ising}(q_d)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.460273+00:00","domain":"probability theory","id":"claim_96890275aefa2c3796dd96e8cb9727900d5eab6ad2d440854824372d88d241df","kind":"definition","schema_version":1,"statement":"[Defn 12 (Kinetic solution of the penalized equation) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A predictable process $u_n$ is called a kinetic solution of \eqref{eq:penalized-hyperbolic}, if it satisfies \eqref{eq:usual moment bound} and there exists a kinetic measure $m_n$ such that $f_n=\one_{\{u_n>\xi\}}$ satisfies, for every $\varphi\in C_c^1\big(\mathbb T^N\times[0,T)\times\mathbb R\big)$,
\begin{align}
&\int_0^T\langle f_n(t),\partial_t\varphi(t)\rangle\dd t+\langle f^0,\varphi(0)\rangle+\int_0^T\langle f_n(t),a(\xi)\cdot\nabla_x\varphi(t)\rangle\,\dd t\nonumber\\
&=-\sum_{k\geq1}\int_0^T\int_{\mathbb T^N}g_k(x,u_n)\varphi(x,t,u_n)\dd x\dd\beta_k(t)\nonumber\\
&\quad-\frac12\int_0^T\int_{\mathbb{T}^N}G^2(x,u_n)\partial_\xi\varphi(x,t,u_n)\dd x\dd t\nonumber\\
&\quad+m_n(\partial_\xi\varphi)-\int_0^T\int_{\mathbb T^N}b_n(u_n-\psi)\varphi(x,t,u_n)\dd x\dd t,
\qquad\text{a.s.},
\end{align}
where
$f^0=\one_{\{u^0>\xi\}}$.","status":"unverified"}

