{"assumptions":[],"created_at":"2026-10-27T09:24:34.411117+00:00","domain":"probability theory","id":"claim_968b0c8d6d1026e1402941b7873209061097cda3328ccd28bd13ce9f5357946f","kind":"theorem","schema_version":1,"statement":"[Theorem 23 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every compact connected two-step pair $(G,L)$,
		\begin{equation}
			\beta_{G,L}
			=\frac{\operatorname{Scal}_G-\operatorname{Scal}_L}{6}
			=\frac1{12}\sum_{a,i}|[Y_a,X_i]|^2
			+\frac1{24}\sum_{i,j}|[X_i,X_j]|^2.
		\end{equation}
		In particular, $\beta_{G,L}\ge0$. For the tangent group $\mathbb N_{G,L}$ and its heat kernel $p_t^0$,
		\begin{equation}
			p_t^0(e)
			=\frac{t^{-Q/2}}{(4\pi)^{Q/2}}
			\int_{\lLie}\mathcal D_{G,L}(Y)\,\mathrm dY,
			\qquad
			C_{G,L}=\vol(G)p_1^0(e).
		\end{equation}
		Equivalently,
		\begin{align}
			C_L&=\frac{\vol(L)}{\vol(T)|\Wt_L|},
			\\
			\mathcal D_{G,L}(H)
			&=\prod_{\omega\in\Sigma_{\pLie}^+}
			w\bigl(\omega(H)\bigr)^{m_\omega},
			\qquad H\in\tLie,

		\end{align}
		and
		\begin{equation}
			C_{G,L}
			=\frac{\vol(G)\vol(L)}
			{(4\pi)^{Q/2}\vol(T)|\Wt_L|}
			\int_{\tLie}\Pi_L(H)^2
			\prod_{\omega\in\Sigma_{\pLie}^+}
			w\bigl(\omega(H)\bigr)^{m_\omega}\,\mathrm dH.
		\end{equation}
		The remaining Cartan integral has the integral-free expansion
		\begin{align}
			\int_{\tLie}\Pi_L(H)^2
			\prod_{j=1}^{N_{\mathrm{iso}}}
			w\bigl(\omega_j(H)\bigr)^{m_j}\,\mathrm dH
			&=\sum_{\mathcal C,\varsigma,\mu}
			\operatorname{vol}_{\tLie}
			(v_{\varsigma,1},\ldots,v_{\varsigma,r_T})
			p_{\mathcal C,\varsigma,\mu}
			\prod_{i=1}^{r_T}\mu_i!
			\notag\\
			&\qquad\quad\times
			\sum_{\mathbf n\in\mathbb N_0^{N_{\mathrm{iso}}}}
			\frac{\displaystyle
				\prod_{j=1}^{N_{\mathrm{iso}}}
				\binom{n_j+m_j-1}{m_j-1}}
			{\displaystyle
				\prod_{i=1}^{r_T}
				\bigl(A_{\mathcal C}(\mathbf n)
				(v_{\varsigma,i})\bigr)^{\mu_i+1}}.

		\end{align}
		All terms are nonnegative, and the multiple Dirichlet series converges absolutely.","status":"unverified"}

