{"assumptions":[],"created_at":"2026-10-27T13:59:53.333264+00:00","domain":"probability theory","id":"claim_97443d6a8ece2ec382be0ff3f248e0bdf2f1c76842d25025474ad0bfa176d4fb","kind":"concept","schema_version":1,"statement":"[Proposition lem-repeat-used of arXiv:2607.22324, 'The conclave process'] {}
