            \draw[dashed,->] (w2) -- (v2) node[midway,above] {$\R$};
        \end{tikzpicture}
        \begin{tikzpicture}
            \node (w) at (0,-2) {$w$};
            \node (w2) at (0,0) {$w'$};
            \node (v) at (2,-2) {$v$};
