{"assumptions":[],"created_at":"2026-10-27T21:35:04.166508+00:00","domain":"probability theory","id":"claim_999e9dd4831f63b1e834507f2ee7722db7a8ef68d99447f3e6c4f8ebbac035cb","kind":"concept","schema_version":1,"statement":"[Theorem thLIL1 of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] Assume
