{"assumptions":[],"created_at":"2026-10-26T20:56:49.281343+00:00","domain":"probability theory","id":"claim_9aa72b164ef6a6536d44de70b112778110567c1b3adab82afcc2dfacac86d871","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\mu \in \eP(T)$,
\begin{align*}
 \eF_\beta(X ; \mu) = \sup_{\nu \in \eP(T)} 
  \set[\Bigg]{\bm{\phi}_\beta(\nu) - \frac{1}{\beta}D(\nu \| \mu)},
\end{align*}
where, for any $\mu\in \eP(T)$, 
\begin{align*}
  \bm{\phi}_\beta(\mu)
  \deq \lim_{\epsilon\downarrow 0} \bm{\phi}_{\beta,\epsilon}(\mu)
  \deq \lim_{\epsilon\downarrow 0}\lim_{N \to \infty} 
  \frac{1}{N}\eF_\beta(\bm{X}^N ; \su_{\cC_{N,\mu,\epsilon}}),
\end{align*}
with $\su_{\cC_{N,\mu,\epsilon}}$ denoting the uniform probability measure on $\cC_{N,\mu,\epsilon}$. In particular, for any $\mu_\beta^*$ that achieves the supremum
$\sup_{\mu\in \eP(T)}\eF(X;\mu)$,
\begin{align*}
  \sup_{\mu\in \eP(T)}\eF_{\beta}(X;\mu)=\eF_\beta(X ; \mu_\beta^*) = \bm{\phi}_\beta(\mu_\beta^*)=\sup_{\mu\in \eP(T)}\bm{\phi}_{\beta}(\mu).
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.844362+00:00","domain":"probability theory","id":"claim_9aa7c369dd0f8a0fe82a20bb732fc54b8bdc874c61c6d1410819ea66a8d9d061","kind":"theorem","schema_version":1,"statement":"[Proposition prop:moments of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $m\ge2$, $\beta>0$, $m\beta>1$, and put $\delta=m\beta/2$. Then
\begin{align}
\mathbb E S_1^2&=\frac{1}{4(m\beta-1)(2m+1)},\\
\mathbb E S_2&=\frac{m\beta}{4(m\beta-1)(2m+1)}.
\end{align}
Moreover,
\begin{equation}
\mathbb E\xi''(0)=-(2\delta-1)\mathbb E\xi'(0)^2.
\end{equation}","status":"unverified"}

