{"assumptions":[],"created_at":"2026-10-27T15:27:25.786599+00:00","domain":"probability theory","id":"claim_9ad1c1a1d3900bf752c9ae6c4d02a7d69c283ccc76e358898c71eb1f85926e62","kind":"theorem","schema_version":1,"statement":"[Cor of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exist absolute constants $C, \beta_0>0$ such that for all $N \ge 1$, $k \in \{-N,...,N\}$ and $\beta>\beta_0$, if $H$ is such that $N M_{N,H} = k = N \tan \varphi_{\mathbf{n}}$, 
    \begin{align*}
       \frac{C^{-1}}{\sqrt{1 + N e^{-2\beta} + k}}  e^{ - \tau_{\beta}(\varphi_{\mathbf{n}}) \|(N,k)\| }\le \Xi(N,\mathbf{n}) \le \frac{C}{\sqrt{1 + Ne^{ - 2\beta}  + k}} e^{ - \tau_\beta(\varphi_{\mathbf{n}})\|(N,k)\|}
    \end{align*}","status":"unverified"}

