    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.641068+00:00","domain":"probability theory","id":"claim_9af05d19cd0d01bf63dc172649c01497bcb24eb324e61b58ea94fa29146d292f","kind":"lemma","schema_version":1,"statement":"[Lemma 25 (Canonical detector and its localized equation) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let $S\in\mathfrak S$, and let $u_S$ and $\tau_S$ be defined as above. Let $\left(X,M,\bigl(A^\alpha\bigr)_{\alpha\in R_+}\right)$ be a generalized weak limit obtained in Proposition~\ref{prop:deg:skorokhod}, and let the decomposition from Proposition~\ref{prop:deg:interior-ident-integrability} hold. Then the following statements hold.

\begin{enumerate}[label=\textup{(\roman*)}]
    \item For every $x\in\Cc$,
    \begin{equation*}
        \tau_S(x)\ge0.
    \end{equation*}
    Moreover,
    \begin{equation*}
        \tau_S(x)=0
        \qquad\Longleftrightarrow\qquad
        \langle x,\beta\rangle=0
        \quad \text{for every } \beta\in S.
    \end{equation*}
    In particular, $\tau_S$ vanishes on $F_S$, and on
    $\mathcal U_{S,\eta,r}$ one has
    \begin{equation*}
        \tau_S(x)=0
        \qquad\Longleftrightarrow\qquad
        x\in F_S.
    \end{equation*}

    \item For every $x\in\Cc$ and every $\beta\in S$,
    \begin{equation*}
        0\le \langle x,\beta\rangle\le \tau_S(x).
    \end{equation*}

    \item For every $\beta\in S$,
    \begin{equation*}
        \langle u_S,\beta\rangle>0.
    \end{equation*}
    Hence $u_S$ is an admissible detector for the face $F_S$, and $\Gamma(S,u_S)=S$. In particular, the constant $c_S:=\min_{\beta\in S}\langle u_S,\beta\rangle$ is strictly positive.

    \item We have 
    \begin{equation*}
        q_S(t,x)
        \le
        |S|\sum_{\beta\in S} a_\beta(t,x),
        \qquad
        (t,x)\in[0,\infty)\times\Cc.
    \end{equation*}
    \item Let $T,r,\eta>0$, and let $\theta$ be a stopping time such that $\theta\le T$, $X(s)\in\mathcal U_{S,\eta,r}$, $0\le s\le\theta$. Then, for every $0\le t\le T$,
    \begin{align}

        \tau_S\bigl(X(t\wedge\theta)\bigr) &= \tau_S(x_0) + M_S(t\wedge\theta) + \int_0^{t\wedge\theta}B_S(s,X(s))\,ds                                      \nonumber\\
    &\quad
    +
    \sum_{\beta\in S}
    \langle u_S,\beta\rangle
    \int_0^{t\wedge\theta}
    \frac{k_\beta(s,X(s))}
         {\langle X(s),\beta\rangle}
    \mathbf 1_{\{\langle X(s),\beta\rangle>0\}}\,ds       \nonumber\\
    &\quad
    +
    \sum_{\beta\in S}
    \langle u_S,\beta\rangle
    \Lambda^\beta(t\wedge\theta),
\end{align}
where $M_S(t):=\langle u_S,M(t)\rangle$.
    \item The process $M_S$ is a continuous local martingale and
\begin{equation}

    \langle M_S\rangle(t)
    =
    \int_0^t q_S(s,X(s))\,ds.
\end{equation}
Consequently,
\begin{equation}

    \langle M_S(\cdot\wedge\theta)\rangle(t)
    =
    \int_0^{t\wedge\theta} q_S(s,X(s))\,ds.
\end{equation}

\end{enumerate}","status":"unverified"}

