{"assumptions":[],"created_at":"2026-10-26T19:33:46.776521+00:00","domain":"probability theory","id":"claim_9d39168111ffcebb1f3a1ec452d4e1e424d232b440b9819ef034908a88551dd1","kind":"concept","schema_version":1,"statement":"[Theorem 7 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] Let $\hat{u}$ be the optimal solution to the consumption problem \eqref{OP}. Then, we derive
\begin{eqnarray*}
\hat{u}(t)&=& \left(\mathbb{E}\left[ \mathbb{E}^{\mathbb{Q}}\left(\Psi(t)\theta\middle|\mathcal{F}_t\right)|\mathcal{G}_t\right]\right)^{-1}\\
&=& \left(\mathbb{E}\left[\frac{\mathbb{E}\left(\Psi(t)M(T)\theta\middle|\mathcal{F}_t\right)}{M(t)}\middle|\mathcal{G}_t\right]\right)^{-1},
\end{eqnarray*}
where $\mathbb{Q}$ is a probability measure defined by
\begin{eqnarray}
	 d\mathbb{Q}=M(T)d\P
\end{eqnarray}
 with
\begin{eqnarray*}
	M(t)=\exp\left(\int_0^t\sigma_0(s)dB(s)-\frac{1}{2}\int_0^t\sigma_0^2(s)ds\right).
\end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:59:45.011347+00:00","domain":"probability theory","id":"claim_9d3db034ada6821f442fa04f2149212310d35d3100dc4d57a83e5dafc750c109","kind":"definition","schema_version":1,"statement":"[Definition W SPDE-1 of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ and $\rho_0$ be defined as in Definition (RKS smooth spde of the paper), for any $\varepsilon,\eta\in(0,1)$, a weak solution  $\rho$ of (equation SPDE-1 of the paper) with initial data $\rho(\cdot, 0)=\rho_0$ is a nonnegative, $\mathcal{F}_{t}$-predictable process that satisfies the following properties.
\begin{enumerate}
		\item Conservation of mass: almost surely for every $t\in[0,T]$,
		\begin{equation}
		\|\rho(\cdot,t)\|_{L^{1}_{\mathbb{T}^{2}}}=\left\|\rho_0\right\|_{L^{1}_{\mathbb{T}^{2}}}.
		\end{equation}




		\item Pathwise entropy dissipation estimates: almost surely, 
		\begin{align}
 \int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
\frac{s_{\eta}(\rho)}{\rho}\nabla\rho\cdot
\xi_{K}
+\varepsilon N_KT+1,
\end{align}
for all $t \in [0,T]$.  

\item The equation: 
for every $\psi \in C^{\infty}_{\mathbb{T}^2}$, almost surely for every $t \in[0, T]$,
