{"assumptions":[],"created_at":"2026-10-27T21:41:19.328840+00:00","domain":"probability theory","id":"claim_9ebc93a427e8d0d6589ed8a8d445faeccfc8c7d3a442e8c1a027e459464815c1","kind":"definition","schema_version":1,"statement":"[Definition def:oriented_cone of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\mathbb G$ be a Carnot group and let $\mathbb H,\mathbb K$ be two
homogeneous subgroups of $\mathbb G$. We say that $\mathbb H$ and
$\mathbb K$ are \emph{complementary} if
\begin{align*}
\mathbb H\cap\mathbb K=\{e\}, \quad \mbox{and} \quad \mathbb G=\mathbb H\mathbb K.
\end{align*}
Assume moreover that $\mathbb K$ is a one-dimensional horizontal homogeneous
subgroup. Thus
\begin{align*}
\mathbb K=\exp(\mathbb RX)
\end{align*}
for some nonzero $X\in V_1$. Set
\begin{align*}
\mathbb K^+:=\{\exp(tX):t\geqslant0\}.
\end{align*}
For $p\in\mathbb G$ and $\beta,\rho>0$, we define the
\emph{oriented intrinsic cone} associated with the decomposition
$\mathbb G=\mathbb H\mathbb K$ by
\begin{align*}
\mathcal C_p^+(\beta,\rho;\mathbb H,\mathbb K)
:=
p\left\{
hk\in\mathbb H\mathbb K:
k\in\mathbb K^+,\ 
\|h\|\leqslant\beta\|k\|,\ 
\|k\|<\rho
\right\}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.356367+00:00","domain":"probability theory","id":"claim_9ebf97f297b27f794f1b611c08ac1c00fcbe6c37913844a10d7dff97810ee7d8","kind":"theorem","schema_version":1,"statement":"[Proposition MSSAdaption_general of arXiv:2412.01635, 'On the Weak Convergence of the Function-Indexed Sequential Empirical Process and its Smoot'] Let $\nu \geq 1$, $\Psi \neq \emptyset$ and $W_1,...,W_n: \Omega \to \ell^\infty(\Psi)$ be arbitrary processes. If there exist $\alpha > 1$ and $g: \{1,...,n\}^2 \to \mathbb R$ which fulfill
	\begin{equation}
		\mathrm E^*\left\{ \norm{S_{i,j}^W}_\Psi^\nu \right\} \leq g^{\alpha}(i,j)
	\end{equation}
	for all $1 \leq i \leq j \leq n,$ and if it holds
	\begin{align*}
		\mathrm{(i')}&:~ g(i,j) \geq 0, \text{ for all } (i,j) \in \{1,...,n\}^2, \nonumber\\
		\mathrm{(ii')}&:~ g(i,j) \leq g(i,j+1), \text{ for all } 1 \leq i \leq j \leq n-1, \nonumber \\
		\mathrm{(iii')}&:~ g(i,j) + g(j+1,k) \leq Q g(i,k), \text{ for all } 1 \leq i \leq j < k \leq n, \nonumber
	\end{align*}
	for some $Q \in [1,2^{(\alpha-1)/\alpha})$, then there exists a constant $A$ that only depends on $\alpha, \nu,$ and $Q$ such that
	\begin{equation}
		\mathrm E^* \left\{\norm{M_{1,n}^W}_\Psi^\nu \right\} \leq A g^{\alpha}(1,n).
	\end{equation}
	One may take
	\begin{equation*}
		A = \left(1 - \frac{Q^{\alpha / \nu}}{2^{(\alpha - 1)/ \nu}} \right)^{-\nu}.
	\end{equation*}","status":"unverified"}

