		\sup_{\substack{k\in\ndZ\\ |k-\mu_B n|\le C n^{2/3}}} \left| g_B n^{2/3}\Prb{B_n=k} - h\left( \frac{\mu_B n-k}{g_B n^{2/3}} \right) \right| \to 0
	\end{align}
	as $n\to\infty$. Set $r = \frac{\mu_B}{\mu_A}$. For $\theta \in \ndR$ and all sufficiently large $n$, define
	\begin{align*}
		m_n(\theta) = \left\lfloor rn + \frac{\theta}{\mu_A}n^{2/3} \right\rfloor.
