{"assumptions":[],"created_at":"2026-10-26T20:57:44.952186+00:00","domain":"probability theory","id":"claim_9f9c748f64ee464a02f117d5038d9e52c0d2e7d303f23f6e143b793d1e718be7","kind":"theorem","schema_version":1,"statement":"[Prop 46 (Concentration bounds, $L^p$-norm) of arXiv:2606.24887, '2606.24887'] Let $r$ be even and $1 \le d \le N$. Let $X_1,...,X_{N}$ and $Y_1,...,Y_N$ be independent random variables satisfying
		\begin{equation*}
			\mathbb{E}Z  =0, ~~~ \mathbb{E}  \abs{Z}^k  \le \frac{1}{N d^{(k-2)/2}},
		\end{equation*}
		for all $Z \in \{X_i,Y_i:~ i \in [N]\}$ and $2 \le k \le r$. Let $(a_{i})_{i \in [N]} \in \CC^N$ and $(b_{ij})_{i,j \in [N]} \in \CC^{N \times N}$ be deterministic sequences. Suppose that
		\begin{equation*}
			\bigg( \frac{1}{N} \sum_{i} \abs{a_i}^2\bigg)^{1/2} \le \gamma,~~ \frac{\max_i \abs{a_i}}{\sqrt{d}} \le \psi
		\end{equation*}
		and 
		\begin{equation*}
			\bigg( \max_{i} \frac{1}{N} \sum_j \left|b_{ij}\right|^2 \bigg)^{1/2} \vee \bigg( \max_{j} \frac{1}{N} \sum_i \left|b_{ij}\right|^2 \bigg)^{1/2} \le \gamma, ~~~ \frac{\max_{i,j} \left|b_{ij}\right|}{d} \le \psi,
		\end{equation*}
		for some $\gamma, \psi \ge 0$. Then
		\begin{align}
			\normbb{\sum_{i}a_i X_i}_{r} &\le \left( \frac{2r}{1+ 2(\log(\psi/\gamma))_{+}} \vee 2 \right) (\gamma \vee \psi),\\
			\normbb{\sum_{i}a_i \left(\abs{X_i}^2  - \mathbb{E}\abs{X_{i}}^2\right) }_{r} &\le 2\left( 1+  \frac{2d}{N} \right) \max_{i} |a_i|\left( \frac{r}{d} \vee \sqrt{\frac{r}{d}} \right),\\
			\normbb{\sum_{i,j} a_{ij}X_i Y_j}_{r} &\le  \left( \frac{2r}{1+ 2(\log(\psi/\gamma))_{+}} \vee 2 \right)^2 (\gamma \vee \psi),\\
			\normbb{\sum_{i\neq j} a_{ij}X_i X_j}_{r} &\le  \left( \frac{4r}{1+ (\log(\psi/\gamma))_{+}} \vee 4 \right)^2 (\gamma \vee \psi).
		\end{align}","status":"unverified"}

