{"assumptions":[],"created_at":"2026-10-27T12:06:55.288960+00:00","domain":"probability theory","id":"claim_a0473961ae74cd12c29c7d8da553abe7faf3136d9a9d00900941ba566786e4b0","kind":"definition","schema_version":1,"statement":"[Defi def:cLSI of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] The \emph{log-Sobolev inequality (LSI)} is satisfied if there exists a constant $\alpha > 0$ such that 
\begin{equation}
\forall \varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}}): \ \ \mathscr{H}_\pi(\varphi)\leq  \frac{1}{\alpha} \mathscr{R}_\pi(\varphi,M).
\end{equation}
The supremum over all possible choices of $\alpha$ is called the \emph{log-Sobolev constant}. We denote it by
\begin{equation}
    \alpha_{\LSI}(M) \coloneqq \inf_{\substack{\varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}})\\\varphi\neq \1}}\frac{\mathscr{R}_\pi(\varphi,M)}{\mathscr{H}_\pi(\varphi)}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.753739+00:00","domain":"probability theory","id":"claim_a04a7709541a78e9e011ca6ff781d79330c9a0959c568574f2bcb0f9086c4297","kind":"theorem","schema_version":1,"statement":"[Prop PropISDEGL of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For any $\gamma\ge \sum_{i=1}^\infty x_i$, whenever $(x_i)_{i\in \mathbb{N}}\in \mathbf{W}_{\infty;+}^\circ$, the projection of $\mathbf{X}_{GL}^\bullet$ on the $(\mathsf{x}_i(\bullet))_{i\in \mathbb{N}}$ solves the infinite system of SDE
\begin{equation*}
\mathsf{x}_i(t)= x_i+\int_0^t\mathsf{x}_i(s)\mathrm{d}\mathsf{w}_i(s) + \frac{\theta}{2}\int_0^t\mathsf{x}_i(s)\mathrm{d}s
 +\int_0^t\sum_{j=1,j\neq i}^{\infty}\frac{\mathsf{x}_i(s)\mathsf{x}_j(s)}{\mathsf{x}_i(s)-\mathsf{x}_j(s)}\mathrm{d}s, \  \forall t\ge 0 , \   i \in \mathbb{N},
 \end{equation*}
with independent standard Brownian motions $(\mathsf{w}_i)_{i\in \mathbb{N}}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:27:56.790507+00:00","domain":"probability theory","id":"claim_a04c9c5f869bd45a1e60e3661da3167ec592e39f709f2631d2ae922a838b66db","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2609.00183, '2609.00183'] Let $u$ be a harmonic map to an $N$-dimensional conical DM-complex $Y_C$ with splitting $u=(V,v):B_{\sigma_j}(0) \to (\mathbb{R}^j \times Y_C^{N-j},d_G)$ satisfying $\Ord_{\phi,v}(0,R_0)\leq \Lambda$ and $\sup_{B_{\sigma_j}(0)}|\nabla u| \leq M$, then there exists $\eta_1>0$ and $\calA\geq 1$, depending only on $\Lambda$, $n$, $M$, and the constant in \cite[(29)--(33)]{dm}, such that for $\sigma\in (0,\eta_1]$ and $\eta\in (0,\eta_1]$, if for $x\in B_{R_0/64}(0)$ there exists a homogeneous Lipschitz map $h:B_{\sigma}(x)\to Y_C$ such that
     \begin{equation*}
         \sup_{B_{\sigma}(x)}d(v,h)\leq \eta\paren{\sigma^{1-n}I_{\phi,v}(x,\sigma)}^{1/2},
     \end{equation*}
     then $\alpha\leq \calA$, where $\alpha$ is the degree of $h$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.341750+00:00","domain":"probability theory","id":"claim_a053e65fe98306211eeebe1430330851d01fd0c97f2633e3c589fa150a0bd696","kind":"theorem","schema_version":1,"statement":"[Them Markov_stationnaire of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider an interval  $T \subset \mathbb{R}$  and  a continuous positive semi-definite kernel $K : T \times T \to \mathbb{R}$ with constant variance function equal to $1.$ We denote by $P$ the centered Gaussian process with covariance function $K.$ For every $(s,t,h^*) \in T \times T \times \mathbb{R}_+^*$, we set  $$C_{s,t}(h^*) := \ens{(v,h)}{v \in [s,t[, v +h \in [s,t], h \in ] 0, h^*]}.$$

		\begin{enumerate}
			\item Assume $\alpha^K$ is well defined, continuous and for every $ s<t \in T \times T$
			\begin{equation}
				 \sup_{(v,h) \in C_{s,t}(h^*)} \left|L^K_v(h) - \alpha^K(v)\right| \xrightarrow[h^* \to 0^+]{} 0.
			\end{equation} 
			Then  $P_{\alpha^K}$ is the strong local Markov transform of $P.$
			\item Assume, for every $s<t  \in T \times T$ 
			\begin{equation}
				\inf_{(v,h) \in C_{s,t}(h^*)} L^K_v(h) \xrightarrow[h^* \to 0^+]{} + \infty.
			\end{equation}
		Then $P_{+\infty}$ is the strong local Markov transform of $P.$
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.352354+00:00","domain":"probability theory","id":"claim_a054813e9f52faef99c1afa684bb19b7080ab27c15b842a9d49cbd61c8230019","kind":"theorem","schema_version":1,"statement":"[Theorem 5 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] Assume that \textbf{Hypothesis (\MakeUppercase{\romannumeral 1})} holds. Let $u_{1}, u_{2} \in L^{1}((0,T)\times \mathbb{R}^{d})\cap L^{\infty}((0,T)\times \mathbb{R}^{d})$ be two distributional solutions to (\ref{1}) in $(0,T)\times \mathbb{R}^{d}$ such that $u_{1}-u_{2} \in L^{\infty}((0,T);H^{-1})$ and
 \begin{equation}
     \displaystyle\lim_{t \rightarrow 0} \displaystyle \esssup_{s \in (0,t)}\left | \left ( u_{1}(s)-u_{2}(s),\varphi  \right )_{2}\right |=0, \quad  \forall \varphi \in C^{\infty}_{0}(\mathbb{R}^{d}). 
 \end{equation}
 Then, $u_{1}\equiv u_{2} $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763830+00:00","domain":"probability theory","id":"claim_a05821f529ce72ebf53f1ad837e703c5a5d11543aff70aaf4ff1980ab290a127","kind":"theorem","schema_version":1,"statement":"[Theorem 9 (Well-posedness of RDEs) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$, $\lambda > 0$,
