{"assumptions":[],"created_at":"2026-10-28T02:56:14.297439+00:00","domain":"probability theory","id":"claim_a17687d7b0e32a16f3850ea208a5850d343fbd97cf32e80ff3a76ca9bd485a59","kind":"concept","schema_version":1,"statement":"[Theorem THM:1 of arXiv:2412.09790, 'Critical threshold for weakly interacting log-correlated focusing Gibbs measures'] Let $\{\lambda_N\}_{N\in \mathbb{N}}$ be 
a non-increasing sequence of positive numbers
tending to $0$ as $N \to \infty$, 
and 
let $\{K_N\}_{N\in \mathbb{N}}$ be a non-decreasing sequence
of positive numbers.
Then, there exist $\lambda^*\ge \lambda_*>0$ such that the following statements hold\textup{:}

\smallskip
\noindent
\textup{(i) (weakly coupling regime).}
Suppose that 
\begin{equation}
 \lambda_N\le \lambda_* (K_N+\log N)^{-1}

\end{equation}

\noindent
for any $N \in \mathbb{N}$.
Then, 
given any $p\geq 1$ we have
\begin{align}

    \sup_{N\in\mathbb{N}}
    \Big\|
    \mathbf 1_{\{|\int_{\mathbb{T}^d} \, : (\pi_N u)^2: \, dx| \, \leq K_N\}}  
    e^{ \lambda_N R_N (u)}
    \Big\|_{L^p(\mu)}<\infty.

\end{align}

\noindent
In particular, we have
\begin{align}
    \lim_{N\rightarrow\infty}
    \mathbf 1_{\{|\int_{\mathbb{T}^d} \, :(\pi_N u)^2: \, dx| \, \leq K_N\}}  
    e^{\lambda_N  R_N (u)}
    =
\mathbf 1_{\{|\int_{\mathbb{T}^d} \, :u^2: \, dx| \, \leq K\}}  
\quad     \text{in}\ L^p(\mu), 

\end{align}

\noindent
where 
$K = \lim_{N \to \infty}K_N \in (0, \infty]$.
Here, 
\[\int_{\mathbb{T}^d} :\!u^2\!:dx = \lim_{N \to \infty}
\int_{\mathbb{T}^d} :\!(\pi_N u)^2\!:dx,\]

\noindent
where the limit is understood in 
$L^p(\mu)$ and $\mu$-almost surely
as in Lemma (LEM:conv0 of the paper).
As a consequence, 
we have

\smallskip
\begin{itemize}
\item[(i.a)] 
 If $K  =  \lim_{N \to \infty}K_N  = \infty$, 
then the truncated Gibbs measure $\rho_N$
in (equation GibbsN1 of the paper)
converges in total variation to the base Gaussian measure $\mu$ in (equation gauss0 of the paper)
as $N \to \infty$.

\smallskip
\item[(i.b)]
 If $K = \lim_{N \to \infty}K_N < \infty$, 
then the truncated Gibbs measure $\rho_N$
in (equation GibbsN1 of the paper)
converges in total variation to the base Gaussian measure
with a renormalized $L^2$-cutoff\textup{:}
\begin{align*}
\mathbf 1_{\{|\int_{\mathbb{T}^d} \, :u^2: \, dx| \, \leq K\}}  d\mu, 

\end{align*}

\noindent
as $N \to \infty$.

\end{itemize}

\smallskip
\noindent
\textup{(ii) (strongly coupling regime).}
Suppose that 
\begin{equation}
\lambda_N\ge \lambda^{*}(K_N+\log N)^{-1}
 \end{equation}

\noindent
for any sufficiently large $N \gg 1$.
Then, we have 
\begin{align}
\sup_{N\in\mathbb{N}}Z_{N}:=
\sup_{N\in\mathbb{N}}\mathbb{E}_{\mu}
\Big[ \mathbf 1_{\{|\int_{\mathbb{T}^d} \, : (\pi_N u)^2: \, dx| \, \leq K_N\}}
e^{ \lambda_N R_N (u)} \Big]
=\infty.
\end{align}

\noindent
As a consequence, 
the truncated Gibbs measure $\rho_N$ in (equation GibbsN1 of the paper)
does not converge   to any  limit in total variation, even up to a subsequence. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:59:24.053376+00:00","domain":"probability theory","id":"claim_a17994846fe0a9d13a9405b6aaa2b1cfed913006f71ee25a7d0239636ffccc85","kind":"lemma","schema_version":1,"statement":"[Lemma lem:residual of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $\ell\geq1$,
