		and
		\begin{equation} 
			\sum_{\sigma\prec\tau} \sigma \otimes D^n(\tau/\sigma) = \sum_{\nu\prec\tau} \downarrow^n\hspace{-2pt} \nu \otimes \tau/\nu.
