			&\mathbb{P}\Bigl(
			\max_{z\in\Lambda}\xi_\varepsilon^{\alpha,z}(T+T_r)
			\geq A_\alpha(T+T_r)+\lambda-n
			\Bigr)\\
			&\quad\leq
			Ce^{-c(\lambda+n)}
