			\exp\bigl\{-d(T+T_r)-c\lambda+c(T+T_r)^\alpha(n+1)\bigr\},
			\qquad n\in\mathbb{Z}_+.
		\end{aligned}
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.597491+00:00","domain":"probability theory","id":"claim_a20cf1cd559a93c01612a9d2fe17dbaf3c21ac8cdad053a8fd6422311a79222c","kind":"definition","schema_version":1,"statement":"[Definition 16 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] The regenerative increment is called full-rank if $\mathcal L$ has rank $d$. If $\mathcal L$ is full-rank, its covolume is

\begin{equation*}
h_{\mathcal L}=|\Z^d/\mathcal L|.
\end{equation*}

The renewal lattice generated by complete cycles is

\begin{equation*}
\mathcal L_* = \mathcal L+\Z y_0,
\end{equation*}

and, when $\mathcal L$ is full-rank, its covolume is

\begin{equation*}
h_* = |\Z^d/\mathcal L_*|.
\end{equation*}

The regenerative increment is called renewal-aperiodic if $\mathcal L_*=\Z^d$.","status":"unverified"}

