{"assumptions":[],"created_at":"2026-10-27T14:18:13.248144+00:00","domain":"probability theory","id":"claim_a31212dbbddcd10d7d72d8a98163359e3ee71a8efc0823f3c683a0e7e6bc1d1e","kind":"concept","schema_version":1,"statement":"[Prop s-sde of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp There exist constants {\small$\mathrm{K},\mathrm{M}=\mathrm{O}(1)$} such that the following holds. We have the following \abbr{SDE} for {\small$\mathbf{S}^{N}$}, in which we use notation to be explained afterwards:

\begin{align}
\d\mathbf{S}^{N}_{\t,\x}&=\mathscr{T}_{N}\mathbf{S}^{N}_{\t,\x}\d\t+[\mathscr{S}^{N}\star(\sqrt{2}\lambda N^{\frac12}\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}\d\mathbf{b}_{\t,\cdot})]_{\x}\\
&+N\sum_{\substack{\n=1,\ldots,\mathrm{K}\\{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\lesssim \mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\d\t\\
&+N\sum_{\substack{\n=1,\ldots,\mathrm{K}\\{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\lesssim \mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{T},\mathrm{av}}_{\mathfrak{t}_{\mathbf{Av}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{X},\mathfrak{q}_{\n}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\d\t\\
&+\mathrm{Err}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}\d\t.
\end{align}

\begin{itemize}
\item We set {\small$\mathscr{T}_{N}:=(N^{2}\alpha+\frac12N\lambda^{2})\Delta$}, where {$\Delta$} is the discrete Laplacian as in (equation eq:phi of the paper), and $\alpha,\lambda$ are defined after (equation eq:ch of the paper). 
\item For each {\small$\n$} in the summations in (equation eq:s-sdeI of the paper)-(equation eq:s-sdeII of the paper), the local function {\small$\mathfrak{q}_{\n}$} is admissible (see Definition (definition:admissible of the paper)).
\item The parameters {\small$\mathfrak{t}_{\mathbf{Av}},\mathfrak{n}_{\mathbf{Av}}$} are from Definition (definition:eq-operators of the paper).
\item The {\small$\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\in\R$} are deterministic coefficients satisfying the following estimates.

\begin{itemize}
\item If {\small$\min\{|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\}\geq2$}, then we have {\small$|\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}|\lesssim 1$}. In general, we have {\small$|\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}|\lesssim N$}.
\end{itemize}

\item The quantity {\small$\mathrm{Err}[\mathbf{R}^{N}\mathbf{S}^{N}]$} is a linear operator in {\small$\mathbf{S}^{N}$} which satisfies the following deterministic estimate for some positive {\small$\mathrm{C}\lesssim1$}, in which {\small$\mathsf{f}:\Z\to\R$} is any test function:

\begin{align}
|\mathrm{Err}[\mathbf{R}^{N}_{\t,\cdot}\mathsf{f}]_{\x}|\lesssim N^{-\frac12+\mathrm{C}\delta_{\mathbf{S}}}\cdot N^{-1+\delta_{\mathbf{S}}}\sum_{|\w|\lesssim N^{1-\delta_{\mathbf{S}}}}\Big(1+\sum_{|\z|\lesssim1}|\bphi_{\t,\x+\w+\z}|^{\mathrm{C}}\Big)\cdot|\mathbf{R}^{N}_{\t,\x+\w}|\cdot|\mathsf{f}_{\x+\w}|.
\end{align}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.163198+00:00","domain":"probability theory","id":"claim_a313d68bccfd0522875f176c00b6ad6a732b1e9fc020912c0c6dc1b9f822490d","kind":"concept","schema_version":1,"statement":"[Prop Prop_K_Tame of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every ${\mathbf{p}} \in \mathbf{Dir}$ and $(Z,[{\mathfrak l}]) \in \mathbf{Ram}$ the graded Fréchet space $\paren{K^\infty\paren{X{\backslash} Z,S\otimes{\mathfrak l};{\mathbf{p}}},(\Abs{-}_{K^k})_{k \in {\mathbf{N}}_0}}$ defined by
  \begin{align*}
    K^\infty\paren{X{\backslash} Z,S\otimes{\mathfrak l};{\mathbf{p}}}
    &\coloneq
      H_a^\infty\paren{X{\backslash} Z,S\otimes{\mathfrak l};0;{\mathbf{p}}}
      \cap
      (D_{\mathbf{p}}^{\mathfrak l})^{-1} w_{\log}^{-1} H_a^\infty\paren{X{\backslash} Z,S\otimes{\mathfrak l};0;{\mathbf{p}}}, \quad\text{and} \\
    \Abs{\phi}_{K^k}
    &\coloneq
      \Abs{\phi}_{H_b^{k+2}} + \Abs{\nabla \phi}_{H_b^{k+1}} + \Abs{w_{\log} D_{\mathbf{p}}^{\mathfrak l}\phi}_{H_b^{k+1}} + \Abs{\nabla w_{\log} D_{\mathbf{p}}^{\mathfrak l}\phi}_{H_b^k}
  \end{align*}
  is tame;
  that is, it has the smoothing operator property.
  Here $w_{\log}$ denotes multiplication by $\bracket{\log(r)} = \sqrt{1 + \log(r)^2}$ and $r$ denotes the distance to $Z$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:33:21.444196+00:00","domain":"probability theory","id":"claim_a316731c96f6c6cab65716878864f08512fc50c5b33bc6e6d98c1060d07abbf0","kind":"concept","schema_version":1,"statement":"[Pro MinorityFraction of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] For the two-element space $S=\{1,2\}$, any positive $\kappa: S \times S \to (0,\infty) $ and any $\mu_1 \in (0,1)$, with the quantities $(\varphi_{k,l}^{\boldsymbol{m}})_{k,l \in \{1,2\}}$ and $\eta_1^{\boldsymbol{m}}$ defined in (equation eq: LyapunovFunction of the paper) and (equation eq: varphik of the paper), almost surely as $n\rightarrow \infty,$ 
\begin{equation}
\begin{split}
\mathbb{E}\Big[\frac{d_{\phi_n}^{\mathrm{mino}}}{d_{\phi_n}} \mid G_n\Big] \stackrel{n \rightarrow \infty}{\rightarrow} B^{\mathrm{mino}}_{k,\boldsymbol{m},\boldsymbol{\varphi}}:=\sum_{k=1}^2A_{k,\boldsymbol{m},\boldsymbol{\varphi}}\left(\eta_1^{\boldsymbol{m}}\varphi_{1,k}^{\boldsymbol{m}}-m_k\mu_k\frac{\varphi^{\boldsymbol{m}}_{k,1}}{\varphi^{m}_{k}}\right)+\mu_k\frac{\varphi^{\boldsymbol{m}}_{k,1}}{\varphi^{\boldsymbol{m}}_{k}}.
\end{split}
\end{equation}
In particular, by (equation eq: Rmino Expansion of the paper), as $c \downarrow 0$,
\begin{equation}
\begin{split}
&\frac{R_\mathrm{mino}(G_n)}{n+n_0} \stackrel{n \to \infty}{\rightarrow}\mu_1+c\left(B^{\mathrm{mino}}_{k,\boldsymbol{m},\boldsymbol{\varphi}}-\mu_1\right)+O(c^2) \quad \text{almost surely}.
\end{split}    
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.751742+00:00","domain":"probability theory","id":"claim_a3169c5d7d556be35ea758a43ce7cfcb9213fd6d387a20b1d0ddc69d07c7bb81","kind":"theorem","schema_version":1,"statement":"[Theorem 52 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] There is a unique probability measure \(\pi_H\) on \(\mathbb R_+\) such
that, with
