{"assumptions":[],"created_at":"2026-10-27T21:48:02.408061+00:00","domain":"probability theory","id":"claim_a32685ba1ec508d34a1b59257b39f9fa088976627a047a3142003a94e9f6d885","kind":"theorem","schema_version":1,"statement":"[Prop twistgroup of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] The group $G_m^{tw}$ is free on $Y = x_{2m+4}$, $H = x_2(x_{m+4}^{-1}x_{m+3})^m$. Killing the trivial-strand meridian gives the quotient
\begin{equation*}
	Q_m^{tw} = \langle a, b \mid w^ma = bw^m \rangle \ \ \ \ \ w = ba^{-1}b^{-1}a
\end{equation*}
In the conventions of [hosteshanahan], this is the fundamental group of the twist knot complement $K_{2m}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.332325+00:00","domain":"probability theory","id":"claim_a329213ace57ff498df55d8845d7c449f2b5837cdea0323e58fdaeaaedd74b6f","kind":"concept","schema_version":1,"statement":"[Theorem 6 of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Suppose that Assumptions~\ref{a1-4} and \ref{a1-5} hold and for $\prob_{0}$-a.e.\ $\omega$,

  \begin{align}
    \inf_{y \in \cC_{\infty}(\omega)} \theta^{\omega}(y) > 0.
  \end{align}

  Further, assume that there exist $p, q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that for $\prob_{0}$-a.e.\ $\omega$,

  \begin{align}
    \sup_{R \geq 1} \Bigl(
      \Norm{1 \vee \theta^{\omega}}{p, B^{\omega}(0, R)}
      + \Norm{1 \vee \nu^{\omega}}{q, B^{\omega}(0, R)}
    \Bigr)
    \;<\;
    \infty.
  \end{align}

  Then, for every $m \geq 2$ and $\prob_{0}$-a.e.\ $\omega$, there exist $C_{10}(\omega) \in (0, \infty)$ and $\alpha, \beta, \gamma \in (0, 1)$ (independent of $\omega$) with $\alpha + \beta + \gamma = 1$ such that for every $f\colon \cC_{\infty}(\omega) \to \bbR$,

  \begin{align}
    \norm{f}{2}{\cC_{\infty}(\omega), \theta^{\omega}}^2
    \;\leq\;
    C_{10}(\omega)\, \cE^{\omega}(f)^{\alpha}\,
    \norm{f}{1}{\cC_{\infty}(\omega), \theta^{\omega}}^{2\beta}\,
    \norm{(\eta^{\omega})^{m/2} f}{2}{\cC_{\infty}(\omega), \theta^{\omega}}^{\gamma},
  \end{align}

  where $\eta^{\omega}(y) \ldef \max\{1, d^{\omega}(0, y)\}$ and

  \begin{align*}
    \cE^{\omega}(f)
    \;\ldef\;
    \frac{1}{2}\,
    \sum_{\substack{x,y \in \cC_{\infty}(\omega) \\ y \sim x}}
    \mspace{-12mu}W^{\omega}(x,y)\, \bigl(f(y) - f(x)\bigr)^2.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.935783+00:00","domain":"probability theory","id":"claim_a32cb274dcb2172fe30974056a21c91565ad8c7436953479a26785b9b89c1c2e","kind":"lemma","schema_version":1,"statement":"[Lemma 32 (cf.\ {\cite[Lemma 3.6) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS23}}] 
