{"assumptions":[],"created_at":"2026-10-27T17:38:58.713783+00:00","domain":"probability theory","id":"claim_a422fc3dc3a245d6d41b61063580b263b0ff0959ea79be821b2e583b69d77125","kind":"definition","schema_version":1,"statement":"[Definition defi:contrlldRG of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap]

Let $j < N < \infty$ and $\Lambda = \Lambda_N$.  \emph{Controlled RG map} at scale $j$ is a function
\begin{align}
\begin{split}
	\Phi^{\Lambda}_{j+1} = (\Phi^U_{j+1} , \Phi^K_{j+1}) : \cD^{(0)}_j \times \cK_j^{\Lambda} \times \mathbb{A}_j (\tilde{m}^2) 
		& \rightarrow \left( (\R + \sigma_{\sf ox} \R)^{\Lambda} \times \cV^{(0)} \right) \times \R\cK^{\Lambda}_{j+1} ,  \\
	(V_j,K_j) 
		& \mapsto \big( (\delta u_{j+1} , V_{j+1} ), K_{j+1} \big) ,
\end{split}	
\end{align}
such that (equation eq:contrlldRGalg of the paper) holds
when $I_{j'} = \cI_{j'} (V_{j'})$ for each $j' \in \{ j,  j+1 \}$,
and bounds (equation eq:controlledRG22 of the paper)--(equation eq:controlledRG24 of the paper) hold
for some $j,N$-independent,  $L$-dependent constants $(M_{p,q} )_{p,q\ge 0}$:
if $R_{j+1}^U$ is defined by (equation eq:RjUdefi of the paper),
\begin{align}
	\norm{D^p_{V_\varnothing} D^q_K R_{j+1}^{U} }_{\ell_{j+1},  T_{j+1} (0)}
		& \le M_{p,q} \times \begin{cases}
			\tilde\chi_{j+1}^{3/2} \tilde{g}_{j+1}^{3} r_{j+1}^{{\ka}-(1-\kt) p} & (p\ge 0,  \; q =0) \\
			r_{j+1}^{-(1-\kt) p}  & (p \ge 0,  \; q=1)  	\\
			r_{j+1}^{-2(1-\kt)}  & (p \ge 0,  \; q=2) \\
			0   &  (p \ge 0,  \; q \ge 3) 
			,
		\end{cases}  \\
	\norm{D_{V_\varnothing}^p D_K^q \Phi_{j+1}^{K}}_{\cW_{j+1}}
		& \le M_{p,q} \times 
			\begin{cases}
			\tilde\chi_{j+1}^{3/2} \tilde{g}_{j+1}^{3-p} r_{j+1}^{{\ka} - p}  & (p \ge 0,  \; q= 0)  	\\
			\tilde{g}_{j+1}^{-p - \frac{9}{4} (q-1)} r_{j+1}^{-p - {\kb} (q-1)} & (p \ge 0,  \; q \ge 1) 
		\end{cases} 
\end{align}
and when $j+1 < N$,  with the same $C_{{\operatorname{RG}}}$ as in Lemma~(lemma:KNbnd of the paper),
\begin{align}
	\norm{D^q_K \Phi_{j+1}^{K}}_{\cW_{j+1}}
		\le 
		\begin{cases}		
			C_{{\operatorname{RG}}} \tilde\chi_{j+1}^{3/2} \tilde{g}_{j+1}^{3} r_{j+1}^{{\ka}} & (q = 0) \\
			\frac{1}{32} L^{-\max\{ 1/2 ,  (d-4 +2\eta) {\ka} \}}  & (q = 1)  .
		\end{cases} 

\end{align}
Moreover,  $D^p_{V_\varnothing} D^q_K R_{j+1}^{U}$ and $D_{V_\varnothing}^p D_K^q \Phi_{j+1}^{K}$ are continuous in $(\textbf{a}_\emptyset, \textbf{a}) \in \mathbb{A}_j (\tilde{m}^2)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.387311+00:00","domain":"probability theory","id":"claim_a423f9bea99a512a9f121c33d8b15bdc5478cc604d1ab15e352ea051e609da63","kind":"concept","schema_version":1,"statement":"[Prop eta_zeta of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] For $s \in {\mathbb R}$, we define
