{"assumptions":[],"created_at":"2026-10-26T19:51:12.740717+00:00","domain":"probability theory","id":"claim_a49fd29a36eb18acb6c0c5674ac850bee25088905410b174a6cad2b4f215496b","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $\lambda\ino(1,\infty)$ and let $\overline{x}\eqo (T,x) \ino \obbT^\bullet\! $, whose depth $\bbn T\bbn_-$ is possibly infinite. Let $\overline{X}_n\eqo (T, X_n)$, $n\ino \bbN$, be a $\lambda$-biased RW with initial state $(T,x)$. We assume that 
\begin{equation}

 \forall x\ino T \backslash \{ \varnothing \}, \quad P_{(T,x)} \big(  \mathtt{H}_{\overleftarrow{x}} \leko \infty \big) \eqo 1 \; .  
\end{equation}
Let $\boo \ino T \backslash \{ \varnothing \}$. Recall from (\ref{ancestral}) that $L_\boo$ stands for 
the ancestral line of $\boo$ and let us denote by $ \boo(p)$ the vertex of $L_\boo$ at distance $p$ from $\boo$, which makes sense if and only if $0\leq p \leqo \bbn o\bbn -\bbn T\bbn_{ -}$. Namely 
\begin{equation}

 \boo(p)\! = \! \boo_{\lll_{\mathbf{(}  -\infty\, ,\,   \bbn \boo \bbn -p \mathbf{]} }}, \quad   0\leqo p \leqo \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -} 
\end{equation}
We also introduce the successive times of visit of $\overline{X}$ in $L_\boo$ that are recursively defined for all $k\ino \bbN$ by $\mathbf{r}^\boo_{k}\! = \! \inf \big\{ n \! >\! \mathbf{r}^\boo_{k-1} : X_n \ino L_\boo \big\}$, 
with the convention that $\mathbf r^\boo_{-1}\eqo -1$ and $\inf \emptyset \eqo \infty$.  
Then, the following holds true. 
\begin{compactenum}

\smallskip

\item[$(i)$] For all $x\ino T$, $P_{(T, x)}$-a.s.~for all $k\ino \bbN$, $\mathbf{r}^\boo_k \! < \! \infty$ and  
there exists a birth-and-death Markov chain $(Z_k)_{k\in \bbN}$ that takes its values in $\bbN \cap [0, \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -} ]$ and such that $\boo (Z_k)\! = \! X_{\mathbf{r}_k}$, $k\ino \bbN$. 
If $T$ has a finite depth, then it is reflected at $\bbn \boo\bbn\!  -\! \bbn T\bbn_{ -}$; otherwise, its transition probabilities are given for all $1\leqo p\leko \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -}$ by 
\begin{equation}

\rho_{p, p+1} \! = \! \frac{\lambda }{\lambda  +  k_{\boo (p) } (T)  } , \; \,  \rho_{p, p-1}\! = \! \frac{1}{ \lambda + k_{\boo (p) } (T)}, \; \,  \rho_{p, p}\! =\! 
\frac{k_{\boo (p) } (T)\! -\! 1 }{ \lambda +  k_{\boo (p) } (T)} \; ,
\end{equation}
and $\rho_{0, 0}\!= \! 1\! -\! \rho_{0, 1} \eqo\frac{k_{\boo} (T)}{ \lambda  + k_{\boo  } (T)}$.  
Moreover, if $T$ has an infinite depth, then $Z$ is transient which implies that $\bbn \boo  \wedge \! X_n \bbn \! \rightarrow \! -\infty$ and that $(X_n)_{n\in \bbN}$ is transient. 

\smallskip

\item[$(ii)$] Let $x,y, z\ino T$ such that $z \preceq y$. Then 
\end{compactenum}
\begin{equation}
P_{(T \!\!, \,  x)} \big(\mathtt H_{y} \! <\! \mathtt H_{z}  \big)\! =  \! 
\frac{(\lambda^{\bbn x\wedge y\bbn }\! -\! \lambda^{\bbn z\bbn })_+}{\lambda^{\bbn  y\bbn }\!  -\! 
\lambda^{\bbn z \bbn }} \; .
\end{equation}
\begin{compactenum}
\item[$(iii)$]  We assume now that $T$ has an infinite depth. For all $x,y\ino T$, we first get 
\end{compactenum}
\begin{equation}

P_{(T \!\!, \,  x)} \big(\mathtt H_{y} \! <\! \infty  \big) \! = \! \lambda^{- (\bbn y \bbn -\bbn x\wedge y\bbn) }  \quad  \textrm{and} \quad P_{(T \!\!, \,  x)} \big(\mathtt H^+_{x} \! <\! \infty  \big) \! = \! \tfrac{1+k_x(T)}{\lambda + k_x (T)} \; .
\end{equation}
\begin{compactenum}
\item[] We denote 
the Green function by $G_T(x,y)\! = \! E_{(T,x)} \big[ \sum_{n\in \bbN}\un_{\{ X_n =  y\} } \big]$. Then 
\end{compactenum}

\begin{equation}

G_T(x, y) = G_T(x\wedge y, y)= \tfrac{\lambda + k_y (T)}{\lambda  -1} \, \lambda^{- (\bbn y \bbn -\bbn x\wedge y\bbn) }.
\end{equation}
\begin{compactenum}
\item[] If $x\preceq y$, we also get $E_{(T,x)} \big[ \sum_{0\leq n < \mathtt H_{\overleftarrow{x}}} \un_{\{ X_n =  y\} } \big]\eqo (\lambda \! + \! k_y (T)) \lambda^{- (\bbn y \bbn- \bbn x \bbn +1)}$. 
\end{compactenum} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

