{"assumptions":[],"created_at":"2026-10-27T15:32:35.578056+00:00","domain":"probability theory","id":"claim_a4e489d368dcb9084a4cd2e0e186230cce8a5643af73238373b55e0e714fc93c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Luk.Wishart.Lemma.2.5 of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Let $\alpha > 3d-3$, $t\geq 0$, and $k\in \mathbb{N}$. Suppose that $h\in C^{kd}(\mathcal{S}_{++}^d)$, and that for every differential monomial $\overline{\nabla}$ of order at most $kd$ in the entries of $\nabla_{\!X}$, including the order-zero monomial, there exist constants $C_{\overline{\nabla}}, N_{\overline{\nabla}}\geq 0$ such that
\begin{equation}
|\overline{\nabla} h(X)| \leq C_{\overline{\nabla}} (1 + \|X\|_F^{N_{\overline{\nabla}}}), \qquad X\in \mathcal{S}_{++}^d.
\end{equation}
Then, for every $(i_1, j_1), \ldots, (i_k, j_k)\in [d]^2$ and $\Lambda\in \mathcal{S}_{++}^d$,
\begin{equation}
\left(\prod_{\ell=1}^k \nabla_{\Lambda, i_{\ell} j_{\ell}}\right) (\mathcal{Q}_t h)(\Lambda)
= e^{-2kt} \, \mathsf{E}\left[\left(\prod_{\ell=1}^k \mathcal{D}_{i_{\ell} j_{\ell}}\right) h(\mathfrak{Y}_{k,t})\right],
\end{equation}
where $\mathcal{D} = \nabla_{\!X} \, \mathrm{adj}(I_d - 2\nabla_{\!X})$, $\mathfrak{Y}_{k,t}\sim \mathcal{W}_d(\alpha + 2k, I_d, e^{-2t}\Lambda)$ and is defined in (equation eq:Wishart.Q.operator.def of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.504322+00:00","domain":"probability theory","id":"claim_a4e8cfcdd83337439c9d3c9b193500d12193e20ec1eb8025b78b356ba81d2fa4","kind":"theorem","schema_version":1,"statement":"[Proposition prop:comparing_moments of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Let $\boldsymbol{u}_i(s)$ be random variables sampled according to the \hyperref[setup:star]{Setup ($\star$)}{}. Let $g_i$ be a $\mathcal{N}(0, 1/d)$ truncated above $z_p/\sqrt{d}$ if $si\in E(H)$ and below $z_p/\sqrt{d}$ if $si\notin E(H)$, where $z_p=\Phi^{-1}(1-p)$.
\begin{enumerate}[label=(\roman*)]
    \item 
    We then have
    \begin{equation}
        \mathbb{E}\big[\boldsymbol{u}_i(s)\big]=\mathbb{E}[g_i]+\lambda_{si}(z_p-\lambda_{si})\langle \pi_{s-1} (\boldsymbol{v}_i), \pi_{s-1} (\boldsymbol{v}_s)\rangle + \widetilde O\Big(\frac{n}{d^{3/2}}\Big).
    \end{equation} In particular, since $\mathbb{E}[g_i]=\frac{\lambda_{si}}{\sqrt{d}}$, we have $\mathbb{E}[\boldsymbol{u}_i(s)]=\frac{\lambda_{si}}{\sqrt{d}}+ \widetilde O\Big(\frac{|\lambda_{si}|\sqrt{n}}{d}\Big)$.
    \item 
    We also have \begin{equation}
    \big|\mathbb{E}[g_i^2]-\mathbb{E}[\boldsymbol{u}_i(s)^2]\big|\leq \widetilde O\Big(\frac{|\lambda_{si}|\sqrt{n}}{d^{3/2}}\Big), \text{ and so} \Var(\boldsymbol{u}_i(s))=\Big(1+\widetilde O\Big(\frac{\sqrt{n}}{\sqrt{d}}\Big)\Big)\frac{1+\lambda_{si}(z_p-\lambda_{si})}{d}.
    \end{equation}
\end{enumerate}","status":"unverified"}

