				|\angrmd \varphi |_{\gtorus} & \le (1 + \mathcal{O}(\auxbootsmall)) |\nullangrmD \varphi |_{\gnulltori} + \mathcal{O}(\auxbootsmall)|L\varphi|,   \\
				|\nullangrmD \varphi |_{\gnulltori} & \le (1 + \mathcal{O}(\auxbootsmall))|\angrmd \varphi |_{\gtorus} + \mathcal{O}(\auxbootsmall)|L\varphi| 
			\end{align} 
		\end{subequations}

	In addition, we have the following for $A = 2,3$:
