 {\rm d} q_{i} = \frac{2}{\sqrt{\beta \gamma}} q_{i} {\rm d} b_i + \left( \left(\frac{a}{\gamma} + \frac{2}{\beta \gamma}\right) q_{i} - q_{i}^2 - \lambda {\rm e}^{-r x} + q_{i} \sum_{j \neq i} \frac{ q_{i} + q_{j}}{ q_{i}- q_{j} } \right) {\rm d} x,
