{"assumptions":[],"created_at":"2026-10-26T19:45:38.361129+00:00","domain":"probability theory","id":"claim_a7a0bd6a50778a7cf34c247b0c274a87919a11eefaca6a8b3fab9fc3665dbc8c","kind":"concept","schema_version":1,"statement":"[Lemma 13 ({cf.,e.g.,\cite[Lemma~1.1) of arXiv:2604.21389, 'Existence and uniqueness for \\ singular stochastic differential equations \\ with piecewi'] {le2006one}~\cite[Lemma IX.3.3]{revuz2013continuous}}]

