{"assumptions":[],"created_at":"2026-10-27T23:03:39.762644+00:00","domain":"probability theory","id":"claim_a7e18e2391f6a574d8bdb711c8879a7b64ec0192f9fea74c5a667c8eeb5925bc","kind":"concept","schema_version":1,"statement":"[Prop eq:lower.bound.ind of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{thm:lower.bound}
