			\end{equation}
			with the coefficient $\widetilde c_{l,m} $  defined as 
			\begin{equation}
				\widetilde c_{l,m} := \frac{1}{|{\scaleobj{1}{\square}}_m|}\sum_{e\in E_d({\scaleobj{1}{\square}}_m)}\mathbb{E}
				\left \langle \nabla v_m(\mathbf{a}),(\mathbf{a}^e-\mathbf{a})\sum_{\substack{G \subseteq E_d({\scaleobj{1}{\square}}_m) \\ |G|=l-1}}D_{G}\big(\nabla v_m(\mathbf{a}^e)\big)\right \rangle_{{\scaleobj{1}{\square}}_m}.
