{"assumptions":[],"created_at":"2026-10-27T22:52:32.335189+00:00","domain":"probability theory","id":"claim_a91a1dce0f85aa0fd308cde11d43d14a831a49b732783410bec6892d1eee4e6d","kind":"theorem","schema_version":1,"statement":"[Proposition prop:patchinginappendix of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(\Omega,\Omega_w,\Omega_h)$ be a Lipschitz interface triple with interface $\gamma$. Let $\pi\in L^2(\Omega)$ and set $w \coloneq  \pi |_{\Omega_w}, h  \coloneq  \pi |_{\Omega_h}.$
    \begin{enumerate}
        \item Assume $w\in H^1(\Omega_w)$ and $ h\in H^1(\Omega_h)$. The functions $w,h$ have matching boundary trace, i.e., $${\operatorname{tr}}^{\gamma}(w) ={\operatorname{tr}}^{\gamma}(h) \textnormal{ in }H^{1/2}(\gamma),$$ if and only if $\pi$ is an element of $ H^1(\Omega)$.
        \item Assume $w\in H^{\operatorname{div}}(\Omega_w) $ and $ h\in H^{\operatorname{div}}(\Omega_h)$. The functions $w,h$ have matching normal trace, i.e., $${\operatorname{tr}}^{\gamma}_N(w) = -{\operatorname{tr}}^{\gamma}_N(h) \textnormal{ in } H^{-1/2}_{0}(\gamma),$$ if and only if $\pi$ is an element of $ H^{\operatorname{div}}(\Omega)$.

        \item Assume $w\in H^\Delta(\Omega_w)$ and $h\in H^\Delta(\Omega_h)$. The functions $w,h$ have matching boundary trace and normal derivative, i.e., $$\qquad {\operatorname{tr}}^{\gamma}(w) ={\operatorname{tr}}^{\gamma}(h)\textnormal{ in } H^{1/2}(\gamma)  \quad \textnormal{and}\quad {\operatorname{tr}}^{\gamma}_N(\nabla w) = -{\operatorname{tr}}^{\gamma}_N(\nabla h) \textnormal{ in } H^{-1/2}_{0}(\gamma),$$ if and only if $\pi$ is an element of $ H^\Delta(\Omega)$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.970011+00:00","domain":"probability theory","id":"claim_a92064191472c9a4c5e33c66c3f5d336cd2bfdbb1aebf75de228b1500bc14025","kind":"lemma","schema_version":1,"statement":"[Lemma mainleammapart1 of arXiv:2606.15203, 'The existence of invariant sublinear expectations for $G\text{-}$SDEs'] If the $G\text{-}$Brownian motion is non-degenerate, i.e. $\underline{\sigma}^2>0$, then for any $\varphi \in B_b(S^1)$, we have
