   & \max \Big\{ \E \big[\sup_{s\in [t_0,t]} e^{- \gamma (t-s)} \| X^{\epsilon,v}_{s;t_0,\xi_1}-X^{\epsilon,v}_{s;t_0,\xi_2} \|_{H}^2 \big]^{\frac{1}{2}}, \E \big[ (\gamma_0 -\tilde{\gamma}_0) \int_{t_0}^{t} e^{- \gamma (t-s)}   \| X^{\epsilon,v}_{s;t_0,\xi_1}-X^{\epsilon,v}_{s;t_0,\xi_2} \|_{V}^2 \, \d s \big]^{\frac{1}{2}} \Big\}  \nonumber \\
    & \leq 2 (\E \| \xi_1-\xi_2 \|_{H}^2 )^{\frac{1}{2}}  e^{\frac{  C_{\rho_1}}{\gamma_0} \big( \| \xi_2 \|_{H}^{2} + \| \xi_2 \|_{H}^{2+\beta} + \big(2+\frac{\beta}{2} \big) \frac{ 2 C_{A,\rho} + 4C_B M+ \beta C_{B} \tilde{\epsilon}  }{\lambda_1 \gamma_0} \big)+ \frac{C_B M}{\lambda_1(\gamma_0-\tilde{\gamma}_0)}} e^{-\frac{\gamma }{2}(t-t_0)}, 
