{"assumptions":[],"created_at":"2026-10-26T19:28:31.956748+00:00","domain":"probability theory","id":"claim_a9c7c66c7425c0fb3d2a7eb6d5f7dc7ac52bfc891126ac8bd023715e47247ed9","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2512.01483, 'Scaling Limits of Line Models in Degenerate Environment'] Let $A_i :=  \frac{1+ \varepsilon_i^+}{1- \varepsilon_1^+ \varepsilon_2^+}$, $i=1,2$. Let $C,\kappa >0 $, and let $h,v : \mathbb{R}_+ \to \mathbb{R}_+$ be two continuous functions.
\begin{enumerate}
\item If $h$ and $v$ satisfy the system of differential inequalities
\begin{equation}

\forall t \in  [0,T], \quad \begin{cases}
h(t) \leq C(\kappa + A_1  \int_0^{t}  v(s)^{\varepsilon_1^+} \, ds) \\
v(t) \leq C(\kappa +  A_2 \int_0^{t}  h(s)^{\varepsilon_2^+} \, ds), 
\end{cases}
\end{equation}
then, for all $t \in [0,T]$,
$$h(t) \leq [(C\kappa)^{1/A_1}+Ct]^{A_1}, \qquad v(t) \leq [(C\kappa)^{1/A_2}+Ct]^{A_2}. $$ 

\item If $h$ and $v$ satisfy the system of differential inequalities
\begin{equation}

\forall t \in  [0,T], \quad \begin{cases}
h(t) \leq C(\kappa + A_1  \int_0^{t}  v(s)^{\varepsilon_1^+ \varepsilon_2^+} \, ds) \\
v(t) \leq C(\kappa + \frac{A_2}{\varepsilon_2^+} \int_0^{t}  h(s)^{\varepsilon_2^+} v(s)^{1-\varepsilon_2^+} \, ds),
\end{cases}
\end{equation}
then, for all $t \in [0,T]$,
$$h(t) \leq [(C\kappa)^{1/A_1} + C t]^{A_1}, \qquad v(t) \leq [(C\kappa)^{1/B_2} +Ct]^{B_2}, $$
where $B_2=\frac{A_2}{{\varepsilon_2}^+}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.732711+00:00","domain":"probability theory","id":"claim_a9c9637f426e2c5f3151627862480063dcd5650e6645cf39ad79a383df6a57af","kind":"theorem","schema_version":1,"statement":"[Corollary coro:Langevin-to-Laplacian-Rayleigh of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Let $\mathsf{Gap}(-\mathcal L)$ be the first positive eigenvalue of $-\mathcal L$ on $\mathbf{S}_N$; $\mathsf{Gap}(\mathcal M)$ be the first positive eigenvalue of $-\Delta_g$ on $\mathcal M$. For $H_0 =C N$ for a large enough constant $C$, we have that:  
