{"assumptions":[],"created_at":"2026-10-28T02:39:12.272277+00:00","domain":"probability theory","id":"claim_aa057119562082aaee6f28cc4e9b03867e00be8579368b3925b33f095db8c1d8","kind":"theorem","schema_version":1,"statement":"[Corollary cor: rand_series_ample of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that $E\to M$ is a smooth real vector bundle over the compact smooth manifold $M$. Fix a smooth  Riemann metric $g$ on $M$,  a smooth metric $h$ on $E$ and a smooth connection  on $E$ compatible with $h$. Let $k\in {{\mathbb N}}$ and suppose that $(\phi_n)_{n\in {{\mathbb N}}}$ is a sequence  of $C^k$ sections of $E$ that span  a dense subset of $C^k(E)$. Suppose that
 \begin{equation}
 \Vert \phi_n\Vert_{C^k(E)}= O(n^\alpha)\;\;\mbox{as $n\to\infty$},
 \end{equation}
 for some $\alpha>0$.  Fix a sequence of positive numbers $(\lambda_n)_{n\in{{\mathbb N}}}$ satisfying ((poly_eval of the paper)). Let $(X_n)_{n\in {{\mathbb N}}}$ be a sequence of $\mathrm{i.i.d.}$ standard normal random variables and suppose that $\mathfrak{a}\in \EuScript{S}({\mathbb R})$ is an even Schwartz function such that $\mathfrak{a}(0)=1$. Then the following hold.

 \begin{enumerate}

\item For any $R >0$ the random series  
\begin{equation}
\sum_{n\in {{\mathbb N}}} \mathfrak{a}\big(\,  \lambda_n/R\,\big) X_n \phi_n
\end{equation}
converges  $\mathrm{a.s.}$ in $C^k(E)$. Denote by $\Phi^R$ the resulting $C^k$  Gaussian section  of $E$.

\item There exists $R_0>$ such that $\forall R>R_0$ the  Gaussian section $\Phi^R$ is $J_k$-ample, i.e., for any ${\boldsymbol{x}}\in M$ the Gaussian vector
\[
J_k\Phi^R({\boldsymbol{x}})=\bigoplus_{j=0}^k \nabla^j\Phi^R({\boldsymbol{x}})
\]
is nondegenerate.

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.772219+00:00","domain":"probability theory","id":"claim_aa05e5d1140364d3da82882ec6a9843d53a2610052891ac0a93f908e2de3a0e8","kind":"theorem","schema_version":1,"statement":"[Prop link-with-compositions-new-2 of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Under the assumptions of Proposition (prop:link-with-compositions-new-1 of the paper), we have for $n\geq 0$ the identity $\PFtrees{\mathbf{w}} {nd+1}=\PFComp{{\mathbf{w}},{\mathbf{b}}}{nd}$, and for $T\in\trees[d]_{nd+1}$ if we write $c(T)=\underline{n}_1 \cdots  \underline{n}_i$ and $\varphi(T)=(T^{[1]},\dots,T^{[i]})$, then
