{"assumptions":[],"created_at":"2026-10-27T14:05:52.386827+00:00","domain":"probability theory","id":"claim_aa528a142ae3d608845aeaf384b7575503a5e3de6ee0b87a5dd3d3431140741d","kind":"theorem","schema_version":1,"statement":"[Proposition Ito formula of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] Let $\mathcal{H}_1 \subset \mathcal{H}_2 \subset \mathcal{H}_3$ be a triplet of embedded Hilbert Spaces where $\mathcal{H}_1$ is dense in $\mathcal{H}_2$, with the property that there exists a continuous nondegenerate bilinear form $\inner{\cdot}{\cdot}_{\mathcal{H}_3 \times \mathcal{H}_1}: \mathcal{H}_3 \times \mathcal{H}_1 \rightarrow \mathbb{R}$ such that for $\phi \in \mathcal{H}_2$ and $\psi \in \mathcal{H}_1$, $$\inner{\phi}{\psi}_{\mathcal{H}_3 \times \mathcal{H}_1} = \inner{\phi}{\psi}_{\mathcal{H}_2}.$$ Suppose that for some $T > 0$ and stopping time $\tau$,
\begin{enumerate}
        \item $\boldsymbol{\Psi}_0:\Omega \rightarrow \mathcal{H}_2$ is $\mathcal{F}_0-$measurable;
        \item $f:\Omega \times [0,T] \rightarrow \mathcal{H}_3$ is such that for $\mathbbm{P}-a.e.$ $\omega$, $f(\omega) \in L^2([0,T];\mathcal{H}_3)$;
        \item $B:\Omega \times [0,T] \rightarrow \mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)$ is progressively measurable and such that for $\mathbbm{P}-a.e.$ $\omega$, $B(\omega) \in L^2\left([0,T];\mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)\right)$;
        \item   $\boldsymbol{\Psi}:\Omega \times [0,T] \rightarrow \mathcal{H}_1$ is such that for $\mathbbm{P}-a.e.$ $\omega$, $\boldsymbol{\Psi}_{\cdot}(\omega)\mathbbm{1}_{\cdot \leq \tau(\omega)} \in L^2([0,T];\mathcal{H}_1)$ and $\boldsymbol{\Psi}_{\cdot}\mathbbm{1}_{\cdot \leq \tau}$ is progressively measurable in $\mathcal{H}_1$;
        \item  The identity
        \begin{equation} 
            \boldsymbol{\Psi}_t = \boldsymbol{\Psi}_0 + \int_0^{t \wedge \tau}f_sds + \int_0^{t \wedge \tau}B_s d\mathcal{W}_s
        \end{equation}
        holds $\mathbbm{P}-a.s.$ in $\mathcal{H}_3$ for all $t \in [0,T]$.
    \end{enumerate}
The the equality 
  \begin{align} \norm{\boldsymbol{\Psi}_t}^2_{\mathcal{H}_2} = \norm{\boldsymbol{\Psi}_0}^2_{\mathcal{H}_2} + \int_0^{t\wedge \tau} \bigg( 2\inner{f_s}{\boldsymbol{\Psi}_s}_{\mathcal{H}_3 \times \mathcal{H}_1} + \left\Vert B_s \right\Vert^2_{\mathscr{L}^2(\mathfrak{U};\mathcal{H}_2)}\bigg)ds + 2\int_0^{t \wedge \tau}\inner{B_s}{\boldsymbol{\Psi}_s}_{\mathcal{H}_2}d\mathcal{W}_s\end{align}
  holds for any $t \in [0,T]$, $\mathbbm{P}-a.s.$ in $\mathbb{R}$. Moreover for $\mathbbm{P}-a.e.$ $\omega$, $\boldsymbol{\Psi}_{\cdot}(\omega) \in C([0,T];\mathcal{H}_2)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:38:58.728682+00:00","domain":"probability theory","id":"claim_aa53821f0c56ae6e008912d7fc6fb984133eff3550b2ea52212c3ea2d3110d21","kind":"concept","schema_version":1,"statement":"[Lemma tildelambdadecomp of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\beta \in (0, 1)$.  
