{"assumptions":[],"created_at":"2026-10-27T12:13:31.933840+00:00","domain":"probability theory","id":"claim_ab6b6086be7a58b303988f0aa08263913e283c1ec619a8b4582e0448a7bcf116","kind":"lemma","schema_version":1,"statement":"[Lemma lem:mult_concentration of arXiv:2506.12171, 'The multinomial dimer model'] Let $k_i$ denote the number of tiles on edges of type $e_i$, and let $\overline{k}_i = \mathbb{E}_{\mu_{n,N,w}}[k_i]$. There exists a constant $c=c(w)>0$ such that for any $\varepsilon>0$ and $N$ large enough given $n,\varepsilon$, 
    \begin{equation}
        \mathbb{P}_{\mu_{n,N,w}}(|k_i-\overline{k}_i|>\varepsilon \overline{k}_i)\leq \exp(-\varepsilon^2 N/2cn^d).
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.421359+00:00","domain":"probability theory","id":"claim_ab6c09e6641ddefc0be08ba7877151f4b7fc6a31852c14ce4970612a95b6b46c","kind":"definition","schema_version":1,"statement":"[Definition traffic freeness of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] We say that $\mathbf{A}_{N}^{(1)},\cdots,\mathbf{A}_{N}^{(L)}$ are \emph{asymptotically traffic independent} whenever $\mathbf{A}_{N}:=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ converges in traffic distribution and for any *-test graph $T=(V,E,\gamma,\epsilon)$,
        \begin{equation}
            \tau_{N}\left(T(\mathbf{A}_{1}^{(N)},\cdots,\mathbf{A}_{L}^{(N)})\right)\underset{N\rightarrow\infty}{\longrightarrow}\sum_{\substack{\pi\in\mathcal{P}(V) \\ \mathrm{s.t.}\mathcal{GCC}(T^{\pi}) \\ \text{is a tree}}}\prod_{S\in\mathcal{CC}(T^{\pi})}\lim_{N\rightarrow\infty}\tau_{N}^{0}\left(S(\mathbf{A}_{N}^{(\ell(S))})\right),
        \end{equation}
    where $\ell(S)$ is the index of the family of the labels of the colored component $S$. Since the injective traces in the product can also be written in terms of (non-injective) traces, asymptotic traffic independence entirely characterizes the limiting traffic distribution of $\mathbf{A}_{N}=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ in terms of the traffic distributions of the $\mathbf{A}_{N}^{(l)}$'s.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.250455+00:00","domain":"probability theory","id":"claim_ab7156b3f8f5ed8d6ba6a6256db92acb82659f3e4828e40b349937e223c895ab","kind":"concept","schema_version":1,"statement":"[Lem 51 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,D$ satisfy \eqref{eq:costanti}. Also let $q$ be a real number and $k \ge 0$ be an integer satisfying 
		\begin{equation}

			q \in [N^{A\delta-1}, \varepsilon_0], \quad k \le \ell_0 (q) + 5.
		\end{equation}

		\noindent Further let $q' \ge 0$ satisfy
		\begin{flalign}

			q' \in [q - 2^k N^{(D+2)\delta-1}, q - 2^{k}  N^{(D-2) \delta-1}]; \qquad \mathsf{t} = q'^{-1} k 2^k N^{1+6A\delta}.
		\end{flalign} 

		\noindent Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned} 
				& H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \bigcup_{\ell=1}^{k+1} \mathcal{A}_{\ell}^{q}$ }. 
			\end{aligned}
		\end{flalign}

		\noindent Then we have w.o.p. that
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{\ell = 1}^k \mathcal{A}_{\ell}^{q'}$ and $t \in [\mathsf{t}, N^5]$}.
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.116577+00:00","domain":"probability theory","id":"claim_ab719bbff76ab96cdd58eb12a272791bc6d9a46c6d3140276ade301116f537f0","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Assume $k>2$.  For all sufficiently small $\eps>0$, the form $\omega_\eps$ defined by \eqref{gt:eq:approximate-metric} extends to a smooth K\"ahler metric on $\widetilde X$, and
\begin{equation}
  [\omega_\eps]=\pi^*[\omega]-\eps^2[E].
\end{equation}
Moreover:
\begin{enumerate}[label=\textup{(\roman*)}]
\item on the exterior region, \(\omega_\eps=\omega\);
\item on the outer annulus, for every fixed $j\ge0$,
\begin{equation}
  \abs{\nabla^j\left[
  \eps^2\gamma_2\psi_k(\eps^{-2}d^2)
  \right]}
  \le C_j\eps^{2k-2}r_\eps^{4-2k-j};
\end{equation}
\item on the inner annulus, potentials for $\eps^{-2}\omega_\eps$ and $\omega_k$ in the rescaled coordinates are respectively
\begin{align*}
  F&=|Z|^2+|W|^2
      +\eps^{-2}\Phi(\eps Z,\eps W)
      +\psi_k(\eps^{-2}d^2),\\
  F_{\mathrm{prod}}&=|Z|^2+|W|^2+\psi_k(|Z|^2),
\end{align*}
and, on the rescaled coordinate balls specified above,
\begin{equation}
  \abs{\nabla_{Z,W}^j(F-F_{\mathrm{prod}})}
  \le C_j\eps^{j-2}d^{3-j}
  \qquad(2\le j\le6).
\end{equation}
In particular, $\eps^{-2}\omega_\eps$ is uniformly equivalent to $\omega_k$ there;
\item on the blowup region, in the coordinates
\eqref{gt:eq:blowup-coordinates},
\[
  \eps^{-2}\omega_\eps=\omega_k+O(\eps)
\]
in $C^\ell$ on compact subsets of each blowup chart, for every fixed $\ell$.  In particular, $\eps^{-2}\omega_\eps$ converges locally smoothly to $\omega_k$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.340639+00:00","domain":"probability theory","id":"claim_ab7236edd0383819aebe5baed95c562e13d808876b71f7ac4b7cba38e2424c00","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lyap:symLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(\mu,\gamma, \mathbf{X})$ be a solution to the $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$ and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Let $f : \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ be a measurable function such that for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have
\begin{equation}
    \mathbb E\Big[\big|f\big(X_0(s), X_v(s)\big)\big|^2 + \big|f\big(X_v(s), X_0(s)\big)\big|^2 \Big] < \infty.

\end{equation}
Then the following properties hold:
\begin{enumerate}
    \item For $u \in \{0, \ldots, \kappa\}$, let $\bar{u} = 0$ when $u = 0$ and $\bar{u} = 1$ otherwise. Given any $v \in \{1, \ldots, \kappa\}$ and $u \in \{0, v\}$, for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have 
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{u} \log \mu_s\big(\mathbf{X}(s)\big)\Big] = \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{\bar{u}} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
    \item For all $v \in \{1, \ldots, \kappa\}$ and $s \in \ensuremath{\mathbb{R}}_+$ we have
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{0} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big] = \mathbb E\Big[f\big(X_v(s), X_0(s)\big) \nabla_{1} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.757394+00:00","domain":"probability theory","id":"claim_ab76c8f859ae4f80d493e4f1e5566cdbe4bac66886b153e19a0571200dd5263a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:massive-massless-continuous-correction of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix a disk $U\Subset\mathbb R^2$ and $m_0>0$.  Write $\Delta_U$ for the
Dirichlet Laplacian on $U$ and set $L_0^U:=-(2\pi)^{-1}\Delta_U$.  Consider
a centered Gaussian field $Z_U$ with covariance operator
\begin{equation}
 \Cov(Z_U)=C_U^{(m_0)}
 :=(L_0^U)^{-1}-(L_0^U+m_0^2)^{-1}
 =m_0^2(L_0^U)^{-1}
   (L_0^U+m_0^2)^{-1}.

\end{equation}
Then $Z_U$ has a continuous version.  More precisely, for every $K\Subset U$
there is $C_{K,U,m_0}<\infty$ such that
\begin{equation}
 \mathbb E|Z_U(z)-Z_U(z')|^2
 \le C_{K,U,m_0}r^2
 \left(1+\log\frac1r\right),
 \qquad
 z,z'\in K,\quad 0<r:=|z-z'|\le\frac12.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.955632+00:00","domain":"probability theory","id":"claim_ab7878b4be96b605d77ac6dc12ae0602a3c7e8700cabdeb92d6ebaa0bc6e5877","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85,Slep62})
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item $\mE(X_{i}^2)=\mE(Y_{i}^2)$
\item $\mE(X_{i}X_{l})\leq \mE(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
\mE(\min_{i} X_{i})\leq \mE(\min_i Y_{i}) \quad  \Longleftrightarrow \quad \mE(\max_{i} X_{i})\geq \mE(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.712875+00:00","domain":"probability theory","id":"claim_ab79d2a8a4e173796e12ca39c655f710b9a744550ca5025a0babb0a7f53668ce","kind":"concept","schema_version":1,"statement":"[Proposition W_1 of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] For every $\delta>0$ and $y\in \mathbb{Z}^d$, there exist finite positive constants $C$ and $s$ depending only on $d,\mathfrak{p},\delta$ and  a nonnegative $\omega$-measurable random variable $\mathcal{T}_\delta^{(1)}(y)$ satisfying
		\begin{equation}
			\forall T\geqslant 0, \qquad \mathbb{P}_{\mathfrak{p}}\left(\mathcal{T}^{(1)}_\delta (y)\geqslant T\right)\leqslant C \exp\left(-\frac{T^s}{C}\right),
		\end{equation}
		such that on the event $\{y\in\mathscr{C}_\infty\}$, when $t>\mathcal{T}^{(1)}_\delta(y)$, we have
		\begin{equation}
			W_1(p^\omega(t,\cdot+y,y), \bar{p}(t,\cdot))\leqslant K t^\delta,
		\end{equation}
		where $K$ is a finite positive constant depending on $d,\mathfrak{p},\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.629071+00:00","domain":"probability theory","id":"claim_ab79e77565a215f5bae0b72a900089c125466d04d4fed689051a9a79fa8868e1","kind":"concept","schema_version":1,"statement":"[Proposition prop:SP of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $a^0 = (a^0_{ij})_{1 \leq i,j \leq d}$ and $b^0 = (b^0_1,\ldots,b^0_d)$ consist of Borel measurable coefficients 
    \[
    a^0_{ij}, b^0_i: (0,\infty)\times \mathbb{R}^d \to \mathbb{R}
    \]
    such that $a^0$ is pointwise symmetric and non-negative definite.
    Suppose that $u: (0,\infty)\times \mathbb{R}^d \to [0,\infty)$ is a probability solution to the linear Fokker--Planck equation
    \begin{equation}
        \partial_t u(t,x) = \partial_{ij}\bigl(a^0_{ij}(t,x) u(t,x)\bigr) - \partial_i \bigl(b^0_i(t,x) u(t,x)\bigr)
    \end{equation}
with a probability measure-valued initial datum $\zeta$, satisfying
\begin{equation}
    a^0_{ij}, b^0_i \in L^1\bigl( [0,T]\times \mathbb{R}^d;u(t,x) \,\mathrm d x \mathrm d t \bigr),\quad \forall T>0.
\end{equation}

Then there exists a probabilistically weak solution $X = (X_t)_{t\geq 0}$ to the SDE
\begin{equation*}
    \mathrm d X_t = b^0(t,X_t) \,\mathrm d t + \sigma^0(t,X_t) \,\mathrm d W_t,
\end{equation*}

with $\sigma^0:(0,\infty)\times \mathbb{R}^d \to \mathbb{R}^{d\times d}$ such that $\sigma^0 (\sigma^0)^T = 2 a^0$, $\mathcal{L}(X_t) = u(t,x)\,\mathrm d x$ for all $t>0$, and $\mathcal{L}(X_0) = \zeta$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.490906+00:00","domain":"probability theory","id":"claim_ab80195dc4b537b4cecbacc10c8c85ec59998dad0e0e7a16e316d5d602cc6f2a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lower of arXiv:2607.05054, 'Root Dynamics of Differentiated Polynomials with Rotationally Invariant Structure'] Under the same assumptions, after $ \ell m $ differentiations, the $ j $-th smallest radius $ r_j^{(n,m,\ell)} $ (for $ 1 \leq j \leq n-\ell $) satisfies  
\begin{align}
r_j^{(n,m,\ell)} \geq r_{j+\ell} \prod_{s=1}^{\ell} \left(1 - \frac{1}{\max\left(1, j+s-2 - y\right)}\right).
\end{align}  
In particular, if $ j > y + 2 $, then  
\begin{align}
r_j^{(n,m,\ell)} \geq r_{j+\ell} \frac{j - 2 - y}{j + \ell - 2 - y} \geq r_{j+\ell} \frac{j - 2 - y}{j + \ell}.
\end{align}  
For $ j \leq y + 2 $, the bound holds trivially as the right-hand side is nonpositive.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.483104+00:00","domain":"probability theory","id":"claim_ab8051ef5cc51284588d7436190c4d72823adfa669d513a1f5d175be58b9c199","kind":"theorem","schema_version":1,"statement":"[Pro rec of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] Let ${\sf U}$ be an {\sf AUD}\xspace irreducible transition matrix on an infinite tree $T$, and $(X_k,k\geq 0)$ a ${\sf U}$-Markov chain. For any set of nodes $A$, denote by
  \[\tau_{A}=\tau_A(X)=\inf\left\{k: X_k\in A\right\}\] the hitting time of $A$; for a single node, as the root $\varnothing$, we write $\tau_{\varnothing}$ instead of $\tau_{\{\varnothing\}}$. Let $T_{\geq h}=\{u \in T, |u|\geq h\}$ be the subset of $T$ consisting of the nodes at distance $\geq h$ from $\varnothing$.
  \begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
	\addtocounter{c}{1}\item[($\roman{c}$)]  ${\sf U}$ is recurrent on $T$ if and only if for each node $i$ of the first generation ($i\in c_T(\varnothing)$), we have
	\begin{eqnarray}\lim_{b \to +\infty} {\mathbb{P}}(\tau_{\varnothing} < \tau_{T_{\geq b}}~|~X_0=i)=1.\end{eqnarray}
	\addtocounter{c}{1}\item[($\roman{c}$)] 
Let  $T_{i,< h}=\{u \in T_i,~|u|<h\}$ be the restriction of the subtree $T_i$ to the $h-1$ first levels (of $T$), and $U_{[i,<h]}$ be the matrix obtained by keeping only the rows and columns of ${\sf U}$ corresponding to the elements of $T_{i,< h}$ (and ${\sf U}^{(i)}_{[i,<h]}$ for the same matrix, deprived from the row and column indexed by $i$). We have:
	\begin{eqnarray}
	{\mathbb{P}}(\tau_{\varnothing} <  \tau_{T_{\geq h}}~|~X_0=i)=\frac{\det({\sf Id}-{\sf U}^{(i)}_{[i,<h]})}{\det({\sf Id} -{\sf U}_{[i, <h]})} {\sf U}_{i,\varnothing}. 
	\end{eqnarray}
\end{itemize}\vspace{-2em}~","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.765732+00:00","domain":"probability theory","id":"claim_ab827e4a739f25664d7b3dae9f115bd7fc77f149dbd7cb03673809664fd1450f","kind":"lemma","schema_version":1,"statement":"[Lem thm:master-lemma of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $p\in (0,\infty)$, and $\beta \in\mathds{R}$ such that $\beta <-\frac{d}{p}$.
Let further $(\xi_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ be a family of random variables.
Then for all $j\in\mathds{N}_0$ and $t\in \left\{F,M\right\}^d$, we have
\begin{equation}
Z_{j,t}\mathrel{\mathop:}= \mnorm{\lr{\lr{1 + \frac{\left\lVertm\right\rVert_\infty}{2^j}}^\beta \abs{\xi_{j,t,m}}}_{m\in\mathds{Z}^d}}_{\ell_p}\lesssim 2^{j\frac{d}{p}} \cdot \Xi^{\frac{1}{p}},
\end{equation}
where the implied constant only depends on $d$, $\beta$, and $p$.
Here
\begin{align}
\Xi_t&\mathrel{\mathop:}= \sup_{j \in \mathds{N}_0} \lr{\frac{1}{M_j} \sum_{\tau=1}^{M_j} \abs{\xi_{j,t,\phi(\tau)}}^p+\sup_{\ell\geq j} \frac{1}{N_\ell} \sum_{\tau=M_\ell + 1}^{M_{\ell+1}} \abs{\xi_{j,t,\phi(\tau)}}^p}\nonumber\\
\intertext{for $t\in\left\{F,M\right\}^d$, and}
\Xi&\mathrel{\mathop:}= \max_{t\in\left\{F,M\right\}^d}\Xi_t
\end{align}
where $\phi:\mathds{N}\to \mathds{Z}^d$ is a bijection such that $\tau\mapsto \left\lVert\phi(\tau)\right\rVert_\infty$ is nondecreasing, and for $j\in\mathds{N}_0$, we set
\begin{align*}
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}},\\
\intertext{and}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.072301+00:00","domain":"probability theory","id":"claim_ab8299a84d7a40be2abdad2a6437f8f3d633a86bf67cca30890720f7fdb67aa5","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] It holds
    \begin{align*}
        \hat{P}_{a,y,\theta}(z)&=c_{0,0}(\theta,a,z) H_0(y),~~~~~y\in A_0,
\\
        \hat{P}_{a,y,\theta}(z)&=\sum_{i=0}^1c_{1,i}(\theta,a,z)H_i(y),~~~~~y\in A_1,
    \end{align*}
    with \begin{align*}
   c_{0,0}&\coloneqq c_{0,0}(\theta,a,z)\coloneqq \frac{1}{1-zF(z)},
        \\c_{1,0}&\coloneqq c_{1,0}(\theta,a,z)\coloneqq  c_{0,0}+\frac{ -az}{a+1}\,c_{0,0} \qquad\text{and}\qquad
        c_{1,1}\coloneqq c_{1,1}(\theta,a,z)\coloneqq  \frac{- z\theta}{a+1}\,c_{0,0}.
