   \Phi \le C e^{-\mu_1 t}\Bigl(\zeta_1(t)\varphi_1-\nu |\zeta_1'(t)| r^{-4}\Gamma(r,t) \Bigr) \quad \text{in $B_1 \times (T,\infty)$.}
