{"assumptions":[],"created_at":"2026-10-26T21:00:30.487191+00:00","domain":"probability theory","id":"claim_af2fc3953fde080908fb858b5820cccec34d35301a5f1f497b0a5814f46a0167","kind":"concept","schema_version":1,"statement":"[Lem 7 of arXiv:2607.03360, 'Smoluchowski-Kramers Approximation Meets Khasminskii Averaging Principles in Nonequilibriu'] For each $\e>0$ and any fixed $R>0$, let $e_1, e_2: \rr^{d_1} \times \rr^{d_2} \to \rr$ be continuous functions satisfying $|e_1(x,y)| \leq C_{e_1}(1+|x|)$ and $|e_2(x,y)| \leq C_{e_2}$ for some constant $C_{e_1}, C_{e_2} > 0$.  Then,  for each $i,j, \iota =1,\dots, d_1$ and $\ell=1,\dots, d_2$, we have
\beq{inner-mv}
\lim_{\e \to 0} \EE \bigg[ \bigg( \sup_{t\in [0,T]} \Big|\int_0^t \big[M^{-1}_{R,n} \big]_{ij}(x_s^m, y_s^\e) e_1(x_s^m, y_s^\e) m (v_s^m)_i ds \Big|\bigg)^2 \bigg]=0,
\eeq
\beq{mv-W}
\lim_{\e \to 0} \EE \bigg[\bigg(\sup_{t \in [0,T]} \bigg| \int_0^t  \big[M^{-1}_{R,n} \big]_{ij}(x_s^m, y_s^\e) e_1(x_s^m, y_s^\e) m (v_s^m)_i d(W_s)_j \bigg| \bigg)^2 \bigg]=0,
\eeq
and 
\beq{ev-B}
\lim_{\e \to 0} \EE \bigg[\bigg(\sup_{t\in [0,T]} \bigg| \sqe \int_0^t \big[M^{-1}_{R,n} \big]_{ij}(x_s^m, y_s^\e) e_2(x_s^m, y_s^\e) \sqrt{m} (v_s^m)_\iota d(B_s)_\ell \bigg|\bigg)^2 \bigg]=0.
