{"assumptions":[],"created_at":"2026-10-27T21:28:49.056622+00:00","domain":"probability theory","id":"claim_afb5eddf56b6460b3836d8093b610465558a181d20da893e50e1cece4147f245","kind":"definition","schema_version":1,"statement":"[Definition def:regular-time-weight of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$.  A \emph{regular time weight of order $\alpha$} is
\begin{equation*}
 w(t)=t^\alpha e^{\phi(t)},
 \qquad \phi\in W^{1,1}(0,T),
 \qquad \phi(T)=0.
\end{equation*}
The normalization only fixes $w(T)=T^\alpha$ and entails no loss of generality.
The ratio $w(t)/t^\alpha=e^{\phi(t)}$ has a positive continuous extension to
$[0,T]$.  For $0\leq r_0<r_1\leq T$ and $I=(r_0,r_1)$, define its intrinsic
logarithmic oscillation by
\begin{equation*}
 \operatorname{osc}_{\alpha,I}(w)
 :=\max_{t\in\overline I}\log\frac{w(t)}{t^\alpha}
   -\min_{t\in\overline I}\log\frac{w(t)}{t^\alpha},
\end{equation*}
where the quotient at $t=0$, when needed, is understood through this extension.
We write $\operatorname{osc}_\alpha(w)$ on the full interval.  For $\kappa\geq0$,
define on the full interval
\begin{equation*}
 w_\kappa(t):=w(t)e^{-2\kappa(T-t)},\qquad 0<t<T,
\end{equation*}
and use its restriction on subintervals.  For every measurable field $h$,
\begin{equation}
 \left(\min_{t\in\overline I}\frac{w_\kappa(t)}{t^\alpha}\right)^{1/2}
 \left\lVert h\right\rVert_{\alpha;I}
 \leq \left\lVert h\right\rVert_{w_\kappa;I}
 \leq
 \left(\max_{t\in\overline I}\frac{w_\kappa(t)}{t^\alpha}\right)^{1/2}
 \left\lVert h\right\rVert_{\alpha;I}.

\end{equation}
In particular, for every fixed $\kappa$, these norms define the same underlying
space, and $w_\kappa\leq w$.  On the full interval,
\begin{equation}
 e^{-\operatorname{osc}_\alpha(w)/2-\kappa T}\left\lVert h\right\rVert_\alpha
 \leq \left\lVert h\right\rVert_{w_\kappa}
 \leq e^{\operatorname{osc}_\alpha(w)/2}\left\lVert h\right\rVert_\alpha.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.437830+00:00","domain":"probability theory","id":"claim_afb61e1aba110cde90f1af6ea0a83f391680261095678f7eb5e579b038872d66","kind":"definition","schema_version":1,"statement":"[Definition mixingdef of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $t_N$ be a non-decreasing sequence of positive integers. A Markov chain $([N], P_N)$  is said to be \emph{Short-to-Long Mixing} at time \(t_N\) if its $n$-step transition probability $p_n(x,y)$ satisfies the following two conditions:

\begin{enumerate}[leftmargin=*,label=(B\arabic*)]
    \item  \textbf{(Short-time average mixing)}  
    There exists a constant $\gamma \ge 1$ and $N_0 > 0$ such that for all $N \ge N_0$ and all $x, y \in [N]$,
    \begin{equation}
        \frac{1}{t_N} \sum_{n=1}^{t_N} p_n(x, y) \le \frac{\gamma}{N}.
    \end{equation}

    \item  \textbf{(Long-time uniform mixing)} 
    There exists  $\delta \in (0, 0.1)$, such that for all $n \ge t_N$ and all $x, y \in [N]$,
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{N} \right| \le \frac{\delta}{N}.
    \end{equation}
\end{enumerate}
The additional assumption that  $\delta = \delta_N \to 0$  may be imposed   when necessary.","status":"unverified"}

