	& \textbf{a}^{(\emptyset)} = \textbf{a}, \quad \textbf{a}^{({\nabla\nabla})} = - \nu_{c,\textbf{a}}^{({\nabla\nabla})}, \quad \textbf{a}^{(\Delta)} = - \nu_{c,\textbf{a}}^{(\Delta)} ,  \\
