{"assumptions":[],"created_at":"2026-10-27T11:07:35.012874+00:00","domain":"probability theory","id":"claim_b34579538664f30b5568b87052d1bbdd6d374f9f4c6012c0781f86ee1c3ce638","kind":"theorem","schema_version":1,"statement":"[Proposition 55 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For $1\le t\le c_a$, there is an exact sequence
\begin{equation}
 0\longrightarrow R_{a+t}^{\langle a\rangle}
 \longrightarrow C_{a,t}
 \longrightarrow C_{a,t-1}\longrightarrow0.
\end{equation}
Moreover, there is a natural surjection
\begin{equation}
 \cL_{a+1}\oplus\cdots\oplus\cL_n
 \twoheadrightarrow C_{a,t}.
\end{equation}
Thus every $C_{a,t}$ is globally generated, and
\begin{equation}
 c_{c_a}(C_a\otimes\cM)
 =\prod_{t=1}^{c_a}
 \bigl(c_1(R_{a+t}^{\langle a\rangle})+h_z\bigr).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:09.907231+00:00","domain":"probability theory","id":"claim_b34f2eb23a809a3cc2203dc44cf9c1dc1cef6084c918ab6ceff2d76488a3e5d3","kind":"lemma","schema_version":1,"statement":"[Lemma lem:uniform of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] For $t \geq t^*$, conditioned on the marked set $M_t$, $\rho_t$ is uniform on $\Omega_{t}(S_t)$. In particular, $\rho_{\tau_3}|\{\tau_3= t\}$ is uniform on $\Omega_t$. Consequently, if $k$ is odd, then
    \begin{align*}
        \rho_{\tau_3}\sim U_{\mathfrak{A}_n}.
    \end{align*}
    If $k$ is even, then
\begin{align*}
    \rho_{\tau_3}\sim \mathbf{P}(\tau_3\text{ is even}) \, U_{\mathfrak{A}_n}+\mathbf{P}(\tau_3\text{ is odd}) \, U_{\mathfrak{A}_n^c}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.652230+00:00","domain":"probability theory","id":"claim_b352b95769f5c8be42cfdf64aab2b396d0f5e3780d61cc5850f702af7bc9870b","kind":"theorem","schema_version":1,"statement":"[Prop 13 of arXiv:2607.24170, '\large\bf ON NON-MONOTONICITY OF LOGARITHMIC ENERGY\\ FOR RANDOM MATRICES'] With $a_0,a_1$ as in \eqref{EqAZero}--\eqref{EqAOne}, put
