\end{align}
where $0<\mu<\overline{\mu}=\frac{1}{2}\min \{2\mu_2,\nu+1,2\overline{\gamma},\overline{\gamma}+\mu_1\}$ with $\bar\gamma = \min\{{\alpha}_1, \alpha_2, \alpha_3, \gamma_1, \gamma_2\}$, $\beta={\sqrt{L_{b }}+p^{\frac{1}{\overline{\nu}+1}}L_{\sigma }^{\frac{2}{\overline{\nu}+1}}}$ with $\bar{\nu} = \min\{\nu, \nu_1, \nu_2\}$,   and $L_b, L_\sigma$ are the Lipschitz constants of $b$ and $\sigma$ respectively, $M$ is defined in \eqref{E:DefM}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:46:00.356623+00:00","domain":"probability theory","id":"claim_b3e91e0677791cca737d8daa7c602f31ebefb8c3664e71c458c6317c491ee937","kind":"concept","schema_version":1,"statement":"[Theorem th:lm:SPDE of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Suppose $2H\alpha =3$, and fix $z_0 = (t_0\,,x_0) \in (0\,,\infty) \times \mathbb{R}$. Then, a.s.,
\begin{align}
    \lim_{h\to0^+} \sup_{x: 0<|x-x_0|\le h} \frac{|u(t_0\,,x)-u(t_0\,,x_0)|}{|x-x_0|\sqrt{\log(1/|x-x_0|) \log\log\log(1/|x-x_0|)}} = K_6,
\end{align}
\begin{align}
    \lim_{h\to0^+} \sup_{t: 0<|t-t_0|\le h} \frac{|u(t\,,x_0)-u(t_0\,,x_0)|}{|t-t_0|^{1/\alpha}\sqrt{\log\log(1/|t-t_0|)}} = K_7,
