{"assumptions":[],"created_at":"2026-10-27T12:59:58.445970+00:00","domain":"probability theory","id":"claim_b612e40831f74ac5628512ffa4c5c4c696b0d1ee47bfadea8f921566be4a07b6","kind":"definition","schema_version":1,"statement":"[Definition eq:defXYmodellambda of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \geq 2$, a parameter $\lambda > 0$, two inverse temperatures $\beta_1 , \beta_2 \geq 0$, and a site percolation configuration $r \in \{ 0 , 1\}^{\Lambda_L}$, we define
 \begin{itemize}
    \item The XY height function
  \begin{multline*}
     \mu_{L , n ,\beta_1, \beta_2 , \lambda,r }^{\ensuremath{\mathbb{Z}} - \mathrm{XY}} (\left\{ \varphi \right\}) \\
     := \frac{1}{Z_{\Lambda,J}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} }  I_{\left(\varphi(0)\right)} \left( \lambda \right)\prod_{x \sim y}  \left[ I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_y \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left(  n \beta_2 \right)^{n-2} \right].
 \end{multline*}
 We denote the variance associated with this measure by $\mathrm{Var}_{L , n ,\beta_1, \beta_2 , \lambda,r}^{\ensuremath{\mathbb{Z}} - \mathrm{XY}}$.
 \item The generalised XY model
 \begin{multline} 
     \mu_{L , n , \beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}} (d \theta) \\
     := \frac{1}{Z_{\Lambda_L , n ,\beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}}} \exp \left( \lambda \cos(\theta_{0g}) \right) \exp \left( \beta_1  \sum_{ x \sim y} \left( r_x \cos(\theta_{xy,1}) + r_y \cos(\theta_{xy,n}) \right) \right)  \\ \times \exp  \left( n \beta_2 \sum_{ x \sim y}  \sum_{2 \leq k \leq  n-1} \cos(\theta_{xy,k})  \right)  d \theta.
 \end{multline}
We denote by $\left\langle \cdot \right\rangle_{L , n , \beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}}$ the expectation with respect to this measure.
\end{itemize}
In both cases when the percolation configuration is $r \equiv 1$ (i.e., all the sites are open), we omit the subscript $r$ from the notation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.506741+00:00","domain":"probability theory","id":"claim_b614bbaabeb4756fde83bf5636f7ebed7eca5a95e123ebdc75c0f93205d03b46","kind":"lemma","schema_version":1,"statement":"[Lemma STassump of arXiv:2607.22991, 'Mixing times and spectra of non-equilibrium symmetric exclusion processes on general graph'] Consider the dynamics ${\mathcal Q}={\mathcal S}+{\mathcal H}$ with heat bath~${\mathcal H}$, as in~(equation Sin of the paper) and~(equation Hh of the paper),
