{"assumptions":[],"created_at":"2026-10-26T19:47:01.670426+00:00","domain":"probability theory","id":"claim_b652d5586fc05c817f94891432524d88bb60f31e922a2c3863e979bb6972df6e","kind":"concept","schema_version":1,"statement":"[Proposition 3 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] {Assume  \eqref{as:generatorf}, \eqref{as:b:sigma} and \eqref{as:int:X:nablaX}.}
