{"assumptions":[],"created_at":"2026-10-26T19:40:21.308349+00:00","domain":"probability theory","id":"claim_ba4db366c7aec6c30d6da5c201d6b9eb749ebd948efe33a1518fda934a3694ed","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2604.07697, 'Stochastic fractional heat equation with general rough noise'] \begin{itemize}
