  \widehat{\PP}_T(\sigma_T>R)
  \leq C_H(1+\log R)R^{-H}.

\end{equation}
Consequently, under \(\widehat{\PP}_a\), the families \((U_a)_{a>0}\) and
\((V_a)_{a>0}\) are tight, and, as \(a\to\infty\),
\begin{equation}
  a-U_a\longrightarrow\infty
  \quad\text{in probability}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.683729+00:00","domain":"probability theory","id":"claim_bb70e48e1d72619ea8990865d0facfeae9f14b05b83ecdcf5fab67b036588b77","kind":"lemma","schema_version":1,"statement":"[Lem 20 of arXiv:2609.03777, '2609.03777'] Let $N,r\in\ZZ_{>0}$. For $\tau\in C$ and $\mu_1,\mu_2\in\Lambda_\tau$ with $\mu_1\ordN\mu_2$ and $\mu_1\succ\mu_2$, we have
