         \,,
       \end{align}
       we have
       \begin{align*}
         &
         \norm{
         \sum_{t=1}^n
         (G_n(X_t)
         \ - \
         \EE[G_n(X_0)])
         \ - \
         G_{\infty,n}'(0)
