{"assumptions":[],"created_at":"2026-10-27T09:05:57.797195+00:00","domain":"probability theory","id":"claim_bda9cf7dbea977ba1d16d8d6887a7911e32ba9945db1796f5ca7668f4eae7f71","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] If $p>1$, $\alpha\in(0,1]$, $(p,\alpha)\neq(2,1)$, $u(0)=0$, and $u\in\ell^p(\N,x^{-2})$, then
\begin{equation}
    \mathcal{E}_p^{\N_0}(u)
    \geq
    \sum_{x\in\N} w_{p,\alpha}(x)|u(x)|^p,
\end{equation}
where
\begin{equation}
    w_{p,\alpha}(x)
    :=
    \frac{1}{a_p+1}
    \frac{\Delta x^{\alpha a_p}}{x^{\alpha a_p}}
    +
    \frac{a_p}{a_p+1}
    \frac{\Delta x^\alpha}{x^\alpha},
    \qquad x\in\N.
\end{equation}
The Hardy weight $w_{p,\alpha}$ is strictly positive; it is critical whenever
\begin{equation}
\alpha\leq\frac{1}{a_p+1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.251727+00:00","domain":"probability theory","id":"claim_bdad24d51bed9cadb628f6273e286c468d8ab9fdfe469ac948bee336947f6da8","kind":"concept","schema_version":1,"statement":"[Lemma 18 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $p_0,p_1,q_0,q_1 \in[1,\infty]$ and $\alpha_0,\alpha_1,\mu_0,\mu_1 \in \R$ and $p,q,\alpha,\mu$ such that
\begin{equation*} 
\frac{1}{p}=\frac{1-\theta}{p_0}+\frac{\theta}{p_1},\quad \frac{1}{q}=\frac{1-\theta}{q_0}+\frac{\theta}{q_1},
\end{equation*}
and
\begin{equation*}
\alpha=(1-\theta)\alpha_0+\theta\alpha_1, \quad  \mu=(1-\theta)\mu_0 + \theta \mu_1
\end{equation*}
for $\theta \in[0,1]$. Then there exists $C>0$ such that
\begin{equation*} 
\|u\|_{\mathcal{B}^\alpha_{p,q,\mu}(\R^d)} \leq C \|u\|_{\mathcal{B}^{\alpha_0}_{p_0,q_0,\mu_0}(\R^d)}^{1-\theta} \|u\|_{\mathcal{B}^{\alpha_1}_{p_1,q_1,\mu_1}(\R^d)}^{\theta}.
\end{equation*}
In particular, we have
\begin{equation*}
\|u\|_{\CH_\mu^\alpha}\le C\|u\|_{\CH_{\mu_0}^{\alpha_0}}^{1-\theta}\|u\|_{\CH_{\mu_1}^{\alpha_1}}^\theta.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.686060+00:00","domain":"probability theory","id":"claim_bdad384bd4ec0a9022f83ff037ab8a240b2648fc1b89452fe9ef257def8f9d1c","kind":"concept","schema_version":1,"statement":"[Theorem thm:Wolf-strong-isospectrality of arXiv:2609.01920, 'Isospectral and not strongly isospectral spherical space forms with non-cyclic fundamental'] Let $\Gamma=\Gamma_d(m,n,r)$ be a Type I group, $p$ a positive integer, and
\begin{equation*}
	\rho= \bigoplus_{j=1}^{p} \left(\pi_{k_j,\ell_j}\oplus \overline{\pi}_{k_j,\ell_j} \right)
	\qquad\text{and}\qquad
	\rho'= \bigoplus_{j=1}^{p} \left(\pi_{k'_j,\ell'_j}\oplus \overline{\pi}_{k'_j,\ell'_j} \right)
\end{equation*}
two fixed point free real representations of $\Gamma$. 
Suppose that there exist integers $a$ and $b$ with $\gcd(a,m)=1$, $\gcd(b,n)=1$, a permutation $\sigma$ of $\{1,\ldots,p\}$,  $\epsilon_1,\dots,\epsilon_p\in\{-1,1\}$, and integers $c_1,\dots,c_p\in\{0,\ldots,d-1\}$ such that 
\begin{align*}
	k_{\sigma(j)}' &\equiv \epsilon_j ak_{j}r^{c_j} \pmod m,&
	\ell_{\sigma(j)}' &\equiv \epsilon_j b\ell_{j} \pmod {n/d},
	\qquad 
	\text{for all $1\leq j\leq p$}.
\end{align*}
Then, the spherical space forms
$S^{2dp-1}/\rho(\Gamma)$ and $S^{2dp-1}/\rho'(\Gamma)$ are strongly isospectral. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

