{"assumptions":[],"created_at":"2026-10-27T17:48:24.519605+00:00","domain":"probability theory","id":"claim_bdc47d2645794b4fb5b49a34abd5b2d8c2434285108c78682d12126029fb7af2","kind":"concept","schema_version":1,"statement":"[Theorem thm:PDEs of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] Let $\mathcal{D}\coloneq \{(z,t)\in\mathbb{C}^2: t=|t|e^{i\theta}\neq 0, e^{-i\theta/2} z \in \mathcal{D}_{|t|}\}$.
\begin{enumerate}
\item The logarithmic potential $U_t$ satisfies the Hamilton-Jacobi PDE
\begin{align}
\partial_{t}U_t(z)=-(\partial_z U_t(z))^2, \quad (z,t)\in\mathcal{D},
\end{align}
where $\partial_t$ is the Wirtinger derivative of $t\in\mathbb{C}$.
\item The Stieltjes transform $m_t$ satisfies the PDEs
\begin{align}
\partial_t m_t(z)&=-\frac{1}{2}\partial_z(m_t^2(z))=-m_t(z)\partial_z m_t(z), \quad (z,t)\in\mathcal{D},\\
\partial_{\bar t}m_t(z)&=-\frac{1}{2}\partial_z\overline{(m_t^2(z))}=-\overline{m_t(z)}\partial_z \overline{m_t(z)}, \quad (z,t)\in\mathcal{D} .
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

