\item for every $(x, y) \in \mathrm{dom}(Q)$ and $\alpha$ with $\mathrm{ht}(x) < \alpha < \mathrm{ht}(y)$, $\pi_\alpha(Q(x, y)) = Q(x, \pi_\alpha(y))$;
\item for every $x, y$ and $\alpha < \beta < \mathrm{ht}(x)$, if $x = Q(\pi_\alpha(x), y)$, then $x = Q(\pi_\beta(x), y)$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.803565+00:00","domain":"probability theory","id":"claim_be5beb1f9a57aba752321fb35d84b9a820dd5812f480ce5cfc6d20dba5f9a885","kind":"lemma","schema_version":1,"statement":"[Lemma L:K3-4 of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] Let the terms $\mathsf{K}_3(t, r_1 \vee r_2; \varepsilon, \eta)$ and $\mathsf{K}_4(t, r_1 \vee r_2; \varepsilon, \eta)$ be defined in equation (equation E:Second-der-X-W2W2 of the paper). Then, for any $p \in \mathbb{N}$ and $t \ge r_1 \vee r_2,$ there exists a time-independent positive constant $K$ such that
\begin{equation*}
