    &- \frac{2}{1+l_\mathbf{X}\left((\mathbf{w}^{(1)}\vee \mathbf{w}^{(2)})^\alpha\right)} \nonumber  .
\end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:23:25.637269+00:00","domain":"probability theory","id":"claim_bf0a8b499d8855da13fcd42f5870e371614225c18dcc389d3bd547eb5858b2d6","kind":"concept","schema_version":1,"statement":"[Cor Jackson_integral_qMPL of arXiv:2609.01458, 'Confluence relations for $q$-analogues of multiple zeta values'] Let $d\geq1$. When $x_{1},\dots,x_{d}$
are constant with respect to $z$, we have
\begin{align*}
\int\frac{\mathrm{Li}_{q;k_{1},\dots,k_{d}}(x_{1},\dots,x_{d-1},x_{d}z)}{z}d_{q}z & =\mathrm{Li}_{q;k_{1},\dots,k_{d-1},k_{d}+1}(x_{1},\dots,x_{d-1},x_{d}z),\\
\int\frac{\mathrm{Li}_{q;k_{1},\dots,k_{d}}(x_{1},\dots,x_{d-1},x_{d}z)}{z-a^{-1}}d_{q}z & =-\mathrm{Li}_{q;k_{1},\dots,k_{d},1}(x_{1},\dots,x_{d-1},x_{d}a^{-1},az),\\
\int\frac{1}{z-a^{-1}}d_{q}z & =-\mathrm{Li}_{q;1}(az),
\end{align*}
where $a\in\mathbb{C}^{\times}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:48:43.476534+00:00","domain":"probability theory","id":"claim_bf0c40288e76ecb9f0988b8b2791ec07edd0c98ccc8f9736bce55c11efd4908d","kind":"theorem","schema_version":1,"statement":"[Proposition 8 (Failure of smoothness at an atom) of arXiv:2608.06565, 'Smoothness of the survival probability in models with a random environment: the annuity an'] Let $K=1$, $\sigma>0$, $\alpha>0$, let the measure $F$ have an atom at a point
$-b<0$ of weight $\varkappa:=F(\{-b\})>0$ and no other atoms in some punctured
neighbourhood of $-b$, and let $\Phi(0+)>0$. Then $\Phi\in C^1(0,\infty)$, the
second derivative has one-sided limits at $b$, and
