and 
\begin{equation}

\sum_{k=1}^n r_k= o\left(n^{1-\rho^*-\delta_0}\right)
\text{ a.s. for some } \delta_0>0.
\end{equation}
Then there exists a random variable $L$, such that, 
\begin{equation}

n^{\rho^*}\left(\theta_n-\theta^*\right)\rightarrow L, \text{ a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.691790+00:00","domain":"probability theory","id":"claim_bf1628a0042868df601a902b921d3a29118f6f59a5f4eb878faa3ed057366544","kind":"theorem","schema_version":1,"statement":"[Proposition prop:lipptx33 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] Let $\delta_1,\delta_2\in [0,1)$, $\lambda_1\geq 0$ and $l\in \mathcal{H}_1^{\delta_1,\lambda_1}(\mathbb{R}^d)$, $h\in \mathcal{H}_1^{\delta_2}(\mathbb{R}^d)$, $z\in \mathbb{R}^d$. For $t\in [0,1)$ and $\theta_1,\theta_2\in \mathbb{R}^d$, in the case $\beta\geq 1$ we have 
    \begin{align*}
        \|&\int (l(y)-l(z))h(y)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
        & \leq C \sum_{i=1}^2\left(\|\theta_1-\theta_2\|^{\delta_1}\log(\|\theta_1-\theta_2\|^{-1})^{-\lambda_1}\Biggl(\int\|h(y)\|^2p^{t,\theta_i}(y) \right)^{1/2}+\|\theta_1-\theta_2\|^{\delta_2}\left(\int\|l(y)-l(z)\|^2p^{t,\theta_i}(y) \right)^{1/2}\Biggl).
    \end{align*}
    and in the case $\beta<1$, $l(y)-l(z)=y-t\theta_1$, $h(y)=H(y,\theta_2)$ we have
    \begin{align*}
        &\|\int (y-t\theta_1)H(y,\theta_2)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
         \leq &C\|\theta_1-\theta_2\|\left(\|\int H(y,\theta_2)dp^{t,\theta_2}(y) \|+\|\int \left(y-t\theta_1 \right)dp^{t,\theta_2}(y)\|\right)\\
        & +C\frac{\|\theta_1-\theta_2\|^{\beta}}{\log(\|\theta_1-\theta_2\|^{-1})^{\theta}}\left(\int\|y-t\theta_2\|^2dp^{t,\theta_2}(y) \right)^{1/2}\left(\int\|H(y,\theta_2)\|^2p^{t,\theta_1}(y) \right)^{1/2}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.240648+00:00","domain":"probability theory","id":"claim_bf1adcdb89af785b614f12f922b0b348dd2c0e36b4750cb99ddd9f842fb06fee","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ibp_sig of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Under the assumptions of Proposition~(ibp_proposition of the paper), suppose that 
    \begin{enumerate}
        \item $G \in \mathcal{P}(\sigW[T])$ with the coefficient $\bm{\ell}^G \in \TA$.
        \item $F \in \mathcal{R}(\sigW[T])$, i.e., $F = \dfrac{\bracketsigW[T]{\bm{\ell}^F_1}}{\bracketsigW[T]{\bm{\ell}^F_2}}$ for some $\bm{\ell}^F_1, \bm{\ell}^F_2 \in \TA$.
        \item $h$ is a process of the form (equation eq:h_class of the paper).
        \item The coefficients $\bm{\ell}^G, \bm{\ell}^{F_1}, \bm{\ell}^{F_2}, \vec\bm{\ell}^h$ are such that $\dfrac{F}{\bracket{\mathbf{D} G}{h}_{L^2}} = \dfrac{\bracketsigW[T]{\bm{\ell}^F_1}}{\bracketsigW[T]{\bm{\ell}^F_2}\bracketsigW[T]{\bm{\ell}^G \diamond \vec\bm{\ell}^{h}}} \in \mathbb{D}^{1,2}$.
    \end{enumerate} 
    Then, 
    \begin{equation}
        \mathbb{E}\left[f'(G)F\right] = 
        \mathbb{E}\left[
        f(G)\pi_T\right],
    \end{equation}
    where $\pi_T \in \mathcal{R}(\sigW[T])$ is given by
    \begin{equation}
    \begin{aligned}
        \pi_T &= 
        \dfrac{\bracketsigW[T]{\bm{\ell}^F_1}\bracketsigW[T]{\sum_{i=1}^d({\bf \Lambda}_{{\color{NavyBlue}{\mathbf{i}}}} - {{\bf\Psi}}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}})(\bm{\ell}^{h}_i)}}{\bracketsigW[T]{\bm{\ell}^F_2}\bracketsigW[T]{\bm{\ell}^G \diamond \vec\bm{\ell}^{h}}}
        - \dfrac{\bracketsigW[T]{\bm{\ell}^F_1 \diamond \vec\bm{\ell}^{h}}}{\bracketsigW[T]{\bm{\ell}^F_2}\bracketsigW[T]{\bm{\ell}^G \diamond \vec\bm{\ell}^{h}}} \\
        &\quad+ \dfrac{\bracketsigW[T]{\bm{\ell}^F_1}\bracketsigW[T]{\bm{\ell}^F_2 \diamond\vec\bm{\ell}^{h}}}{\bracketsigW[T]{\bm{\ell}^F_2}^2\bracketsigW[T]{\bm{\ell}^G \diamond \vec\bm{\ell}^{h}}} 
        + \dfrac{\bracketsigW[T]{\bm{\ell}^F_1}\bracketsigW[T]{\bm{\ell}^G \diamond\vec\bm{\ell}^{h}\diamond \vec\bm{\ell}^{h}}}{\bracketsigW[T]{\bm{\ell}^F_2}\bracketsigW[T]{\bm{\ell}^G \diamond \vec\bm{\ell}^{h}}^2}.
    \end{aligned}       
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.278355+00:00","domain":"probability theory","id":"claim_bf1dd1153a0b77afec3fd20dd3c1b3c88ee3c9f73cc94796ff362d4bce9a7f83","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Let $G=(V,E)$ be a graph, let $v\in V$, and let $U\subseteq N(v)$ be a set of neighbors of~$v$ with $|U|\ge k$. Let $\boldsymbol{\sigma}(0)$ be an arbitrary deterministic initial configuration on $V$, subject only to the condition that $v$ is $k^{1/24}$-lit among $U$ at time 0. Then there exists an event $A^{(v)}\in \mathcal{G}(v, U)$, such that for all sufficiently large $k$, the following holds:
\begin{enumerate}
  \item[\normalfont (i)] On ${A}^{(v)}$, the vertex $v$ remains $k^{1/96}$-lit among $U$ throughout the time interval $\big[0,\tfrac{1}{48}\log k\big]$;
  \item[\normalfont (ii)] On ${A}^{(v)}$, the vertex $v$ remains $k^{1/24}$-lit among $U$ throughout the time interval $[\frac{1}{48}\log k ,3k^{\min\{\rho,\lambda,1\}/200}]$;
