{"assumptions":[],"created_at":"2026-10-27T14:55:18.924887+00:00","domain":"probability theory","id":"claim_bf681e1e4a83c895cacd1639c1fc040d8f1d381b63bb181712e5a5a4c022cc97","kind":"theorem","schema_version":1,"statement":"[Theorem general-ThmB of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Consider the setting of Lemma~(le:uniform-estimate of the paper).
     Then the  following statements hold.
    \begin{itemize}
        \item[(i)] There exists a subsequence $\{ u^{\epsilon_n}\}$ such that $u^{\epsilon_n} \rightarrow u$ in  $L^{2}([0,T];H) \cap C([0,T],H_{w})$, 
        and the limit $u$ is a rough path solution to (equation eq:limit-eq of the paper)
        \begin{equation*}
            \partial_t u = \nu \Delta u- \Pi[(u \cdot \nabla) u] - \Pi[(d \mathbf{B} \cdot \nabla) u],
        \end{equation*}
        in case of ((sf of the paper)) and in case of (equation sf2 of the paper), it solves 
         \begin{equation*}
            \partial_t u = \nu \Delta u- \Pi[(u \cdot \nabla) u] - \Pi[(d \mathbf{Z} \cdot \nabla) u].
        \end{equation*}

        \item[(ii)] The convergence $\{ u^{\epsilon_n}\}$ also holds in an analog of a controlled rough path distance, meaning:
        $$ u^{\epsilon_n} \rightarrow u \text{ in } C^{\frac{1}{\alpha-\delta} \textrm{-var}}([0,T]; H^{-1})$$
        $$ R^{u^{\epsilon_n}} \rightarrow R^u \text{ in } C^{\frac{1}{2(\alpha-\delta)}\textrm{-var}}([0,T]; H^{-2})$$
        hold for any $\delta>0$.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.705623+00:00","domain":"probability theory","id":"claim_bf69f24b3ae770e7de8db518cdd6f8cd641ec49b4c490f71a110d39a0fde3bb6","kind":"lemma","schema_version":1,"statement":"[Lem 54 of arXiv:2608.30990, 'Convergence of symmetries: nilpotency, dimension, and perfectness'] Let $G_i$ be a sequence of locally compact Hausdorff groups, $G$ a metrizable locally compact group, and open symmetric subsets $H_i \subset G_i$ and $H \subset G$.  Let $\phi_i : H_i \to H$ be a sequence of local good approximations with regular neighborhoods $A_i \subset H_i$ and $A \subset H$. Assume that for each $i$, there is a sequence of subgroups $H_{i,j} \subset G_i$ such that for each  identity neighborhood $V \subset G_i$, one has $A_i \subset H_{i,j} V$ for $j$ large enough. If for each $i$, we choose $j (i) $ sufficiently large, then the  restrictions 
 \begin{equation}
          \phi_i : H_i \cap H_{i,j(i)} \to H          
    \end{equation}
    are local good approximations with regular neighborhoods $A_i \cap H_{i,j(i)} \subset H_{i,j (i)}$ and $A \subset G$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.582571+00:00","domain":"probability theory","id":"claim_bf6b899d5fd1760f0a7040ba6963a8abe0976f5e7c04eb50b49acc5941d23b90","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2609.01333, '2609.01333'] For each $\kappa>0$, there exists $\gamma_*=\gamma_*(\kappa)\in  \Big(0, \, \frac{1}{2\pi} \tfrac{1}{\frac{1}{\kappa} - \frac{1}{\sqrt{\kappa^2+1}}}\Big)$ such that for every $\alpha \in (0,1)$ and $\gamma\in (0,\gamma_*)$, there exists   $\lambda_{*}=\lambda_*(\kappa, \gamma)>0$ and a smooth curve
\begin{align*}
 I: (-\varepsilon_0,\varepsilon_0) &\longrightarrow  (0,\infty) \times C^{2,\alpha}(\R),\quad  s\longmapsto (\lambda_s,u_s)
 \end{align*}
satisfying   $I(0)= (\lambda_0,u_0) \equiv( \lambda_{*},0)$. Moreover,  the  following properties hold.
\begin{enumerate}[$(a)$]
\item For each $s \in (-\varepsilon_0, \varepsilon_0)$,  $u_s\in C^{2,\alpha}(\R)$ is even, $2\pi$-periodic, and takes the form
\begin{align*}
u_s(t) = s\big(\cos(t) + \omega_s(t)\big),
\end{align*}
where $\omega: (-\varepsilon_0, \varepsilon_0) \to C^{2,\alpha}(\mathbb{R})$, $s \mapsto \omega_s$ is a smooth curve satisfying $\omega_0 \equiv 0$, $\omega_s\in C^{2,\alpha}(\R)$ is even, $\omega_s$ is $2\pi$-periodic and satisfies
\begin{align*}
\int_{0}^{2\pi} \omega_s(t) \cos(t) \mathrm{d}t = 0.
\end{align*}
\item Each function $\varphi_s = \lambda_s + u_s$ satisfies  $\varphi_s\in C^{2,\alpha}(\R)$,  $\varphi_s\geq \frac{\lambda_*}{2}$, $\varphi_0=\lambda_*$ and
\begin{align}

H_{\partial\Omega_{\varphi_s}}(x) + \gamma \int_{\Omega_{\varphi_s}} G_\kappa(|x-y|)  \mathrm{d}y = C_{\lambda_s,\kappa} \qquad \text{for all } x \in \partial\Omega_{\varphi_s}
\end{align}
where the constant $C_{\lambda_s,\kappa}$ satisfies $C_{\lambda_s,\kappa}\leq C_{\lambda_*,\kappa}$ with

\begin{align*}
C_{\lambda_s,\kappa} &=H_{\partial\Omega_{\lambda_s}}\hspace{-0.7ex}
(0,\lambda_s e_1)+\gamma \int_{\Omega_{\lambda_s}}\hspace{-2ex} G_\kappa(|(0,\lambda_s e_1)-z|) \mathrm{d}z=\frac{1}{\lambda_s}
+ 2\gamma\lambda_s^2 \int_{B_1} \hspace{-2ex}K_0(\lambda_s \kappa|e_1-y|)\mathrm{d}y,
\end{align*}
\end{enumerate}
where $e_1=(1,0)\in \R^2$ and  $K_\nu$ is the modified Bessel function of the second kind of order $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.451626+00:00","domain":"probability theory","id":"claim_bf6dbf0495c6bf832fdf167354dfb252d3301aa2cc60c24b4f657bbfa38396e9","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] If $\mathbf{f} \in \cC^k_1(\cB)$, then $f^{\cA} \in C^k\big(\cA_{c,\sa}^{\cB};\cA\big)$, and
\begin{equation}
    Df^{\cA}(x)[y] = \partial f^{\cA}(x,x)\sh y + \tau\otimes\id_{\cA}\left( \widetilde{\partial}f^{\cA} \sh (y\otimes 1) \right) \qquad \left(x, y \in \cA_{c,\sa}^{\cB}\right), 
\end{equation}
where $D$ denotes the Fr\'echet derivative---in particular, $D^0f^{\cA}=f^{\cA}$ and,
$$ D^jf^{\cA}(x)[y_1,\dots,y_j] = \lim_{t\to 0} \frac{D^{j-1}f^{\cA}(x+ty)[y_1,\dots,y_{j-1}] - D^{j-1}f^{\cA}(x)[y_1,\dots,y_{j-1}]}{t}. $$
Besides, there exists a universal constant $C_j$ such that for all $x\in \cA^{\cB}_{c,\sa}$ with $\norm{x}_{\cA,c}\leq R$,
\begin{equation}

    \norm{D^jf^{\cA}(x)[y]}_{\cA^{0,1}} \leq C_j \norm{f}_{j,c,R} \norm{y_1}_{\cA,c}\dots \norm{y_j}_{\cA,c}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.636653+00:00","domain":"probability theory","id":"claim_bf75f3d28f0ef138b73b36224b15777c07abee7ba19c4a486c6ea1268c170dd8","kind":"concept","schema_version":1,"statement":"[Lemma 28 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $\eps > 0$. Then, there exists $C = C(\eps,P,\G)$ such that 
