{"assumptions":[],"created_at":"2026-10-26T20:55:18.053247+00:00","domain":"probability theory","id":"claim_bfecb622ee64589ec294948b9cd69d17790cd644a5028c44019175a59a413bc2","kind":"definition","schema_version":1,"statement":"[Definition 38 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $H\in Z\hC^{\gamma}(\Delta_T^3;B_\alpha)$ and let $\mathsf s$ be the heat spectral splitting rule described below.  We say that $H$ satisfies the {\bf parabolic tail condition} with parameters $(\beta,\sigma,K)$ if, for every dyadic parent interval $[a,c]$ with midpoint $b$, length $L=c-a$, $h=c-b=L/2$, and residual $Q_{ca}$ generated by the recursion, the vector $Y_{cba}:=Q_{ca}-H_{cba}$ satisfies
\begin{equation}

\norm{P_{>N_h}Y_{cba}}_{H^\alpha}\le K L^{\gamma+\rho},
\end{equation}
where $\rho:=\frac{\sigma\beta}{2}>0$. At the critical endpoint $\gamma=1$, the same condition is required with $L^{1+\rho}$ in \eqref{eq:parabolic-tail-bound}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.750803+00:00","domain":"probability theory","id":"claim_bfedc6c405ea2f997d6c391e25558b556d9563ac614247bb13da80d736e5c150","kind":"concept","schema_version":1,"statement":"[Proposition 21 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that Assumption \ref{Assumption} holds.
\begin{enumerate}
\item If $\rho>0$, for every $t>0$, there exists a random variable $\ga_t(B)$ such that
\begin{align}

\lim_{\eps\to0}\be^\eps_t(B)=\ga_t(B)
\qquad\text{in $L^2$}.
\end{align}
Moreover, for every $c,t>0$, one has
\begin{align}

\sup_{\eps>0}\mbf E\left[\exp\big(c\be^\eps_t(B)\big)\right]\leq\mbf E\left[\exp\big(c\ga_t(B)\big)\right]<\infty.
\end{align}
\item If $\rho\leq0$, for every $t>0$, there exists a random variable $\ga_t(B)$
such that
\begin{align}

\lim_{\eps\to0}\Big(\be^\eps_t(B)-\mbf E\big[\be^\eps_t(B)\big]\Big)=\ga_t(B)
\qquad\text{in $L^2$}.
\end{align}
Moreover, for every $c>0$, there exists $\th_c>0$ such that for every $t\in(0,\th_c)$,
\begin{align}

\sup_{\eps>0}\mbf E\left[\exp\Big(c\big(\be^\eps_t(B)-\mbf E\big[\be^\eps_t(B)\big]\big)\Big)\right]<\infty
\quad\text{and}\quad
\mbf E\left[\exp\big(c\ga_t(B)\big)\right]<\infty.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

