\end{equation}
We denote $\bar{Q} =\Phi_{\boldsymbol{G}^T}(\bar{X}) $ and $\bar{Y} =\Psi_{\boldsymbol{G}^T}(\bar{X})$ and call them as the reflected process and regulator, respectively. It is apparent that $\bar{Q}(0)\ge0$ and $\bar{X}\in\mathcal{C}_T(L_1)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.442427+00:00","domain":"probability theory","id":"claim_c1372e205f966476d590f8dcad673b8766a528bf497c7549cc99ca86f5f25841","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $V\in\cC^{4k+7}(X_1,\dots,X_d)$ be a $k$-regular potential (see Definition \ref{definition:kregular}), and $Y^N$ a multimatrix model with potential $V$ (see Definition \ref{def:randompot}). There exists a transport map $T^N$ between the law of $Y^N$ and the one of a $d$-tuple of independent GUE random matrices $X^N$, i.e., $T^N$ such that for all measurable functions $f$,
    $$ \E\left[ f(Y^N) \right] = \E\left[ f\circ T^N(X^N) \right].$$

    \noindent Moreover, there exists $T^0 \in (\cC^k(X_1,\dots,X_d))^d$, as well as $T^m\in (\cC^{k+1-m}(X_1,\dots,X_d))^d$ for $m\in [1,k]$, such that, for all $N\geq 1$,
    \begin{equation}

        \sup_{H\in\M_N(\C)_{sa}^d}\ \norm{T^N(H) - \sum_{i=0}^k \frac{T^i(H)}{N^{2i}} } \leq \frac{C_{V,k}}{N^{2k+2}},
    \end{equation}
    for some constant $C_{V,k}$. Besides, there exists another constant $C_{V,k}$ such that
    \begin{align}

        \norm{T^0 - \id }_{\cC^k,\infty}\leq C_{V,k}, \quad\quad \norm{T^m}_{\cC^{k+1-m},\infty}\leq C_{V,k},\quad 1\leq m\leq k.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

