{"assumptions":[],"created_at":"2026-10-27T22:52:32.334706+00:00","domain":"probability theory","id":"claim_c15ece7c9825d3253a07d2e1d8c6654661199274ce4d75052ee02cce5593e5bf","kind":"theorem","schema_version":1,"statement":"[Theorem thm:logdecay of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(\Omega,\Omega_w,\Omega_h)$ be a Lipschitz interface triple in $\mathbb{R}^n$ and let $S\in L^\infty(\Omega_h,\mathbb{C}^{n\times n}) $ be an accretive heat coefficient, i.e., 
    $$\re(\overline{v}^\top S(x) v) \gtrsim  |v|^2 $$ for all $x\in \mathbb{C}^n$ and almost all $x \in \Omega_h$. Then the semigroup $T_S^\perp$ generated by the generator $A_S^\perp$ of the coupled wave-heat system~(equation eq:1 of the paper) possesses logarithmic decay with rate $1/d=1$, i.e.,  \begin{align*}
        \forall k \in \mathbb{N} ~ \exists C_k>0:  \|T_S^\perp(t)x\|_{\mathbb{H}_1} \leq \frac{C_k}{\log(t+2)^k} \|x\|_{(A_S^\perp)^k} ~ \forall t\geq0,  x\in \operatorname{dom}\left((A_S^\perp)^k\right).
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.654091+00:00","domain":"probability theory","id":"claim_c15fc516a72a813373d705d70e038e7427e14e7344bfd00461f82043c8cd8ccf","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and consider an initial value
\begin{equation}
    (u^0,w^0)\in W_{p}^{1,+}(\Omega)  \times L_\infty^+(\Omega) \,.
\end{equation}
Then there is a unique couple $(u,w)$ of functions satisfying
\begin{subequations}
\begin{align}
&u \in  C^1\big((0,\infty),L_p(\Omega)\big) \cap  C\big((0,\infty),W_{p,N}^{2}(\Omega)\big)\cap C\big([0,\infty),W_{p}^{1}(\Omega) \big)\,,\\
& w\in C^1 \big([0,\infty),L_\infty(\Omega)\big)\,,\qquad v := \mathcal{K}[w-\langle w\rangle] \in C^1\big([0,\infty),W_{p,N}^{2}(\Omega)\big)\,,
\end{align}
such that $(u,v,w)$ is a global non-negative strong solution to~\eqref{E}.
\end{subequations}
In fact, the mapping 
\begin{equation*}
	\boldsymbol{\Psi}:(u^0,w^0)\mapsto (u,w)
\end{equation*} 
defines a global semiflow on $W_{p}^{1,+}(\Omega) \times L_\infty^+(\Omega)$.  
Moreover, 
\begin{itemize}
    \item  for $t\ge 0$, it holds that
    \begin{equation}
        \|u(t)\|_1 = \|u^0\|_1\,, \quad \|w(t)\|_1 \le \max\big\{ \|w^0\|_1 , \|u^0\|_1 \big\}\,; 
    \end{equation}
	\item  if $u\in L_\infty((0,\infty),L_m(\Omega))$, then $(u,w)\in L_\infty((0,\infty)\times\Omega,\R^2)$;
	\item  if $\Omega=\mathbb{B}_R$  and $(u^0,w^0)$ are radially symmetric, then $(u,v,w)(t)$ are radially symmetric for all $t\ge 0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.092931+00:00","domain":"probability theory","id":"claim_c15fd828a375a981d01a4064e2cba2f5001790d3bc4f716ce7a4abd4fa82d711","kind":"theorem","schema_version":1,"statement":"[Prop eq:strong:Markov:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $T$ be a $(\overline{\mathcal{F}}_{t+})$-stopping time such that  $T > 0$, $\mathbf{N}_{x,r}$-a.e. For every non-negative $\overline{\mathcal{F}}_{T+}$-measurable function $\Phi$  and non-negative measurable function $F$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_{f}(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$, we have 
\begin{equation} 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}} \Phi \cdot  F \big( (\rho_{T + s }, \overline{W}_{T + s } : s \geq 0  ) \big)  \big) 
    = 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}}  \Phi \cdot  \mathbb{E}^{\dag}_{\rho_T, \overline{W}_T} [ F ]   \big).  
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.834616+00:00","domain":"probability theory","id":"claim_c161a00e7ad551d760d2d1e5f7e8bfe81597b30d31954d7493f54787ebdc4a9c","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1< p<\infty$, $\max\{1,p-1\}\le q<\infty$ and $\la>0$.
    Assume that  $|F|\in L^{q}_{\loc}(\Omega_T)$ and that $u\in  L^{q}_{\loc}(0,T;W^{1,q}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$.
 For $\Qla(z_0)=B_\rho(x_0)\times I^\la_\rho(t_0)\Subset\Om_T$ with $\rho>0$ and $\la>0$, let $(y,s)\in Q_1=B_1(0)\times I_1(0)$ and
 \begin{equation}
 \begin{split}
     v(y,s)
        &=  (\la\rho)^{-1} u (x_0+ \rho y, t_0+ \la^{2-p} \rho^2 s ),\\
         \mathcal{B}( y, s,\xi)&= \la^{1-p} \mathcal{A}(x_0+ \rho y, t_0 + \la^{2-p}\rho^2s , \xi),\\
        G(y,s)&= \la^{-1} F (x_0+ \rho y, t_0+\la^{2-p}\rho^2s ).
 \end{split}
 \end{equation}
 Then $v\in  L^{q}_{\loc}(I_1(0) ;W^{1,q}_{\loc} (B_1(0);\mathbb{R}^N))$ satisfies 
 \[
 \iint_{Q_1} (-v\cdot \varphi_t+\mathcal{B}(y,s, \la \na v) \cdot \na \varphi) \,dy\,ds
=\iint_{Q_1} |G|^{p-2}G\cdot \na \varphi\,dy\,ds
 \]
 for every $\varphi\in C_0^\infty(Q_1 ;\mathbb{R}^N)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:49.835877+00:00","domain":"probability theory","id":"claim_c16544aae39d16379b126029ce1a40cc862503bf2e6c9f07f22558b0af78bfbd","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Global solution) of arXiv:2506.12834, 'Space-time fractional stochastic partial differential equations driven by L\'evy white noi'] \begin{enumerate}
