\end{equation}
The result in \eqref{eq:patchedFullCase1} holds true with $\mathcal{D}_{n^{-1}}$ replaced by $\mathcal{V}_{\delta^{-1}}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.750175+00:00","domain":"probability theory","id":"claim_c19de2d4ffde3d6bf8621e6e6956ae4463ef0ff1ae8a920e850b7c2febfbb8e9","kind":"concept","schema_version":1,"statement":"[Corollary 12 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that Assumption \ref{Assumption} holds,
and let $\ka>0$.
\begin{enumerate}
\item If $\rho>H_0-1$, then
\[\mbf E\big[\msf Q_\ka(t)\big]=o(t^{H_0})
\qquad\text{and}\qquad
\mbf E[\msf Q_\ka(t)^2]^{1/2}\sim\ka\mf c\,t^{H_0}.\]
\item If $\rho=H_0-1$ and $H_0\neq1$, then
\[\mbf E\big[\msf Q_\ka(t)\big]\sim\frac{\ka^2|D|(2H_0-1)}{(H_0-1)2^{H}}\prod_{j=1}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}\,t^{H_0}
\qquad\text{and}\qquad
\sqrt{\mbf{Var}[\msf Q_\ka(t)]}\sim\ka\mf c\,t^{H_0}.\]
\item Otherwise:
\begin{enumerate}
\item If $\rho=H_0-1$ and $H_0=1$, then
\[\lim_{t\to0}\frac{\msf Q_\ka(t)}{t\log(1/t)}=-\frac{\ka^2|D|}{2^{d-1}}\prod_{j=1}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}\qquad\text{in probability.}\] 
\item If $\rho<H_0-1$, then
\[\lim_{t\to0}\frac{\msf Q_\ka(t)}{t^{1+\rho}}
=\frac{\ka^2|D|H_0(2H_0-1)}{2^H(1+\rho)\rho}\prod_{j=1}^d\frac{\Ga(2H_j+1)}{\Ga(H_j)}\qquad\text{in probability.}\]
\end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.325107+00:00","domain":"probability theory","id":"claim_c19eb78c708d0e335b72031ae069a589176f21cfa90dc7f29726aea87461b904","kind":"lemma","schema_version":1,"statement":"[Lem lem-fixed-pos of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] Consider a $d$-type branching process $X = \{X(n)\}_{n\in\mathbbm N_0}$ for which the extinction probability started from any state is one. Let $f$ be the corresponding generating function and let $q \in (0,\infty)^d$ solve $f(q) = q$. Then   
\begin{equation} 
q_k \geq 1, \quad \forall k \in \{1, \dots, d\}  .
\end{equation} 
Moreover, if the branching process is positive regular, then either $q_k = 1$ for every $k\in \{1,\dots,d\}$ or $q_k > 1$ for every $k \in \{1,\dots,d\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.932688+00:00","domain":"probability theory","id":"claim_c1a46413cac200a089d6be980b384e4e0948e780f9fadfe75f7839931aec48f7","kind":"concept","schema_version":1,"statement":"[Thm 34 (Good regularity estimates: $q$ and $Q$ are regularly varying) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] There exist two slowly varying functions $\svfq, \svfbQ$ such that for all $k \geq 1$,
    \begin{equation*}
        q(k)=k^{-\frac{1}{2\alpha}-1} \svfq(k)
        \qquad \text{and}\qquad 
        Q(k)=k^{-\frac{1}{2\alpha}} \svfbQ(k),
    \end{equation*}
    where $\alpha \in \left( 1/2,1 \right)$ is as in \cref{thm:main}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:15.350480+00:00","domain":"probability theory","id":"claim_c1a5726be0f7a5cffa69147f2df03b626670b06d0e0fcc896d21a235ae582508","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Let $\Lambda(dz)$ be a finite measure on $[0,1]$ with density satisfying \emph{(}\ref{eq:density}\emph{)}. Now let $(X(t))_{t \geq 0}$ be a coordinated particle system with a single site, coalescence according to $\Lambda(dz)$, death according to a finite measure $D(dz)$ on $[0,1]$, no reproduction, and an infinite number of particles present at $t = 0$. Then

    \begin{align*}
        \lim_{n \to \infty} P(X(t) = n \text{ for some $t \geq 0$}) = \alpha - 1.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:37:20.358465+00:00","domain":"probability theory","id":"claim_c1a762f19c448471bdbe951c91304233bc4fb335df2dc42961307189d44518b9","kind":"theorem","schema_version":1,"statement":"[Theorem non i.i.d of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(\sigma_n)_{n\ge 1}$ be positive numbers. Let $(g_n)_{n\ge 1}$ be simple graphs where $V(g_n)=[n]$ and consider the weighted graph $(g_n,\sigma^2)$, where $\sigma^2(i)=\sigma_i^2$. Assume that $(g_n,\sigma^2)_n$ converges to a graphon $w$, and that
    \begin{align*}
        &\vert \sigma^2\vert =\sum_{k\in [n]}\sigma_i^2 \to \infty; \quad \frac{\sigma_{\max}^2}{\vert \sigma^2\vert}\to 0.
    \end{align*}
    Let $a_1^{(n)},\ldots,a_n^{(n)} \in \mathcal{A}$ be $g_n$-independent centered random variables with variance $\operatorname{var}(a_k^{(n)})=\sigma_k^2$, for every $n \ge 1$. 
    Assume that there exist constants $C_p\ge 1$ that depends only on $p\ge 1$ such that for any $n,k,p\ge 1$, we have 
    \begin{align*}
       \tau\left(|a_k^{(n)}|^p\right)\le C_p\sigma_k^p.
    \end{align*}
    Then
    \begin{align*}
        S_n=\frac{1}{\sqrt{\vert\sigma^2\vert}}\sum_{k \in [n]} a_k^{(n)}
    \end{align*}
    converges in distribution to $\mu_w$, the law defined in (equation eq: definition of mu_w of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.610406+00:00","domain":"probability theory","id":"claim_c1a7a53b3660eb8cf4403cd4f8d7113039277ab38bb3718c4d4a71a30f9e43b8","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] Assume that $\mu,\nu \in\mathcal{P}_2(\Rd)$ share  the barycentre. Then,
	\begin{align*}
		\Pi_{\succeq_c \mu} (\nu)   = 	\Pi_{\succeq_c \nu} (\mu)  =   \argmin_{ \rho \succeq_c \mu, \  \rho \succeq_c \nu} m_2(\rho).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:23.370657+00:00","domain":"probability theory","id":"claim_c1ab0a9a6308537f8e04e3726f747444f3b84315bc4ee8a85d29a1609cbd0dec","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega$ be a bounded, open set with $C^{1,1}$ boundary and $X=(X_t)_{t\ge 0}$ be a translation invariant isotropic process such that 
		\begin{align*}
			\E_0\left[\left(\overline{X}^{(1)}_T\right)^p\right]<\infty
		\end{align*}
		for some $T>0$ and $p>1$, and 
		\begin{align*}
			\lim_{t\downarrow 0}\frac{\E_0\left[\left(\overline{X}^{(1)}_t\right)^p\right]}{\E_0\left[\overline{X}^{(1)}_t\right]}=0.
		\end{align*}
		Then, 
		\begin{align*}
				\lim_{t\downarrow 0}\frac{\Vol(\Omega)-Q^X_\Omega(t)}{\E_0\left[\overline{X}^{(1)}_t\right]}=\Per(\Omega).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:45:17.709417+00:00","domain":"probability theory","id":"claim_c1b165d9c11640c53e87f3689b8c85d05a9078f2ead2618887f5e7c2f7587e66","kind":"concept","schema_version":1,"statement":"[Proposition prop occup time invar of arXiv:2604.10509, 'Nonequilibrium fluctuations and moderate deviations for the occupation time of the SSEP wi'] Let $\{\mathcal{Y}_t, 0 \leq t \leq T\}$ be the process introduced in Proposition (prop density fluc of the paper). The following statements hold.
\begin{itemize}
