{"assumptions":[],"created_at":"2026-10-26T19:29:52.210539+00:00","domain":"probability theory","id":"claim_c28437707730bf9b132e415fa789f8ae2b53b36937bb4f56b86f5cd771de754a","kind":"lemma","schema_version":1,"statement":"[Lemma 22 (Reduction to simple integrals) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$ and $(a,b) \in \R^2$ such that $b > 0$ and $(a,b) \neq z_0$. Then, for $\e > 0$ small enough, $g^{z_0}(a,b)$ can be written as $g^{z_0}(a,b) = I_1^{z_0}(a,b) + I_2^{z_0}(a,b)$, where
\begin{equation}
I_1^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\phi^{z_0}(x)\frac{\gamma(x, Y^+(x), Z^+(x))}{\partial_y\gamma_+(x, Y^+(x))} e^{-ax - bY^+(x)}
\, dx
\end{equation}

and
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)x} \left(
e^{(b_0 - b)Y^+(x)}\fc_{b_0>0} 
+ e^{b_0Z^+(x) - bY^+(x)}\fc_{b_0 < 0}
\right)}{\partial_y\gamma_+(x, Y^+(x))} \, dx \quad \textnormal{if } b > b_0.
\end{equation}

Furthermore, the following expressions hold for $I_2^{z_0}(a,b)$ if $b_0 > 0$:
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)X^+(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^+(y), y)} \, dy \quad \textnormal{if } a > a_0
\end{equation}
\begin{equation}
I_2^{z_0}(a,b) = \frac{-1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)X^-(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^-(y), y)} \, dy \quad \textnormal{if } a < a_0.
\end{equation}","status":"unverified"}

