         C^{-1}\left(\frac{R}{r}\right)^{\alpha_L} \leq \frac{\nu(B(x,R))}{\nu(B(y,r))} \leq C \left(\frac{R}{r}\right)^{\alpha_U}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.670962+00:00","domain":"probability theory","id":"claim_c41aefef324cf08c52be3009617316357de497f646d9f9a24fa0564b83b5738c","kind":"theorem","schema_version":1,"statement":"[Proposition 35 (Gram symmetrization) of arXiv:2609.03736, '2609.03736'] The pair $(K^\perp, L^\perp)$ is normalized and satisfies
