0,T_{d}^{n}(x_{d})]}(\prod_{i=1}^{d}u_{i})\,dL_{n}(u_{1},\dots ,u_{d}),

\end{equation}
for $(x_{1},\dots ,x_{d})\in \lbrack 0,1]^{d}$, with initial condition $
L_{0} $ obtained from $F$ by \textit{Definition~(d-centering of the paper)}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.526121+00:00","domain":"probability theory","id":"claim_c45e7c748f9e06289dff534ad956b947c1e01679e5b1f3d7fc796423d47b8a95","kind":"concept","schema_version":1,"statement":"[Corollary of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose that $\{X_k\}_{k\geq 1}$ is a d-dimensional $\alpha$-mixing stationary sequence on a regular sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ for some $\alpha>0$ with $\hat{\mathbb{E}}[|X_1|^{2}]<\infty$. If $X_1$ has no mean-uncertainty, then 
