        \node[world] (b0) at (4, 0) {$b_0$};

        \node[world] (c1) at (2,-2) {$c_1$};
        \node[world] (b1) at (2, 0) {$b_1$};

        \node[world] (c2) at (0,-2) {$c_2$};
        \node[world] (b2) at (0, 0) {$b_2$};

        \node        (c3) at (-2,-2) {$\cdots$};
        \node        (b3) at (-2, 0) {$\cdots$};

        \draw[->] (b0) -- (a) node[midway,above] {$\R$};

