\end{equation}
whenever $\displaystyle \varepsilon>\sqrt{\frac{2C}{|\Lambda|}\,\log\frac{1}{\nu(E)}}$\,. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.572218+00:00","domain":"probability theory","id":"claim_c724f6f7b6ab2c7632e29de385cf4652f875f435e0ec8d8684e07e3b9a6b5c06","kind":"concept","schema_version":1,"statement":"[Theorem thm:smoothness.estimates.wishart of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Let $m\in \mathbb{N}$, let $\alpha > 3d-3$ and $\Sigma\in \mathcal{S}_{++}^d$. Let $h\in C_b^{md}(\mathcal{S}_{++}^d)$ be real-valued, and let $f_h$ denote the semigroup solution of the Wishart Stein equation defined in (equation eq:fh.def.Wishart.beta of the paper). Then the following hold:
\begin{itemize}
\item[(i)] If $h\in \mathcal{B}^{\mathcal{D}, \Sigma}_{m}(\mathcal{S}_{++}^d)$, then for any index pairs $(i_1,j_1), \ldots,(i_m,j_m)\in [d]^2$,
\begin{equation}
\left\|\left(\prod_{\ell=1}^m \nabla_{\!W, i_{\ell} j_{\ell}}\right) f_h\right\|_{\infty}
\leq \frac{1}{2m} \sup_{t > 0} \left\|\left(\prod_{\ell=1}^m (\mathcal{D}_{t, \Sigma})_{i_{\ell} j_{\ell}}\right) h\right\|_{\infty}.
\end{equation}

\item[(ii)] For any sufficiently smooth $g:\mathcal{S}_{++}^d\to\mathbb{R}$, define
\begin{equation}
\mathcal{M}_m(g)
 \vcentcolon= \sup_{W\in \mathcal{S}_{++}^d} \, \sup_{\substack{U_1, \ldots,U_m\in \mathcal{S}^d\\ \|U_1\|_F = \cdots = \|U_m\|_F = 1}} \big|D^m g(W)[U_1, \ldots,U_m]\big|.
\end{equation}
Define also
\begin{equation}
\mathcal{M}_m^{\mathcal{D}, \Sigma}(h)
 \vcentcolon= \sup_{t > 0} \, \sup_{W\in \mathcal{S}_{++}^d} \, \sup_{\substack{U_1, \ldots,U_m\in \mathcal{S}^d\\ \|U_1\|_F = \cdots = \|U_m\|_F = 1}}
\left|\Big(\prod_{\ell=1}^m \langle U_{\ell}, \mathcal{D}_{t, \Sigma}\rangle_F\Big) h(W)\right|,
\end{equation}
where
\[
\langle U, \mathcal{D}_{t, \Sigma}\rangle_F \vcentcolon= \sum_{i,j = 1}^d U_{ij} \, (\mathcal{D}_{t, \Sigma})_{ij}.
\]
If $\mathcal{M}_m^{\mathcal{D}, \Sigma}(h) < \infty$, then
\begin{equation}
\mathcal{M}_m(f_h) \leq \frac{1}{2m} \, \mathcal{M}_m^{\mathcal{D}, \Sigma}(h).
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

