{"assumptions":[],"created_at":"2026-10-27T15:32:35.563861+00:00","domain":"probability theory","id":"claim_c7fd1510558a86973b5eadde368982690ca24f29f0415cb0ac80584fc29fec84","kind":"lemma","schema_version":1,"statement":"[Lemma lem.clock-negnorm of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $s\in(0,1/2]\cap(0,d/2)$ and $\varepsilon>0$. There exists $C_\varepsilon=C_\varepsilon(d,\Lambda,s,\varepsilon,r_0)<\infty$ such that, for every integer $N\ge0$,
		\begin{equation}
			\mathbb{Q}\Bigl(\text{there is an integer }M\ge N\text{ with }\|e^{-2V}-\mathbb{E}[e^{-2V(0)}]\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-s}(\square_M)}>3^{\varepsilon M}\Bigr)\le C_\varepsilon 3^{-2\varepsilon N}\, .
		\end{equation}
		Moreover, for $\mathbb{Q}$-a.e.\ $\omega$, the bound $\|e^{-2V}-\mathbb{E}[e^{-2V(0)}]\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-s}(\square_M)}\le 3^{\varepsilon M}$ holds for all sufficiently large integers $M$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.829695+00:00","domain":"probability theory","id":"claim_c7fd8cccfcea648bb472500c456e1be920b625b2e3b4d868cbff2037848a273b","kind":"theorem","schema_version":1,"statement":"[Theorem thm:affine-pgf of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] For the unaugmented scalar counting path $N$, the Marcus signature collapses to
\begin{equation}
\mathrm{Sig}^M(N)_{0,T}=\exp_{\otimes}(N_T e_1).
\end{equation}
Consequently, its expected signature is determined by the moment generating function
\begin{equation}
M(T,\theta)=\mathbb{E}[e^{\theta N_T}].
\end{equation}
For the exponential Hawkes model, $M$ has the affine representation
\begin{equation}
M(T,\theta)=\exp\{A(T,\theta)+B(T,\theta)\ell\},
\end{equation}
where
\begin{equation}
\frac{\partial B}{\partial T}= -\beta B+e^{\theta+\alpha B}-1,
\qquad
\frac{\partial A}{\partial T}=\beta\mu B,
\qquad
A(0,\theta)=B(0,\theta)=0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.368459+00:00","domain":"probability theory","id":"claim_c7fdd3b9b866d5a0278ff065ba14c664c0764b62aa48a5f3abe873dc14064603","kind":"concept","schema_version":1,"statement":"[Lemma of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $p \geq 2$, $\tilde{\gamma}_\bullet, \tilde{\gamma}_\circ  >1/p$, and $\gamma_\bullet< \tilde{\gamma}_\bullet-1/p $, $\gamma_\circ< \tilde{\gamma}_\circ-1/p$. Let ${\color{purp}G}= (G^\bullet, G^\circ,\mathbb{G}^{\bullet \bullet}, \mathbb{G}^{\circ \bullet}, \mathbb{G}^{\bullet \circ} )$,  $\purp{\bar{G}}= (\bar{G}^\bullet, \bar{G}^\circ,\bar{\mathbb{G}}^{\bullet \bullet}, \bar{\mathbb{G}}^{\circ \bullet}, \bar{\mathbb{G}}^{\bullet \circ} )$ random variables with values in $\mathcal{R}^{\gamma_\bullet, \gamma_\circ}$. Assume further that there exist 
   constants   $K_{ij}$, $i,j \in \{ \bullet, \circ\}$, such that for all $(s,t)$
    \begin{equs}
        \| G^i_{s,t}-\bar{G}^i_{s,t}\|_{L_p}\leq  K_i |t-s|^{\tilde{\gamma}_i}, \qquad   
        \| \mathbb{G}^{i j }_{s,t}-  \bar{\mathbb{G}}^{i j}_{s,t}\|_{L_{p/2}}\leq  K_{ij} |t-s|^{\tilde{\gamma}_i+\tilde{\gamma}_j}
    \end{equs}
    for $i,j \in \{ \bullet, \circ\}$ with $(i,j) \neq (\circ, \circ)$. Then, there exists a constant $C=C(\gamma_\bullet, \tilde{\gamma}_\bullet, \gamma_\circ, \tilde{\gamma}_\circ, p)$, such that 
    \begin{equs}
        \| [G^i-\bar{G}^i]_{\mathcal{C}^{\gamma_i}} \|_{L_p} \leq N K_i, \qquad \| [\mathbb{G}^{ij}-\bar{\mathbb{G}}^{ij}]_{\mathcal{C}^{\gamma_i+\gamma_j}_2} \|_{L_p/2} \leq  N ( K_{ij}+K_iK_j). 
    \end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.608981+00:00","domain":"probability theory","id":"claim_c8018b3f954b0899149a91293dd172a84524c60c183acc9fef20be0abcc455c6","kind":"concept","schema_version":1,"statement":"[Proposition prop:W_n_var of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have 
\begin{equation}
    \mathbb{E} [W_k^2] = \frac{\Gamma(k + 2q)}{ \Gamma(k)} \sum_{l = 1}^{k} \frac{\Gamma(l)}{\Gamma(l + 2q)} \\
    = H(k, q),
\end{equation}
where 
\begin{equation}
    H(k, q) := \begin{cases}
            \frac{k}{(2q - 1)}\big(\frac{\Gamma(k + 2q)}{\Gamma(k + 1) \Gamma(2q)}-1\big) & \text{if } q \ne 1/2, \\[0.5em]
            k \sum_{j = 1}^{k} \frac{1}{j} & \text{if } q = 1/2.
        \end{cases}
\end{equation}
Consequently, for any $p \in [0, 1)$, there is a constant $C_p > 0$, such that for all $n \ge 1$,
\begin{equation}
    \mathbb{E} W_n^2 \le C_p n^2 r_n^{-2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:19:00.931688+00:00","domain":"probability theory","id":"claim_c801b9023717d422fc69a010b236488b0f84914028c0126f24987bf991360ed7","kind":"concept","schema_version":1,"statement":"[Proposition 14 (Persistent supercritical misalignment) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Suppose that $0<\beta_1<1$ and $w_{\max}>2$.  For every $v_0>0$ satisfying
$w_0=c\eta/(\sqrt{v_0}+\varepsilon)>2$, there exist $x_0\ne0$ and
$m_0\in\R$ such that
\begin{equation}
    x_t(m_t+cx_t)<0
    \qquad\text{for every }t\ge0.

\end{equation}
Along this trajectory,
\begin{equation}
    w_t\ge w_0,
    \qquad
    \abs{x_t}\le(w_0-1)^{-t}\abs{x_0},
    \qquad t\ge0.

\end{equation}
In particular, $(x_t,m_t,v_t)\to(0,0,0)$ and $w_t\to w_{\max}$,
although the trajectory remains uniformly supercritical for all time. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.290621+00:00","domain":"probability theory","id":"claim_c8028e6d82f4de4a295cb5e8813c8815181ea59751216a8a971a22d5c2a1b2d0","kind":"lemma","schema_version":1,"statement":"[Lemma 26 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $q\in\N$, and let $F:\ccC_T^d\to \R^q$
    be a continuous non-anticipative functional. Assume that there exists a constant
    $C>0$ such that
    \begin{equation*}
        \|F(t,x)\|
        \leq C \biggl(1+\sup_{s\in[0,t]}\|x(s)\|\biggr), \quad (t,x)\in\ccC_T^d .
    \end{equation*}
    Then there exist continuous non-anticipative functionals
    \begin{equation*}
        F^n:\ccC_T^d\to\R^q,\quad n\in\N,
    \end{equation*}
    such that the following properties hold.

    \begin{enumerate}
        \item $F^n\to F$ locally uniformly on $\ccC_T^d$.

        \item For each $n\in\N$, $F^n$ is Lipschitz continuous with respect
              to the metric $d_{\ccC_T}$.

        \item There exists a constant $C'>0$, independent of $n$, such that
              \begin{equation*}
                  \|F^n(t,x)\|
                  \leq C'\biggl(1+\sup_{s\in[0,t]}\|x(s)\|\biggr),
                  \quad (t,x)\in\ccC_T^d,\ n\in\N .
              \end{equation*}
    \end{enumerate}

    In particular, for each $n\in\N$ and each fixed $t\in[0,T]$, there
    exists a constant $L_n>0$ such that
    \begin{equation*}
        \|F^n(t,x)-F^n(t,y)\|
        \leq L_n \sup_{s\in[0,t]}\|x(s)-y(s)\|,
        \quad x,y\in C([0,t],\R^d).
    \end{equation*}","status":"unverified"}

