{"assumptions":[],"created_at":"2026-10-27T22:46:36.161313+00:00","domain":"probability theory","id":"claim_c8981b3b06e082983b3c9b86ace16d1569a4eb31b43ca89cf97670cfdba63aaa","kind":"theorem","schema_version":1,"statement":"[Prop Prop_SliceDerivativeOfUniversalDiracOperator of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir}\times\mathbf{Ram}$ the following hold:
  \begin{enumerate}
  \item

    For every $\dot{\mathbf{p}}_\mathrm{BG} = (\dot g;\dot \gamma^\mathrm{BG},\dot\nabla^\mathrm{BG};0) \in H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathrm{BG}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      - \frac12 \sum_{i,j=1}^d \dot g(e_i,e_j) \gamma(e_i)\nabla_{e_j} \phi
      + \frac14\gamma\paren[\big]{(\nabla^*\dot g)^\sharp + \nabla(\tr_g\dot g)}\phi.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\mathscr{G} = (0;[\xi,\gamma],-\nabla\xi;0) \in V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathscr{G}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \paren[\big]{
        [\xi,\gamma(e_i)] \nabla_{e_i} \phi
        - \gamma(e_i) (\nabla_{e_i}\xi) \phi
      }.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\nabla = (0;0,\dot\nabla;0) \in V_{\nabla;{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\nabla}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \gamma(e_i) \dot\nabla_{e_i}\phi.
    \end{equation*}    
  \end{enumerate}
  Moreover, $\nabla^\mathbf{Sl} \mathbf{res} = 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.700266+00:00","domain":"probability theory","id":"claim_c89ab4d26ee084f1240528ceb3ac636e6b5d020670e32950654ee8727ceea66d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:volume-cancel-transitive of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Suppose $G$ is a transitive graph with a transitive cycle basis that
