{"assumptions":[],"created_at":"2026-10-28T02:16:53.569092+00:00","domain":"probability theory","id":"claim_ca0a7483cd6b3ae37c2c993cf67e45288021aa9f82415847e5abe6b0bd304ee6","kind":"theorem","schema_version":1,"statement":"[Theorem thm:cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $(\lambda^k)_{k \in \mathbb{N}^*}$ be a sequence of measurable processes, satisfying $c \leq \lambda^k \leq C$ $(\mathbb{P} \otimes dt)$-a.e., $\forall\, k \in \mathbb{N}^*$, for some constants $0 < c < C$. Suppose that $\Omega$ supports a sequence of i.i.d.\ $\operatorname{Exp}(1)$ random variables $(E_k)_{k \in \mathbb{N}^*}$ and a sequence of i.i.d.\ non-vanishing integrable random variables $(J_k)_{k \in \mathbb{N}^*}$ such that $\mathcal{F}_\infty$, $(E_k)_{k \in \mathbb{N}^*}$ and $(J_k)_{k \in \mathbb{N}^*}$ are independent. Let $\tau_0 \coloneqq 0$. For $k \in \mathbb{N}^*$, inductively define the random time
	\begin{equation*}
		\tau_k \coloneqq \inf\biggl\{t > \tau_{k-1}: \int_{\tau_{k-1}}^t \lambda^k_s \,ds \geq E_k\biggr\},
	\end{equation*}
	and define the filtration $\mathbb{A}^k = (\mathcal{A}^k_t)_{t \geq 0}$ by $\mathcal{A}^k_t \coloneqq \sigma(J_k \bm{1}_{\{\tau_k \leq s\}}; s \leq t)$. Let $\mathbb{G}^0 \coloneqq \mathbb{F}$, $\mathbb{G}^k \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^k \mathbb{A}^i)$ for $k \in \mathbb{N}^*$ and $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^\infty \mathbb{A}^i)$. Suppose that each $\lambda^k$ is progressively measurable with respect to $\mathbb{G}^{k-1}$. Then, the pure jump process $X_t \coloneqq \sum_{k=1}^\infty J_k \bm{1}_{\{\tau_k \leq t\}}$, $t \geq 0$, is well-defined and the process
	\begin{equation*}
		M_t \coloneqq X_t - \mathbb{E}[J_1] \int_0^t \sum_{k=1}^\infty \bm{1}_{\{\tau_{k-1} < s \leq \tau_k\}} \lambda^k_s \,ds,\quad t \geq 0,
	\end{equation*}
	is a $\mathbb{G}$-martingale.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:55:57.002451+00:00","domain":"probability theory","id":"claim_ca0d8c1e1dfe1d3fbb824213bb406de2f63b6b4264978da3f6411afac77e5787","kind":"lemma","schema_version":1,"statement":"[Lemma 7 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let \( G_n = \operatorname{diag}(\sigma_1, \dots, \sigma_n) =\begin{pmatrix}
G_k & 0 \\
0 & \widetilde{G_k}
\end{pmatrix}\), where \( \sigma_i  \) is decreasing. Let $A \in \R ^{m\times n}$, $A_{ij}\stackrel{i.i.d}{\sim} \mathcal{N}(0,1)$. Then the following expectation identities hold:
\begin{align}
   \mathrm  E_A \left\| G_k P_{M_k^T} - G_k \right\|_F^2 + \| \widetilde{G_k }\|_F^2 =  \big\| G_n\big\|_F^2- \mathrm E_{A_k}\big\langle G_k^2,P_{M_k^T} \big\rangle.

\end{align}
\begin{align}
 \mathrm  E_{A} \left\| G_k (M_k)^\dagger M_k \right\|_F^2 =\mathrm E_{A_k} \left\| G_k (M_k)^\dagger \right\|_F^2 \sum_{i=k+1}^{n} \sigma_i^2.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:52:08.658883+00:00","domain":"probability theory","id":"claim_ca124849c0a5fc42dc44a9c2e30615573002fb5fe5c4e1d929ba41f354ae2212","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] For $1\leq p\leq\infty, k \geq 0$,
\begin{equation}
\begin{split}
&\|\nabla^{k}(S_{0}u)\|_{L^{p}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{p}(\R^{d})} \sim 2^{kj}\|\Delta_{j}u\|_{L^{p}(\R^{d})}.
\end{split}
\end{equation}
For $1<p<q<\infty, k\geq 0$,
\begin{equation}
\begin{split}
&\|\nabla^{k}(S_{0}u)\|_{L^{\infty}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(S_{0}u)\|_{L^{q,1}(\R^{d})}\lesssim \|S_{0}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{\infty}(\R^{d})}\lesssim 2^{(k+\frac{d}{p})j}\|\Delta_{j}u\|_{L^{p,\infty}(\R^{d})},\\
&\|\nabla^{k}(\Delta_{j}u)\|_{L^{q,1}(\R^{d})}\lesssim 2^{(k+\frac{d}{p}-\frac{d}{q})j}\|\Delta_{j}u\|_{L^{p,\infty}(\R^{d})}.
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.548013+00:00","domain":"probability theory","id":"claim_ca16ce355ca217fa0f6a90e85b08d4fcde329403bc4b4ed6ef6ba5d11c22c373","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\emprashomonset$, $\rretailset$, and $x$ satisfy Assumption \ref{assume:rashomon} for parameters $\sigma, \rashlexpctparam > 0$. Let $\rlocaltestmat =  \{\rlocaltest_{j}: j \in [\nogaussianpts]\}$ be a random set of perturbations of $x$, distributed $\iid \Unif(\ltwohsphere(x,\sigma))$, and $\ensmretset(\retailset,\localtestmat)$ be the ensemble model defined in \ref{def: local ensemble}.
Define
\begin{align}
   \lallavg(x) = \abs*{\ensmretset(\rretailset,\rlocaltestmat) - \frac{1}{2}}.
\end{align}
Then for any $\slackgap > 0$, 
    \begin{align}
    \prob_{\rretailset,\rlocaltestmat}*{
        \abs*{  \lallavg(x) - \explallavg(x)}
    \ge \slackgap }
