{"assumptions":[],"created_at":"2026-10-27T06:25:55.385237+00:00","domain":"probability theory","id":"claim_ca3595103bf6433c1e22250e70e0691d13f13eb6b71294a42bb0a318ccf1248e","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Consider functions $b:I \to \R$ measurable, and $\sigma:I \to (0,\infty)$ satisfying the assumptions of Lemma~\ref{lem:ODE_nu}. Further, suppose that the function $\zeta$ of \eqref{eq:zeta_halfline} is bounded on $I$. Then, \begin{enumerate}[label = (\roman*),noitemsep]
        \item  the unique global solution $(f,\nu)$, with $f:I \to I$ belonging to  $W^{2,1}(I)$ and $\nu \in (0,\infty)$, to the equation \eqref{eq:nonlinear_ODE_nu}, is given by
        \begin{equation} 
           f(y) = g^{-1}\bigg(\frac{y}{\nu}\bigg) \quad \text{for } y \in I, \qquad   \nu = \bigg(\int_0^1 \frac{1}{\sigma(u)}du\bigg)^{-1},
        \end{equation}
         where $g$ is the function in \eqref{eq:g};

        \item  the SDE \eqref{eq:X_SDE_nu},
        with $\nu$ given by \eqref{eq:nu}, with  
        \begin{equation} 
          \alpha(x) = \nu\sign\big(x-\Even(x)\big)\,\zeta\Big(f\big(|x-\Even(x)|\big)\Big),  \qquad \text{for a.e.~}  x \in \R,
        \end{equation}
        and with $\zeta$ as in \eqref{eq:zeta_halfline},
        has a pathwise unique, strong solution for every initial value $X_0 \in \R$;
        \item the process $Y = f(|X-\Even(X)|)$ satisfies the RSDE \eqref{eq:RSDE} with initial condition $Y_0 = f(|X_0-\Even(X_0)|)$, finite variation process
        \begin{equation}  \Phi = \frac{1}{\nu}\sum_{n \in \Z}\big(\sigma(0)L^{2n}(X) - \sigma(1)L^{2n+1}(X)\big),
        \end{equation} and Brownian Motion $W = \int_0^\cdot \mathrm{sign}(X_t-\Even(X_t))dB_t$. 
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.983042+00:00","domain":"probability theory","id":"claim_ca3663962838cbd3b859bd2b43ffc6b90ceea72038a6e85d69212658e985fd59","kind":"concept","schema_version":1,"statement":"[Theorem 37 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose $\mu$ satisfies Assumption \ref{as:mu_tail} for some $\alpha > 0$.  There exists a constant $C = C(\mu) >0$ such that for any $\delta > 0$, if $\beta \leq C (n/\log n)^{1/\alpha}$ and $n$ is sufficiently large, then 
