{"assumptions":[],"created_at":"2026-10-28T02:04:40.964677+00:00","domain":"probability theory","id":"claim_ca3b9bab0cbe0017d290057d862b3e899c111f43c8db86d35f70745dd159bb64","kind":"concept","schema_version":1,"statement":"[Lemma L:Gronwall of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $g(\cdot)$ be a nonnegative and monotone function on $[0,\infty)$ that
  decreases to $0$ as $t\to\infty$, and such that $g(0)<\infty$. Let $k(\cdot)$
  be a nonnegative and integrable function on $[0,\infty)$ and define
  \begin{align}
    h(t) \coloneqq \int_t^{\infty} k (s) \ensuremath{\mathrm{d}} s.
  \end{align}
  Then, we have:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_0^t g \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le g(0) h \left(\frac{t}{2^{n + 1}}\right) + h(0) g \left(\frac{t}{2^{n + 1}}\right).
      \end{align}
      In particular, when $g = h$ as defined in (equation E:def-gnr-H of the paper), the above
      inequality~(equation E:g*h of the paper) reduces to
      \begin{align}
        \int_0^t h \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le 2 h(0) h \left(\frac{t}{2^{n + 1}}\right).
      \end{align}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_{[0, t]^{n}_<}
            & \ensuremath{\mathrm{d}} u_n \cdots \ensuremath{\mathrm{d}} u_1\:  g \left(t - u_n \right) \prod_{i = 1}^n k(u_{i} - u_{i - 1} ) \nonumber \\
        \le & \left( 2^{n} - 1\right) g(0) h(0)^{n-1} h \left(\frac{t}{2^{n}}\right) + h(0)^n g \left(\frac{t}{2^{n}}\right),
      \end{align}
      where $[0, t]_<^{n} \coloneqq \left\{(s_1,\dots, s_n) \in [0,t]^n; 0 <
      s_1< \dots < s_n <t\right\}$ and we have used the convention that $u_0
      \equiv 0$.

    \item Let $f$ be a function on $[0,\infty)$ such that
      \begin{align*}
        f(t) \le g(t) + \beta \int_{0}^t f(t - s) k(s) \ensuremath{\mathrm{d}} s, \quad \text{for all $t\ge 0$ with $\beta>0$}.
      \end{align*}
      Then, whenever $\beta < [2 h(0)]^{-1}$, the following convergence is true,
      \begin{align}
        \lim_{t\to \infty} f(t) = 0.
      \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.435203+00:00","domain":"probability theory","id":"claim_ca3d84a84424f80510f29aaab60cee746b7fb80fa6b3bccf3792c3b9abe9a1f9","kind":"definition","schema_version":1,"statement":"[Definition Integer-valued height function on a shift-invariant graph of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given a two-dimensional shift-invariant graph $G = (W, E)$ embedded in $\ensuremath{\mathbb{R}}^2$ and an integer $L \in \ensuremath{\mathbb{N}}$, we consider the space of functions 
	$$\Omega_{L,W} := \left\{ \varphi : W \to \ensuremath{\mathbb{Z}} \, : \, \varphi(x) = 0 ~\mbox{for}~ x \notin [-L , L]^2 \right\}.$$ 
	Given an inverse temperature $\beta \geq 0$, we define the integer-valued height function with potential $V$ to be the probability distribution on the set $\Omega_{L,W}^\ensuremath{\mathbb{Z}}$ given by the identity
\begin{equation*}
    \mu_{L , G , \beta}^{\ensuremath{\mathbb{Z}}-V} (\left\{ \varphi \right\}) := \frac{1}{Z_{L , G,\beta}^{\ensuremath{\mathbb{Z}}-V}} \exp \left( - \sum_{xy \in E}  V \left( \frac{ \varphi(x) - \varphi(y)}{\sqrt{\beta}} \right)\right).
\end{equation*}
We denote by $ \mathrm{Var}_{L , G , \beta}^{\ensuremath{\mathbb{Z}}-V}$ the variance with respect to the measure $\mu_{L , G , \beta}^{\ensuremath{\mathbb{Z}}-V}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.698312+00:00","domain":"probability theory","id":"claim_ca3f98da7ee339e8132b29ca792e01f7b34518aea3138d73f3b5db806a0749d5","kind":"definition","schema_version":1,"statement":"[Definition defn:PHlamzeta of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] The state space is $\Omega_H = 2^{V(H)}$. For any $y \in \Omega$, we set
\[P_{H,\lambda,\zeta} y = P^u_{H,\lambda,\zeta} y\] 
where $u \in V(H)$ is chosen uniformly at random, and
\[
P_{H,\lambda,\zeta}^u y = \begin{cases}
y \cup \{u\} &\text{w.p. $\frac{\lambda (1 - \zeta)^{d(v)}}{1 + \lambda (1 - \zeta)^{d(v)}}$, and}\\
y \setminus \{u\} &\text{w.p. $\frac{1}{1 + \lambda (1 - \zeta)^{d(v)}}$}
\end{cases}
\]
where $d(v)=d_y(v)$ denotes the degree of $v$ in the subgraph of $H$ induced by $y\cup \{v\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:52:51.770225+00:00","domain":"probability theory","id":"claim_ca474e81d459a74d4eefba15bad439c6f05f6e054df81dd992ea07577c8a3e1f","kind":"concept","schema_version":1,"statement":"[Cor probability of exploration processes of arXiv:2605.03151, 'Giants through Higher-Order paths in Random Simplicial Complexes'] Let $X_n \sim \MRSC_d(n; \bm{p})$ with the assumptions ((eq: 1.3.1 assumption 1 of the paper)) and ((eq: 1.3.2 assumption 2 of the paper)). Then, conditional on $\mathcal{X}_{k-1}$, the number of new forward $(d-1)$-simplices at each step $k$, denoted by $F_k$, satisfies
\[  \tag{3.2.27}
F_k \geq_{\mathrm{st}} d \mathsf{Bin} \left( n - s_0(\mathcal{X}_{k-1}), p_k^F \right),
\]
and the number of new backward $(d-1)$-simplices at each step $k$, denoted by $B_k$, satisfies
\[  \tag{3.2.28}
B_k \geq_{\mathrm{st}} d \mathsf{Bin} \left( s_0(\mathcal{X}_{k-1}) - C \sum_{\ell = 1}^{d-1} \max_{\rho \in S_{\ell -1}(\mathcal{X}_{k-1}} \deg_{\ell -1, d-1}^{\mathcal{X}_{k-1}}(\rho), p_k^B \right),
\]
where the constant $C > 0$ only depends on $d$. Furthermore, conditional on $\mathcal{X}_{k-1}$, $F_k$ and $B_k$ are independent, and it holds that
\[  \tag{3.2.29}
F_k + B_k \geq_{\mathrm{st}} d  \mathsf{Bin} \left( n - C \sum_{\ell = 1}^{d-1} \max_{\rho \in S_{\ell - 1}(\mathcal{X}_{k-1})} \deg_{\ell - 1, d-1}^{\mathcal{X}_{k-1}}(\rho), \min\{p_k^F, p_k^B\} \right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.570022+00:00","domain":"probability theory","id":"claim_ca4e431c25dcccd57777575e8958a6dce8521748d10748cd8f4ec906e6ad5fd5","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and \ref{ass:rand_ent}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then, for any sufficiently small $\tau>0$, uniformly for $z=E+\ii\eta\in\mb D_*^{\eps_*}(\tau)$,
        \begin{align}
                G(z)-\Pi(z) = O_{\prec}\left(\sqrt{\frac{\Im m(z)}{N\eta}}+\frac1{N\eta}\right). 
        \end{align}
        Moreover, for every deterministic matrix $B\in\C^{L\times L}$ with $\|B\|\leq1$,
        \begin{align}
