{"assumptions":[],"created_at":"2026-10-27T13:47:12.028089+00:00","domain":"probability theory","id":"claim_cb32788f21d02b4d05bd7f5402fa3339d0f82c5b18098d8d56faf0fdd41f30c9","kind":"concept","schema_version":1,"statement":"[Lemma lem:5 of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] {GM20}}]

