{"assumptions":[],"created_at":"2026-10-27T12:43:43.438913+00:00","domain":"probability theory","id":"claim_cb48a8ff689cd9ceef3ce842284889d141eeff2b021f030e7f2c5912e4e3004f","kind":"definition","schema_version":1,"statement":"[Definition def:BSF of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] The term \emph{scale function} refers to any function $\Psi : X \times (0,\infty) \to (0,\infty)$ which satisfies the following doubling type property for some $\beta_U,\beta_L > 0$.
    There is $C \geq 1$ such that for all $x,y \in X$ and $0 < r \leq R < \infty$ such that $B(y,r) \cap B(x,R) \neq \emptyset$,
    \begin{equation}
        C^{-1}\left(\frac{R}{r}\right)^{\beta_L} \leq \frac{\Psi(x,R)}{\Psi(y,r)} \leq C\left(\frac{R}{r}\right)^{\beta_U}.
    \end{equation}
    We refer to $\beta_L$ and $\beta_U$ as \emph{lower} and \emph{upper exponents} of $\Psi$, respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:23:58.622682+00:00","domain":"probability theory","id":"claim_cb48d6716e4000de3e9e34894ad7c55f5a3493632c639cc5f4b6a1c487d106fa","kind":"lemma","schema_version":1,"statement":"[Lemma 191 (Sharp decomposition of  $\rm{d} \tander^N \vortrenormalized$ and $\rm{d} \tander^N \GradEnt$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] For a $\Sigma_t$-tangent vectorfield $\SigmatTan$, let $(\mathrm{d} \SigmatTan_\flat)_{\alpha\beta} = \partial_\alpha \SigmatTan_\beta - \partial_\beta \SigmatTan_\alpha$ denote its spacetime exterior derivative. Let $\upepsilon_{\alpha\beta\gamma\delta}$ denote the fully anti-symmetric spacetime tensor normalized by $\upepsilon_{0123} = 1$. Then, the following identities hold:
	\begin{subequations}
		\begin{align}
			\begin{split} 
				(\rmd[(\tander^N \vortrenormalized)_\flat])_{\alpha\beta} & \eqdef \p_\alpha (\tander^N \vortrenormalized)_\beta  -\p_\beta(\tander^N\vortrenormalized)_\alpha \\
				& = 2 (\partial_\beta \ln \Speed)(\tander^N \vortrenormalized)_\alpha - 2 (\partial_\alpha \ln \Speed)(\tander^N \vortrenormalized)_\beta  - \Transport_\alpha (\tander^N \vortrenormalized)_a \p_\beta v^a + \Transport_\beta (\tander^N \vortrenormalized)_a \p_\alpha v^a \\
				& \ \  - \Transport_\alpha ( \vortrenormalized)_a \p_\beta \tander^N v^a + \Transport_\beta ( \vortrenormalized)_a \p_\alpha \tander^N v^a + \Speed^{-2} \exp(\LogDensity) \upepsilon_{\alpha\beta\gamma\delta} \Transport^\gamma \tander^N \VortVort^\delta \\ 
				& \ \ + \Speed^{-4} \exp(-2\LogDensity) \frac{p_{;\Ent}}{\overline{\varrho}} \upepsilon_{\alpha\beta\gamma\delta} \left\{ -(\Transport \tander^N v^\gamma)\GradEnt^\delta + \Transport^\gamma \GradEnt^\delta (\p_a \tander^N v^a) - \Transport^\gamma S^a\p_a \tander^N v^\delta\right\} \\
				& \ \ + \frac{1}{\upmu} \left\{ \updelta_\alpha^0 \gfour_{\beta d} - \updelta_\beta^0 \gfour_{\alpha d}\right\}\, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^d  + \frac{1}{\upmu} \Speed^{-2} \upepsilon_{\alpha\beta\gamma d} \Transport^\gamma \,^{(\tander^N)}\ehcurrent_{(\vortrenormalized;2)}^d,
			\end{split} \\
			\begin{split} 
				(\rmd[(\tander^N \GradEnt)_\flat])_{\alpha\beta} & \eqdef \p_\alpha (\tander^N \GradEnt)_\beta  -\p_\beta(\tander^N\GradEnt)_\alpha \\			
				& =  2 (\partial_\beta \ln \Speed)(\tander^N \GradEnt)_\alpha - 2 (\partial_\alpha \ln \Speed)(\tander^N \vortrenormalized)_\beta  - \Transport_\alpha (\tander^N \GradEnt)_a \p_\beta v^a + \Transport_\beta (\tander^N \GradEnt)_a \p_\alpha v^a \\
				& \ \  + \Transport_\alpha ( \GradEnt)_a \p_\beta \tander^N v^a - \Transport_\beta ( \GradEnt)_a \p_\alpha \tander^N v^a \\
				& \ \ + \frac{1}{\upmu} \left\{ \updelta_\alpha^0 \gfour_{\beta d} - \updelta_\beta^0 \gfour_{\alpha d}\right\}\, ^{(\tander^N)}\ehcurrent_{(\GradEnt;1)}^d  + \frac{1}{\upmu} \Speed^{-2} \upepsilon_{\alpha\beta\gamma d} \Transport^\gamma \, ^{(\tander^N)}\ehcurrent_{(\GradEnt;2)}^d, 
			\end{split} 				
		\end{align}
	\end{subequations}
where:  
	\begin{subequations}
		\begin{align}
			\begin{split} 
				^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^d & = [\upmu\Transport,\tander^N] \vortrenormalized^d - \vortrenormalized^a[\upmu \p_d,\tander^N]v^a + \sum_{\substack{ \tander^{N_1}\tander^{N_2} = \tander^N \\ N_2 \le N - 1}} (\tander^{N_1} \vortrenormalized^a) \tander^{N_2} (\upmu \p_d v^a) \\
				& \ \ - \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \upepsilon_{dab} \left([ \upmu \Transport,\tander^N]v^a\right) \GradEnt^b \\
				& \ \ + \sum_{\substack{ \tander^{N_1}\tander^{N_2}\tander^{N_3} = \tander^N \\ N_2 \le N - 1}} \upepsilon_{dab} \left(\tander^{N_1} \left\{ \exp(-2\LogDensity)\Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \right\}\right)\left( \tander^{N_2} (\upmu \Transport v^a) \right) \tander^{N_3} \GradEnt^b, 
			\end{split} \\
			\begin{split} 
				^{(\tander^N)}\ehcurrent_{(\vortrenormalized;2)}^d & = \upepsilon_{dab}[\upmu \p_a,\tander^N]\vortrenormalized^b +  \sum_{\substack{ \tander^{N_1}\tander^{N_2}\tander^{N_3} = \tander^N \\ N_3 \le N - 1}} \left( \tander^{N_1} \upmu\right) \left(\tander^{N_2}\exp(\LogDensity)\right) \tander^{N_3} \VortVort \\
				&  \ \ - \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \left( [\upmu\p_a,\tander^N] v^a\right) \GradEnt^d + \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\ov","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.355114+00:00","domain":"probability theory","id":"claim_cb4bb447613c14fb4ecef88b5b429123b7bc7cb16643fdb62f4f3b74bdfb7563","kind":"definition","schema_version":1,"statement":"[Dfn 219 (admissible controls) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $B,W,U,U',\cF_X,\cF_{\Ising}$ be as in
Definition~\ref{d:achievable-msrs-sym}. Let
\begin{align*}
    \sS &= \lt\{
        \begin{array}{ll}
        (b,\sigma): & \textup{$b,\sigma\in\ProgMsrbl(\cF_X)$, with
        $\sigma_t \ge 0$ almost surely} \\
        &\textup{and
        $\max\{\bbE[(b_t)^2], \bbE[(\sigma_t)^2]\} < \infty$ for all $t\in[0,1]$}
        \end{array}
    \rt\}\,, \\
    \sW &= \lt\{
        \begin{array}{ll}
        w : & \textup{$w\in\ProgMsrbl(\cF_{\Ising})$, with 
        $\bbE [(w_t)^2] = 1$ and} \\
        &\textup{$X^{\Ising}(1) \in \{\pm 1\}$ almost surely} 
        \end{array}
    \rt\}\,,
\end{align*}
where $X^{\Ising}$ is as in \eqref{eq:X-ising-intro}.
    For $p\in \sP$, let $\Adm^{\Ising}(\alpha,p)$
 denote the set of controls $(b,\sigma,w)\in \sS \times \sW$ satisfying, for all $0\le t\le 1$, the \textbf{Ising budget constraint}
    \beq

        \bbE \bigg[(b_t)^2 + \frac{(tp)'(t)}{p(t)}(\sigma_t-1)^2\bigg]
        \le \frac{(\bbE w_t)^2 }{ \alpha}\,.
    \eeq
Similarly, let $\Adm^{\sph}(\alpha,p)$ denote the set of controls $(b,\sigma)\in\sS$ satisfying, for all $0\le t\le 1$, the \textbf{spherical budget constraint}
    \beq

        \bbE \bigg[(b_t)^2 + \frac{(tp)'(t)}{p(t)}(\sigma_t-1)^2\bigg]
        \le \frac1\alpha\,.
    \eeq
Then $\Adm^{\Ising}(\alpha,p)$ and $\Adm^{\sph}(\alpha,p)$ are the \textbf{admissible controls} for the stochastic control problems corresponding to the Ising and spherical problems.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.741736+00:00","domain":"probability theory","id":"claim_cb4eca6a96524abd0275c05696cc5c7c2f31c4d77dc28c7b6a1e5f23e30d96ab","kind":"theorem","schema_version":1,"statement":"[Proposition 39 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\textbf{Proposition 12 in \cite{Minh2024:FisherRaoGaussian}}]

Let $\nu = \Ncal(0,C_{\nu}) \in \Gauss(\Hcal,\mu_{*})$ be fixed but arbitrary, with $C_{\nu} = C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}$.

	Let $\mu_i = \Ncal(0,C_i)$, $C_i = C_{*}^{1/2}(I-S_i)C_{*}^{1/2}$,  $S_i \in \SymHS(\Hcal)_{< I}$,
	$i=1,2$.

	Then 
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu_1}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\mu_2}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\nu)}
		\nonumber
		\\
		&\leq \frac{1}{2}\left(||I-S_{\nu}||^2 + ||S_{\nu}||_{\HS}^2+ [||S_1||_{\HS} + ||S_2||_{\HS} + ||S_1S_2||_{\HS}]^2\right)
		\nonumber
		\\
		& \quad \times ||(I-S_1)^{-1}||^2||(I-S_2)^{-1}||^2||S_1-S_2||^2_{\HS}. 

	\end{align}
	\begin{comment}
	\begin{align}
		&\left\| \log\left\{{\frac{d\mu}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_{*})}=
		\frac{1}{2}||S(I-S)^{-1}-T(I-T)^{-1}||^2_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}(\log\dettwo[(I-S)^{-1}] - \log\dettwo[(I-T)^{-1}])^2.

	\end{align}
	Furthermore,
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_{*})}

		\\
		&\leq \left(\frac{1}{2} + \frac{1}{4}[||S||_{\HS} + ||T||_{\HS} + ||ST||_{\HS}]^2\right)||(I-S)^{-1}||^2||(I-T)^{-1}||^2||S-T||^2_{\HS}.
		\nonumber
	\end{align}
	\end{comment}

\begin{proposition}

Let $\Xcal$ be a Polish space and $\Bsc(\Xcal)$ its Borel $\sigma$-algebra.

Let
$\mu, \nu \in \Pcal(\Xcal)$ be such that $\nu << \mu$. Then
\begin{align}
\KL(\nu||\mu) \leq \left\|\log\left(\frac{d\nu}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\nu)}.
\end{align}
Consequently,
\begin{align}
\left\|\log\left(\frac{d\nu}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\nu)} = 0 \equivalent \KL(\nu||\mu ) = 0 \equivalent \nu = \mu.
\end{align}
In particular, let $\{\mu_k\}_{k \in \Nbb} \in \Pcal(\Xcal)$ be such that $\mu_k \sim \mu$ $\forall k \in \Nbb$. Then
\begin{align}
\lim_{k \approach \infty}\left\|\log\left(\frac{d\mu_k}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\mu)} = 0 \imply \lim_{k \approach \infty}\KL(\mu||\mu_k) = 0.
\end{align}","status":"unverified"}

