{"assumptions":[],"created_at":"2026-10-26T19:28:31.994725+00:00","domain":"probability theory","id":"claim_cc15dbe6b193885a4c35bd93be1cca81e9ec77fef88ad1a01738d8f4144171cc","kind":"concept","schema_version":1,"statement":"[Thm 31 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $0<N\geq M\geq 0$ be fixed integers such that $N+M$ is even.
    Consider two families of polynomials $\Phi_0(x),\dots,\Phi_{N-M-1}(x)$ and $\Upsilon_{N-M}(x),\dots,\Upsilon_{N-1}(x)$ which are such that $\Phi_k$ is of degree $k$ and $\Upsilon_{\ell}$ is of degree $\ell$. Additionally, for all $1\leq j\leq N,1\leq k\leq M$, define
    \begin{equation}

        \Upsilon^{(j)}_{N-k} (x) = \Upsilon_{N-k}\fconv\phi_{-(j,N]}(x),
    \end{equation}
    so that in particular $\Upsilon^{(N)}_{N-k}=\Upsilon_{N-k}$.
    Suppose that the first family of polynomials satisfies the following skew-biorthogonality relations:
    \begin{align}
        \begin{split}

            \sum_{x,y=1}^\infty \Phi_{2i}(x) \Psi(x,y) \Phi_{2j}(y) & = 0, \\
            \sum_{x,y=1}^\infty \Phi_{2i+1}(x) \Psi(x,y) \Phi_{2j+1}(y) & = 0, \\
            \sum_{x,y=1}^\infty \Phi_{2i}(x) \Psi(x,y) \Phi_{2j+1}(y) & = -\delta_{i,j},
        \end{split}
    \end{align}
    for all $0\leq i,j< (N-M)/2$.
    Next, suppose that the second family of polynomials satisfy the following biorthogonality relation:
    \begin{equation}

        \sum_{x=1}^\infty \Upsilon_{N-k}(x) \Xi_{N-\ell}(x) = \delta_{k,\ell},
    \end{equation}
    for all $1\leq k,\ell\leq M$. Additionally, suppose that both families satisfy the following orthogonality relation:
    \begin{equation}

        \sum_{x,y=1}^\infty \Upsilon_{N-k}(x) \Psi(x,y) \Phi_{i}(y) = 0
    \end{equation}
    for all $1\leq k\leq M$ and $0\leq i< N-M$. Then for a fixed integer $m\geq 0$, let $\{p_1,\dots,p_m\}\subseteq\{1,\dots,N\}$ be indices denoting particles such that $p_1<p_2<\cdots<p_m$. The half-space TASEP with initial conditions given by $y=(y_1,\dots,y_M)$ where $y_M>N-M+1$ has conditional joint distribution given by the Fredholm Pfaffian 
    \begin{equation}

        \mathbb{P}\left[\bigcap_{k=1}^m \left\{X_{t}(p_k) > a_k\right\} \given \abs{X_t} = N\right] = \pf\left(J - \bar\chi_a K \bar\chi_a\right)_{\ell^2(\{p_1,\dots,p_m\}\times \mathbb{N})},
    \end{equation}
    where $\bar\chi_a(p,x) = \mathbbm{1}_{x\leq a_p}$ and $K$ is the kernel given by
    \begin{equation}
        K = K^0 - \left(K^\mathsf{A}+K^\mathsf{B}+K^\mathsf{C}\right)
    \end{equation}
    with the blocks on the right hand side specified as follows.
    Firstly, $K^0$ is given by \eqref{eq:cond prob kernel empty 0}, namely
    \begin{equation}

            K^0(i,x_1;j,x_2) = \left[\begin{array}{cc}
        \Psi_{(i,j)} & -\mathbbm{1}_{i<j}\phi_{(i,j]}\\[3pt]
        \mathbbm{1}_{j<i}\phi_{(j,i]}^T & 0
    \end{array}\right](x_1,x_2),
    \end{equation}
    while $K^\mathsf{A}$ is given as in \eqref{eq:cond prob kernel empty A} but with $\mathcal{T}_N$ replaced by $\mathcal{T}_{N-M}$, namely
    \begin{equation}

        \text{$K^{\mathsf{A}}$}(i,x_1;j,x_2) = \left[\begin{array}{cc} \Psi_{(i,N)}\conv\mathcal{T}_{N-M} \conv\Psi_{(N,j)} & -\Psi_{(i,N)}\conv\mathcal{T}_{N-M} \fconv\phi_{-(j,N]}\\[3pt]
        \phi_{-(i,N]}^T\fconv\mathcal{T}_{N-M}\conv\Psi_{(N,j)} & -\phi_{-(i,N]}^T\fconv\mathcal{T}_{N-M}\fconv\phi_{-(j,N]} \end{array}\right](x_1,x_2),
    \end{equation}
    Next, $K^\mathsf{B}$ is given as
    \begin{equation}

        K^\mathsf{B}(i,x_1;j,x_2) = \left[\begin{array}{cc}
        K^\mathsf{B}_{11}(i,x_1;j,x_2) & K^\mathsf{B}_{12}(i,x_1;j,x_2) \\
        K^\mathsf{B}_{21}(i,x_1;j,x_2) & K^\mathsf{B}_{22}(i,x_1;j,x_2)
    \end{array}\right]
    \end{equation}
    with 
    \begin{align}
    \begin{split}

    K^\mathsf{B}_{11}(i,x_1;j,y_2) &= \sum_{k=1}^M \left(\Xi^{(i)}_{N-k}(x_1)\left(\Upsilon_{N-k}\hspace{-1pt}\conv\hspace{-1pt}\Psi_{(N,j)}\right)(x_2)+\left(\Psi_{(i,N)}\hspace{-1pt}\conv\hspace{-1pt}\Upsilon_{N-k}\right)(x_1)\,\,\Xi^{(j)}_{N-k}(x_2)\right), \\
    K^\mathsf{B}_{12}(i,x_1;j,x_2) &= -\sum_{k=1}^M \Xi^{(i)}_{N-k}(x_1)\,\,\Upsilon^{(j)}_{N-k}(x_2),\\
    K^\mathsf{B}_{21}(i,x_1;j,x_2) & = \sum_{k=1}^M \Upsilon^{(i)}_{N-k}(x_1)\,\,\X (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

