{"assumptions":[],"created_at":"2026-10-26T20:54:34.578194+00:00","domain":"probability theory","id":"claim_cccc7144b3e901b65f1c03bec0528d673fd4d0a0c8784047ec2e955dc22e0824","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $1\leq q\leq p\leq 2$,
\begin{equation}
    \frac{\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}/\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q) = \left(M(p)^{-\frac{2}{p}}+\frac{pq}{4\upe(2-q)}\right)^{-\frac{p}{2}}  \gtrsim 2-q$, where $M(p) := p \, 2^{-\frac{p}{2}} \max_{x\geq 0} \frac{1-\upe^{-x}}{x^{p/2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.035536+00:00","domain":"probability theory","id":"claim_cccf86834c1885782ae7d97816beb57d638d516a1a580a761e81e581b96242cd","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Gaussian comparison in Kolmogorov distance) of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] \cite[Theorem 2.3]{lopes2022CLT}
Let $\bm{Z} \sim \mathcal{N}(\bm{0},\bm{\Sigma})$ and $\bm{Z}' \sim \mathcal{N}(\bm{0},\bm{\Sigma}')$ where $\bm{\Sigma}$ and $\bm{\Sigma}'$ are $d \times d$ covariance matrices. Denote $\bm{D} = \mathsf{diag}\{\Sigma_{11},\Sigma_{22},...,\Sigma_{dd}\}$, and define
\begin{align*}
\Delta = \|\bm{D}^{-\frac{1}{2}}(\bm{\Sigma}' - \bm{\Sigma})\bm{D}^{-\frac{1}{2}}\|_{e,\infty}.
\end{align*}
Then the Kolmogorov distance between $\bm{Z}$ and $\bm{Z}'$ is bounded by
\begin{align*}
d_{\mathsf{K}}(\bm{Z},\bm{Z}') \lesssim \|\bm{D}^{\frac{1}{2}}\bm{\Sigma}^{-1}\bm{D}^{\frac{1}{2}}\| \Delta \log \frac{1}{\Delta}\log_+d.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

