{"assumptions":[],"created_at":"2026-10-27T20:36:16.061559+00:00","domain":"probability theory","id":"claim_cf1ac626449dec1ef56568fe545423bb51fcbe68c7dd486612775360913990c6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:convergence of the roots of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] for $\alpha\geqslant 0$, the limit $\ell_\alpha := \lim_{t\to \infty} k_\alpha(t)/t$ exists almost surely;
\item[{\em (3)}] there is a unique $\alpha_*\in(0,\overline{\alpha})$ such that $\ell_{\alpha_*}=0$.
\end{enumerate}
Let $\alpha(t)=\sup{{\left\{\alpha\geqslant 0: k_\alpha(t)=0\right\}}}$ denote the largest root of $\alpha\mapsto k_\alpha(t)$. Then
\[
\lim_{t\to \infty} \alpha(t) = \alpha_* \quad \text{almost surely.}\]
In addition, we have $\alpha_0\leqslant \alpha_*$, where $\alpha_0$ is the rough decay rate introduced in Proposition~(prop:estimation ruin probability for the collective model of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.957748+00:00","domain":"probability theory","id":"claim_cf1bfa466679863b1e7a01315caf5302b6a2665905163389810b1a47ee9f6eda","kind":"lemma","schema_version":1,"statement":"[Lemma 2 (Schatten ideal, interpolation, and tensor regrouping) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $U,V,U',V'$ be Hilbert spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
 \item If $T\in\cL(U,V)\cap\Sch_2(U,V)$ and $2\le r<\infty$, then
 \begin{equation}
  \norm{T}_{\Sch_r}
  \le \norm{T}_{\rm op}^{1-2/r}\norm{T}_{\Sch_2}^{2/r}.
 \end{equation}
 \item If $A\in\cL(V,V')$, $B\in\cL(U',U)$, and $T\in\Sch_r(U,V)$, then
 \begin{equation}
  \norm{ATB}_{\Sch_r(U',V')}
  \le \norm{A}_{\rm op}\norm{T}_{\Sch_r(U,V)}\norm{B}_{\rm op}.
 \end{equation}
 \item The canonical regroupings of Hilbert tensor products, for instance
 $((\cA\otimes_2\cB)\otimes_2\cC)\simeq\cA\otimes_2\cB\otimes_2\cC$, are unitary.  Consequently Hilbert--Schmidt norms are unchanged by a mere reorientation of tensor legs.  Multiplication by unimodular factors on any frequency leg is also unitary and hence preserves every Schatten norm.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.335140+00:00","domain":"probability theory","id":"claim_cf240a4b606d1e6fe93d1bd0fd61e95b4833da99b3d6650a96f0673d2be3b2b5","kind":"concept","schema_version":1,"statement":"[Lemma lem:aftercancellation of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Define $\ell \coloneqq  \lceil |\alpha| / 2 \rceil$
    For every $\beta \subseteq \alpha$ and any $\mathbf{t}$, we have
    \begin{align*}
        \sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}  \hspace{.1cm}\varphi_{\beta}(\mathbf{t}) = e^{-\frac{\widehat{\sigma}^2}{2} \|\mathbf{t}\|^2 } \left( \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t}) + \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \right).
    \end{align*}
    with \begin{align*}
        \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t})  \coloneqq  \frac{(-1)^\ell}{2^\ell \ell!}  \sum_{ \substack{ r_1, \ldots r_k \in \alpha \times \alpha \\ {\textsc{Supp}}(r_1, \ldots, r_k ) = \alpha }} \Phi_{\alpha}^{(r_1, \ldots, r_k)}(\mathbf{t}) \text{ and } \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \coloneqq\sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}\sum_{k=\ell + 1}^\infty \frac{(-1)^k}{2^k k!} (\mathbf{t}^\top \! (\boldsymbol{\Sigma}_\beta - \widehat{\sigma}^2\mathbf{I}) \ \mathbf{t})^k
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.495851+00:00","domain":"probability theory","id":"claim_cf255a75a7ed6f347eb53de37ca07d95bc2eef92bf5ee910ccc6286c08563285","kind":"concept","schema_version":1,"statement":"[Lemma 4 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] For any $K \in \mathbb{N}$, the measure $(\mu^{K}_t)_{t\geq 0}$ defined in \eqref{eq: defemp0} satisfies the following stochastic differential equation
	\begin{equation}
		\begin{split}
			\big< \phi, \mu^{K}_t\big>  =&  \big< \phi, \mu^{K}_0\big>
			+\int_{0}^{t}\int_{\mathbb{R}}  \Big(\partial_t\phi(s, x) +\frac{1}{2} \partial_{xx}\phi(s, x ) \Big) \mu^{K}_s(dx)ds\\
			&+\int_0^t \int_{\mathbb{R}}\phi(s,x)\Big(1-2\int_x^\infty\mu^{K}_s(dy)+2c_K\Big)\mu^{K}_s(dx)ds +L^{K,\phi}_t 
		\end{split},
	\end{equation}
	for all bounded functions $\phi(t,x) \in C^{1,2}_b(\mathbb{R}_+\times\mathbb{R})$. Here, $(L^{K,\phi}_t )_{t\geq 0}$ is a c\`adl\`ag martingale defined by 
	\begin{align*}
		L^{K,\phi}_t : = B^{K,\phi}_t + M^{K,\phi}_t  - D^{K,\phi}_t,
	\end{align*} 
	where $(B^{K,\phi}_t )_{t\geq 0}$, $(D^{K,\phi}_t )_{t\geq 0}$ and $(M^{K,\phi}_t)_{t\geq 0}$ are square-integrable martingales given by 
	\begin{equation}
		\begin{split}
			&B^{K,\phi}_t  = \int_0^t\int_{\mathbb{R}} \phi(s,x)\nu^b(ds,dx) - \int_0^t \frac{1}{m_K}\sum_{u \in \mathcal{N}^K_s}\phi(s,X^K_u(s))ds \, ;\\
			& D^{K,\phi}_t  = \int_0^t\int_{\mathbb{R}} \phi(s,x)\nu^d(ds,dx) - \int_0^t  \frac{2c_K}{m_K}  \sum_{u \in \mathcal{N}^K_w} \phi(w,X^K_u(w))\Bigg(\sum_{v \in \mathcal{N}^K_w}\mathbb{1}_{\{X^K_u(w)\leq X^K_v(w)\}}-1\Bigg)dw \, \text{; and}\\
			& M^{K,\phi}_t  = \frac{1}{m_K}\sum_{u\in\mathbb{T}^K: \tau^b_u \leq t }\int_{0}^{t} \mathbb{1}_{\{\tau^{b}_u\leq s< \tau^{d}_u\}}\partial_x\phi(s, X^K_u(s)) dX^K_u(s), 
		\end{split}
	\end{equation}
	respectively. Furthermore, $L^{K,\phi} $ has  predictable quadratic variation 
	\[
	\begin{split}
