    \item[\emph{(ii)}] There exists $u\in\tau$ such that $\sum_{j=1}^{\mathrm{k}_u(\tau)}\big(\mathrm{Ht}(\theta_{u*j}\tau)+1\big)\wedge n^{1/2-3\alpha}>\tfrac{1}{2}n^{1/2-2\alpha}$.
