{"assumptions":[],"created_at":"2026-10-27T19:52:51.763065+00:00","domain":"probability theory","id":"claim_cf93c5dbb2e54f35e713b5fb20bb82094953bae2663b0c13eae98af33f03fdca","kind":"definition","schema_version":1,"statement":"[Definition Def:ms-dissipative-schurz of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let $\left\{X(t):t\in[0,\infty)] \subseteq D \subseteq \mathbb{R}^d \right\}$ be a solution of the SDE (equation eq:main_d of the paper) corresponding to initial data $X(0)\in D$ which is measurable with respect to $\mathcal{F}_0$. The SDE is called 
    \begin{enumerate}
    \item mean-square dissipative if  there exist $r,R>0$ such that     $$\limsup_{t\to\infty}\mathbb{E}\left[\|X(t)\|^2\right]<R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right]<r^2$;

    \item uniformly mean-square dissipative if  there exist $r,R>0$ such that $$\lim_{t\to\infty}\expect{\sup_{0\leq s \leq t}\|X(s)\|^2} <R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right] < r^2$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:16:46.122200+00:00","domain":"probability theory","id":"claim_cf9b09ca7d8b02f4df564792056a2569ae18e6294091733f7376b9b8869375b7","kind":"concept","schema_version":1,"statement":"[Prop geodconfigstable of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] Let $\omega \in \Omega_0$, $\theta \in \mathbb{R}\setminus\Theta^\omega$, and $(x,s)\in\mathbb{R}^2$. Then the following are the only possible configurations of $\theta$-directed geodesics emanating from $(x,s)$. Each of the configurations occurs at a dense set of starting points $(x,s)$.  See the first four configurations on the first row of Figure (fig:geodesics of the paper).
    \begin{enumerate}[label={\rm(\alph*)}, ref={\rm\alph*}] \itemsep=1pt
        \item $(x,s)\not\in {\mathrm{NU}}_1^\theta$ and hence $\Gamma_{{(x,s)}}\dir{L}{\theta}{} = \Gamma_{{(x,s)}}\dir{R}{\theta}{}$. \item $(x,s)\in{\mathrm{NU}}_1^{\theta}$. There exist times $t>s'>s$ such that $t = s+{\mathfrak a}^{\theta}(x,s)$, 
        \begin{align}
        \Gamma_{{(x,s)}}\dir{L}{\theta}{}\big|_{(s,t)}\prec\Gamma_{{(x,s)}}\dir{R}{\theta}{}\big|_{(s,t)},\quad
        \Gamma_{{(x,s)}}\dir{L}{\theta}{}\big|_{[t,\infty)} = \Gamma_{{(x,s)}}\dir{R}{\theta}{}\big|_{[t,\infty)},
        \end{align}
        and exactly one of the following occurs:
        \vspace{5pt}

        \begin{enumerate}[label={{\rm(}(prop:geods-stability.b of the paper).\rm\roman*)}, ref={(prop:geods-stability.b of the paper).\rm\roman*}] \itemsep=1pt
            \item   $\Gamma_{{(x,s)}}\dir{M}{\theta}{}=\Gamma_{{(x,s)}}\dir{L}{\theta}{}$ for all time, or

            \item $\Gamma_{{(x,s)}}\dir{L}{\theta}{}\big|_{(s,s')}\prec\Gamma_{{(x,s)}}\dir{M}{\theta}{}\big|_{(s,s')}\prec\Gamma_{{(x,s)}}\dir{R}{\theta}{}\big|_{(s,s')}$, and the middle geodesic intersects exactly one of $\Gamma_{{(x,s)}}\dir{L}{\theta}{}$ or $\Gamma_{{(x,s)}}\dir{R}{\theta}{}$ at time $s'$, proceeding with said geodesic for all times beyond $s'$. Each of the two configurations occurs at a dense set of starting points $(x,s)$.
        \end{enumerate}       
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.285665+00:00","domain":"probability theory","id":"claim_cf9b4d14b32b875e8e602a05497339f8d78af0e6f5b7f3b71f69382aff19afbd","kind":"definition","schema_version":1,"statement":"[Definition def:SUSY1eps of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta\in\mathrm{Prefix}_2(u,q)$ for some $u,q\in(0,1)$.
		We define $\mathrm{SUSY}_1(\zeta,\varepsilon)$ as the set of $\mathbf{m}\in[-1+\delta_\varepsilon,1-\delta_\varepsilon]^N$ such that
		\begin{equation*}
			\left|\frac{1}{N}\|\mathbf{m}\|^2-q\right|\leq\varepsilon,
			\qquad
			\left|\frac{1}{N}\langle\partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle
			-\xi'(q)\int_0^1\zeta([0,t])\,\mathrm{d} t\right|\leq \varepsilon,
		\end{equation*}
		and
		\begin{equation*}
			\mathrm{dist}\!\bigl(\zeta_\mathbf{m},\,\zeta|_{(q,1]}+\zeta([0,q])\,\delta_q\bigr)\leq\varepsilon,
		\end{equation*}
		where we recall that $\mathrm{dist}$ is as in (equation def:dist of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:24:45.942235+00:00","domain":"probability theory","id":"claim_cf9b9895f304ea448b9a3f36f3612c0ae27c0ed1557cef415aef05d0e0368a62","kind":"lemma","schema_version":1,"statement":"[Lemma lem:conv_drift_exp of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let $a\in \mathbb{R}$ and let $X_0\in \mathcal{C}_{tem}^+$. Then there  exists $T_0>0$, independent of $X_0$, such that the following convergences hold:
	\begin{enumerate}[label=(\roman*)]
		\item 
		\begin{equation*}
			\begin{split}
				&\lim_{m\rightarrow \infty}\mathbb{E}\Big[ (-1)^{J_t^{m,m}} \exp\Big(-\langle Y^{m,m}_{t}, X_0\rangle-a\int_0^t\langle Y^{m,m}_s,1\rangle ds\Big)\Big]\\
				& = \mathbb{E}\Big[ (-1)^{J_t^{\infty,\infty}} \exp\Big(-\langle Y^{\infty,\infty}_{t}, X_0\rangle-a\int_0^t\langle Y^{\infty,\infty}_s,1\rangle ds\Big)\Big],
			\end{split}
		\end{equation*}
		\item 
		\begin{equation*}
			\begin{split}
				&	\lim_{n \rightarrow \infty}\mathbb{E}\Big[ (-1)^{J_t^{n,m}} \exp\Big(-\langle Y^{n,m}_{t}, X_0\rangle-a\int_0^t\langle Y^{n,m}_s,1\rangle ds\Big)\Big] \\
				&= \mathbb{E}\Big[ (-1)^{J_t^{\infty,m}} \exp\Big(-\langle Y^{\infty,m}_{t}, X_0\rangle-a\int_0^t\langle Y^{\infty,m}_s,1\rangle ds\Big)\Big],
			\end{split}
		\end{equation*}
		\item
		\begin{equation*}
			\begin{split}
				&	\lim_{m \rightarrow \infty}\mathbb{E}\Big[ (-1)^{J_t^{\infty,m}} \exp\Big(-\langle Y^{\infty,m}_{t}, X_0\rangle-a\int_0^t\langle Y^{\infty,m}_s,1\rangle ds\Big)\Big] \\
				&= \mathbb{E}\Big[ (-1)^{J_t^{\infty,\infty}} \exp\Big(-\langle Y^{\infty,\infty}_{t}, X_0\rangle-a\int_0^t\langle Y^{\infty,\infty}_s,1\rangle ds\Big)\Big],
			\end{split}
		\end{equation*}
	for all $t \in [0,T_0]$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224212+00:00","domain":"probability theory","id":"claim_cf9e9a9a83a417da92c23a4b82dc92aa730bbc4376003b7a7d4d95b429ce3c56","kind":"concept","schema_version":1,"statement":"[Proposition AS of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(M,[\hat{h}])$ be the conformal infinity of an asymptotically hyperbolic manifold $(X^{n+1},g^+)$, and $p\geq 3$. Let $u_0$ be a non-integrable minimizer of the fractional Yamabe energy and suppose that it satisfies the $\text{AS}_p$ condition. Then, there exists a sequence $(u_k)_{k\in \mathbb{N}} \subset H^\gamma (M)$ with $u_k \to u_0$ in $H^\gamma (M)$ such that 
\begin{align*}
    \lim_{k\to \infty}\frac{I_\gamma [u_k,\hat{h}] -\Lambda_\gamma (M,[\hat{h}])}{\|u_k - u_0\|_{H^\gamma (M)}^{p-\alpha} } = 0 \quad \forall \alpha>0.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.317674+00:00","domain":"probability theory","id":"claim_cfa70df8544a10da243eb7985dda2c7d5f1ee654d946a0116185f33c3c9b9709","kind":"concept","schema_version":1,"statement":"[Corollary 4 (Central limit theorem) of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Assume that at least one of the following sets of conditions is met:
