{"assumptions":[],"created_at":"2026-10-27T09:15:16.647412+00:00","domain":"probability theory","id":"claim_cfb19d3a398448cbb92d67562681fff13b40cbaaf8e901d301f888c08c60af02","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] A probability measure $P$ on $(C([0,T];\R^d),\mathcal{B}(C([0,T];\R^d)))$ is called \textup{solution to the distribution-dependent Volterra local martingale problem} given $(\mu_0,b,\sigma,K_b,K_\sigma)$ if
  \begin{enumerate}
    \item[(i)] $(Z_t)_{t\in[0,T]}$ is a $d$-dimensional semimartingale and $Z_0 \sim \mu_0$, 
    \item[(ii)]the process $(\mathcal{M}^f_t)_{t\in[0,T]}$, given by
    \begin{equation}
      \mathcal{M}^f_t:= f(Z_t)-\int_0^t \mathcal{A}^f(s,X_s,\L(X_s),Z_s)\dd s,\quad \mathcal{F}_t, \quad t\in [0,T],
    \end{equation}
    is a local martingale for every $f\in C_0^2(\R^d)$, where 
	\begin{equation}
      \mathcal{A}^{f}(t,x,\rho,z):=\sum_{i=1}^d b_i(t,x,\rho)\frac{\partial f(z)}{\partial z_i}+\frac{1}{2}\sum_{i,j=1}^d (\sigma\sigma^\top)_{ij}(t,x,\rho) \frac{\partial^2 f(z)}{\partial z_i \partial z_j},
	\end{equation}
	and
    \begin{equation}
      X_t := Z_0 +\int_0^t K_b(s,t)\dd A_s + \int_0^tK_\sigma(s,t)\dd M_s, \quad t\in[0,T],
      \quad P\text{-a.s},
    \end{equation}
	$(A_t)_{t\in[0,T]}$ is predictable of bounded variation and $(M_t)_{t\in[0,T]}$ is a local martingale with $M_0=0$, such that $Z=A+M$. Here $\mathcal{F}_t = \mathcal{G}_{t+}$, and $(\mathcal{G}_t)_{t \in [0,T]}$ is the augmentation under $P$ of the canonical filtration $(\mathcal{B}_t)_{t \in [0,T]}$ with $\mathcal{B}_t := \sigma(Z_s\, :\, s\in [0,t])$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.638208+00:00","domain":"probability theory","id":"claim_cfb42ff0422c2faa9a91de5e3b8b8eafc63968f01204ded3edef72492312b9c6","kind":"concept","schema_version":1,"statement":"[Corollary 2 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, we have:
