{"assumptions":[],"created_at":"2026-10-28T01:54:57.568519+00:00","domain":"probability theory","id":"claim_d1aa2d805f3f4f9f6bd278c3748297dd4a22dbd3f246699c81e0d2fe74ca4d00","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $0 \leq p, \, q \leq \infty$ and $s, \, \beta \in \mathbb{R}$, the Besov space with logarithmic scale is defined by 
\begin{equation}
 B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2) :  = \Big\{ f \in \mathcal{S}'(\mathbb{R}^2)~:~ \,  \sum_{j \in \mathbb{N}} j ^{-\beta q} 2^{jsq} \Vert \Delta_j f\Vert_p^q < \infty\big\}
\end{equation}
and we define a norm on $B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)$ by
$$
\Vert f \Vert_{B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)} = \left( \sum_{j \in \mathbb{N}} j ^{-\beta q} 2^{jsq} \Vert \Delta_j f \Vert_p^q \right)^{1/q}.
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.778529+00:00","domain":"probability theory","id":"claim_d1aa7880679c804eee81c8b93c11ed9407ea268bf1c384afa48f953d4f39987e","kind":"theorem","schema_version":1,"statement":"[Proposition 25 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $(\SC, \varrho)$ be a non-empty quasi-metric space.
 Let $\mu$ be a Borel probability measure on $\SC$, and let $s\in (0,\infty)$ and $t\in \RR$.
 Assume that there exist $r_0>0$ and $c_0>0$ such that
 \begin{equation*}
     \om{\mu} \bigl( \ball(x,r)\bigr) 
    \le \exp\biggl( - c_0 \cdot \Bigl( \frac{1}{r}\Bigr)^{s} \cdot \Bigl( \log_2 \Bigl(\frac{1}{r}\Bigr)\Bigr)^{t}\biggr)
    \quad \text{for all $x\in \SC$ and all $r\in (0,r_0)$.}
 \end{equation*}
 Then for every $\eps\in (0,r_0)$ there exists an $\eps$-separated subset $P_{\eps}$ with
 \begin{equation*}
   \num P_{\eps}
   \geq \exp
        \biggl(
          c_0
          \cdot \left(\frac{1}{\eps}\right)^s
          \cdot \left(\log_2 \left(\frac{1}{\eps}\right)\right)^{t}
        \biggr).
 \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:43:04.730371+00:00","domain":"probability theory","id":"claim_d1ac9cc44ccb6ea06cff11315faf49ce1a46d060161e83d270272a1ddd656253","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let $p \in (0,1)$, $q > 0$ and $\gamma \in \R$ s.t.~$0<|\gamma| < q$, and $[u_1,u_2] \subset \B$ s.t.~$[pu_1,pu_2] \subset \B$. For $f$ and $h \in  C_\mathrm{b}(\B)$, consider the integral operator $\mathcal{A} : C_\mathrm{b}(\B) \rightarrow C_\mathrm{b}(\B)$ s.t.~
		\begin{equation}
			\mathcal{A}f(x) = h(x) + \gamma \int^{u_2}_{u_1} \f^{(q)}(x,y) f(py) \dd y.   
		\end{equation}
		Then, the (unique) fixed point $g \in C_\mathrm{b}(\B)$ of $\mathcal{A}$ is of the form
		\begin{equation}
			g(x) = h(x) + \int^{u_2}_{u_1} \overline{\V}^{(p)}_\gamma[\f^{(q)}](x,y)  \, h(py)\, \dd y,
		\end{equation} 
		where $\overline{\V}^{(p)}_\gamma[r^{(q)}]$ is given in Definition \ref{Def:ResolventDefn}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:01:48.648264+00:00","domain":"probability theory","id":"claim_d1af73209367ddde5d742d0a6c5cb8c18e895224ad6c475283749e69271d179b","kind":"concept","schema_version":1,"statement":"[Theorem thm:long_range_cluster of arXiv:2607.04002, 'Collisions of random walks in unimodular random graphs: applications to the random geometr'] For each regime, we assume that the percolation model with edge probabilities~$\mathsf P_{\beta,s}$ admits a unique infinite connected component~$\mathcal C_\infty$ almost surely.
\begin{enumerate}
    \item For~$d = 1$ with~$s =2$, and~$d=2$ with~$s \ge 4$, the long-range percolation cluster~$\mathcal C_\infty$ has the discrete and continuous infinite collision property almost surely.
    \item For~$d = 1$ with~$s \in (1,2)$, and~$d \ge 2$ with~$s \in (d,d+2)$, the long-range percolation cluster~$\mathcal C_\infty$ has the discrete and continuous finite collision property almost surely.
    \item [BenjaminiCurien2012] For~$d \ge 1$ with~$s \in (d,2d)$, the tail~$\sigma$-algebra~$\mathcal T_\mathrm{rw}(\mathcal C_\infty)$ is trivial almost surely.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.823384+00:00","domain":"probability theory","id":"claim_d1b38a980a492b8f8b3d38c02f4fa4234705e534b6a8a90010df78f291f1cf8a","kind":"concept","schema_version":1,"statement":"[Prop simplecasetheta of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] In each of the following cases, one has $\overline{\theta}_{\,\scriptscriptstyle\Phi, \hat{\Sigma}}=\underline{\theta}_{\,\scriptscriptstyle\Phi, \hat{\Sigma}}$, and we denote by $\theta$ this common value:
    \begin{enumerate}
        \item If $\Phi(0)=\lambda>0$ then $\theta=\begin{cases} &\!\!\!\!\!\frac{\lambda}{\hat a} \text{ if } \hat{a}>0\\
        &\!\!\!\!\!\infty\ \text{ if } \hat{a}=0. \end{cases}  $
        \item If $\Phi(0)=0$ and $\hat{a}>0$ then $\theta=0$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:04:55.816143+00:00","domain":"probability theory","id":"claim_d1b652e6a6a9223920d90d52036bce2e4ad34f2e9beeda7f0ec4e6a153043e99","kind":"concept","schema_version":1,"statement":"[Thm t:normalform of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] For any $A\in\Omega^1(\Sigma,\mathfrak{g})$, there exist $\mathrm{g}_\infty\in L^{\infty}(\Sigma,G)$ such that the following holds: 
\begin{enumerate}
\item $F(A_T)$ converges (in the sense of currents) to $F_\infty:=\mathrm{g}_\infty^{-1}F(A)\mathrm{g}_\infty$  as $T\rightarrow\infty$ and 
$$
\mathcal{S}_{\operatorname{YM}}(A)=\int_{\Sigma}\|\star_hF_\infty\|_{\mathfrak{g}}^2\upsilon,
$$
\item there exists $\beta_\infty\in\mathcal{D}^\prime(\Sigma,T^*\Sigma\otimes\mathfrak{g})\cap\ker(\iota_V)$ such that $\int_0^T\varphi_f^{-t*}(\iota_V(F_\infty)dt$ converges (in the sense of currents) to $\beta_\infty$ and $A_T$ converges (in the sense of currents) to
\begin{equation}
A_\infty:=\sum_{j=2}^{2g+1}\mathfrak{b}_j[W^u(a_j)]+\beta_\infty,
\end{equation}
where $\mathfrak{b}_j:=\int_{W^s(a_j)}A\in\mathfrak{g}$;
\item $\beta_\infty$ and $\mathrm{g}_\infty$ are smooth on $W^u(a_1):=\Sigma\setminus\cup_{j=2}^{2g+1}\overline{W^u(a_j)}$ and, for every $1\leq q< 2$, $\beta_\infty$ belongs to $L^q(\Sigma,T^*\Sigma\otimes\mathfrak{g})$;
\item one has\footnote{Here, $[a]$ denotes the current of integration on the point $a$.} $dA_\infty=F_\infty-\left(\int_\Sigma F_\infty\right)[a_{2g+2}]$;

\item for any $\gamma:[0,1]\rightarrow\Sigma$ of class $\mathcal{C}^1$ such that $\gamma(0),\gamma(1)\in W^u(a_1)$, one has 
$$
\lim_{T\rightarrow +\infty}\operatorname{Hol}_{\gamma}(A_T)=\mathrm{g}_\infty(\gamma(1))^{-1}\operatorname{Hol}_{\gamma}(A)\mathrm{g}_\infty(\gamma(0));
$$
\item for any gauge equivalent $A_1,A_2 \in \Omega^1(\Sigma,\mathfrak{g})$, i.e. $A_2=\mathrm{g}^{-1}d\mathrm{g}+\mathrm{g}^{-1}A_1\mathrm{g}$ for some $\mathrm{g}\in C^\infty(\Sigma,G)$, the limiting 
connections $A_{1,\infty},A_{2,\infty}$ satisfy
$$A_{2,\infty}=\mathrm{g}(a_1)^{-1}A_{1,\infty} \mathrm{g}(a_1)\quad\text{on}\quad W^u(a_1),$$
and, under the assumption of the previous item, 
$$
\lim_{T\rightarrow +\infty}\operatorname{Hol}_{\gamma}(A_{2,T})=\lim_{T\rightarrow +\infty}\mathrm{g}(a_1)^{-1}\operatorname{Hol}_{\gamma}(A_{1,T})\mathrm{g}(a_1).
$$
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.605108+00:00","domain":"probability theory","id":"claim_d1bb91d15fce7efa770f9014b955d5e68fac618b6cc63611ece5f47a2b803d16","kind":"concept","schema_version":1,"statement":"[Lem LLNlr of arXiv:2608.13084, '\bf Branching random walk in random environment'] For any $x\in{\mathbb Z}^d$ and for ${\bf P}_p$-a.s. environment $\omega$, 
\begin{equation*}
