\end{equation*}
The similar result holds for $(l_j)_{j\ge1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:30:36.755877+00:00","domain":"probability theory","id":"claim_d1c226af3abc696516b9f7fce838c35fdbc20cb185e632e91e946241c935ce41","kind":"concept","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Assume that the conditions \textbf{(A)} and \textbf{(B)} hold with $r \in (1/2, 1)$. Let $\beta_N$ be a sequence of inverse temperatures satisfying $\beta_N N^{H/2} \to \beta \in [0, \infty)$ as $N \to \infty$. Then there exists a positive constant $C$ such that for any $N \ge 1$ and $k \ge 1$,
\begin{equation} 
\| \rho_k \|_{\mathcal{L}_K^k}^2 \le \frac{C^k \Gamma^k(H)}{\Gamma(kH + 1)}
\end{equation}
and
\begin{equation} 
k! \| \psi_N^k \|_{\mathcal{L}_K^k}^2 \le \frac{C^k \Gamma^k(H)}{\Gamma(kH + 1)},
\end{equation}
where
\begin{equation*}
\rho_k(\mathbf{t}, \mathbf{x}) := \prod_{i=1}^k \rho(t_i - t_{i-1}, x_i - x_{i-1}), \quad (\mathbf{t}, \mathbf{x}) \in \Delta_k(1) \times \mathbb{R}^k.
\end{equation*}
In particular, since $H > 0$, the bounds in \eqref{eq:rho_k_bound} and \eqref{eq:psi_k_bound} guarantee the summability of the following series:
\begin{equation} 
\sum_{k=1}^\infty (\sqrt{2}\beta)^{2k} \| \rho_k \|_{\mathcal{L}_K^k}^2 < \infty,
\end{equation}
and
\begin{equation} 
\lim_{l \to \infty} \limsup_{N \to \infty} \sum_{k \ge l} (\sqrt{2}\beta_N N^{H/2})^{2k} k! \| \psi_N^k \|_{\mathcal{L}_K^k}^2 = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.604271+00:00","domain":"probability theory","id":"claim_d1c5ad8a33167c69a3e9278495ec92bc75ae802a8211788c0748479f14b46d96","kind":"concept","schema_version":1,"statement":"[Theorem t:hp of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] Let $(P_t)_{t \in \mathbb T}$ be a transition probability function on $S$.
    If $(P_t)_{t \in
    \mathbb T}$ is increasing and there exists a positive $u \in \mathbb T$ such that $P_u$
    satisfies the MMC, then $(P_t)_{t \in \mathbb T}$ is globally stable on $\mathscr{P}(S)$
    under $\beta$ and convergence to the unique fixed point $\phi^*$ is
    exponential: 

    \begin{equation}
        \beta(\phi P_t, \phi^*) \leq C e^{-\alpha t}
        \quad \text{for all $\phi \in \mathscr{P}(S)$ and $t \in \mathbb T$},
    \end{equation}

    where $C \coloneq 2/(1-\epsilon)$ and $\alpha \coloneq \ln(1/(1-\epsilon))/u$.
    Moreover, when $\mathbb T = \mathbb{Z}_+$, each $P$-Markov process is monotone ergodic:

    \begin{equation*}
        \mathbb P
        \left\{
             \lim_{n \to \infty}
             \frac{1}{n} \sum_{t=0}^{n-1} h(X_t) = \phi^*(h)
        \right\} = 1
        \quad \text{for all } h \in ibS.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.610474+00:00","domain":"probability theory","id":"claim_d1c5b5605e72e5977ff591992cd3902fd78201a7ea0376fea1b091976a563d67","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $G$ be an undirected, unweighted graph without multiple edges, possibly with loops, whose vertex set $v(G)\subseteq S$ is locally finite. The adjacency measure $\xi_G$ associated with $G$ is given by 
