and its eigenvalues are precisely the branch derivatives:
\begin{equation}
 \{\lambda_j'(0):1\le j\le r\}
 =\Spec\bigl(B_f^\Lambda(M_x)\bigr)
 \quad\text{as multisets}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.857984+00:00","domain":"probability theory","id":"claim_d24c3182a8058d320acee50d19f320b27c327e4004a1c05e17732b92c03b1276","kind":"concept","schema_version":1,"statement":"[Lemma 10 of arXiv:2609.02019, '2609.02019'] Let $s>5/2$. Let  $J_n$ be the Friedrichs mollifier defined in \eqref{Define Jn}.
		Then we have
		\begin{equation*}
			\left|\IP{\mathcal{H} u\partial_x u, u}_{H^{s}}\right|
			\lesssim  (\|u_x\|_{L^\infty}+\|\mathcal{H} u_x\|_{L^\infty})\|u\|^2_{H^{s}},\quad u\in H^{s+1}.
		\end{equation*}
		and
		\begin{equation*}
			\sup_{n\ge1}\left|\bIP{J_n (\mathcal{H} u\partial_x u), J_n u}_{H^{s}}\right|
			\lesssim  (\|u_x\|_{L^\infty}+\|\mathcal{H} u_x\|_{L^\infty})\|u\|^2_{H^{s}},\quad u\in H^{s}.
		\end{equation*}
		Moreover, for all $u,v\in H^s$, all $n,m\ge1$, and every
		$\theta\in(3/2,s-1)$,
		\begin{align*}
			\left|\IP{J_n \left[\mathcal{H} J_n u\partial_x J_nu\right]-J_m \left[\mathcal{H} J_m v\partial_x J_mv\right],u-v}_{H^\theta} \right|
			\lesssim  \Big(1+\|u\|^4_{H^s}+\|v\|^4_{H^s}\Big)
			\left((n\wedge m)^{-2(s-1-\theta)}+\|u-v\|^2_{H^\theta}\right).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:44:28.075613+00:00","domain":"probability theory","id":"claim_d24d756fa2716bc9baad480ab3481b85fdbdc32eb350de2ab9439daab20955c0","kind":"definition","schema_version":1,"statement":"[Defi 2 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] On a given 
        probabilistic set-up $(\Omega,\mathfrak{F},{\mathbb F}=\{\mathfrak{F}_t\}_{t\geq 0},\mathbb{P},(W_t)_{t \geq 0})$, and for
        an $\mathfrak{F}_0\text{-measurable}$ initial condition $X_0$ with values in $\mathcal{U}^2(\mathbb{S})$, satisfying 
        ${\mathbb E}[\| X_0\|_2^p]<+\infty$ for all $p \geq 1$, we say that a pair of processes $(X_t,\eta_t)_{t\geq 0}$ solves the rearranged SHE \eqref{0.1}, initialized at $X_0$, if
		\begin{itemize}
			\item[1.] $(X_t)_{t\geq 0}$ is a continuous $\mathbb{F}\text{-adapted}$ process with values in $\mathcal{U}^2(\mathbb{S})$;
			\item [2.]  $(\eta_t)_{t\geq 0}$ is a continuous $\mathbb{F}\text{-adapted}$ process with values in $\mathcal{H}^{-2}_{\mathrm{Sym}}(\mathbb{S})$, starting from $0$ at $0$, such that, with probability one, for any $\phi \in \mathcal{H}^{2}_{\mathrm{Sym}}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S})$, the path $(\langle \eta_t,\phi\rangle)_{t\geq 0}$ is non-decreasing;
			\item[3.] with probability one, for any $\phi \in \mathcal{H}^{2}_{\mathrm{Sym}}(\mathbb{S})$, for all $t\geq 0$,
			\begin{equation}
				\langle X_t,\phi\rangle = \langle X_0,\phi\rangle + \int_0^t \langle X_s,\Delta \varphi\rangle \mathrm{d}s + \langle W_t,\phi\rangle + \langle \eta_t,\phi \rangle.
			\end{equation}
			\item[4.] for any $t\geq 0$,
			\begin{align}
				\lim_{\epsilon\searrow 0 }\mathbb{E} \int_0^t {\rm e}^{\epsilon \Delta} X_s\cdot \mathrm{d} \eta_s = 0.
			\end{align}
		\end{itemize}","status":"unverified"}

