{"assumptions":[],"created_at":"2026-10-26T21:02:38.602296+00:00","domain":"probability theory","id":"claim_d544344670491bccf2218a241d6cd0865956944760bbf6e73f1c0fbd67d3d972","kind":"theorem","schema_version":1,"statement":"[Theorem 36 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume the hypotheses of Theorem~\ref{thm:augmented-semigroup}. Let $\rho:\mathcal E\to\X$ be the projection $\rho(x,u)=x$, and let

\begin{equation}
\Lambda_h((x,u),A)=R_h((x,u),A\times\N^d),
\qquad h\in\N^d,
\quad A\in\calX.
\end{equation}

The following assertions are equivalent.
\begin{enumerate}[label=\textup{(L\arabic*)},leftmargin=2em]
\item For every initial law concentrated on $\mathcal E$, the projected field $Z=\rho(Y)$ is a homogeneous $\N^d$-indexed Markov chain with respect to its lower-rectangle filtration

\begin{equation*}
\mathcal G_k^Z=\sigma\{Z_m:m\leqd k\}.
\end{equation*}
\item For every $h\in\N^d$ there exists a Markov kernel $P_h^Z$ on $\X$ such that

\begin{equation}
\Lambda_h((x,u),A)=P_h^Z(x,A)
\end{equation}

for every $A\in\calX$ and every $(x,u)\in\mathcal E$.
\end{enumerate}
When these equivalent conditions hold, $(P_h^Z)_{h\in\N^d}$ is a Markov semigroup on $\X$:

\begin{equation}
P^Z_{\zerod}=I,
\qquad
P^Z_{h+r}=P^Z_hP^Z_r,
\qquad h,r\in\N^d,
\end{equation}

and the coordinate kernels $P^Z_{e_1},\ldots,P^Z_{e_d}$ commute.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.465814+00:00","domain":"probability theory","id":"claim_d54adbea63e7c761c87d5dfb78de013168ba1b372f11d6eb4c0e366bd30dc0f2","kind":"theorem","schema_version":1,"statement":"[Theorem 11 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $g:\mathbb{R}^n \rightarrow \mathbb{R}$ be measurable, satisfy 
\begin{enumerate}[label=(\roman*)]
\item $0 \leq x_i \leq y_i, i=1,...,n  \implies g(x_1,...,x_n) \leq g(y_1,...,y_n)$
\item $\forall (x_1,...,x_n) \in \mathbb{R}^n, \ g(x_1,...,x_n) \leq g(|x_1|,....,|x_n|)$
\end{enumerate}
Let $f \in \mathcal{B}^n$ \eqref{absolutetails} be an $n$-tuple of absolute tail bounds. Then, 
\begin{equation}
   \sup_{X \in \mathcal{T}(f)} P(g(X) \geq t) = P(g(\widetilde{X}) \geq t), \ \forall t \in \mathbb{R}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:23.368342+00:00","domain":"probability theory","id":"claim_d54b27233aee23c1433a6127a0902f332fde6f54dd2ab5d2a9e04c28c1b2077e","kind":"concept","schema_version":1,"statement":"[Lemma 27 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] There exist a constant $C > 0$ and a family of positive random variables $(\Psi^1_{s,t})_{0 \leqslant s < t}$, where the Malliavin-Sobolev norm of each $\Psi^1_{s,t}$ does not depend on $s$ or $t$, such that
