{"assumptions":[],"created_at":"2026-10-27T18:44:24.705021+00:00","domain":"probability theory","id":"claim_d5ecb0364408df1e8114c7a5daf1aecc67922aba23fe18e3fbeb809d01ce48fb","kind":"definition","schema_version":1,"statement":"[Definition def:F-double-critical of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For    an  $r\times r$ matrix
\begin{equation}
    \mathfrak{A}(t) := \sum_{i=1}^q e^{\tau_i t} \boldsymbol{v}_i \boldsymbol{v}_i^T, \quad t \ge 0,
\end{equation}
we   define a quadratic form  in real variables $\{z_i\}$ by
\begin{equation}
    \mathfrak{A}[t;\{z_i\}_{i=1}^r](x,y)=\sum_{i,j=1}^r (\mathfrak{A}(t))_{ij}\sqrt{\delta(x-z_i)}\sqrt{\delta(y-z_j)}.
\end{equation}
For a typical connected diagram $\Gamma = (V, E)$,  we define the weight function  $\mathcal{W}_\Gamma$ as
\begin{equation}
    \mathcal{W}_\Gamma(x, \{\alpha_e\}) = \prod_{e=(u,v) \in E_{\mathrm{int}}} \theta_{\alpha}(x_u - x_v, \alpha_e \gamma^\alpha) \prod_{e=(u,v) \in E_b} \mathfrak{A}[\alpha_e;\{z_i\}_{i=1}^r](x_u,x_v),
\end{equation}
and the corresponding limiting diagram function $\mathcal{F}^{\mathfrak{A}}_\Gamma$   for  $t_1, \dots, t_s > 0$ as the integral
\begin{equation}
    \mathcal{F}^{\mathfrak{A}}_\Gamma(t_1, \dots, t_s; \{z_i\}_{i=1}^r;\gamma^\alpha) =
    \frac{C_\Gamma}{\prod_{j=1}^s t_j}  \int_{\mathbb{T}^{|V|}} \int_{\mathfrak{C}(\{t_i\})} \mathcal{W}_\Gamma(x, \{\alpha_e\}) \prod_{e \in E} d\alpha_e \prod_{v \in V} dx_v.
\end{equation}
Here in the product $\prod_{e=(u,v) \in E_b}$, each vertex  $u\in V_b$ carries   the variable $x_u$   exactly twice and   the square-root delta functions are interpreted according to the rule
\begin{equation}
    \sqrt{\delta(x_u-z_1)}\sqrt{\delta(x_u-z_2)}=\begin{cases}
        \delta(x_u-z_1),&z_1=z_2,\\
        0,&z_1\ne z_2.
    \end{cases}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.703619+00:00","domain":"probability theory","id":"claim_d5ee002e11d094a5f024c56cc08f6745daae7aa37c84058a8a9c2bf51d6cb26e","kind":"lemma","schema_version":1,"statement":"[Lemma LEM:SCHOP of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] For sufficiently large $L\ge 1$ and any $x_0 \in \mathbb{T}_{L^2}$, we can define an Ornstein Uhlenbeck type measure $ \nu^\perp_{Q, x_0}$ as follows
\begin{align}
\nu^\perp_{Q,x_0}= \nu_{C_{1,x_0}^Q}^{\perp} \otimes  \nu_{C_{2,x_0}^Q}^{\perp}, 

\end{align}

\noindent
where 
\begin{align*}
d\nu_{C_{1,x_0}^Q}^{\perp}(\Re  h^\perp )&=Z_{L}^{-1} e^{-\frac 12 \jb{(C_{1,x_0}^Q)^{-1} \Re  h^\perp, \Re  h^\perp} } \prod_{x\in \mathbb{T}_{L^2}}\mathrm{d} \Re  h^\perp(x)\\
d\nu_{C_{2,x_0}^Q}^{\perp}(\Im  h^\perp)&=Z_{L}^{-1} e^{-\frac 12 \jb{(C_{2,x_0}^Q)^{-1} \Im  h^\perp, \Im  h^\perp} } \prod_{x\in \mathbb{T}_{L^2}}\mathrm{d} \Im  h^\perp(x).
\end{align*}

\noindent
Here, $\nu_{C_{1,x_0}^Q}^{\perp}$, $\nu_{C_{2,x_0}^Q}^{\perp}$ have 
covariance operators $(B_1^Q)^{-1}$ and $(B_2^Q)^{-1}$, projected on $\overline V_{x_0,0}^{L^2, \textup{Re}}$ and $\overline V_{x_0,0}^{L^2, \textup{Im}}$, defined in (equation VRE of the paper) and (equation VIM of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:19:00.931460+00:00","domain":"probability theory","id":"claim_d5efc371d29e1f4f8cff08fa3b7ee613744b487105a900e49e021263a640b45f","kind":"concept","schema_version":1,"statement":"[Lemma 12 (Supercritical sign geometry) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Suppose that $w_{t+1}>2$.
