{"assumptions":[],"created_at":"2026-10-27T06:25:55.402639+00:00","domain":"probability theory","id":"claim_d6a9a33e647b637cbb4ed6561a057d450fd0cf9d29417c4805bf19cce739693c","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Consider measurable functions $b:D \to \R^d$ and $\sigma:D \to \R^{d \times d}$, such that $\sigma$ satisfies the assumptions of Lemma~\ref{lem:ODE_cube}. Furthermore, let constants $\nu^{ii}$ be given by \eqref{eq:nus_cube}, construct the diagonal matrix $\nu$ of these elements, and suppose that the function $\xi$ defined in \eqref{eq:xi} is bounded. Then,
\begin{enumerate}[label = (\roman*),noitemsep]
    \item  the function $f:D \to D$ given by equation \eqref{eq:f_quadrant} with flow maps satisfying \eqref{eq:flows_cube} is well-defined, belongs to $W^{2,\infty}(D)$, has $D$ as its range, and is the unique solution to the PDE \eqref{eq:nonlinear_PDE_cube} satisfying the boundary condition \eqref{eq:f_boundary_cube};
    \item with 
    \begin{equation} 
    \alpha(x) = \nu\sign(\overline x)\, \xi\big(f(|\overline x|)\big), \qquad \text{for a.e. } x \in \R^d,
    \end{equation}
    and $\overline x = x - \Even(x)$, 
     the SDE \eqref{eq:X_SDE_nu} has a pathwise unique, strong solution $X$ for every initial value $X_0 \in \R^d$;
    \item the process $Y = f(|X-\Even(X)|)$ satisfies the RSDE \eqref{eq:RSDE} on $D$ with initial condition $Y_0 = f(|X_0-\Even(X_0)|)$, normally reflecting processes
    \begin{equation}

\begin{aligned} 
\Phi_t^i  = &  \frac{1}{\nu^{ii}}\sum_{n \in \Z} \int_0^t \sigma^{ii}\Big(f\big(|X_s - \Even(X_s)|\odot ({\bf 1}_d - e_i)\big)\Big)dL_s^{2n}(X^i) \\
&  - \frac{1}{\nu^{ii}}\sum_{n \in \Z} \int_0^t \sigma^{ii}\Big(f\big(|X_s - \Even(X_s)|\odot ({\bf 1}_d - e_i)+e_i\big)\Big)dL_s^{2n+1}(X^i), 
    \end{aligned}
\end{equation}
for $i=1,\dots,d$,  $ t \geq 0$, 
    and Brownian Motion $W = \int_0^\cdot\sign(X_t-\Even(X_t))dB_t$. 
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.601014+00:00","domain":"probability theory","id":"claim_d6acd9e85eea2c35f71222afced3938168cec021f164fb3253cacafbe89aaf1b","kind":"concept","schema_version":1,"statement":"[Proposition 13 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper), and let \(\eta\) be given by
(equation 3 of the paper). The following statements are
equivalent:
\begin{enumerate}[(i)]
\item \(\eta\) is branch-stationary;
\item \(B^aZ\sim_\alpha Z\) for every \(a\in\mathcal T\);
\item the punctured tail measure is branch-invariant, i.e.,
\begin{equation}
  \nu_Z^\circ\bigl((B^a)^{-1}A\bigr)
  =
  \nu_Z^\circ(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad a\in\mathcal T,

\end{equation}
where
\[
  (B^a)^{-1}A
  =
  \{f\in\mathcal F^\circ:B^af\in A\};
\]
\item the local spectral tail fields satisfy
\begin{equation}
  B^a\Theta^{[au]}\stackrel{\mathrm d}{=}\Theta^{[u]},
  \qquad a,u\in\mathcal T;

\end{equation}
\item for every \(a,u\in\mathcal T\) and every \(F\in\mathfrak H_0\),
\begin{equation}
  \E*{
    Z_{au}^{\alpha}F(B^aZ)
  }
  =
  \E*{
    Z_u^{\alpha}F(Z)
  }.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.605451+00:00","domain":"probability theory","id":"claim_d6b2e7d1d3b1d0363cd6af7f82950005bdcf7fe2c3745a4a41ee00b80d7bd4b8","kind":"concept","schema_version":1,"statement":"[Corollary cor:a.s of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $(Z_t)_{t\in[0,1]}$ and $(Z^n_t)_{t\in[0,1]}$  be the solutions corresponding to (equation eq:SDE of the paper) and (equation eq:SDE-EM of the paper).
       If  Assumption (ass:main1 of the paper) holds, 
         then  we have  for any $m\in(2,\infty)$ and  $\varepsilon>0$ being small, there exists a constant $N=N(\|b\|_{{\mathbb C}_{\boldsymbol{a}}^\beta}, \|b\|_{{\mathbb C}_x^{\frac{\alpha+\beta}{1+\alpha}}}, m,\alpha,\beta,\epsilon)$ and an a.s. finite random variable $\Xi$ so that for a.e. $\omega\in\Omega$
         \begin{align}

           \sup_{t\in[0,1]}|Z_t(\omega)-Z_t^n(\omega)|\leqslant N\Xi(\omega) n^{-(\frac{1}{2}+\frac{\beta}{\alpha(1+\alpha)}\wedge \frac{1}{2})+\epsilon}.
         \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.440090+00:00","domain":"probability theory","id":"claim_d6b3f1d375d802676d96b8cfffedbdd9f820796b0903876e780933c1d9cccdef","kind":"lemma","schema_version":1,"statement":"[Lem 27 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\widetilde{m}$ be  an order function satisfying \eqref{Hypothèse fonction d'ordre Mildred} with $\alpha$ replaced by $t$. Let $\psi\in \mathscr{C}^\infty_c(\R)$ and consider $0<h^{1-2\eta}\ll\alpha\leq t\leq \beta$ with notations \eqref{Scaling en fonction de t}, \eqref{Scaling de q atchek en fonction de t}, \eqref{Scaling de q_0 atchek en fonction de t} and \eqref{Fonction d'ordre théorème central - version en t}. Then, under the assumptions of Theorem \ref{Théorème central}, for $a\in \{0,1\}$ the following decomposition holds:
        \begin{equation}
        \mathrm{tr}\pr{\frac{1}{t^a}\psi\pr{\frac{\atc{q}_{N,t_1,t_2}}{t}}}=N^d\Bigl(I^a_t+II^a_t+III^a_t+IV^a_t\Bigl)

    \end{equation}
    where for $k\geq 1$,
    \begin{equation}
        \begin{split}
            I^a_t &:=\frac{(h^\eta t)^d}{t^a}\int_{\mc{T}_{t_1,t_2}}\psi\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            II^a_t &:=\mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}\int_{\mc{T}_{t_1,t_2}}\widetilde{\chi}\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            III^a_t &:= \mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}^M\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}\\
            IV^a_t &:= \mc{O}_k(1)\frac{(h^\eta t)^d}{t^a}\pr{Nh^\eta t^{1/2}}^{-k}\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}.
        \end{split}

    \end{equation}
    and where $\widetilde{\chi}\in \mathscr{C}^{\infty}_c(\R;[0,1])$ is such that $\widetilde{\chi}\equiv 1$ on a neighborhood of $[0,\sup\mathrm{supp}(\psi)]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.283288+00:00","domain":"probability theory","id":"claim_d6b63ec2909ef55ed620c1110feab24e79557bf00b99558159ed253b72b3361a","kind":"concept","schema_version":1,"statement":"[Theorem 5 (Span theorem and sharp ambiguity) of arXiv:2608.21496, '2608.21496'] For $\cF=\{f\in L^\infty(\mu):0\le f\le1\}$ and validation operator $Kf=(\langle v_j,f\rangle)_{j=1}^p$:
\begin{enumerate}[label=(\roman*)]
\item $R_k(f)$ is identified by $Kf$ for every $f\in\cF$ if and only if $k\in S_V$.
\item The largest separation between two validation-equivalent worlds is
\begin{equation}
\sup_{\substack{f,g\in\cF\\Kf=Kg}}
|R_k(f)-R_k(g)|=b(k;V).

\end{equation}
\item If all kernels integrate to one, the evidence $Kf=(1/2,\ldots,1/2)$ has an exact identified interval of width $b(k;V)$, centered at $1/2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.412011+00:00","domain":"probability theory","id":"claim_d6b74af2ef407688f46f5a3d26208b864f5bb21f626e43d0fbfaa13e2a296ddd","kind":"lemma","schema_version":1,"statement":"[Lemma Uniform bounds on long edges of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:unif_bounds_long_edges}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.    

    For $r \in \mathbf{N}$, $b \geq 2$, and $\mathbf{m} \in \mathcal{M}(b)$, there exists $c = c(G,J) > 0$ such that for all $r$ sufficiently large,

    \begin{equation}
        \sum_{\mathbf{r} \in \mathcal{R}(b,\mathbf{m},r)}
        \prod_{i = 0}^{b-2}
        \expdegrad{o}{r_i}
        \leq 
        c
        r^{d(1-\alpha)}
        (b-2)^{d\alpha - d + 1}
        \mathbf{E}_{\beta}\left[\deg(o)\right]^{b-1}
        .
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.534352+00:00","domain":"probability theory","id":"claim_d6b86abe56d6307263aff23c756e51987a517e71352eda1bc5678ed8d44234af","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] $\mathcal{Z}_{\mathrm{fine}}(\Phi) \subseteq \mathscr{S}^n$ is the set of fine boundary multislopes achieved by $\Phi$-horizontal foliations. $\mathcal{Z}_{\aleph, \mathrm{fine}} \subseteq \mathscr{S}^n$ where the following wildcard substitutions are permitted to eliminate $\aleph$ components:
    \begin{align*}
    \aleph^\natural & \longmapsto [-\infty^\sharp,+\infty^\flat],\\
    \aleph^\flat & \longmapsto \{-\infty^\dagger\},\\
    \aleph^\sharp &\longmapsto \{+\infty^\dagger\},\\
    \aleph^\dagger &\longmapsto \varnothing.
    \end{align*}
    Similarly define $\mathcal{Z}^\pm_{\mathrm{fine}}(\Phi)$ as the sets of fine boundary multislopes achieved by $\Phi$-horizontal contact structures.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.899250+00:00","domain":"probability theory","id":"claim_d6ba976ca336e952699c9b988ba941201fa47ef3968cef7cd3c49cae946c2e0c","kind":"definition","schema_version":1,"statement":"[Definition 21 of arXiv:2601.16377, '2601.16377'] Given an equilibrium measure $\boldsymbol{\mu}$, we will use the following terminology for each $h \in [H]$.
\begin{itemize}
\item[$\bullet$] A \emph{void} is a maximal (for the inclusion) and closed interval in $[\hat{a}'_h,\hat{b}'_h]$ where
$\mu_h(x) =0$.
\item[$\bullet$] A \emph{saturation} is a maximal closed interval in
$[\hat{a}'_h,\hat{b}'_h]$ where $\mu_h(x) = \frac{1}{\theta_{h,h}}$.
\item[$\bullet$] A \emph{band} is a maximal open interval in $[\hat a'_h,\hat b'_h]$ where $0<\mu_h(x)<\frac{1}{\theta_{h,h}}$.
\end{itemize}
We denote by $\amsmathbb{V}_{h}$ (respectively $\amsmathbb{S}_{h}$, $\amsmathbb{B}_{h}$) the union of voids (respectively saturations, bands) in $[\hat{a}'_{h},\hat{b}'_{h}]$. If we speak of a \emph{saturated segment} (respectively, a \emph{void segment}), we mean a segment included in a saturation (respectively, in a void) but not necessarily maximal.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.256815+00:00","domain":"probability theory","id":"claim_d6bdb3ac78a9ec7741f45a40f0cf46a849527defb1275721785840e5db489aff","kind":"concept","schema_version":1,"statement":"[Proposition YASHAsd of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let \( \mathcal{A} \) be a \( \mathrm{P} \)-weak point attractor. Then
	\begin{align}
		\mu_{\omega^-}\big({\mathcal{A}}(\omega^-)\big) = 1  \quad \mathbf{P}\text{-a.s.},
	\end{align}
	which in particular implies that
	\begin{align}
