{"assumptions":[],"created_at":"2026-10-27T23:00:22.777555+00:00","domain":"probability theory","id":"claim_d821e74e8ef72b7c285505f7c32225fcb84a621f30e4f002ed781024a0c74cc4","kind":"concept","schema_version":1,"statement":"[Theorem thm::main_boundary of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $n,\ell$ be non-negative integers such that $n+\ell\geq 2$. Let $z_1,\ldots,z_n\in \mathbb{H}$ and $x_1,\ldots,x_{\ell}\in \mathbb{R}$.

		Suppose that $z_1^a,\ldots,z_{n}^a\in a(\mathbb{H}\cap \mathbb{Z}^2)$ and $x_1^a,\ldots,x_{\ell}^a\in \partial(\mathbb{H}\cap \mathbb{Z}^2)$ are  vertices satisfying $\lim_{a\to 0}z_j^a=z_j, \lim_{a\to 0}x_k^a=x_k$ for $1\leq j\leq n$ and $1\leq k\leq \ell$. Let $\mathbf{Q}$ be a partition of $\{1,2,\ldots,n+\ell\}$ that contains no singletons. Then 
		\begin{equation} 
			R(\mathbf{Q};z_1,\ldots,z_n;x_1,\ldots,x_{\ell}):=\lim_{a\to 0} a^{-\frac{n}{8}-\frac{\ell}{2}} \times \mathbb{P}^a_{\mathbb{H}}\left[G(\mathbf{Q};z_1^a,\ldots,z_n^a,x_1^a,\ldots,x_{\ell}^a)\right]
		\end{equation}
	exists and belongs to $(0,\infty)$. Moreover, if $\varphi$ is a conformal map from $\mathbb{H}$ onto itself such that $\varphi(x_k)\neq \infty$ for  $1\leq k\leq \ell$, {$\varphi(z_j)\neq \infty$ for  $1\leq j\leq n$}, then we have 
	\begin{equation*}
		R(\mathbf{Q};\varphi(z_1),\ldots,\varphi(z_n);\varphi(x_1),\ldots,\varphi(x_{\ell}))=R(\mathbf{Q};z_1,\ldots,z_n;x_1,\ldots,x_{\ell})\times \prod_{j=1}^n |\varphi'(z_j)|^{-\frac{1}{8}}\times \prod_{k=1}^{\ell} |\varphi'(x_k)|^{-\frac{1}{2}}.
	\end{equation*}
When the number of vertices is small, we have explicit expressions for $R$ up to multiplicative constants:
\begin{enumerate}[label=\textnormal{(\arabic*)}, ref=(\arabic*)]
	\item For $n=0$ and $\ell\in \{2,3\}$, there exist constants $C_4,C_5\in (0,\infty)$ such that 
	\begin{equation}
		R(\mathbf{Q}_2;x_1,x_2)=C_4|x_1-x_2|^{-1},\quad R(\mathbf{Q}_3;x_1,x_2,x_3)=C_5|x_1-x_2|^{-\frac{1}{2}}|x_1-x_3|^{-\frac{1}{2}}|x_2-x_3|^{-\frac{1}{2}}.
	\end{equation}
As a consequence, we have the factorization formula
\begin{equation*}
R(\mathbf{Q}_3;x_1,x_2,x_3)=\frac{C_5}{C_4^{\frac{3}{2}}}\sqrt{R(\mathbf{Q}_2;x_1,x_2)\times R(\mathbf{Q}_2;x_1,x_3)\times R(\mathbf{Q}_2;x_2,x_3)}.
\end{equation*}
\item For $n=\ell=1$, $x_1=0$ and $z_1=re^{\mathfrak{i}\theta}=x+\mathfrak{i} y\in \mathbb{H}$, there exists a constant $C_6\in(0, \infty)$ such that 
\begin{equation*}
	R(\mathbf{Q};0;z)=C_6\frac{y^{\frac{3}{8}}}{|z|} =C_6\frac{\left(\sin\theta\right)^{\frac{3}{8}}}{r^{\frac{5}{8}}}.
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.577355+00:00","domain":"probability theory","id":"claim_d822cba6e726eff6b31ed19ab4075bd20a6d0cb5322195df13d26887417d865a","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ satisfy 
	\eqref{c1}. Let $Y_N=I_q(g_N)$ with $p<q<2p$ and 
	$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$. Define
	\begin{equation}
		h_N := \frac{f_N\otimes_p g_N}
		{\|f_N\|^2_{H^{\otimes p}}}\in H^{\odot(q-p)},
	\end{equation}
	\begin{equation*}
		g_N^{(2)} := g_N - \frac{q!}{p!(q-p)!}
		f_N\widetilde\otimes h_N\in H^{\odot q},
		\qquad
		\varepsilon_N := I_q(g_N^{(2)}).
	\end{equation*}
	Then for every $N\geq 1$:
	\begin{equation}
		Y_N = \frac{1}{p\sigma^2}X_N\cdot Y_{1,N} 
		+ \varepsilon_N + r_N,
	\end{equation}
	where:
	\begin{enumerate}
		\item $f_N\otimes_p g_N^{(2)}=0$, and consequently 
		$\langle DX_N, D\varepsilon_N\rangle_H\to 0$ in 
		$L^2(\Omega)$, so $\varepsilon_N$ is asymptotically 
		independent of $X_N$;
		\item $r_N\to 0$ in $L^2(\Omega)$ as $N\to \infty$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

