{"assumptions":[],"created_at":"2026-09-07T12:18:08.279009+00:00","domain":"probability theory","id":"claim_da7898b5d45c53f7dad4798ef7383b01ef1cbb755a5cdaa8dc0f67b6c57ac3a7","kind":"concept","schema_version":1,"statement":"[Theorem 6 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Assume that $\{\delta_{i}, 1\le i\le n \}$ and $\{\zeta_{i}, 1\le i\le n \}$ are two independent sequences of random variables, where $\delta_{i}\sim\textnormal{Bernoulli}(p)$ are independent and $\zeta_{i}$ are independent $\alpha$-sub-exponential random variables with mean $0$ and variance $1$.
    Consider a random vector $\xi=(\xi_{1}, \cdots, \xi_{n})$  with $\xi_{i}=\delta_{i}\cdot\zeta_{i}$. Let $A$ be an $m\times n$ fixed matrix. Then for $0<\alpha\le 2$ and $t\ge 0$,
    \begin{align}
        \mathbb{P}\Big\{ \big\vert \Vert A\xi\Vert_{2}-\sqrt{p}\Vert A\Vert_{F} \big\vert>L^{2}(\alpha)t \Big\}\le 2\exp\Big\{-c(\alpha)\min \big\{\big(\frac{t}{\Vert A\Vert_{l_2\to l_2}}\big)^{2}, \big(\frac{t}{\Vert A\Vert_{l_2\to l_2}} \big)^{\alpha} \big\}    \Big\},
    \end{align}
    where $L(\alpha)=\max_{i}\Vert \zeta_i\Vert_{\Psi_{\alpha}}$ and $c(\alpha)>0$ is a constant depending only on $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.390823+00:00","domain":"probability theory","id":"claim_da79012828b32ec77bc6de591a5a7ebfd4d56d57817faa0738ad5061bce097cd","kind":"concept","schema_version":1,"statement":"[Lem l.sum of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] For $m\in\mathbb{N}$ and $i\in[\![m]\!]$, let $\mathcal{T}_{i}(t):L^2(\mathbb{R}^{d_i},\mathrm{d} x) \to L^2(\mathbb{R}^{d_{i-1}},\mathrm{d} x)$ be a $t$-parameterized operator with a nonnegative kernel.
Assume that, for $c', c_1, \ldots, c_{m}\in[0,\infty)$, $b_i\in(0,1)$,  and for a partition $A_1,A_2,A_3$ of $[\![m]\!]$, the following bounds hold for all $t>0$.
\begin{subequations}

\begin{align}

	&\text{When } i \in A_1,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \, t^{-b_i}\ .
\\

	&\text{When } i \in A_2,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \,t^{-1} \, \big|\log(\tfrac{1}{2}\wedge t)\big|^{-2} \ .
\\

	&\text{When } i \in A_3,
	\quad
	\Normop{ \mathcal{T}_{i}(t) }
	\leq
	c_{i} \, e^{c't} \,t^{-1}
	\text{ and }
	\NOrmop{\int_{0}^\infty \mathrm{d} t\ e^{-c' t} \mathcal{T}_{i}(t) } \leq c_i\ .
\end{align}
\end{subequations}
There exists a universal $c>0$ such that for all $m\in\mathbb{N}$, $\ell=0,\dots,|A_2|-1$, $t>0$, and $\lambda \geq c'+2$
\begin{align}

\begin{split}
	\NOrmop{ \int_{\Sigma(t)} &\mathrm{d} \vec{u} \, \prod_{i\in[\![m]\!]} \mathcal{T}_{i}(u_{i}) }
	\leq
	c^m\, m^{2} \, t^{|A_1|-1} \,  e^{\lambda t} \,
	\prod_{i\in[\![m]\!]} c_i 
	\cdot 
	\prod_{j\in A_1}\frac{t^{-b_j}}{1-b_j}
\\
	&\cdot
	\begin{cases}
	\displaystyle
	\frac{1}{ |\log(\lambda-c'-1)|^{|A_2|-1-\ell} \, |\log(t\wedge\frac{1}{2})|^{\ell+1} } & \text{ when } |A_2|>0\ ,
	\\
	\ 1 &\text{ when } |A_2|=0\ .
	\end{cases}
\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.576308+00:00","domain":"probability theory","id":"claim_da7b3d1412c1c6634e85648022882cd1acb73f6dadd3f0e51a2e253844245026","kind":"concept","schema_version":1,"statement":"[Lemma 3 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and $q\geq 1$ two integer numbers. Let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $f_{N} \in H ^{\odot p}$ for all $N\geq 1$. Assume (\ref{c1}). Then

		\begin{enumerate}
