					r=1,...,q, \mbox{ if } p\not =q\\
					r=1,..., p-1 \mbox{ if } p=q. 
				\end{cases}
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:38:17.794457+00:00","domain":"probability theory","id":"claim_da7f90a4cc17f79d112ede5ae9388d57368499835be5a0d0076c8f8186735b96","kind":"concept","schema_version":1,"statement":"[Theorem thm:main_u_R of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] For 
