\rs (a, b) := \displaystyle\bigcap_{\substack{(a_1, b_1) \in \landsc \\ a_1\in ]a, a+R]}} \Biggl(\{(x, y) \in \Half: (x\geq a_1-R &\text{ and } \frac{b-y}{a-x} \geq \frac{b_1-b}{a_1-a}\}\\&  \cup\{(x, y)\in \Half:a-Rx <a_1-R\}\Biggl).
\end{align*}

\begin{figure}[h]
