{"assumptions":[],"created_at":"2026-10-26T20:49:17.497977+00:00","domain":"probability theory","id":"claim_db62bfb102549016427e88cf46829eaaf8b3361724564ae4b59922aa5678e72b","kind":"theorem","schema_version":1,"statement":"[Thm 2 of arXiv:2605.29469, 'Multiscale Asymptotic Analysis of Kernel-Smoothed Solutions to Fractional Riesz-Bessel Equ'] Consider the random field $u(t,x)$, $t>0$, $x\in\mathbb{R}$, defined by \eqref{FRBE} and the random initial condition given by \eqref{Icond}, satisfying Assumption~{\rm\ref{Asumptionmain}} with $A_0 \ne 0$.

For the scaling parameters $\rho_1=-{\kappa_0\rho_3}/{2},$ $\rho_2=\alpha\rho_3/\beta,$ and $\rho_3>0$, when $\varepsilon\to 0$, the finite-dimensional distributions of $U_\varepsilon^{g}(t,x)$ converge weakly to those of a zero-mean Gaussian random field $\tilde{U}_0^{g}(t,x)$ given by
\begin{equation} 
\tilde{U}_0^{g}(t,x)
:=
\sqrt{C(\kappa_0,A_0)}
\int_{\mathbb{R}}
\widehat{g}(\lambda,x)\,
E_\beta\!\left(-\mu t^\beta |\lambda|^\alpha\right)
|\lambda|^{\frac{\kappa_0-1}{2}}
\,W(d\lambda).
\end{equation}

The limit random field $\tilde{U}_0^{g}(t,x)$ has the covariance function
\begin{align}
\operatorname{Cov}\bigl(\tilde{U}_0^g(t,x),\tilde{U}_0^g(t',x')\bigr)
&=
 C(\kappa_0,A_0)
\int_{\mathbb{R}}
\widehat{g}(\lambda,x)\overline{\widehat{g}(\lambda,x')}\nonumber\\
&\quad \quad \times
E_\beta(-\mu t^\beta |\lambda|^\alpha)
E_\beta(-\mu (t')^\beta |\lambda|^\alpha)
|\lambda|^{\kappa_0-1}\,d\lambda. 
\end{align}","status":"unverified"}

