{"assumptions":[],"created_at":"2026-10-27T13:01:22.628756+00:00","domain":"probability theory","id":"claim_db7d08b5f82afadfbe97d67237be573dfa1c6de2489f0e4b67ca197a5179104c","kind":"definition","schema_version":1,"statement":"[Definition def:lin-FPE of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $z\in \mathbb{R}^d$ and $s\geq 0$. 
    We say that $u: (0,\infty)\times \mathbb{R}^d \to [0,\infty)$ is a \emph{probability solution} to (equation eq:lin-FPE of the paper) with initial datum $\zeta \in \mathcal P$ if
    \begin{enumerate}[(i)]
        \item $u(t,x) \,\mathrm d x \in \mathcal P$ for all $t>0$, $t\mapsto u(t,x) \,\mathrm d x$ is weakly continuous on $(0,\infty)$, and $u(t,x) \,\mathrm d x \to \zeta$ weakly as $t \to 0$;
        \item The maps $(t,x) \mapsto a_{ij}(x,f^z_Q(s+t))$ and $(t,x) \mapsto b_i(x,f^z_Q(s+t))$ belong to $L^1([0,T]\times \mathbb{R}^d; u(t,x) \,\mathrm d x \mathrm d t)$ for each $T>0$;
        \item For all $\varphi \in C^2_c(\mathbb{R}^d)$ and $t>0$,
        \begin{align*}
            &\int_{\mathbb{R}^d}\varphi(x) u(t,x) \,\mathrm d x - \int_{\mathbb{R}^d}\varphi(x) \,\mathrm d\zeta(x)
            \\&= \int_0^t \int_{\mathbb{R}^d} \Bigl(a_{ij}\bigl(x,f^z_Q(s+r)\bigr) \partial_{ij}\varphi(x) + b_i\bigl(x,f^z_Q(s+r)\bigr) \partial_i \varphi(x) \Bigr) u(r,x) \,\mathrm d x \mathrm d r.
        \end{align*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:00:30.493808+00:00","domain":"probability theory","id":"claim_db7fcc31f01ef7b85ffcfd7e632141c64b7764787ba8f0e22ef0e4f52633e286","kind":"concept","schema_version":1,"statement":"[Theorem 16 of arXiv:2607.04138, 'Hives from deformed GUE minor processes'] \lab{thm:6}

