{"assumptions":[],"created_at":"2026-10-27T21:42:57.183645+00:00","domain":"probability theory","id":"claim_db9527b89bd4889017bbaf0cfc737d95b5e860218165eff1d715ca15d15e86d0","kind":"concept","schema_version":1,"statement":"[Lemma lem:metric-ball-locality of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {kkmt2026cle4_part2}}]
