{"assumptions":[],"created_at":"2026-10-27T11:19:42.656822+00:00","domain":"probability theory","id":"claim_db9ae31740dbc5b6a0a4008fefb73b480f66800fb698423d754cf1333c5c21c0","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Averaging and Fluctuations of the Effective Model) of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] Assume $\psi_0\in L^2$ and the validity of \cref{hp:noise}. Let $\Psi^{\tau}$ be the unique solution of \eqref{eq:simplified_model} given by \autoref{prop:well_effective} and let  $\Xi^{\tau}=\frac{\Psi^\tau-\bar{\psi}}{\sqrt{\tau}}$. Then for each $\theta_1\in [-2,0),\theta_2\in [-3,-\frac{5}{3})$ and $q\geq 1$
 \begin{align}
     \mathbb{E}\left[\sup_{t\in [0,T]}\|\Psi_t^{\tau}-\bar{\psi}_t\|_{H^{\theta_1}}^q\right]&\lesssim \tau^{-\frac{q\theta_1}{4}},\\
     \mathbb{E}\left[\sup_{t\in [0,T]}\|\Xi_t^{\tau}-\xi_t\|_{H^{\theta_2}}^q\right]&\lesssim \begin{cases}\tau^{-\frac{q(3\theta_2+5)}{4}}\quad &\text{if }\theta_2\in [-2,-\frac{5}{3}),\\
        \tau^{-\frac{q(\theta_2+1)}{4}}\quad &\text{if }\theta_2\in [-3,-2].
     \end{cases}
 \end{align}
 Above we denote by $\bar{\psi}$ the unique weak solution of \eqref{eq:averaging} given by \cref{prop:well_posed_averaging_limit} and by $\xi$ the unique weak solution of \eqref{eq:gaussianlimit} given by \cref{prop:well_posed_fluctuations}, driven by the same Brownian motions as $\Psi^\tau$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.887503+00:00","domain":"probability theory","id":"claim_dba0f373e8f134388373934ac38ddf70f836cfa01fa9c66792e6d27a26eae5d4","kind":"concept","schema_version":1,"statement":"[Lemma 31 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] For every fixed $k\ge 0$ and $\vv \zeta=( \zeta_0,\dots,\zeta_k)$,
