{"assumptions":[],"created_at":"2026-10-27T10:02:28.587929+00:00","domain":"probability theory","id":"claim_dbda936cc1e3e5674398723a9f43c8a721a46f8ae60d6f227ef6da97ac12e301","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2609.01346, '2609.01346'] Let
