	\end{align*}
	where $(X_s,Y_s)_{s\in [s_0,t]}$ is a Brownian motion on $\mathbb{R}^2$ starting from $(x,y)$ at time $s_0$ under $\mathbb{P}_{(s_0,x,y)}$, and $(R_s,\theta_s)_{s\in [s_0,t]}$ is a representation of its polar coordinates. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:20.952108+00:00","domain":"probability theory","id":"claim_dc4cc0fe1f62051f0caf03a33425c940c2f396b8ee6b50a23aa355af50bcccb3","kind":"concept","schema_version":1,"statement":"[Theorem 9 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] {\cite[Theorem 1.1]{Bobkov-Nayar-Tetali-2017-nonLip}}

Suppose $\nu \in \mP(\R^d)$ satisfies a T$_2$ inequality with constant $\sigma^2$. For a Borel set $A\subseteq \R^d$ with $\nu(A)>0$, define  $\nu_A(S):=\nu(A\cap S)/\nu(A)$. Then $\nu_A$ satisfies a T$_2$ inequality with constant $\sigma^2_A$, and
\begin{align*}
    \sigma_A^2\leq c\log\Big(\frac{e}{\nu(A)}\Big)\sigma^2,
\end{align*}
where $c$ is a universal constant. In particular for every $L \in (0, \infty)$ and each $L$-Lipschitz function $f:\R^d\to \R$ with $\int f\,d\nu_A=0,$ the following hold:
\begin{enumerate}
    \item For each $\lambda\in \R$ we have
\begin{align}
    \int_{\R^d} e^{\lambda f(x)}d\nu_A(x)\leq e^{L^2\lambda^2\sigma^2_A/2}.

    \end{align}
    \item For each $\lambda < \frac{1}{2\sigma_AL}$, we have
    \begin{equation}
    \int_{\R^d} e^{\lambda^2 f(x)^2/2} d\nu_A(x)\leq 2.

    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.332687+00:00","domain":"probability theory","id":"claim_dc52a57b0917bef9c1d78557cfbba4b896f77510b97e0a906124a5fe684b00b3","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $a, a', b, b', c > 0$. Then, there exists constants $\alpha, \beta, \gamma \in (0, 1)$ with $\alpha + \beta + \gamma = 1$ such that, for any $A, B, C \in (0, \infty)$

  \begin{align}
    \inf_{r > 0, R > 0}
    \biggl(
      r^{a'} R^{a} A + r^{-b'}\biggl(\frac{R}{r}\biggr)^{\!\!b}\,B
      + R^{-c}\, C
    \biggr)
    \;\leq\;
    3\, A^{\alpha} B^{\beta} C^{\gamma}.
  \end{align}

  In particular, for $a' = 2 - d/q$, $a = d/q$, $b' = b = d$, $c = m$ with $d \geq 2$, $q > d/2$ and $m \geq 2$,

  \begin{align}
    \frac{d+2}{2}\,\beta + \frac{m+2}{2}\,\gamma \;=\; 1.
  \end{align}","status":"unverified"}

